-- Competency Assessment — question bank seed data (Section 27 companion file)
-- Generated from 9 role-specific question sets (~23 questions each, ~207 total). Safe to re-run:
-- each role's insert is guarded by "no rows for this job_role yet", so admin edits/deactivations
-- made afterward through the Question Bank screen are never overwritten by a later re-run of this
-- file. Run this once after schema.sql's Section 27 (comp_question_bank must already exist).

-- ---- welding_inspector (23 questions) ----
insert into comp_question_bank (job_role, category, sub_category, difficulty, question_text, reference_answer, key_points, excellent_answer_indicators, common_mistakes, standard_reference)
select 'welding_inspector', x.category, x.sub_category, x.difficulty, x.question_text, x.reference_answer,
       coalesce(x.key_points, '[]'::jsonb), coalesce(x.excellent_answer_indicators, '[]'::jsonb), coalesce(x.common_mistakes, '[]'::jsonb), coalesce(x.standard_reference, '')
from jsonb_to_recordset('[{"category":"GENERAL","sub_category":"نقش ناظر جوش / تعامل با ذی‌نفعان","difficulty":"L1","question_text":"نقش و جایگاه مهندس ناظر جوش را در چرخه اجرای یک پروژه احداث خط لوله گاز، از مرحله تأیید WPS تا تحویل نهایی، و نحوه تعامل او با واحد QC پیمانکار، مشاور و کارفرما را توضیح دهید.","reference_answer":"ناظر جوش پیش از شروع عملیات، WPS و PQR ارائه‌شده توسط پیمانکار را بازبینی و تأیید می‌کند و در کوالیفیکیشن جوشکاران به‌عنوان شاهد حضور دارد. در حین اجرا، پیش‌گرم، فیت‌آپ، پارامترهای جوشکاری و بازرسی چشمی را کنترل می‌کند، نقاط توقف (Hold Point) تعریف‌شده در ITP را با تیم QC پیمانکار هماهنگ می‌کند و نتایج NDE را بازبینی می‌نماید. در صورت بروز عدم انطباق، NCR تنظیم و پیگیری می‌شود و در پایان کار، داسیه جوش برای تحویل نهایی تکمیل می‌گردد. ناظر جوش باید استقلال نظارتی خود را در برابر فشار تولید پیمانکار حفظ کند و مستقیماً یا از طریق مشاور به کارفرما گزارش دهد.","key_points":["بازبینی و تأیید WPS/PQR قبل از شروع عملیات","حضور و شاهد بودن در کوالیفیکیشن جوشکاران","کنترل حین اجرا: پیش‌گرم، فیت‌آپ، پارامترهای جوشکاری","هماهنگی نقاط توقف (Hold Point) با ITP","بازبینی نتایج NDE و مدیریت NCR","تدوین و تکمیل داسیه جوش برای تحویل","حفظ استقلال نظارتی در تعامل با پیمانکار و گزارش‌دهی به مشاور/کارفرما"],"excellent_answer_indicators":["اشاره به نقش به عنوان خط دفاعی مستقل کیفیت، نه صرفاً بازرس فرم‌پرکن","تسلط بر ارتباط بین ITP، ذی‌نفعان و ردیابی کامل مستندات","ذکر مدیریت اینترفیس بین جوش، PWHT، NDE و پوشش‌دهی","نمونه واقعی از حل تعارض یا تصمیم مستقل"],"common_mistakes":["محدود کردن نقش به فقط بازرسی بصری نهایی","عدم اشاره به مرحله پیش از تولید (WPS/PQR/WPQ)","ندانستن جایگاه سازمانی و خط گزارش‌دهی"],"standard_reference":""},{"category":"GENERAL","sub_category":"مدیریت مستندات / ITP و داسیه جوش","difficulty":"L1","question_text":"فرض کنید در پایان یک اسپول جوشکاری‌شده، هنگام تکمیل داسیه (Weld Dossier) متوجه می‌شوید یکی از رکوردهای ردیابی (traceability) جوشکار یا الکترود مصرفی گم شده است. اولین اقدام شما چیست و چگونه از تکرار این مشکل جلوگیری می‌کنید؟","reference_answer":"ابتدا کار روی همان اتصال متوقف می‌شود تا وضعیت شفاف شود و مدارک جایگزین مانند لاگ روزانه جوشکاری، رجیستر مصرف الکترود و نقشه شماره‌گذاری جوش بررسی می‌گردد. اگر ردیابی واقعاً قابل اثبات نباشد، موضوع به‌عنوان یک عدم انطباق ثبت شده و ریسک آن با مشاور و کارفرما ارزیابی می‌شود؛ در برخی موارد ممکن است نیاز به NDE اضافی برای اطمینان از کیفیت باشد. علت ریشه‌ای معمولاً نبود کنترل روزانه در نقطه ثبت مدارک است و اقدام اصلاحی، ممیزی روزانه مدارک قبل از پوشش‌دهی یا خاکریزی خط لوله است.","key_points":["توقف کار روی آن اتصال تا شفاف‌سازی وضعیت","بررسی مدارک جایگزین: لاگ روزانه جوش، رجیستر الکترود، نقشه شماره‌گذاری جوش","در صورت عدم اثبات ردیابی، ثبت NCR و ارزیابی ریسک با کارفرما/مشاور","بررسی امکان NDE اضافی برای اطمینان از کیفیت","علت‌یابی ریشه‌ای نقص در فرآیند ثبت روزانه","اقدام اصلاحی: ممیزی روزانه مدارک قبل از پوشش‌دهی/خاکریزی"],"excellent_answer_indicators":["تأکید بر جلوگیری از دفن خط لوله بدون ردیابی کامل","پیشنهاد سیستم بارکد یا دیجیتال برای ردیابی جوش","درک ریسک ایمنی و قانونی ناشی از عدم ردیابی، به‌خصوص در سرویس ترش یا فشار بالا"],"common_mistakes":["نادیده گرفتن مشکل و تکمیل داسیه با فرض","عدم ثبت NCR","ندانستن این‌که traceability بخشی الزامی مشخصات فنی پروژه است"],"standard_reference":""},{"category":"GENERAL","sub_category":"مدیریت NCR","difficulty":"L2","question_text":"فرآیند کامل مدیریت یک NCR مرتبط با جوش، از لحظه کشف عدم انطباق تا بسته شدن نهایی آن در سیستم مستندسازی پروژه را شرح دهید.","reference_answer":"به‌محض کشف عیب، موضع معیوب تگ‌گذاری و متوقف می‌شود و شرح کامل شامل شماره جوش، نوع عیب و مدرک پشتیبان مانند فیلم RT یا عکس ثبت می‌گردد. سپس تحلیل علت ریشه‌ای انجام شده و یکی از گزینه‌های تعمیر، برش و جوش مجدد یا استفاده در وضعیت موجود (use-as-is) با توجیه مهندسی پیشنهاد می‌شود که باید طبق سطح دسترسی تعریف‌شده توسط مشاور یا کارفرما تأیید شود. پس از اجرای اقدام اصلاحی، بازرسی و NDE مجدد انجام می‌شود و در نهایت NCR با امضای تمام طرف‌های ذی‌ربط بسته می‌شود. یک بخش مهم و اغلب مغفول، پیگیری روند تکرار NCRهای مشابه برای شناسایی مشکلات سیستمی است.","key_points":["توقف کار و تگ‌گذاری موضع معیوب بلافاصله پس از کشف","ثبت کامل: شماره جوش، شرح عیب، مدرک (فیلم RT/عکس)","تحلیل علت ریشه‌ای (RCA)","ارائه disposition: تعمیر، برش و جوش مجدد، یا use-as-is با توجیه مهندسی","تأیید کارفرما/مشاور طبق سطح دسترسی تعریف‌شده","بازرسی/NDE مجدد پس از اقدام اصلاحی","بستن رسمی NCR و پیگیری روند تکرار مشابه (trend analysis)"],"excellent_answer_indicators":["تفکیک روشن گزینه‌های disposition و معیار انتخاب هرکدام","اشاره به تحلیل روند NCRها برای شناسایی مشکل سیستمی","تأکید بر اینکه use-as-is نیازمند تأیید مهندسی/طراح است، نه صرفاً ناظر"],"common_mistakes":["فرض که همه NCRها باید تعمیر شوند بدون بررسی علت","نادیده گرفتن نیاز به تأیید چندجانبه","عدم اشاره به بازرسی مجدد پس از تعمیر"],"standard_reference":""},{"category":"GENERAL","sub_category":"مدیریت تعارض و ارتباط با پیمانکار","difficulty":"L3","question_text":"پیمانکار نسبت به رد شدن یک جوش توسط شما اعتراض می‌کند و مدعی است معیار شما سخت‌گیرانه‌تر از استاندارد پروژه است. چگونه با این تعارض برخورد می‌کنید؟","reference_answer":"ابتدا با آرامش و بدون واکنش احساسی، مبنای رد جوش را مجدداً و مستقل در برابر مرجع مکتوب یعنی مشخصات فنی پروژه، WPS مصوب و معیار پذیرش استاندارد بازبینی می‌کنم، نه صرفاً قضاوت شخصی. اگر پیمانکار مدرکی مبنی بر معیار متفاوت ارائه دهد، آن را با سلسله‌مراتب مرجع تصمیم یعنی مشخصات پروژه، قرارداد، نقشه و سپس استاندارد مقایسه می‌کنم. در صورت تداوم اختلاف، موضوع را برای داوری فنی به مشاور یا کارفرما ارجاع می‌دهم و کل گفتگو و تصمیم نهایی را کتباً مستند می‌کنم. تصمیم فنی هرگز صرفاً به دلیل فشار پیمانکار، بدون مستند فنی معتبر، تغییر نمی‌کند.","key_points":["بازبینی مستقل مبنای رد جوش با مرجع مکتوب (مشخصات فنی/WPS/استاندارد)","عدم تغییر تصمیم صرفاً به دلیل فشار، مگر با مستند فنی معتبر","درخواست مستندات پیمانکار و مقایسه دقیق","در صورت تداوم اختلاف، ارجاع به مشاور/کارفرما برای داوری فنی","مستندسازی کتبی از مکاتبات و نتیجه نهایی","حفظ رفتار حرفه‌ای و عدم ورود به تنش شخصی"],"excellent_answer_indicators":["تأکید بر سلسله‌مراتب مرجع تصمیم (مشخصات پروژه، قرارداد، نقشه، استاندارد)","اشاره به اهمیت مستندسازی برای محافظت از خود و پروژه در آینده","مثال از تجربه واقعی حل چنین اختلافی"],"common_mistakes":["تسلیم شدن به فشار پیمانکار بدون بررسی فنی","برخورد احساسی/تقابلی به‌جای رجوع به مستندات","عدم مستندسازی گفتگو و تصمیم نهایی"],"standard_reference":""},{"category":"GENERAL","sub_category":"تصمیم‌گیری تحت فشار زمانی و اخلاق حرفه‌ای","difficulty":"L3","question_text":"نزدیک پایان پروژه و تحت فشار شدید زمانی، سرپرست پروژه از شما می‌خواهد نقطه توقف بازرسی (Hold Point) روی یک اتصال جوش حیاتی را نادیده بگیرید تا کار متوقف نشود. چه تصمیمی می‌گیرید؟","reference_answer":"از نادیده گرفتن Hold Point الزامی تعریف‌شده در ITP مصوب امتناع می‌کنم، زیرا این یک الزام قراردادی و کیفی است، نه یک گزینه اختیاری. ریسک ایمنی و یکپارچگی خط لوله، به‌ویژه در جوش‌های حیاتی، در صورت پوشاندن یا ادامه کار بدون بازرسی به‌وضوح برای سرپرست توضیح داده می‌شود. به‌جای حذف بازرسی، راهکار جایگزینی مانند اولویت‌دهی و تسریع همان بازرسی یا تخصیص منابع اضافی پیشنهاد می‌شود. در صورت تداوم فشار، موضوع به‌صورت کتبی به مدیریت پروژه یا کارفرما اطلاع داده می‌شود و در هیچ شرایطی بازرسی انجام‌نشده امضا نخواهد شد.","key_points":["امتناع از نادیده گرفتن Hold Point الزامی طبق ITP مصوب","توضیح ریسک ایمنی و یکپارچگی خط لوله ناشی از پوشاندن جوش بدون بازرسی","ارائه راه‌حل جایگزین: تسریع بازرسی، تخصیص منبع اضافی به‌جای حذف بازرسی","مکاتبه و اطلاع‌رسانی کتبی در صورت تداوم فشار","امتناع قطعی از امضای بازرسی انجام‌نشده"],"excellent_answer_indicators":["تفکیک روشن بین فشار مدیریتی و الزام قراردادی/ایمنی","ذکر پیامدهای حقوقی و حرفه‌ای امضای گزارش کذب","ارائه راهکار عملی برای کاهش تأخیر بدون قربانی کردن کیفیت"],"common_mistakes":["پذیرش درخواست برای حفظ روابط کاری","امضای بازرسی بدون انجام واقعی آن","عدم مستندسازی و اطلاع‌رسانی به سطح بالاتر"],"standard_reference":""},{"category":"TECHNICAL","sub_category":"WPS/PQR","difficulty":"L3","question_text":"در بازبینی یک WPS ارائه‌شده توسط پیمانکار برای جوشکاری خط لوله گاز فولادی API 5L X65، چه مواردی (essential variables) را بررسی می‌کنید و چگونه تشخیص می‌دهید که WPS با PQR پشتیبان آن و مشخصات فنی پروژه مطابقت دارد؟","reference_answer":"متغیرهای اساسی مانند گروه و رده فلز پایه، محدوده ضخامت، فرآیند جوشکاری، پوزیشن، جنس و قطر فلز پرکننده، محدوده پیش‌گرم و بین‌پاسی، heat input، الزام یا عدم الزام PWHT و طراحی اتصال و شکاف ریشه بررسی می‌شود. سپس هر یک از این پارامترها با مقادیر واقعی تست‌شده در PQR پشتیبان مقایسه می‌شود تا اطمینان حاصل شود که صرفاً ارجاع به شماره PQR کافی نیست و مقادیر واقعاً در محدوده کوالیفای قرار دارند. علاوه بر کد پایه، باید بررسی شود که آیا مشخصات فنی پروژه الزامات سخت‌گیرانه‌تری دارد، مانند پیش‌گرم بالاتر یا heat input محدودتر برای سرویس ترش. در نهایت آخرین ریویژن معتبر و امضاهای تأیید WPS نیز کنترل می‌شود.","key_points":["تطبیق متغیرهای اساسی (essential variables): فلز پایه، ضخامت، فرآیند، پوزیشن، پرکننده","بررسی محدوده پیش‌گرم/بین‌پاسی و heat input نسبت به PQR","کنترل الزام PWHT در صورت نیاز","تطبیق root gap/joint design با نقشه و مشخصات فنی پروژه","اطمینان از اینکه پارامترهای WPS در بازه تأییدشده PQR واقعی قرار دارند نه فقط ارجاع به شماره PQR","بررسی سخت‌گیری اضافه مشخصات فنی پروژه نسبت به استاندارد پایه (مثلاً برای سرویس ترش)","تأیید آخرین ریویژن معتبر و امضاهای تأیید"],"excellent_answer_indicators":["اشاره به تفاوت بین کد پایه و مشخصات فنی پروژه که می‌تواند سخت‌گیرتر باشد","مثال مشخص از یک essential variable که اغلب اشتباه تنظیم می‌شود","ذکر لزوم بررسی PQR اصلی نه فقط گزارش خلاصه"],"common_mistakes":["اکتفا به بررسی وجود شماره PQR بدون تطبیق مقادیر واقعی","نادیده گرفتن الزامات سخت‌گیرانه‌تر مشخصات فنی پروژه","عدم توجه به محدوده ضخامت و قطر قابل قبول طبق کد"],"standard_reference":"ASME Section IX"},{"category":"TECHNICAL","sub_category":"کوالیفیکیشن جوشکار (WPQ)","difficulty":"L2","question_text":"یک جوشکار برای جوشکاری اتصالات لوله با قطر ۱۶ اینچ و ضخامت ۱۲.۷ میلی‌متر در پوزیشن 6G کوالیفای شده است. آیا این جوشکار می‌تواند بدون آزمون مجدد روی لوله ۴ اینچ در پوزیشن ثابت یا روی پلیت جوش کند؟ محدوده کوالیفیکیشن (range of qualification) را توضیح دهید.","reference_answer":"کوالیفیکیشن در پوزیشن 6G روی لوله معمولاً پوشش‌دهنده تمام پوزیشن‌های دیگر است، اما محدوده قطر و ضخامت قابل قبول باید دقیقاً بر اساس جدول range of qualification استاندارد مرجع بررسی شود، نه بر اساس فرض کلی. کوالیفیکیشن روی لوله معمولاً پلیت را نیز پوشش می‌دهد، ولی عکس این موضوع الزاماً درست نیست و باید بررسی شود. همچنین باید اطمینان حاصل شود که جوشکار در دوره زمانی مجاز تداوم کد، از همان فرآیند استفاده کرده باشد؛ در غیر این صورت نیازمند requalification است.","key_points":["پوزیشن 6G معمولاً پوشش‌دهنده تمام پوزیشن‌ها است اما باید طبق جدول کد بررسی شود","محدوده قطر و ضخامت کوالیفای بر اساس مقادیر تست‌شده و جداول استاندارد تعیین می‌شود، نه فرض کلی","کوالیفیکیشن روی لوله معمولاً پلیت را هم پوشش می‌دهد ولی عکس آن الزاماً درست نیست","لزوم بررسی جدول range of qualification کد مرجع (نه حدس)","اهمیت تداوم (continuity) جوشکار طبق دوره زمانی مجاز کد"],"excellent_answer_indicators":["ارجاع دقیق به مفهوم جدول range of qualification به‌جای پاسخ کلی","اشاره به الزام کوالیفیکیشن مجزا برای فرآیند یا پوزیشن متفاوت","توجه به سوابق تداوم و لزوم requalification در صورت وقفه"],"common_mistakes":["فرض اینکه کوالیفیکیشن 6G همه چیز را بدون قید و شرط پوشش می‌دهد","ندانستن تفاوت پوشش لوله و پلیت","نادیده گرفتن موضوع تداوم جوشکار"],"standard_reference":"ASME Section IX"},{"category":"TECHNICAL","sub_category":"پیش‌گرم و دمای بین‌پاسی","difficulty":"L2","question_text":"چرا کنترل دمای پیش‌گرم و بین‌پاسی در جوشکاری فولادهای با استحکام بالا در پروژه‌های خط لوله اهمیت دارد و در صورت مشاهده عدم رعایت آن حین اجرا، چه اقدامی انجام می‌دهید؟","reference_answer":"پیش‌گرم با کاهش سرعت سرد شدن، ریسک ترک هیدروژنی در منطقه متأثر از حرارت (HAZ) را کاهش می‌دهد، به‌ویژه در فولادهایی با کربن معادل بالاتر. سقف دمای بین‌پاسی نیز از رشد بیش از حد دانه‌ها و افت چقرمگی ناشی از heat input بالا جلوگیری می‌کند که در فولادهای استحکام بالا و سرویس ترش اهمیت ویژه دارد. در صورت مشاهده عدم رعایت این دما حین اجرا، باید بلافاصله جوشکاری متوقف شود، دمای واقعی با ابزار کالیبره‌شده در برابر الزام WPS تأیید گردد و پیش از ادامه کار اصلاح صورت گیرد. همچنین باید بررسی شود که آیا لازم است پیش از NDE نهایی، زمان تأخیری برای احتمال ترک تأخیری (delayed cracking) در نظر گرفته شود.","key_points":["پیش‌گرم برای کاهش سرعت سرد شدن و ریسک ترک هیدروژنی در HAZ","کنترل دمای بین‌پاسی برای جلوگیری از رشد دانه و افت چقرمگی در heat input بالا","اهمیت ویژه در فولادهای استحکام بالا و سرویس ترش","توقف فوری کار در صورت مشاهده عدم رعایت","تأیید دمای واقعی با ابزار کالیبره‌شده در مقابل الزام WPS","بررسی نیاز به تأخیر در NDE برای احتمال ترک تأخیری (delayed cracking)"],"excellent_answer_indicators":["اشاره به تأخیر زمانی لازم قبل از UT/RT نهایی برای فولادهای مستعد ترک هیدروژنی","ذکر رابطه کربن معادل (Carbon Equivalent) با نیاز به پیش‌گرم بالاتر","تجربه عملی از تشخیص عدم رعایت پیش‌گرم در میدان"],"common_mistakes":["اشاره فقط به یک هدف بدون ذکر مکانیزم ترک هیدروژنی","ندانستن دلیل وجود سقف بالا برای دمای بین‌پاسی","عدم اقدام فوری و ادامه جوشکاری تا پایان پاس"],"standard_reference":"API 1104"},{"category":"TECHNICAL","sub_category":"عملیات حرارتی پس از جوش (PWHT)","difficulty":"L2","question_text":"هدف از انجام PWHT روی یک جوش را توضیح دهید و اگر مشاهده کنید که پارامترهای ثبت‌شده نمودار PWHT (نرخ گرمایش، دمای هولد، زمان هولد) با WPS مصوب مطابقت ندارد، چه تصمیمی می‌گیرید؟","reference_answer":"PWHT برای تخلیه تنش‌های پسماند ناشی از جوشکاری، تمپر شدن ریزساختار سخت و کاهش سختی HAZ و بهبود چقرمگی انجام می‌شود و در سرویس ترش برای کنترل ریسک ترک ناشی از هیدروژن اهمیت ویژه‌ای دارد. اگر پارامترهای ثبت‌شده در نمودار PWHT با WPS مصوب مطابقت نداشته باشد، جوش باید فوراً به‌عنوان عدم انطباق علامت‌گذاری شود و جهت انحراف (کمتر یا بیشتر از حد مجاز) بررسی گردد، زیرا عملیات ناقص ریسک تنش پسماند و سختی بالا را باقی می‌گذارد در حالی که دمای بیش از حد می‌تواند خواص مکانیکی را تغییر دهد. پیش از پذیرش جوش، باید ارزیابی مهندسی، احتمالاً تست سختی و در صورت امکان PWHT مجدد انجام شود و موضوع به‌عنوان NCR ثبت گردد.","key_points":["هدف PWHT: تخلیه تنش پسماند، تمپر شدن ریزساختار سخت، بهبود چقرمگی","اهمیت ویژه در سرویس ترش برای کنترل سختی HAZ","عدم تطابق نمودار با WPS باید بلافاصله به NCR منجر شود","بررسی جهت انحراف (کمتر یا بیشتر از حد مجاز) و پیامد هرکدام","نیاز احتمالی به تست سختی یا PWHT مجدد قبل از پذیرش","عدم پذیرش جوش تا رفع ابهام فنی"],"excellent_answer_indicators":["اشاره به ریسک بیش‌تمپرشدن (over-tempering) در صورت دمای بیش از حد","ذکر لزوم تست سختی پس از PWHT برای تأیید نتیجه","ارتباط دادن موضوع به الزامات سرویس ترش"],"common_mistakes":["پذیرش جوش صرفاً بر اساس وجود چارت بدون بررسی تطابق مقادیر","ندانستن ریسک دمای بیش از حد در کنار دمای کمتر از حد","عدم ثبت NCR در صورت انحراف"],"standard_reference":""},{"category":"TECHNICAL","sub_category":"کنترل مصرفی‌های جوشکاری (الکترود/فیلر)","difficulty":"L1","question_text":"الزامات کنترلی برای نگهداری، توزیع و مصرف الکترودهای کم‌هیدروژن (Low Hydrogen) در سایت پروژه را توضیح دهید و بگویید چرا رعایت این الزامات اهمیت دارد.","reference_answer":"الکترودهای کم‌هیدروژن باید در کوره با دمای مشخص طبق دستور سازنده یا WPS نگهداری شوند تا از جذب رطوبت جلوگیری شود. هنگام توزیع به جوشکار، باید در کوئیورهای گرم قابل حمل نگهداری شده و مدت مواجهه آن‌ها با هوا محدود باشد؛ در صورت عبور از این مدت، نیاز به بازپخت با تعداد دفعات محدود دارند. ردیابی کامل بچ یا شماره ذوب الکترود تا موضع جوش مصرف‌شده باید حفظ شود. عدم رعایت این الزامات باعث افزایش هیدروژن نفوذی و ریسک ترک سرد در HAZ می‌شود که به‌خصوص در فولادهای استحکام بالا و سرویس ترش بسیار حیاتی است.","key_points":["نگهداری در کوره با دمای مشخص طبق دستور سازنده/WPS","استفاده از کوئیور گرم هنگام توزیع به جوشکار با محدودیت زمانی مجاز","محدودیت تعداد دفعات بازپخت (rebake)","ردیابی کامل بچ/شماره ذوب الکترود تا جوش مصرف‌شده","ریسک افزایش هیدروژن نفوذی و ترک سرد در صورت عدم رعایت"],"excellent_answer_indicators":["ذکر تقریبی محدودیت زمان مجاز مواجهه الکترود با هوا (بسته به کلاس آن)","ارتباط با کنترل پیش‌گرم به‌عنوان مکمل کنترل هیدروژن","اشاره به ممیزی دوره‌ای انبار مصرفی‌ها توسط QC"],"common_mistakes":["ندانستن محدودیت زمان مواجهه با هوا پس از خروج از کوره","نادیده گرفتن ردیابی بچ الکترود","تصور اینکه فقط نگهداری اولیه در انبار کافی است"],"standard_reference":""},{"category":"TECHNICAL","sub_category":"آماده‌سازی اتصال، فیت‌آپ، شکاف ریشه و هم‌محوری","difficulty":"L2","question_text":"پیش از تأیید فیت‌آپ یک اتصال جوش لوله برای شروع جوشکاری، چه پارامترهایی را بازرسی می‌کنید و اگر مشاهده کنید اختلاف ضخامت جداره (hi-lo mismatch) بین دو لوله از حد مجاز فراتر رفته چه اقدامی انجام می‌دهید؟","reference_answer":"پیش از تأیید فیت‌آپ، زاویه پخ، root face، شکاف ریشه، تمیزی و عدم آلودگی داخل پخ، هم‌محوری داخلی (hi-lo) و خارجی، کیفیت و پوشش تک‌ولدها طبق WPS و تطبیق جنس و heat لوله‌ها با ایزومتریک بررسی می‌شود. اگر hi-lo mismatch از حد مجاز مشخصات پروژه یا کد فراتر رود، کار نباید ادامه یابد تا اصلاح صورت گیرد، مثلاً از طریق ماشین‌کاری یا سنگ‌زنی داخلی برای نرم کردن گذر بین دو ضخامت، استفاده از قطعه واسط، یا اجرای تکنیک ویژه پاس ریشه در صورت وجود WPS مصوب برای این شرایط. نادیده گرفتن این مغایرت ریسک نفوذ ناقص و تمرکز تنش در ریشه اتصال را به همراه دارد.","key_points":["بررسی زاویه پخ، root face، شکاف ریشه، تمیزی و عدم آلودگی","کنترل هم‌محوری داخلی (hi-lo) و خارجی","بررسی کیفیت و پوشش تک‌ولدها طبق WPS","تطبیق جنس/heat لوله‌ها با ایزومتریک","در صورت hi-lo بیش از حد مجاز، توقف کار تا اصلاح (ماشین‌کاری/سنگ‌زنی یا اتصال واسط)","ریسک نفوذ ناقص و تمرکز تنش در صورت عدم اصلاح"],"excellent_answer_indicators":["ذکر حد مجاز تقریبی hi-lo طبق کد/مشخصات پروژه","پیشنهاد راه‌حل مهندسی عملی (تیک‌بندی خاص یا تکنیک پاس ریشه ویژه)","توجه به تأثیر مستقیم بر کیفیت پاس ریشه و نتیجه RT/UT بعدی"],"common_mistakes":["توجه فقط به شکاف ریشه و نادیده گرفتن hi-lo","پذیرش فیت‌آپ نامناسب با این فرض که جوشکار ماهر جبران می‌کند","عدم توقف کار و اجازه ادامه جوشکاری با وعده اصلاح بعدی"],"standard_reference":"API 1104"},{"category":"TECHNICAL","sub_category":"بازرسی چشمی جوش","difficulty":"L1","question_text":"رویکرد سیستماتیک شما برای بازرسی چشمی یک جوش تکمیل‌شده لوله چیست و به دنبال چه عیوبی می‌گردید؟","reference_answer":"بازرسی چشمی باید در سه مرحله پیش از جوش، حین جوش (بازرسی بین‌پاسی و تمیزی) و پس از اتمام کار انجام شود. در بازرسی نهایی به دنبال عیوبی مانند undercut، overlap، تقعر یا تحدب بیش از حد، تخلخل سطحی، ترک سطحی، پاشش و جرقه قوس هستم و پروفیل و یکنواختی عرض جوش را بررسی می‌کنم. از گیج‌های مناسب مانند weld gauge برای اندازه‌گیری دقیق ابعاد و نور و بزرگنمایی کافی استفاده می‌شود. نتایج باید با معیار پذیرش مصوب پروژه تطبیق داده و مستند شود پیش از آنکه جوش برای NDE یا پوشش‌دهی آزاد شود.","key_points":["بازرسی در سه مرحله: پیش از جوش، حین جوش (بین‌پاسی) و پس از اتمام","بررسی undercut، overlap، تقعر/تحدب بیش از حد، تخلخل سطحی، ترک سطحی، جرقه قوس","استفاده از گیج مناسب (weld gauge) برای اندازه‌گیری دقیق ابعاد","تطبیق یافته‌ها با معیار پذیرش مصوب پروژه","نور و بزرگنمایی کافی برای بازرسی دقیق","ثبت مستند نتایج بازرسی قبل از NDE/پوشش‌دهی"],"excellent_answer_indicators":["اشاره به بازرسی حین‌کار (in-process) نه فقط بازرسی نهایی","ذکر ابزار دقیق اندازه‌گیری و کالیبراسیون آن‌ها","ارتباط دادن یافته بصری با احتمال عیب داخلی"],"common_mistakes":["توجه فقط به بازرسی نهایی و نادیده گرفتن کنترل حین اجرا","عدم استفاده از گیج و تکیه صرف بر مشاهده چشمی","ندانستن معیار کمی پذیرش عیوب سطحی"],"standard_reference":"API 1104"},{"category":"TECHNICAL","sub_category":"انتخاب روش آزمون غیرمخرب (NDE)","difficulty":"L3","question_text":"برای بازرسی جوش‌های ساختمانی محل نصب (field weld) یک تجهیز فرآیندی با دسترسی محدود به یک طرف اتصال، بین RT، UT، MT و PT چگونه روش مناسب را انتخاب و توجیه می‌کنید؟","reference_answer":"انتخاب روش به نوع عیب مورد انتظار (حجمی یا صفحه‌ای/سطحی)، جنس، دسترسی به اتصال، ضخامت و الزام مشخصات فنی پروژه بستگی دارد. RT برای عیوب حجمی مانند تخلخل و سرباره مؤثر است اما معمولاً به دسترسی دوطرفه و محدوده حفاظتی پرتودهی نیاز دارد که در فضای محصور یا شلوغ عملی نیست؛ در مقابل UT، به‌ویژه با تکنیک‌های پیشرفته، برای عیوب صفحه‌ای مانند عدم ذوب یا ترک مناسب است و با دسترسی یک‌طرفه و بدون خطر پرتودهی قابل انجام است. MT برای عیوب سطحی و نزدیک سطح در مواد فرومغناطیس و PT برای مواد غیرمغناطیس یا به‌عنوان مکمل استفاده می‌شود. در هر حال، انتخاب نهایی باید با الزام ITP و مشخصات فنی پروژه مطابقت داشته باشد و هرگونه تغییر روش مصوب نیازمند تأیید کارفرما یا مشاور است.","key_points":["تفکیک عیوب حجمی (RT مناسب) از عیوب سطحی/صفحه‌ای (UT/MT/PT مناسب)","محدودیت دسترسی یک‌طرفه به نفع انتخاب UT به‌جای RT","ملاحظات ایمنی پرتودهی RT در فضای محصور/شلوغ","کاربرد MT برای مواد فرومغناطیس و PT برای مواد غیرمغناطیس یا مکمل","الزام تطابق روش نهایی با ITP/مشخصات فنی پروژه، نه صرفاً ترجیح عملی","نیاز به تأیید کارفرما/مشاور برای هرگونه تغییر روش مصوب"],"excellent_answer_indicators":["اشاره به phased array UT یا TOFD به‌عنوان جایگزین پیشرفته RT در شرایط خاص","توجه هم‌زمان به جنبه فنی و جنبه قراردادی/تأییدیه تغییر روش","ذکر محدودیت‌های ایمنی HSE در انتخاب RT در مناطق پرتردد"],"common_mistakes":["انتخاب روش صرفاً بر اساس سهولت اجرا بدون توجه به نوع عیب هدف","تغییر روش NDE بدون تأیید رسمی کارفرما/مشاور","ندانستن محدودیت دسترسی یک‌طرفه برای RT"],"standard_reference":"API 1104"},{"category":"TECHNICAL","sub_category":"ملاحظات جوشکاری در سرویس ترش (H2S)","difficulty":"L4","question_text":"چه ملاحظات ویژه‌ای در WPS و اجرای جوشکاری برای خطوط لوله در سرویس ترش (Sour Service) نسبت به سرویس معمولی باید در نظر گرفته شود و چرا کنترل سختی جوش در این شرایط حیاتی است؟","reference_answer":"جوشکاری در سرویس ترش نیازمند کنترل دقیق‌تر سختی فلز جوش و HAZ است تا از ترک تنشی سولفیدی (SSC) در محیط H2S جلوگیری شود، که این حد سختی معمولاً طبق NACE MR0175/ISO 15156 و مشخصات پروژه تعریف می‌شود. این موضوع منجر به الزاماتی مانند کنترل دقیق‌تر heat input، الزام غالباً اجباری PWHT حتی در مواردی که برای سرویس شیرین لازم نیست، پیش‌گرم و بین‌پاسی سخت‌گیرانه‌تر، مصرف کانسیومبل کم‌هیدروژن کوالیفای‌شده و اغلب استفاده از فلز پایه با کربن معادل پایین‌تر می‌شود. پس از جوشکاری و PWHT، تست سختی میدانی در چند نقطه روی کپ جوش، HAZ و فلز پایه الزامی است تا انطباق تأیید شود؛ در صورت عبور از حد مجاز، باید NCR ثبت و علت ریشه‌ای پارامترهای جوشکاری یا ترکیب متریال بررسی شود.","key_points":["هدف اصلی: جلوگیری از ترک تنشی سولفیدی (SSC) در محیط H2S","محدودیت سختی حداکثر روی فلز جوش و HAZ طبق NACE MR0175/ISO 15156 و مشخصات پروژه","الزام غالباً اجباری PWHT حتی در مواردی که برای سرویس شیرین لازم نیست","کنترل دقیق‌تر heat input و پیش‌گرم/بین‌پاسی","الزام تست سختی میدانی پس از جوش/PWHT در چند نقطه","در صورت عبور از حد سختی، ثبت NCR و بررسی علت ریشه‌ای"],"excellent_answer_indicators":["ذکر مقدار تقریبی حد سختی رایج (حدود ۲۲ HRC برای فولاد کربنی) با تأکید بر نیاز به تأیید مقدار دقیق از مشخصات پروژه","اشاره به کنترل ترکیب شیمیایی/کربن معادل فلز پایه و پرکننده","تجربه عملی از رد جوش به دلیل عبور از حد سختی در سرویس ترش"],"common_mistakes":["عدم تفکیک الزامات سرویس ترش از سرویس معمولی","ندانستن ضرورت تست سختی میدانی","نام بردن استاندارد بدون درک مکانیزم SSC"],"standard_reference":"NACE MR0175 / ISO 15156"},{"category":"SCENARIO","sub_category":"تشخیص علت رد جوش و تصمیم تعمیر یا برش","difficulty":"L3","question_text":"نتیجه RT یک جوش دورانی خط لوله نشان‌دهنده یک عیب خطی به طول ۲۵ میلی‌متر در ریشه است که به نظر می‌رسد Lack of Fusion باشد. به‌عنوان ناظر جوش چگونه تصمیم می‌گیرید که این جوش باید کاملاً برش و جوش مجدد شود یا امکان تعمیر موضعی وجود دارد؟","reference_answer":"ابتدا نوع، موقعیت دقیق و عمق عیب باید از تفسیر فیلم RT و در صورت لزوم با UT تکمیلی تأیید شود، زیرا RT به‌تنهایی برای اندازه‌گیری دقیق عمق عیوب صفحه‌ای کافی نیست. سپس معیار پذیرش مصوب پروژه بررسی می‌شود؛ Lack of Fusion معمولاً یک عیب صفحه‌ای مردود است و برخلاف تخلخل، بر اساس طول به‌تنهایی پذیرفته نمی‌شود. امکان تعمیر موضعی طبق WPS تعمیر مصوب و محدودیت طول/عمق مجاز آن ارزیابی می‌شود، اما در صورتی که عدم ذوب در ریشه گسترده یا در موضع تکراری باشد، این می‌تواند نشانه مشکل سیستمی فیت‌آپ یا تکنیک جوشکاری باشد که برش کامل را ترجیح می‌دهد. سابقه تعمیرهای قبلی همان اتصال نیز باید بررسی شود زیرا اغلب مشخصات پروژه سقفی برای تعداد دفعات مجاز تعمیر دارند. تصمیم نهایی باید در قالب NCR با توجیه فنی مستند شود.","key_points":["تأیید دقیق نوع، موقعیت و عمق عیب (احتمالاً تکمیل با UT) قبل از تصمیم‌گیری","بررسی معیار پذیرش مصوب پروژه برای عیوب صفحه‌ای مانند Lack of Fusion","ارزیابی امکان تعمیر موضعی طبق WPS تعمیر مصوب و محدودیت طول/عمق مجاز","بررسی سابقه تعمیر قبلی همان اتصال و محدودیت تعداد دفعات مجاز تعمیر","توجه به احتمال مشکل سیستمی (فیت‌آپ/تکنیک) در صورت تکرار در همان موضع","مستندسازی تصمیم نهایی از طریق NCR با توجیه فنی"],"excellent_answer_indicators":["تفکیک روشن بین عیوب حجمی و صفحه‌ای در تصمیم تعمیر","اشاره به محدودیت تعداد دفعات تعمیر مجاز و ریسک تجمع تنش پسماند از تعمیرهای مکرر","پیوند دادن یافته به بررسی ریشه‌ای فرآیند (پارامتر جوشکاری یا فیت‌آپ)"],"common_mistakes":["تصمیم‌گیری صرفاً بر اساس طول عیب بدون توجه به نوع آن","نادیده گرفتن سابقه تعمیر قبلی همان جوش","اجازه تعمیر نامحدود بدون سقف تعداد دفعات"],"standard_reference":"API 1104"},{"category":"PROBLEM_SOLVING","sub_category":"تحلیل روند افزایش نرخ تعمیر جوش","difficulty":"L4","question_text":"طی دو هفته گذشته، نرخ رد جوش (repair rate) در بخشی از پروژه از حدود ۵٪ به بیش از ۲۰٪ افزایش یافته است. به‌عنوان ناظر جوش چگونه ریشه این افزایش را بررسی می‌کنید و چه اقداماتی پیشنهاد می‌دهید؟","reference_answer":"ابتدا داده‌های رد جوش را بر اساس جوشکار، نوع اتصال یا WPS، شیفت کاری، بچ مصرفی الکترود و نوع عیب (مثلاً تخلخل در برابر عدم ذوب یا ترک) تفکیک می‌کنم تا مشخص شود مشکل مربوط به جوشکار خاص، رویه/کانسیومبل یا عوامل محیطی است. سپس تغییرات اخیر مانند ورود عرشه جوشکار جدید، تغییر بچ کانسیومبل، بازنگری WPS، تغییر تأمین‌کننده متریال یا شرایط آب‌وهوایی بررسی می‌شود و با جوشکاران و تیم QC میدانی گفتگو می‌شود تا سرنخ‌های عملی به دست آید. بر اساس علت شناسایی‌شده، اقدام هدفمند مانند بازآموزی یا ری‌کوالیفای جوشکار، ممیزی انبار و شرایط نگهداری کانسیومبل، یا بازنگری فیت‌آپ صورت می‌گیرد. تا بازگشت نرخ به سطح پایه، فراوانی بازرسی و نقاط توقف موقتاً افزایش می‌یابد و یافته‌ها به مدیریت پروژه گزارش می‌شود.","key_points":["تفکیک داده رد جوش بر اساس جوشکار، نوع اتصال/WPS، شیفت، بچ الکترود و نوع عیب","بررسی تغییرات اخیر: عرشه جوشکار جدید، تغییر بچ کانسیومبل، بازنگری WPS، شرایط آب‌وهوایی","مصاحبه با جوشکاران و تیم QC میدانی برای سرنخ عملی","اقدام هدفمند بر اساس علت شناسایی‌شده (بازآموزی/ری‌کوالیفای جوشکار، ممیزی انبار کانسیومبل، بازنگری فیت‌آپ)","افزایش موقت فراوانی بازرسی و نقاط توقف تا بازگشت نرخ به سطح پایه","گزارش‌دهی رسمی روند و اقدام اصلاحی به مدیریت پروژه"],"excellent_answer_indicators":["رویکرد داده‌محور با تفکیک چندبعدی به‌جای حدس کلی","طرح فرضیه‌های متعدد و آزمون سیستماتیک هرکدام","ذکر معیار کمی برای اعلام بازگشت به وضعیت عادی و پایان نظارت تشدیدشده"],"common_mistakes":["نسبت دادن فوری مشکل به یک جوشکار خاص بدون بررسی داده","نادیده گرفتن عوامل محیطی یا تغییر کانسیومبل","عدم گزارش‌دهی رسمی و صرفاً افزایش بازرسی بدون تحلیل ریشه‌ای"],"standard_reference":""},{"category":"SCENARIO","sub_category":"عدم تطابق طراحی/WPS در میدان","difficulty":"L4","question_text":"هنگام بازرسی یک اتصال Tie-in متوجه می‌شوید که ضخامت واقعی لوله نصب‌شده در سایت با ضخامتی که WPS مصوب برای آن رده تعریف کرده مطابقت ندارد (لوله ضخیم‌تر از محدوده کوالیفای‌شده PQR است). چه تصمیمی می‌گیرید و چه مراحلی را طی می‌کنید؟","reference_answer":"بلافاصله جوشکاری روی آن اتصال متوقف می‌شود، زیرا جوشکاری خارج از محدوده ضخامت کوالیفای‌شده WPS/PQR مجاز نیست و منجر به تولید جوشی غیر کوالیفای می‌شود. ضخامت واقعی لوله در برابر ایزومتریک و گواهی متریال راستی‌آزمایی می‌شود تا از واقعی بودن مغایرت اطمینان حاصل شود، نه صرفاً خطای مستندسازی. مهندسی طراحی و QA/QC مطلع می‌شوند تا علت ریشه‌ای مغایرت مانند ارسال متریال اشتباه، ایزومتریک قدیمی یا عدم پوشش واقعی محدوده WPS بررسی شود. سپس یا WPS/PQR جدید یا با محدوده گسترش‌یافته درخواست می‌شود یا در صورت وجود، از WPS کوالیفای دیگری استفاده می‌شود و پیش از از سرگیری کار، تأیید کارفرما/مشاور اخذ می‌گردد. موضوع به‌عنوان NCR ثبت شده و سایر اتصالات Tie-in مشابه نیز برای همین ریسک بررسی می‌شوند.","key_points":["توقف فوری جوشکاری روی اتصال با ضخامت خارج از محدوده کوالیفای WPS/PQR","راستی‌آزمایی ضخامت واقعی لوله در برابر ایزومتریک و گواهی متریال","اطلاع‌رسانی به مهندسی طراحی/QA برای ریشه‌یابی مغایرت (متریال اشتباه، نقشه قدیمی، یا WPS ناقص)","درخواست WPS/PQR جدید یا گسترش محدوده کوالیفیکیشن قبل از ادامه کار","تأیید کارفرما/مشاور قبل از از سرگیری جوشکاری","ثبت NCR و بررسی سایر اتصالات مشابه برای همان ریسک سیستمی"],"excellent_answer_indicators":["رویکرد سیستمی: بررسی سایر Tie-inها برای جلوگیری از تکرار مشکل مشابه","تفکیک دقیق بین خطای مستندسازی و خطای واقعی متریال","تأکید بر عدم شروع مجدد بدون WPS معتبر برای ضخامت واقعی"],"common_mistakes":["ادامه جوشکاری با این فرض که تفاوت جزئی است","عدم اطلاع به مهندسی طراحی و حل مشکل صرفاً در سطح میدانی","نادیده گرفتن احتمال تکرار مشکل در سایر اتصالات مشابه"],"standard_reference":"API 1104"},{"category":"SCENARIO","sub_category":"فشار پیمانکار برای رد نقطه توقف / NCR فیت‌آپ","difficulty":"L3","question_text":"پیمانکار برای جبران تأخیر برنامه‌ای، از شما می‌خواهد که پیش از بازرسی فیت‌آپ (Hold Point) اجازه شروع پاس ریشه را بدهید و بازرسی را «بعداً به‌صورت مستندسازی» انجام دهید. چه پاسخی می‌دهید؟","reference_answer":"این درخواست قاطعانه رد می‌شود، زیرا بازرسی فیت‌آپ پیش از پاس ریشه دقیقاً به این دلیل نقطه توقف الزامی است که پارامترهای حیاتی مانند شکاف ریشه، هم‌محوری، تمیزی و hi-lo پس از شروع جوشکاری قابل راستی‌آزمایی یا اصلاح نیستند و مستندسازی گذشته‌نگر بازتاب واقعیت پیش از جوش نخواهد بود و در حقیقت مصداق جعل مستندات بازرسی است. رد شدن از این نقطه توقف ریسک عیوب ریشه غیرقابل جبران یا پرهزینه را به همراه دارد و اعتبار کل سوابق کیفی پروژه را زیر سؤال می‌برد. به‌جای حذف بازرسی، پیشنهاد می‌شود بازرسی فیت‌آپ با اولویت و سرعت بیشتر انجام شود تا تأخیر به حداقل برسد، و در صورت تداوم فشار، موضوع کتباً به مدیریت پروژه اطلاع داده می‌شود.","key_points":["امتناع قطعی از تأیید بازرسی فیت‌آپ به‌صورت گذشته‌نگر","توضیح این‌که پارامترهای فیت‌آپ پس از شروع جوش قابل راستی‌آزمایی نیستند","تأکید بر این‌که این کار مصداق جعل مستندات بازرسی است","ریسک عیوب غیرقابل جبران در ریشه در صورت عدم بازرسی به‌موقع","ارائه راهکار جایگزین: تسریع بازرسی به‌جای حذف آن","مستندسازی و اطلاع‌رسانی در صورت تداوم فشار پیمانکار"],"excellent_answer_indicators":["اشاره صریح به مفهوم جعل مستندات و پیامد حرفه‌ای/قانونی آن","ارائه راه‌حل عملی برای کاهش تأخیر بدون قربانی کردن کیفیت","تجربه یا مثال واقعی از مواجهه مشابه"],"common_mistakes":["پذیرش درخواست به بهانه حفظ روابط کاری یا برنامه زمانی","امضای مستندات بازرسی برای رویدادی که واقعاً مشاهده نشده","عدم گزارش موضوع به سطح بالاتر"],"standard_reference":""},{"category":"PROBLEM_SOLVING","sub_category":"تناقض نتایج NDE در جوش Tie-in","difficulty":"L4","question_text":"در یک جوش حیاتی Tie-in زیرزمینی، نتیجه UT وجود یک عیب احتمالی در ناحیه ریشه را نشان می‌دهد، اما فیلم RT گرفته‌شده از همان موضع، عیب قابل توجهی نشان نمی‌دهد. با این تناقض چگونه برخورد می‌کنید و تصمیم نهایی چگونه اتخاذ می‌شود؟","reference_answer":"نتیجه مطلوب‌تر یعنی RT سالم را بدون بررسی دلیل تناقض نمی‌پذیرم، زیرا UT و RT حساسیت متفاوتی دارند؛ UT معمولاً برای عیوب صفحه‌ای مانند عدم ذوب یا ترک در ریشه حساس‌تر است، در حالی که RT ممکن است عیوب صفحه‌ای با جهت‌گیری نامناسب نسبت به پرتو را نشان ندهد. درخواست می‌کنم یک تکنسین ارشد UT مستقل مجدداً اسکن کند و فیلم RT نیز دوباره برای احتمال عیب مغفول یا هندسه نامناسب مرور شود. در صورت تداوم ابهام، از روش تکمیلی مانند Phased Array یا TOFD استفاده می‌شود یا موضوع برای بررسی فنی مشترک به کارفرما، مشاور و متخصص NDE ارجاع می‌گردد. با توجه به هزینه بسیار بالای خرابی بعد از خاکریزی در یک اتصال حیاتی مدفون، رویکرد محافظه‌کارانه اتخاذ شده و اتصال تا رفع کامل ابهام برای خاکریزی آزاد نمی‌شود.","key_points":["عدم پذیرش خودکار نتیجه مطلوب‌تر (RT) بدون بررسی دلیل تناقض","درک تفاوت حساسیت UT و RT برای عیوب صفحه‌ای در ریشه","درخواست بازبینی مستقل توسط تکنسین ارشد UT و مرور مجدد فیلم RT","استفاده از روش تکمیلی (مثل Phased Array/TOFD) در صورت تداوم ابهام","ارجاع به بررسی فنی مشترک با کارفرما/مشاور/متخصص NDE پیش از پذیرش","رویکرد محافظه‌کارانه به دلیل هزینه بسیار بالای خرابی بعد از خاکریزی"],"excellent_answer_indicators":["تحلیل فنی دقیق از تفاوت مکانیزم تشخیص UT و RT برای عیوب صفحه‌ای در برابر حجمی","تأکید بر منطق ریسک-هزینه ویژه اتصالات مدفون و حیاتی","پیشنهاد مشخص روش تکمیلی برای رفع ابهام به‌جای حدس"],"common_mistakes":["پذیرش جوش صرفاً چون RT ظاهراً تمیز است","ندانستن تفاوت حساسیت دو روش برای عیوب صفحه‌ای","تصمیم‌گیری بدون مشورت فنی یا روش تکمیلی"],"standard_reference":"API 1104"},{"category":"EXPERIENCE_BASED","sub_category":"تجربه واقعی مدیریت NCR جوش","difficulty":"L3","question_text":"بزرگ‌ترین یا پیچیده‌ترین NCR مرتبط با جوش که در طول تجربه کاری خود با آن مواجه شده‌اید را شرح دهید: چه اتفاقی افتاد، چگونه تشخیص دادید، چه تصمیمی گرفتید و نتیجه نهایی چه بود؟","reference_answer":"این سؤال باز است و باید بر اساس صحت و عمق تجربه واقعی، نه یک داستان از پیش تعیین‌شده، ارزیابی شود. پاسخ قوی شامل شرح مشخص از پروژه، نوع و گستره عیب واقعی، روش تشخیص علت ریشه‌ای (کدام NDE یا تحلیل به کار رفته)، تصمیم disposition اتخاذشده با توجیه فنی مبتنی بر مشخصات یا استاندارد، اقدامات اصلاحی و پیشگیرانه واقعی پیاده‌سازی‌شده، و نتیجه نهایی ملموس یا قابل اندازه‌گیری همراه با درس آموخته است.","key_points":["شرح مشخص و واقعی از پروژه، نوع عیب و گستره آن","روش تشخیص علت ریشه‌ای (کدام NDE/تحلیل به کار رفت)","تصمیم disposition اتخاذشده و توجیه فنی آن بر مبنای مشخصات/استاندارد","اقدامات اصلاحی و پیشگیرانه واقعی که پیاده‌سازی شد","نتیجه نهایی ملموس یا قابل اندازه‌گیری","درس آموخته‌ای که در پروژه‌های بعدی به کار گرفته شد"],"excellent_answer_indicators":["جزئیات فنی دقیق و قابل راستی‌آزمایی (اعداد، نام استاندارد، نوع عیب واقعی)","نشان دادن نقش فعال و تصمیم‌گیری مستقل، نه صرفاً اجرای دستور دیگران","تفکر سیستمی: تبدیل یک مورد به بهبود فرآیندی گسترده‌تر","بیان واضح نتیجه کمی (مثلاً کاهش نرخ تکرار از یک عدد به عدد دیگر)"],"common_mistakes":["پاسخ کلی و غیرقابل تشخیص از دانش تئوری بدون جزئیات واقعی","عدم ذکر نتیجه نهایی یا پیگیری بعد از رفع مشکل","نسبت دادن تمام تصمیم‌گیری به دیگران بدون نقش شخصی مشخص"],"standard_reference":""},{"category":"EXPERIENCE_BASED","sub_category":"تجربه کشف نقص در WPS/PQR","difficulty":"L3","question_text":"تجربه‌ای را شرح دهید که در آن هنگام بازبینی WPS یا PQR ارائه‌شده توسط پیمانکار، یک نقص یا مغایرت فنی کشف کردید. چگونه متوجه شدید و چه اتفاقی افتاد؟","reference_answer":"این سؤال باز است و باید بر اساس این ارزیابی شود که آیا فرد واقعاً تجربه دست‌اول در بازبینی دقیق اسناد WPS/PQR دارد. پاسخ قوی نوع مشخص نقص کشف‌شده مانند heat input خارج از محدوده کوالیفای، فقدان یک متغیر اساسی، عدم تطابق ضخامت نمونه تست PQR با تولید واقعی یا کلاس نادرست فلز پرکننده را نام می‌برد، روش دقیق تشخیص یعنی تطبیق سیستماتیک با جدول کد یا مشخصات پروژه را توضیح می‌دهد، مسیر حل مانند رد WPS و درخواست PQR جدید یا ارجاع به مهندس جوش پیمانکار را شرح می‌دهد و نتیجه نهایی و تأثیر آن بر پیشگیری از مشکل بزرگ‌تر را بیان می‌کند.","key_points":["نوع مشخص نقص کشف‌شده در WPS/PQR (نمونه واقعی، نه کلی)","روش دقیق تشخیص (تطبیق سیستماتیک با جدول کد/مشخصات، نه حدس)","نحوه تعامل با پیمانکار/مهندس جوش برای اصلاح","مسیر حل نهایی: رد WPS، درخواست PQR جدید یا اصلاح","اثر این کشف بر جلوگیری از مشکل بزرگ‌تر در تولید"],"excellent_answer_indicators":["ذکر essential variable دقیق که اشتباه بود","نشان دادن این‌که کشف زودهنگام از هزینه بازکاری گسترده جلوگیری کرد","تسلط بر اصطلاحات فنی دقیق کد مرجع"],"common_mistakes":["پاسخ مبهم بدون ذکر نوع مشخص نقص","عدم توضیح روش تشخیص و صرفاً ادعای کشف مشکل","نداشتن تجربه واقعی و ارائه پاسخ تئوریک صرف"],"standard_reference":""},{"category":"EXPERIENCE_BASED","sub_category":"تجربه مدیریت عملکرد ضعیف جوشکار","difficulty":"L2","question_text":"تجربه‌ای از مواجهه با جوشکاری که به‌طور مکرر جوش‌های مردودی تولید می‌کرد را شرح دهید: چگونه با موضوع برخورد کردید و نتیجه چه شد؟","reference_answer":"این سؤال باز است و باید بر اساس نحوه واقعی برخورد با موضوع افراد و فرآیند ارزیابی شود. پاسخ خوب شرح می‌دهد که چگونه رد جوش‌های تکراری ردیابی و به یک جوشکار مشخص نسبت داده شد، علت ریشه‌ای مانند مهارت ناکافی، عدم آشنایی با WPS، خستگی یا مشکل تجهیزات بررسی شد، چه اقدام اصلاحی مشخصی مانند بازآموزی، نظارت بیشتر، ری‌کوالیفیکیشن یا در موارد پایدار جابه‌جایی/حذف از تیم انجام شد، چگونه موضوع طبق فرآیند رسمی پروژه مستند گردید و نتیجه قابل اندازه‌گیری پس از اقدام چه بود.","key_points":["روش ردیابی و اسناد رد جوش به جوشکار مشخص","بررسی علت ریشه‌ای (مهارت، آشنایی با WPS، خستگی، تجهیزات)","اقدام اصلاحی مشخص انجام‌شده (بازآموزی، نظارت بیشتر، ری‌کوالیفیکیشن)","مستندسازی موضوع طبق فرآیند رسمی پروژه","نتیجه قابل اندازه‌گیری پس از اقدام"],"excellent_answer_indicators":["برخورد منصفانه و مبتنی بر داده به‌جای قضاوت شخصی","ذکر عدد یا شاخص مشخص بهبود (کاهش نرخ رد جوش)","توجه هم‌زمان به جنبه انسانی (آموزش) و جنبه فرآیندی (کنترل کیفیت)"],"common_mistakes":["پاسخ صرفاً به معنای اخراج/تنبیه بدون تحلیل علت","عدم مستندسازی رسمی موضوع","نداشتن معیار روشن برای سنجش بهبود"],"standard_reference":""},{"category":"EXPERIENCE_BASED","sub_category":"تجربه دفاع از تصمیم فنی تحت فشار زمانی/مدیریتی","difficulty":"L4","question_text":"تجربه‌ای را شرح دهید که در آن تحت فشار شدید مدیریت پروژه یا پیمانکار برای تسریع کار قرار گرفتید ولی همچنان بر رد یک جوش یا توقف کار پافشاری کردید. چگونه از تصمیم خود دفاع کردید و نتیجه چه بود؟","reference_answer":"این سؤال باز و در سطح ارشد است و بر اساس صداقت حرفه‌ای و شجاعت فنی تحت فشار ارزیابی می‌شود. پاسخ قوی مبنای فنی مشخص تصمیم رد یا توقف کار، منبع و شدت واقعی فشار وارده، اقدامات مستند برای دفاع از تصمیم مانند استناد به مشخصات/کد، مکاتبه رسمی یا درگیر کردن کارفرما و مشاور، نحوه حل نهایی موضوع و نتیجه عملی آن، و بازتاب و درس آموخته از این تجربه را شرح می‌دهد.","key_points":["مبنای فنی مشخص تصمیم رد/توقف کار","شرح واقعی منبع و شدت فشار وارده","اقدام مستند برای دفاع از تصمیم (استناد به مشخصات/کد، مکاتبه رسمی، درگیر کردن کارفرما/مشاور)","نحوه حل نهایی موضوع و نتیجه عملی آن","بازتاب و درس آموخته از این تجربه"],"excellent_answer_indicators":["نشان دادن پافشاری مبتنی بر مستندات، نه صرفاً لجاجت شخصی","توانایی مدیریت رابطه حرفه‌ای حتی پس از تعارض","اثبات درستی تصمیم با پیامد بعدی مشهود"],"common_mistakes":["پاسخ کلی بدون مثال واقعی و مشخص","روایتی که در آن تصمیم فنی نهایتاً زیر فشار تغییر کرد بدون توجیه فنی","عدم ذکر نتیجه یا پیامد نهایی ماجرا"],"standard_reference":""}]'::jsonb) as x(
  category text, sub_category text, difficulty text, question_text text, reference_answer text,
  key_points jsonb, excellent_answer_indicators jsonb, common_mistakes jsonb, standard_reference text
)
where not exists (select 1 from comp_question_bank where job_role = 'welding_inspector');

-- ---- mechanical_piping_inspector (23 questions) ----
insert into comp_question_bank (job_role, category, sub_category, difficulty, question_text, reference_answer, key_points, excellent_answer_indicators, common_mistakes, standard_reference)
select 'mechanical_piping_inspector', x.category, x.sub_category, x.difficulty, x.question_text, x.reference_answer,
       coalesce(x.key_points, '[]'::jsonb), coalesce(x.excellent_answer_indicators, '[]'::jsonb), coalesce(x.common_mistakes, '[]'::jsonb), coalesce(x.standard_reference, '')
from jsonb_to_recordset('[{"category":"GENERAL","sub_category":"نقش و مسئولیت‌های ناظر در چرخه پروژه","difficulty":"L1","question_text":"به عنوان ناظر مکانیکال و پایپینگ در یک پروژه EPC خط لوله انتقال گاز، نقش و مسئولیت‌های اصلی شما در مراحل مختلف پروژه (از نصب تا تحویل موقت) را توضیح دهید و بگویید مرز مسئولیت شما با تیم QC/QA و مهندسی طراحی کجاست؟","reference_answer":"ناظر مکانیکال و پایپینگ مسئول تطبیق اجرای فیزیکی نصب لوله‌کشی، تجهیزات ثابت و دوار، اتصالات، ساپورت‌ها و آزمایش‌های مکانیکی با نقشه‌های تاییدشده (ایزومتریک، P&ID، جنرال آرنجمنت)، مشخصات فنی پروژه و استانداردهای مرجع است. این نقش از بازرسی مواد ورودی و کنترل کیفیت نصب در حین اجرا شروع می‌شود و تا هیدروتست، پیش‌راه‌اندازی، تکمیل مکانیکال و تحویل پانچ‌لیست ادامه می‌یابد. مرز با تیم QC/QA این است که QC معمولاً بازرسی‌های روزمره و مستندسازی چک‌لیست‌ها را انجام می‌دهد و ناظر تصمیم‌گیرنده فنی درباره پذیرش/عدم پذیرش کار در نقاط بازرسی (Hold/Witness Point) است، در حالی که مهندسی طراحی مسئول صدور و تفسیر نهایی نقشه‌ها و مشخصات فنی است و ناظر باید ابهامات طراحی را از طریق RFI به آن‌ها ارجاع دهد نه اینکه خودسرانه تصمیم بگیرد.","key_points":["تطبیق اجرا با نقشه‌های تاییدشده و مشخصات فنی","حضور در Hold/Witness Point ها طبق ITP","ارتباط با QC برای مستندسازی و با مهندسی برای RFI","مسئولیت تا مرحله تکمیل مکانیکال و تحویل به کمیسیونینگ","عدم تصمیم‌گیری خودسرانه در ابهامات طراحی"],"excellent_answer_indicators":["اشاره به چرخه کامل پروژه از MTO تا Punch List","تمایز دقیق نقش تاییدکننده کیفیت در مقابل تاییدکننده فنی طراحی","اشاره به مستندسازی و Traceability تصمیمات","تسلط به جریان RFI/NCR/MOC"],"common_mistakes":["محدود کردن نقش فقط به بازرسی ظاهری","عدم تمایز بین وظیفه ناظر و QC","نادیده گرفتن ارتباط با مهندسی در ابهامات فنی"],"standard_reference":""},{"category":"GENERAL","sub_category":"مدیریت مستندات و Dossier","difficulty":"L2","question_text":"فرض کنید در پایان یک بسته کاری (مثلاً یک خط لوله)، پیمانکار داسیه نهایی (Mechanical Completion Dossier) را برای تایید ارائه می‌دهد اما متوجه می‌شوید چند مورد از رکوردهای بازرسی حین کار (مانند گزارش بازرسی جوش یا چک‌لیست نصب ساپورت) در آن مفقود است. چگونه برخورد می‌کنید؟","reference_answer":"در گام اول داسیه را بر اساس چک‌لیست ITP تایید شده پروژه به طور کامل ممیزی می‌کنم تا مشخص شود کدام رکوردها واقعاً مفقودند و کدام صرفاً بد بایگانی شده‌اند. سپس داسیه را رد (Reject) کرده و به صورت مکتوب (Document Transmittal یا کامنت رسمی) کمبودها را به پیمانکار اعلام می‌کنم و مهلت جبران تعیین می‌شود. اگر رکورد بازرسی حین کار (مانند بازرسی ساپورت قبل از عایق‌کاری) واقعاً هرگز انجام نشده و امکان بازرسی مجدد بدون تخریب وجود ندارد، موضوع باید به عنوان یک انحراف مستند (NCR یا Concession Request) ثبت و به کارفرما/مشاور جهت تصمیم‌گیری مهندسی ارجاع شود، نه اینکه به سادگی نادیده گرفته شود. هرگز نباید داسیه ناقص را صرفاً برای رعایت زمان‌بندی امضا و تایید کرد.","key_points":["ممیزی داسیه بر مبنای ITP مصوب","رد رسمی و مکتوب داسیه ناقص","تفکیک بین کمبود بایگانی و عدم انجام واقعی بازرسی","ثبت NCR/Concession برای بازرسی‌های Hold Point انجام‌نشده","عدم تایید تحت فشار زمان‌بندی"],"excellent_answer_indicators":["اشاره به ریسک ایمنی/کیفیت پنهان پشت رکورد مفقود (مثلاً پوشش‌شده بودن ساپورت با عایق)","پیشنهاد اقدام جایگزین مانند بازرسی غیرمخرب در صورت امکان","تاکید بر Traceability برای ممیزی‌های آتی و بیمه/گارانتی","آشنایی با فرآیند Concession/Waiver"],"common_mistakes":["تایید داسیه با وعده تکمیل بعدی مدارک","ندیدن تفاوت بین مشکل بایگانی و مشکل واقعی کیفیت","عدم مستندسازی مکتوب رد داسیه"],"standard_reference":""},{"category":"GENERAL","sub_category":"مدیریت NCR","difficulty":"L2","question_text":"در بازرسی یک بسته لوله‌کشی متوجه می‌شوید که فاصله ساپورت‌ها (Support Spacing) در چند نقطه بیش از حد مجاز نقشه است و لوله در حال حاضر رنگ‌آمیزی و عایق‌کاری هم شده. فرآیندی که برای مدیریت این عدم انطباق طی می‌کنید را شرح دهید.","reference_answer":"ابتدا انحراف را با اندازه‌گیری دقیق مستند و با نقشه ساپورت تاییدشده و مشخصات فنی پروژه مقایسه می‌کنم تا میزان و محل دقیق انحراف مشخص شود. سپس یک NCR رسمی صادر کرده و آن را با جزئیات (شرح انحراف، مدرک مرجع، عکس) برای بررسی به QC/مهندسی و در صورت نیاز به کارفرما/مشاور ارسال می‌کنم؛ در این مرحله کار نباید بدون تصمیم‌گیری رسمی ادامه یابد (Stop/Hold در محدوده مرتبط). تصمیم نهایی (اصلاح، پذیرش مشروط با محاسبه تنش مجدد، یا رد) باید توسط مهندسی طراحی صادر شود، چون افزایش فاصله ساپورت می‌تواند بر تحلیل تنش پایپینگ (Stress Analysis) اثر بگذارد. در نهایت اقدام اصلاحی (Corrective Action) انجام و اقدام پیشگیرانه (مثلاً بازرسی سیستماتیک ساپورت‌های مشابه در بسته‌های دیگر) برای جلوگیری از تکرار تعریف می‌شود.","key_points":["مستندسازی دقیق انحراف با مرجع نقشه/اسپک","صدور NCR رسمی قبل از ادامه کار در ناحیه مرتبط","ارجاع تصمیم فنی به مهندسی به دلیل اثر بر تحلیل تنش","پیگیری اقدام اصلاحی و پیشگیرانه","بررسی گسترش مشکل به بسته‌های مشابه دیگر"],"excellent_answer_indicators":["اشاره صریح به ارتباط فاصله ساپورت با Stress Analysis و ریسک ارتعاش/افت","پیشنهاد بازرسی سیستماتیک سایر بسته‌ها (Extent of Condition)","تسلط به چرخه کامل NCR شامل بستن (Close-out) و اثبات اثربخشی اقدام اصلاحی","توجه به اینکه عایق‌کاری/رنگ نباید مانع اصلاح شود"],"common_mistakes":["نادیده گرفتن انحراف چون لوله ظاهراً خوب کار می‌کند","تصمیم‌گیری شخصی برای پذیرش بدون ارجاع به مهندسی","عدم بررسی سایر نقاط مشابه در پروژه"],"standard_reference":""},{"category":"GENERAL","sub_category":"تعادل کیفیت و زمان‌بندی","difficulty":"L4","question_text":"نزدیک به تاریخ نهایی تکمیل مکانیکال (Mechanical Completion) هستید و مدیر پروژه فشار می‌آورد که برای رعایت زمان‌بندی، هیدروتست چند خط را با پانچ‌لیست باز (نصب ناقص ساپورت‌های موقت) انجام دهید و بعداً اصلاح کنید. به عنوان ناظر چه تصمیمی می‌گیرید و چرا؟","reference_answer":"تصمیم نهایی درباره اینکه چه مواردی می‌توانند به عنوان پانچ لیست B (غیربحرانی) باز بمانند و چه مواردی باید پیش از هیدروتست بسته شوند باید بر اساس معیار ایمنی و صحت تست باشد، نه صرفاً فشار زمان‌بندی. اگر ساپورت‌های موقت یا دائم نصب‌نشده بر توزیع بار خط لوله در حین پر شدن با آب (که وزن قابل توجهی اضافه می‌کند) اثر بگذارند یا ریسک آسیب به تجهیزات/شکست موضعی ایجاد کنند، این مورد باید Punch A (بحرانی) تلقی شده و پیش از تست رفع شود. من موضوع را با ذکر ریسک فنی و مرجع مشخصات پروژه به صورت مکتوب به مدیریت پروژه و مشاور/کارفرما اعلام می‌کنم و اگر اصرار بر ادامه بدون رفع مورد بحرانی وجود داشت، تایید کتبی ریسک‌پذیری را از سطح بالاتر (کارفرما/مشاور) درخواست می‌کنم، چون مسئولیت ایمنی و کیفیت تست را نمی‌توان صرفاً برای برنامه زمانی نادیده گرفت. هرگز به صورت شفاهی یا بدون مستندسازی چنین ریسکی را نمی‌پذیرم.","key_points":["تفکیک پانچ لیست بحرانی (A) از غیربحرانی (B) بر مبنای ریسک ایمنی/فنی","ارزیابی اثر ساپورت ناقص بر وزن آب هنگام هیدروتست","مستندسازی مکتوب نگرانی فنی به مدیریت و کارفرما/مشاور","عدم پذیرش ریسک بحرانی صرفاً بابت فشار زمان‌بندی","درخواست تایید کتبی از مرجع بالاتر در صورت اصرار"],"excellent_answer_indicators":["مثال عینی از عواقب احتمالی (افتادگی لوله، آسیب به فلنج/جوش زیر بار آب)","تسلط به مفهوم Punch List A/B/C و معیار دسته‌بندی","نشان دادن مهارت مذاکره فنی به‌جای رویارویی صرف","تاکید بر مستندسازی تصمیم برای محافظت حرفه‌ای خود و پروژه"],"common_mistakes":["پذیرش بی‌قید و شرط درخواست مدیر پروژه","مقاومت بدون ارائه استدلال فنی مستند","عدم تفکیک پانچ بحرانی از غیربحرانی"],"standard_reference":""},{"category":"GENERAL","sub_category":"مدیریت اینترفیس و Escalation","difficulty":"L2","question_text":"در پروژه‌ای که نصب یک اسکید تجهیزات دوار به دلیل تاخیر در تحویل فونداسیون توسط پیمانکار سیویل عقب افتاده و این تاخیر به طور مستقیم زمان‌بندی تست‌های مکانیکال شما را تحت تاثیر قرار داده، چگونه این موضوع اینترفیسی را مدیریت می‌کنید؟","reference_answer":"ابتدا وضعیت را با اندازه‌گیری دقیق پیشرفت فونداسیون و مقایسه با تاریخ نیاز واقعی (Need Date) در برنامه زمان‌بندی یکپارچه مستند می‌کنم و تاثیر آن بر مسیر بحرانی (Critical Path) فعالیت‌های مکانیکال را مشخص می‌کنم. سپس موضوع را از طریق کانال رسمی اینترفیس پروژه (مثلاً Interface Register یا جلسات هماهنگی بین‌رشته‌ای) به تیم برنامه‌ریزی و مدیریت پروژه اطلاع می‌دهم تا هماهنگی لازم بین پیمانکار سیویل و مکانیکال صورت گیرد. در کنار آن، راهکارهای موازی‌سازی احتمالی را بررسی می‌کنم، مثل پیش‌آماده‌سازی اسکلت و لوله‌کشی جانبی خارج از فونداسیون یا پیش‌بازرسی مواد و اسناد، تا در صورت آماده شدن فونداسیون، زمان نصب کوتاه شود. اگر تاخیر ادامه‌دار و بدون واکنش باشد، موضوع را به صورت رسمی و با تاثیر کمی بر زمان‌بندی به سطح بالاتر مدیریت پروژه ارجاع (Escalate) می‌دهم تا در سطح مدیریتی بین پیمانکاران حل شود.","key_points":["مستندسازی کمی تاخیر و اثر آن بر مسیر بحرانی","استفاده از کانال رسمی اینترفیس/هماهنگی بین‌رشته‌ای","پیشنهاد راهکار موازی‌سازی برای کاهش اثر تاخیر","Escalation رسمی در صورت عدم حل مسئله در سطح اجرایی","عدم اقدام یک‌جانبه بدون هماهنگی با سایر رشته‌ها"],"excellent_answer_indicators":["ارائه راهکار فنی عملی برای کاهش تاثیر تاخیر (پیش‌مونتاژ، پیش‌بازرسی)","تسلط به ابزارهای مدیریت اینترفیس مانند Interface Register","درک اثر تاخیر بر مسیر بحرانی کل پروژه نه فقط بخش خودش","رویکرد حل مسئله مشترک به‌جای انداختن تقصیر بین رشته‌ها"],"common_mistakes":["منتظر ماندن بدون اقدام تا رفع تاخیر توسط دیگران","شکایت غیررسمی بدون مستندسازی و بدون کانال رسمی","عدم بررسی راهکار موازی‌سازی کار"],"standard_reference":""},{"category":"TECHNICAL","sub_category":"P&ID","difficulty":"L1","question_text":"هنگام دریافت یک نسخه P&ID برای شروع بازرسی نصب یک واحد، چه مواردی را در آن بررسی می‌کنید تا مطمئن شوید مبنای درستی برای بازرسی در دست دارید؟","reference_answer":"نخست باید اطمینان حاصل کنم که نسخه در دست من آخرین ریویژن تاییدشده (Issued for Construction) است و با شماره ریویژن ثبت‌شده در سیستم کنترل مدارک پروژه مطابقت دارد، نه یک نسخه قدیمی یا پیش‌نویس. سپس علائم و نمادهای خطوط، شیرها، تجهیزات، ابزار دقیق و کلاس لوله (Piping Class/Line Number) را با Legend پروژه تطبیق می‌دهم تا در تفسیر نمادها اشتباه نکنم. همچنین بررسی می‌کنم که آیا Hold یا نکات باز (Open Items) روی نقشه درج شده که ممکن است بر بخش مورد بازرسی من اثر بگذارد. در نهایت هرگونه ناسازگاری بین P&ID و ایزومتریک یا وضعیت واقعی فیلد را به‌جای تصمیم شخصی، از طریق RFI به مهندسی گزارش می‌کنم.","key_points":["تایید آخرین ریویژن و وضعیت IFC بودن نقشه","تطبیق نمادها با Legend پروژه","بررسی Hold/Open Items روی نقشه","شناسایی ناسازگاری با ایزومتریک یا وضعیت فیلد","ارجاع ابهامات از طریق RFI به‌جای تصمیم شخصی"],"excellent_answer_indicators":["اشاره به کنترل نسخه از طریق سیستم مدیریت مدارک (EDMS)","توجه به شماره خط (Line Number) و کلاس برای ارتباط با اسپک شیت","درک تفاوت نقش P&ID (فرآیندی) در برابر ایزومتریک (اجرایی)"],"common_mistakes":["استفاده از نسخه چاپی قدیمی بدون بررسی ریویژن","نادیده گرفتن Hold Note ها","تفسیر شخصی ابهامات بدون RFI"],"standard_reference":""},{"category":"TECHNICAL","sub_category":"Isometric Drawings","difficulty":"L2","question_text":"در حین بازرسی یک اسپول نصب‌شده متوجه می‌شوید که طول یک بازوی لوله با بعد درج‌شده در ایزومتریک حدود ۱۵ میلی‌متر متفاوت است، هرچند اتصال به فلنج تجهیز بدون مشکل انجام شده. چه تحلیلی از این وضعیت دارید و آیا آن را قابل قبول می‌دانید؟","reference_answer":"صرف اینکه اتصال فیزیکی امکان‌پذیر بوده به معنای قابل قبول بودن انحراف نیست، چون ایزومتریک مبنای طراحی برای تحلیل انعطاف‌پذیری (Flexibility) و تنش خط لوله است و تغییر طول بازوها می‌تواند نیروها و گشتاورهای وارد بر نازل تجهیز یا فلنج مجاور را از حد مجاز خارج کند. من ابتدا رواداری ابعادی مجاز فابریکاسیون اسپول را طبق مشخصات پروژه بررسی می‌کنم؛ اگر انحراف خارج از تلورانس مجاز باشد، آن را به عنوان یک انحراف ثبت (NCR/Deviation) کرده و از مهندسی استرس تحلیل می‌خواهم اثر آن را روی نیروی نازل بررسی کند، به‌ویژه اگر تجهیز حساس (مانند پمپ یا کمپرسور) درگیر باشد. در صورتی که انحراف در بازه رواداری مجاز پروژه باشد و اثر قابل‌توجهی بر نیروی وارده نداشته باشد، می‌توان آن را با مستندسازی و تایید مهندسی پذیرفت. تصمیم نهایی همیشه باید بر مبنای ارزیابی مهندسی باشد نه قضاوت میدانی صرف.","key_points":["ایزومتریک مبنای تحلیل Flexibility/Stress است نه صرفاً راهنمای مونتاژ","بررسی رواداری ابعادی مجاز فابریکاسیون","ارزیابی اثر انحراف بر نیروی نازل تجهیزات حساس","ثبت انحراف و ارجاع به مهندسی استرس در صورت خروج از تلورانس","عدم پذیرش صرفاً بر اساس امکان فیزیکی اتصال"],"excellent_answer_indicators":["اشاره مشخص به اهمیت بیشتر موضوع در صورت اتصال به تجهیز دوار حساس مانند پمپ/کمپرسور","آشنایی با مفهوم Nozzle Load Allowable طبق استاندارد تجهیز (مثلاً API 610)","تاکید بر مستندسازی As-Built برای مرجع آینده"],"common_mistakes":["تایید صرفاً چون بولت‌ها بسته شده‌اند","نادیده گرفتن اثر بر نیروی نازل تجهیزات","عدم مستندسازی انحراف در As-Built"],"standard_reference":""},{"category":"TECHNICAL","sub_category":"Flanges","difficulty":"L2","question_text":"هنگام بستن یک اتصال فلنجی بزرگ (مثلاً ۲۴ اینچ کلاس ۳۰۰)، چه توالی و روشی برای سفت کردن پیچ‌ها رعایت می‌کنید تا از نشتی یا آسیب به گسکت جلوگیری شود؟","reference_answer":"پیش از بستن، باید موازی بودن و صافی دو فلنج (Flange Face Alignment و Flatness) و تمیزی سطح گسکت را کنترل کنم، چون هیچ توالی بستن نمی‌تواند مشکل عدم موازی بودن فلنج‌ها را جبران کند. بستن باید به روش ستاره‌ای (Star/Cross Pattern) و در چند مرحله (معمولاً حداقل سه یا چهار مرحله با درصد افزایشی گشتاور، مثلاً ۳۰-۶۰-۱۰۰ درصد) انجام شود تا فشار به طور یکنواخت روی گسکت توزیع شود و از خم شدن یا آسیب لبه فلنج جلوگیری شود. مقدار گشتاور نهایی باید طبق جدول گشتاور تایید‌شده پروژه (بر اساس نوع پیچ، روان‌کننده و کلاس فلنج) باشد، نه یک عدد حدسی. در پروژه‌های حساس یا فلنج‌های بزرگ، استفاده از هیدرولیک تنشنر (Bolt Tensioning) به‌جای آچار گشتاور برای دقت و یکنواختی بیشتر توصیه می‌شود.","key_points":["کنترل موازی بودن و صافی سطح فلنج قبل از بستن","توالی بستن ستاره‌ای در چند مرحله افزایشی","استفاده از مقدار گشتاور طبق جدول تایید‌شده پروژه","توجه به نوع روان‌کننده و ضریب K در محاسبه گشتاور","استفاده از تنشنر هیدرولیک برای فلنج‌های بزرگ/حساس"],"excellent_answer_indicators":["اشاره صریح به استاندارد ASME PCC-1 برای روش بستن بولت","توضیح اثر عدم یکنواختی گشتاور بر نشتی احتمالی گسکت اسپیرال-وند","تجربه عملی با بازرسی بعد از بستن (مثلاً اندازه‌گیری Gap یکنواخت)"],"common_mistakes":["بستن پیچ‌ها به ترتیب پیوسته دورانی به‌جای الگوی ستاره‌ای","استفاده از گشتاور یکسان برای همه سایزها بدون مرجع","نادیده گرفتن بررسی صافی و موازی بودن فلنج قبل از بستن"],"standard_reference":"ASME PCC-1"},{"category":"TECHNICAL","sub_category":"Bolting/Torqueing","difficulty":"L3","question_text":"پیمانکار برای اتصالات فلنجی حساس (مانند خطوط با سیال خطرناک یا فشار بالا) از آچار گشتاور دستی معمولی استفاده کرده در حالی که مشخصات پروژه استفاده از هیدرولیک تنشنر را برای این کلاس فلنج الزامی کرده است. به عنوان ناظر با این وضعیت چه برخوردی می‌کنید؟","reference_answer":"این موضوع یک عدم انطباق با مشخصات فنی تایید‌شده پروژه است و باید بلافاصله متوقف و به صورت رسمی (NCR) ثبت شود، چون روش بستن نادرست می‌تواند منجر به توزیع نامتوازن بار روی پیچ‌ها، پیش‌تنش ناکافی یا بیش از حد، و در نهایت نشتی یا شکست پیچ در سرویس شود. باید بررسی کنم که آیا اتصالات قبلاً با همین روش نادرست بسته شده‌اند (Extent of Condition) و همه آن‌ها را برای باز کردن و بستن مجدد با روش صحیح فهرست کنم. تصمیم پذیرش یا رد نهایی باید با مشورت مهندسی و طبق مشخصات فنی و در صورت وجود، دستورالعمل تولیدکننده گسکت/تجهیز اتخاذ شود، نه بر اساس ادعای پیمانکار که «آچار دستی هم کافی است». در صورتی که خط قبلاً تحت هیدروتست هم قرار گرفته، باید ارزیابی شود که آیا تست معتبر بوده یا باید پس از اصلاح روش بستن مجدداً تکرار شود.","key_points":["شناسایی این وضعیت به عنوان عدم انطباق با اسپک تایید‌شده","ثبت رسمی NCR و توقف کار در محدوده مرتبط","بررسی گستردگی مشکل در سایر اتصالات مشابه","ارجاع تصمیم فنی نهایی به مهندسی/سازنده گسکت-تجهیز","ارزیابی اعتبار هیدروتست قبلی در صورت انجام‌شده بودن"],"excellent_answer_indicators":["توضیح فنی دلیل الزام تنشنر (کنترل دقیق‌تر پیش‌بار، کاهش پراکندگی گشتاور اصطکاکی)","تسلط به مفهوم Extent of Condition برای بررسی سیستماتیک","توجه به تاثیر احتمالی بر اعتبار تست‌های قبلی انجام‌شده"],"common_mistakes":["پذیرش کار چون ظاهراً نشتی مشاهده نشده","عدم بررسی سایر اتصالات مشابه","تصمیم‌گیری شخصی بدون مشورت مهندسی"],"standard_reference":"ASME PCC-1"},{"category":"TECHNICAL","sub_category":"Piping Supports","difficulty":"L3","question_text":"در بازرسی ساپورت‌های فنری (Spring Hanger) روی یک خط لوله داغ (High Temperature)، چه مواردی را کنترل می‌کنید تا مطمئن شوید ساپورت‌ها به درستی برای شرایط بهره‌برداری تنظیم شده‌اند؟","reference_answer":"باید بررسی کنم که پین قفل‌کننده حمل (Travel Stop/Shipping Pin) هنگام نصب نهایی و پیش از بارگذاری خط (پر شدن با سیال/عایق‌کاری) خارج شده باشد، چون فراموش کردن آن باعث می‌شود ساپورت مانند یک تکیه‌گاه صلب عمل کند و اجازه حرکت حرارتی خط را ندهد. سپس تنظیم بار سرد (Cold Load Setting) را با مقدار مشخص‌شده در نقشه ساپورت مقایسه می‌کنم که باید متناسب با وزن خط در وضعیت سرد باشد. پس از راه‌اندازی و رسیدن به دمای عملیاتی، باید بار گرم (Hot Load) و میزان جابجایی واقعی فنر با مقدار پیش‌بینی‌شده در طراحی تطبیق داده شود تا مطمئن شویم فنر در محدوده عملکردی طراحی حرکت کرده و به بلوکه شدن (Bottoming/Topping Out) نرسیده است. هرگونه انحراف قابل توجه باید به مهندسی استرس گزارش شود چون می‌تواند نشانه خطای طراحی، نصب اشتباه یا انسداد در جای دیگر خط باشد.","key_points":["بررسی خروج پین قفل حمل قبل از بارگذاری نهایی خط","تطبیق تنظیم بار سرد (Cold Setting) با نقشه ساپورت","بررسی بار گرم و جابجایی واقعی پس از راه‌اندازی حرارتی","شناسایی وضعیت بلوکه‌شدگی فنر (Topped/Bottomed out)","گزارش انحراف قابل توجه به مهندسی استرس"],"excellent_answer_indicators":["تشخیص این که فراموشی پین قفل شایع‌ترین خطای میدانی است و پیامد آن (بار غیرمنتظره روی تجهیزات مجاور)","اشاره به Walk-down حرارتی (Hot Walkdown) به عنوان مرحله رسمی تایید عملکرد ساپورت","درک ارتباط بین رفتار غیرعادی فنر و مشکلات پنهان مانند گیرکردگی (Interference) در نقطه دیگر"],"common_mistakes":["توجه فقط به نصب مکانیکی ساپورت بدون بررسی پین قفل","عدم پیگیری بار گرم بعد از راه‌اندازی","ندانستن مفهوم Hot Walkdown"],"standard_reference":""},{"category":"TECHNICAL","sub_category":"Rotating Equipment Alignment","difficulty":"L4","question_text":"پس از انجام هم‌محوری (Alignment) کوپلینگ یک پمپ و موتور الکتریکی در دمای محیط با روش لیزری و رسیدن به مقادیر داخل تلورانس مجاز، آیا این هم‌محوری را نهایی می‌دانید؟ چه ملاحظات دیگری باید در نظر گرفته شود؟","reference_answer":"هم‌محوری سرد به تنهایی کافی نیست، به‌خصوص برای پمپ‌هایی که سیال داغ یا با اختلاف دمای قابل‌توجه بین حالت خاموش و کارکرد جابجا می‌کنند، چون انبساط حرارتی پایه، محفظه پمپ و نازل‌های لوله‌کشی متصل باعث تغییر موقعیت نسبی شفت‌ها در دمای عملیاتی می‌شود. باید مقدار جبران حرارتی (Thermal Growth Compensation) طبق دیتاشیت سازنده پمپ محاسبه و در تنظیم آفست هم‌محوری سرد لحاظ شود، یا در پروژه‌های حساس هم‌محوری گرم (Hot Alignment Check) پس از رسیدن به دمای پایدار عملیاتی انجام و تصحیح شود. همچنین باید بررسی کنم که نیروی لوله‌کشی (Piping Nozzle Load) روی محفظه پمپ در محدوده مجاز سازنده باشد و بولت‌های پایه دچار Soft Foot نباشند، چون هر دو عامل می‌توانند هم‌محوری صحیح سرد را در حین کارکرد به هم بزنند. در نهایت هم‌محوری باید پس از اتصال نهایی لوله‌کشی و سفت کردن کامل بولت‌های پایه بازبینی شود، نه قبل از آن.","key_points":["هم‌محوری سرد به تنهایی برای تجهیزات با اختلاف دمای عملیاتی کافی نیست","لحاظ کردن Thermal Growth طبق دیتاشیت سازنده","بررسی Soft Foot قبل از نهایی کردن هم‌محوری","کنترل نیروی نازل لوله‌کشی روی پمپ در محدوده مجاز","بازبینی هم‌محوری پس از اتصال نهایی لوله‌کشی و سفت‌کاری بولت پایه"],"excellent_answer_indicators":["اشاره صریح به هم‌محوری گرم (Hot Alignment) و روش عملی انجام آن","تسلط به محدودیت نیروی نازل طبق استانداردهایی مانند API 610 برای پمپ‌ها","تجربه در تشخیص Soft Foot با روش عملی (شل کردن تک‌تک بولت‌ها و پایش انحراف)"],"common_mistakes":["اکتفا به هم‌محوری سرد بدون توجه به رشد حرارتی","بستن لوله‌کشی نهایی بعد از تایید هم‌محوری بدون بازبینی مجدد","نادیده گرفتن بررسی Soft Foot"],"standard_reference":"API 686"},{"category":"TECHNICAL","sub_category":"Static Equipment","difficulty":"L3","question_text":"در بازرسی نصب یک مخزن عمودی (Vertical Vessel) قبل از اتصال نهایی لوله‌کشی، چه مواردی را به طور خاص کنترل می‌کنید؟","reference_answer":"ابتدا تراز بودن (Levelness) و شاقولی بودن (Plumbness) مخزن را با استفاده از ابزار دقیق نظیر تئودولیت یا تراز دقیق کنترل می‌کنم و مقادیر را با تلورانس مجاز مشخص‌شده در نقشه نصب یا استاندارد سازنده مقایسه می‌کنم. سپس جهت‌گیری نازل‌ها (Nozzle Orientation) را با پلان جانمایی و ایزومتریک‌های متصل تطبیق می‌دهم تا مطمئن شوم اتصال لوله‌کشی بدون نیاز به تنش اضافی یا اصلاح غیرمجاز امکان‌پذیر است. کنترل سفت شدن یکنواخت و متقارن بولت‌های آنکر (Anchor Bolts) طبق گشتاور مشخص‌شده و بررسی وجود Grouting مناسب زیر پایه از دیگر موارد کلیدی است، چون بی‌توجهی به این موارد می‌تواند در بلندمدت باعث نشست ناهمگون یا ارتعاش غیرعادی شود. در نهایت باید از پاکیزگی داخلی مخزن (Internal Cleanliness) و بستن صحیح منهول‌ها پیش از هیدروتست اطمینان حاصل کنم.","key_points":["کنترل تراز و شاقولی بودن مخزن با ابزار دقیق","تطبیق جهت‌گیری نازل‌ها با پلان و ایزومتریک","کنترل گشتاور یکنواخت و متقارن بولت‌های آنکر","بررسی Grouting مناسب زیر پایه","کنترل پاکیزگی داخلی و بستن منهول قبل از تست"],"excellent_answer_indicators":["اشاره به ریسک نشست ناهمگون در بلندمدت ناشی از Grouting نامناسب","تسلط به رواداری‌های استاندارد نصب تجهیزات ثابت","توجه به توالی صحیح: کنترل تراز/نازل قبل از اتصال نهایی لوله تا از فورس‌فیت جلوگیری شود"],"common_mistakes":["بررسی فقط ظاهری بدون ابزار دقیق برای تراز","نادیده گرفتن جهت‌گیری نازل قبل از اتصال لوله","فراموشی بازرسی داخلی مخزن قبل از بستن منهول"],"standard_reference":""},{"category":"TECHNICAL","sub_category":"Hydrostatic Test","difficulty":"L2","question_text":"پیش از اجرای هیدروتست یک بسته لوله‌کشی، چه پارامترهایی را برای تدوین و تایید بسته تست (Test Package) بررسی و محاسبه می‌کنید؟","reference_answer":"ابتدا فشار طراحی و کلاس فشار کمترین جزء موجود در مسیر تست (Limiting Component، مانند شیر یا فلنج با کلاس پایین‌تر) را شناسایی می‌کنم چون فشار تست باید بر اساس ضعیف‌ترین قطعه در محدوده تست تعیین شود، نه فقط بر اساس فشار طراحی خط اصلی. سپس فشار تست را طبق ضریب مشخص‌شده در کد طراحی پروژه (معمولاً ۱.۵ برابر فشار طراحی برای ASME B31.3) محاسبه کرده و آن را با حداکثر فشار مجاز اجزای موجود مقایسه می‌کنم. باید مطمئن شوم مانومترها و گیج‌های فشار مورد استفاده کالیبره و دارای گواهی معتبر هستند و محدوده دقیق برای فشار تست را پوشش می‌دهند. همچنین مرزبندی بسته تست (Test Boundary با بلایند یا اسپیدبلایند)، حذف یا ایزوله تجهیزات حساس مانند شیرهای کنترل و ابزار دقیق که نباید تحت فشار تست قرار گیرند، و زمان توقف (Hold Time) لازم طبق مشخصات پروژه از دیگر موارد ضروری است.","key_points":["شناسایی ضعیف‌ترین قطعه (Limiting Component) در مسیر تست","محاسبه فشار تست طبق ضریب کد طراحی پروژه","کالیبراسیون معتبر گیج‌های فشار","مرزبندی صحیح بسته تست و ایزوله تجهیزات حساس","تعیین زمان توقف (Hold Time) طبق مشخصات پروژه"],"excellent_answer_indicators":["اشاره دقیق به ضریب ۱.۵ برابر طبق ASME B31.3 و نیاز به بررسی حداکثر فشار مجاز اجزا در دمای تست","توجه به اثر دمای محیط بر فشار تست هیدرواستاتیک (تصحیح حرارتی)","تسلط به مفهوم ایزوله کردن تجهیزات حساس مانند شیرهای کنترل، اورفیس، و ابزار دقیق"],"common_mistakes":["محاسبه فشار تست فقط بر اساس فشار طراحی خط اصلی بدون توجه به ضعیف‌ترین جزء","استفاده از گیج بدون گواهی کالیبراسیون معتبر","فراموش کردن ایزوله تجهیزات حساس از مسیر تست"],"standard_reference":"ASME B31.3"},{"category":"TECHNICAL","sub_category":"Material Control / MTO","difficulty":"L1","question_text":"در حین دریافت محموله فلنج و اتصالات (Fittings) در انبار پروژه، چه بررسی‌هایی برای اطمینان از قابلیت ردیابی (Traceability) و صحت مواد انجام می‌دهید؟","reference_answer":"ابتدا باید مطمئن شوم هر قطعه دارای علامت‌گذاری (Marking) شامل هیت نامبر (Heat Number)، کلاس فشار، جنس متریال و استاندارد ساخت است و این علامت‌گذاری با گواهی کیفیت مواد (Material Test Certificate) ارسالی مطابقت کامل دارد. سپس MTC را با مشخصات فنی خرید (Purchase Specification/Piping Class) تطبیق می‌دهم تا از صحت آنالیز شیمیایی، خواص مکانیکی و روش ساخت (مثلاً فورج در برابر کست) اطمینان یابم. برای اقلام حساس مانند فلزات مقاوم به خوردگی یا کاربردهای سرویس H2S، ممکن است نیاز به بازرسی مضاعف مانند تست PMI (Positive Material Identification) در محل تحویل باشد تا از اختلاط مواد (Mix-up) جلوگیری شود. در نهایت، سیستم ردیابی مواد باید به‌گونه‌ای باشد که از لحظه ورود به انبار تا نصب نهایی در خط، هیت نامبر هر قطعه در مستندات نصب (Weld Log/Spool Record) قابل ردیابی باقی بماند.","key_points":["کنترل تطابق مارکینگ فیزیکی با گواهی کیفیت مواد (MTC)","تطبیق مشخصات MTC با اسپک خرید و کلاس لوله","استفاده از PMI برای اقلام حساس جهت جلوگیری از Mix-up","حفظ Traceability هیت نامبر از انبار تا نصب نهایی","ثبت در Weld Log/Spool Record برای ردیابی آینده"],"excellent_answer_indicators":["اشاره صریح به ریسک Mix-up مواد آلیاژی مشابه ظاهری و نقش PMI در جلوگیری از آن","تسلط به مفهوم Traceability End-to-End تا مرحله نصب و جوش","تجربه در برخورد با محموله دارای مغایرت مارکینگ/MTC"],"common_mistakes":["اکتفا به بررسی ظاهری بدون تطبیق MTC","ندانستن اهمیت PMI برای متریال‌های آلیاژی","عدم ثبت هیت نامبر در مستندات نصب برای ردیابی آینده"],"standard_reference":""},{"category":"SCENARIO","sub_category":"Bolting/Torqueing – Post-Test Verification","difficulty":"L3","question_text":"بسته لوله‌کشی هیدروتست شده و با موفقیت افت فشاری نداشته و توسط شما تایید شده است. چند روز بعد متوجه می‌شوید آچار گشتاوری که برای بستن پیچ‌های فلنج‌های این بسته استفاده شده، گواهی کالیبراسیون معتبر نداشته است. به عنوان ناظر چه تصمیمی می‌گیرید؟","reference_answer":"موفقیت هیدروتست به تنهایی تضمین‌کننده صحت گشتاور بستن پیچ‌ها در بلندمدت و شرایط عملیاتی نیست، چون تست هیدرواستاتیک در دمای محیط و برای مدت محدود انجام می‌شود در حالی که پیش‌بار نامناسب پیچ‌ها می‌تواند در شرایط عملیاتی واقعی (دما، ارتعاش، فشار چرخه‌ای) منجر به نشتی یا شل شدن اتصال شود. ابتدا این موضوع را به عنوان یک انحراف فرآیندی (NCR) ثبت می‌کنم و مشخص می‌کنم دقیقاً کدام اتصالات با این آچار بسته شده‌اند (بررسی گزارش‌های بستن بولت و شناسه ابزار). سپس با کالیبراسیون آچار (حتی اگر بعد از تاریخ استفاده باشد) یا مقایسه با یک آچار کالیبره در شرایط مشابه، میزان انحراف احتمالی از گشتاور واقعی را ارزیابی می‌کنم؛ در صورت وجود انحراف قابل توجه، باید اتصالات مربوطه به روش صحیح و با ابزار کالیبره مجدداً بسته و در صورت لزوم تست هیدرواستاتیک تکرار شود. تصمیم نهایی درباره نیاز به تکرار تست باید با مشورت مهندسی و بر اساس ارزیابی ریسک اتخاذ شود، نه صرفاً بر اساس نتیجه ظاهری موفق تست قبلی.","key_points":["عبور موفق هیدروتست تضمین‌کننده صحت گشتاور بلندمدت نیست","ثبت NCR و شناسایی تمام اتصالات بسته‌شده با ابزار فاقد کالیبراسیون","ارزیابی میزان انحراف احتمالی گشتاور از طریق کالیبراسیون واپسین یا مقایسه","باز و بستن مجدد اتصالات مشکوک با ابزار کالیبره","تصمیم‌گیری درباره تکرار تست بر مبنای ارزیابی ریسک مهندسی"],"excellent_answer_indicators":["تحلیل درست تفاوت شرایط تست (استاتیک، دمای محیط) با شرایط عملیاتی واقعی","رویکرد سیستماتیک Extent of Condition برای شناسایی تمام اتصالات درگیر","توجه به اهمیت کنترل کالیبراسیون ابزار به عنوان یک کنترل پیشگیرانه در آینده (افزودن به چک‌لیست ITP)"],"common_mistakes":["نادیده گرفتن مشکل چون تست هیدرواستاتیک موفق بوده است","عدم بررسی سایر اتصالات بسته‌شده با همان ابزار","تصمیم شخصی بدون ارجاع به مهندسی برای نیاز به تکرار تست"],"standard_reference":""},{"category":"SCENARIO","sub_category":"Gaskets","difficulty":"L3","question_text":"پس از نصب کامل یک بسته لوله‌کشی سرویس هیدروکربن با فشار و دمای بالا، متوجه می‌شوید که به‌جای گسکت اسپیرال-وند با فیلر گرافیتی مشخص‌شده در اسپک، گسکت غیرفلزی معمولی (نوع لاستیکی/فایبری با رتبه فشاری پایین‌تر) نصب شده و خط هنوز تحت هیدروتست قرار نگرفته. چه اقدامی انجام می‌دهید؟","reference_answer":"این یک خطای بحرانی است چون نوع نادرست گسکت می‌تواند در دما و فشار عملیاتی سرویس هیدروکربن دچار خزش (Creep)، سوختن یا از بین رفتن زودهنگام شود و ریسک نشتی و آتش‌سوزی ایجاد کند؛ بنابراین کار باید فوراً متوقف و به عنوان NCR ثبت شود. باید بررسی کنم که آیا این خطا صرفاً یک مورد منفرد است یا ناشی از مشکل سیستماتیک در انبار/توزیع مواد (مثلاً اختلاط گسکت‌ها) که ممکن است در سایر بسته‌های مشابه هم رخ داده باشد، و بازرسی گسترده (Extent of Condition) روی سایر اتصالات مشابه انجام دهم. از آنجا که هیدروتست هنوز انجام نشده، اتصال باید باز و گسکت صحیح طبق اسپک (اسپیرال-وند با فیلر گرافیتی و رتبه فشاری مناسب) با رعایت توالی و گشتاور صحیح بستن، جایگزین شود. علاوه بر این، پیشنهاد می‌کنم علت ریشه‌ای این اشتباه (کنترل انبار، برچسب‌گذاری، آموزش نصاب) بررسی و اقدام پیشگیرانه برای جلوگیری از تکرار در بسته‌های آینده تعریف شود.","key_points":["تشخیص ریسک ایمنی/فرآیندی بالای استفاده از گسکت نامناسب در سرویس هیدروکربن","توقف کار و ثبت رسمی NCR","بررسی گستردگی مشکل در سایر اتصالات مشابه (Extent of Condition)","جایگزینی با گسکت صحیح طبق اسپک قبل از هیدروتست","بررسی علت ریشه‌ای و تعریف اقدام پیشگیرانه"],"excellent_answer_indicators":["تحلیل فنی دقیق پیامد گسکت نامناسب (خزش، عدم تحمل دما/فشار، ریسک آتش‌سوزی)","رویکرد سیستماتیک برای یافتن ریشه مشکل (کنترل انبار/متریال) نه فقط رفع مورد مشاهده‌شده","تاکید بر اینکه چون هیدروتست انجام نشده، این فرصتی برای اصلاح بدون هزینه اضافه باز کردن خط تحت فشار است"],"common_mistakes":["نادیده گرفتن چون ظاهراً گسکت درزبندی می‌کند","تعویض فقط همان یک گسکت بدون بررسی سایر بسته‌های مشابه","عدم بررسی علت ریشه‌ای خطا"],"standard_reference":"ASME B16.20"},{"category":"PROBLEM_SOLVING","sub_category":"Valve Installation","difficulty":"L4","question_text":"در مرحله پیش‌راه‌اندازی (Pre-commissioning) و درست قبل از بلوئینگ خط، متوجه می‌شوید یک شیر یک‌طرفه (Check Valve) روی خط اصلی خروجی کمپرسور در جهت معکوس نصب شده و پروژه در آستانه شروع کمیسیونینگ است. چگونه با این وضعیت برخورد می‌کنید و چه تبعاتی را باید در نظر بگیرید؟","reference_answer":"اولین اقدام، توقف فوری فعالیت‌های بعدی (بلوئینگ/راه‌اندازی) در آن مسیر و اطلاع‌رسانی رسمی و فوری به تیم کمیسیونینگ و مدیریت پروژه است، چون کارکرد در جهت معکوس یک چک‌ولو می‌تواند باعث بازگشت جریان، ضربه قوچ (Water/Surge Hammer) یا آسیب جدی به کمپرسور در لحظه راه‌اندازی شود. سپس باید علت را ریشه‌یابی کنم؛ آیا فلش جهت روی بدنه شیر اشتباه بازرسی شده یا شیر واقعاً برعکس نصب شده، و بررسی کنم که آیا شیرهای مشابه دیگر در پروژه هم دچار همین خطا هستند (Extent of Condition)، چون این نوع اشتباه معمولاً سیستماتیک است. اصلاح مستلزم باز کردن اتصالات فلنجی مجاور و نصب مجدد شیر در جهت صحیح طبق فلش روی بدنه و مطابق با P&ID/ایزومتریک است، و پس از اصلاح باید بازرسی مجدد نصب و در صورت نیاز بازبینی مسیر تست انجام شود. این حادثه باید به عنوان NCR با شرح کامل علت ریشه‌ای و اقدام اصلاحی/پیشگیرانه (مانند افزودن چک جهت شیر به‌عنوان یک Hold Point مستقل در ITP) ثبت شود.","key_points":["توقف فوری فعالیت‌های بعدی قبل از آسیب جدی به تجهیز دوار","اطلاع‌رسانی سریع به تیم کمیسیونینگ و مدیریت پروژه","ریشه‌یابی خطا و بررسی گستردگی آن در شیرهای مشابه دیگر","اصلاح با باز کردن و نصب مجدد در جهت صحیح طبق P&ID/ایزومتریک","ثبت NCR و تعریف اقدام پیشگیرانه مانند افزودن Hold Point اختصاصی برای جهت شیر"],"excellent_answer_indicators":["درک عمیق ریسک فنی واقعی (ضربه فشاری، آسیب به کمپرسور، بازگشت جریان به سمت تجهیز حساس)","رویکرد سیستماتیک به علت ریشه‌ای (چرا این خطا رخ داد و چگونه از تکرار در سایر شیرها جلوگیری شود)","پیشنهاد بهبود فرآیند بازرسی (Hold Point اختصاصی جهت شیر) به‌عنوان اقدام پیشگیرانه بلندمدت"],"common_mistakes":["ادامه کمیسیونینگ با این فرض که مشکل کوچک است و بعداً اصلاح می‌شود","بررسی فقط همان یک شیر بدون چک شیرهای مشابه","عدم ثبت رسمی و صرفاً اصلاح شفاهی بدون مستندسازی"],"standard_reference":""},{"category":"SCENARIO","sub_category":"Punch List / Mechanical Completion","difficulty":"L2","question_text":"در جلسه واک‌داون تکمیل مکانیکال، پیمانکار معتقد است یک مورد باقیمانده (مثلاً عدم نصب لیبل شناسایی خط لوله) باید در دسته پانچ لیست B قرار گیرد تا مانع صدور گواهی تکمیل مکانیکال نشود، اما مشاور کارفرما اصرار دارد این مورد باید پیش از تکمیل مکانیکال رفع شود. چگونه به عنوان ناظر با این اختلاف نظر برخورد می‌کنید؟","reference_answer":"ابتدا باید معیار دسته‌بندی پانچ لیست (A بحرانی و مانع تکمیل مکانیکال/کمیسیونینگ، در برابر B غیربحرانی و قابل تکمیل بعد از راه‌اندازی) را طبق تعریف مندرج در رویه پروژه (Project Procedure) یا قرارداد بررسی کنم، نه صرفاً نظر شخصی. سپس اثر واقعی نبود لیبل شناسایی خط را از منظر ایمنی عملیاتی ارزیابی می‌کنم؛ در بسیاری از پروژه‌ها، لیبل‌گذاری خطوط برای ایمنی اپراتور در حین بهره‌برداری (شناسایی سرویس، جهت جریان، خطر) حیاتی است و ممکن است طبق رویه پروژه یا الزامات HSE، جزو موارد Punch A طبقه‌بندی شود، به‌خصوص اگر خط حاوی سیال خطرناک باشد. نظر نهایی من به عنوان ناظر باید مستقل و مبتنی بر تعریف مکتوب پروژه باشد؛ اگر رویه پروژه صراحتاً این مورد را B تعریف کرده، آن را می‌پذیرم، در غیر این صورت با مشاور هم‌نظر شده و آن را Punch A نگه می‌دارم. در هر حالت تصمیم باید مستند و با ذکر مرجع (بند رویه پروژه) باشد، نه صرفاً یک قضاوت شخصی بین دو طرف.","key_points":["مرجع قرار دادن تعریف مکتوب Punch A/B در رویه پروژه یا قرارداد","ارزیابی اثر واقعی مورد بر ایمنی عملیاتی (نه صرفاً ظاهر آن)","توجه ویژه به الزامات HSE برای لیبل‌گذاری خطوط حاوی سیال خطرناک","حفظ استقلال تصمیم به عنوان ناظر بین ادعای پیمانکار و نظر مشاور","مستندسازی تصمیم نهایی با ذکر مرجع مشخص"],"excellent_answer_indicators":["اشاره به این‌که تصمیم صرفاً بین دو طرف تعیین نمی‌شود بلکه بر مبنای سند مرجع پروژه است","درک این‌که موارد به‌ظاهر جزئی (مثل لیبل) می‌توانند از منظر ایمنی بهره‌برداری حیاتی باشند","پیشنهاد راه‌حل عملی مانند نصب لیبل موقت قابل قبول تا نصب لیبل نهایی در صورتی که رویه اجازه دهد"],"common_mistakes":["تصمیم‌گیری صرفاً بر اساس اینکه کدام طرف قوی‌تر استدلال می‌کند بدون مرجع مکتوب","دست کم گرفتن اهمیت ایمنی لیبل‌گذاری خطوط","عدم مستندسازی مبنای تصمیم نهایی"],"standard_reference":""},{"category":"PROBLEM_SOLVING","sub_category":"Piping Alignment / Flanges","difficulty":"L3","question_text":"در حین نصب یک اسپول لوله به نازل یک تجهیز، مشاهده می‌کنید صورت فلنج لوله و فلنج تجهیز به میزان قابل توجهی (مثلاً چند میلی‌متر Gap یک‌طرفه) موازی نیستند و تیم نصب قصد دارد با سفت کردن بیش از حد پیچ‌ها فلنج‌ها را به هم نزدیک و بولت کند. چه تصمیمی می‌گیرید؟","reference_answer":"اجازه نمی‌دهم فلنج‌ها با فورس‌کردن پیچ‌ها (Force-Fit) بسته شوند، چون این کار باعث ایجاد تنش پسماند بالا (Residual Stress) روی نازل تجهیز، خطر آسیب یا ترک‌خوردگی بلندمدت، و اعمال بار غیرمجاز روی تجهیزی مانند پمپ یا کمپرسور می‌شود که می‌تواند هم‌محوری آن را هم به هم بزند. ابتدا باید علت عدم موازی بودن را بررسی کنم: خطای فابریکاسیون اسپول، خطای نصب ساپورت، یا جابجایی تجهیز نسبت به موقعیت طراحی. اصلاح صحیح شامل بازبینی و اصلاح موقعیت ساپورت‌ها، اصلاح طول/زاویه اسپول در کارگاه فابریکاسیون، یا در صورت لزوم ساخت مجدد اسپول با ابعاد صحیح است، نه فشار آوردن فیزیکی حین نصب. پس از اصلاح، باید Gap بین دو فلنج و موازی بودن آن‌ها با ابزار اندازه‌گیری (فیلر گیج یا خط‌کش) در محدوده تلورانس مجاز پروژه تایید شود و تنها در آن صورت اجازه بستن نهایی پیچ‌ها را می‌دهم.","key_points":["ممنوعیت بستن فلنج با فورس‌فیت به دلیل ریسک تنش پسماند و آسیب به تجهیز","شناسایی علت ریشه‌ای عدم موازی بودن (فابریکاسیون، ساپورت، جابجایی تجهیز)","اصلاح از طریق تصحیح ساپورت یا بازسازی اسپول، نه فشار فیزیکی","کنترل Gap و موازی بودن با ابزار اندازه‌گیری قبل از بستن نهایی","توجه به اثر احتمالی روی هم‌محوری تجهیز دوار متصل"],"excellent_answer_indicators":["توضیح فنی دقیق پیامد تنش پسماند بر عمر تجهیز و نازل","رویکرد ریشه‌یابی سیستماتیک به‌جای رفع موضعی مشکل","اشاره به ارتباط این مشکل با هم‌محوری تجهیزات دوار و لزوم بازبینی مجدد Alignment پس از اتصال لوله"],"common_mistakes":["اجازه دادن به فورس‌فیت برای سرعت بخشیدن به کار","نادیده گرفتن ریشه‌یابی علت عدم تطابق","عدم بررسی اثر روی هم‌محوری تجهیز متصل"],"standard_reference":""},{"category":"EXPERIENCE_BASED","sub_category":"تجربه میدانی – کشف عیب نصب","difficulty":"L3","question_text":"یکی از مهم‌ترین اشکالات نصبی یا اجرایی را که خودتان در یک پروژه واقعی کشف کردید شرح دهید: چگونه متوجه آن شدید، چه اقدامی انجام دادید و نتیجه نهایی چه بود؟","reference_answer":"این سوال تجربه‌محور است و پاسخ صحیح واحدی ندارد؛ ارزیابی باید بر اساس واقعی و ملموس بودن روایت، صحت فنی تشخیص مشکل، تطابق اقدام انجام‌شده با رویه‌های استاندارد صنعت (NCR، ارجاع به مهندسی، مستندسازی)، و وجود نتیجه و درس‌آموخته مشخص باشد. یک پاسخ قوی باید شامل شرح دقیق فنی از نوع اشکال (مثلاً خطای نصب شیر، ساپورت، جوش، یا گسکت)، روش کشف آن (بازرسی چشمی، تست، بررسی مدارک)، فرآیند رسمی پیگیری (ثبت NCR، ارجاع به مهندسی، هماهنگی با پیمانکار) و نتیجه نهایی (اصلاح، تکرار تست، تاخیر احتمالی) باشد. پاسخ‌های ضعیف معمولاً کلی، بدون جزئیات فنی، یا بدون اشاره به فرآیند رسمی مستندسازی هستند.","key_points":["روایت مبتنی بر یک تجربه واقعی و قابل‌باور با جزئیات فنی مشخص","روش صحیح کشف مشکل (بازرسی سیستماتیک/تست/بررسی مدارک)","پیگیری از طریق فرآیند رسمی (NCR، ارجاع مهندسی، هماهنگی)","ذکر نتیجه نهایی و تاثیر آن بر پروژه (زمان، هزینه، کیفیت)","استخراج درس‌آموخته یا اقدام پیشگیرانه از آن تجربه"],"excellent_answer_indicators":["ارائه جزئیات کمی (مثلاً چند مورد مشابه یافت شد، چقدر تاخیر ایجاد شد)","نشان دادن نقش فعال و ابتکار در کشف مشکل، نه صرفاً گزارش دیگران","تسلط به نام و منطق استاندارد مرتبط با آن اشکال","تبدیل تجربه به بهبود فرآیندی ماندگار (مثلاً افزودن یک Hold Point جدید)"],"common_mistakes":["روایت مبهم و کلی بدون جزئیات فنی قابل راستی‌آزمایی","نسبت دادن تمام اعتبار کشف مشکل به شانس بدون فرآیند سیستماتیک","نداشتن اطلاع از نتیجه نهایی یا مرحله بسته شدن NCR"],"standard_reference":""},{"category":"EXPERIENCE_BASED","sub_category":"تجربه میدانی – تعارض فنی با پیمانکار","difficulty":"L2","question_text":"یک مورد واقعی را شرح دهید که در آن با پیمانکار اجرایی بر سر تفسیر یک الزام فنی یا استاندارد اختلاف نظر داشتید. اختلاف چه بود، چگونه آن را حل کردید و در نهایت چه تصمیمی گرفته شد؟","reference_answer":"این سوال تجربه‌محور است؛ معیار ارزیابی، واقعی بودن روایت، صحت فنی موضع فرد در برابر پیمانکار، و نحوه مدیریت حرفه‌ای اختلاف است نه لزوماً یک نتیجه خاص. پاسخ قوی معمولاً شامل شرح دقیق موضوع فنی مورد اختلاف (مثلاً تفسیر یک بند از اسپک یا استاندارد)، استدلال مستند طرفین، نحوه ارجاع به مرجع بالاتر (مهندسی طراحی، مشاور، یا استاندارد مرجع) در صورت عدم توافق، و نتیجه نهایی مبتنی بر شواهد فنی است، نه صرفاً غلبه یک طرف بر دیگری. باید مشخص شود که فرد چگونه از موضع فنی خود در برابر فشار احتمالی زمان‌بندی یا تجاری دفاع کرده است.","key_points":["شرح دقیق موضوع فنی اختلاف با استناد به مدرک/استاندارد مشخص","روش حل تعارض (ارجاع به مرجع فنی بالاتر، نه صرفاً بحث شخصی)","حفظ رابطه حرفه‌ای با پیمانکار در عین ایستادگی بر موضع فنی صحیح","مستندسازی نتیجه نهایی تصمیم","توانایی توضیح چرایی موضع فنی خود با استدلال مهندسی"],"excellent_answer_indicators":["استناد دقیق به بند/مرجع استاندارد یا مشخصات فنی در تشریح موضوع","نشان دادن مهارت مذاکره فنی بدون تخریب رابطه کاری","اشاره به نتیجه بلندمدت (مثلاً جلوگیری از یک مشکل بزرگ‌تر بعدی)"],"common_mistakes":["روایت صرفاً احساسی/رابطه‌ای بدون محتوای فنی مشخص","ادعای پیروزی بدون ذکر مبنای فنی تصمیم نهایی","عدم اشاره به مستندسازی یا مرجع رسمی حل اختلاف"],"standard_reference":""},{"category":"EXPERIENCE_BASED","sub_category":"Commissioning / Flushing","difficulty":"L4","question_text":"یک تجربه واقعی از مرحله فلاشینگ، بلوئینگ یا پیش‌راه‌اندازی را شرح دهید که در آن مشکلی (مانند آلودگی باقیمانده در خط، عدم دستیابی به معیار پاکیزگی، یا خرابی در حین تست) کشف شد. چگونه آن را تشخیص دادید و چه اقدامی برای رفع آن انجام شد؟","reference_answer":"این سوال تجربه‌محور است؛ ارزیابی بر مبنای صحت فنی تشخیص مشکل در مرحله پیش‌راه‌اندازی، آشنایی با معیارهای پذیرش پاکیزگی خط، و فرآیند تصمیم‌گیری فرد است. پاسخ قوی معمولاً شامل توضیح روش تست پاکیزگی مورد استفاده (مثلاً تارگت پلیت در فلاشینگ، یا اسکای‌پلیت برای بلوئینگ با هوا/بخار)، معیار پذیرش مشخص‌شده در رویه پروژه، نحوه کشف عدم انطباق (مثلاً وجود ذرات جوش یا زنگار روی پلیت هدف)، و اقدام اصلاحی (تکرار فلاشینگ/بلوئینگ، بازرسی و تمیزکاری نقاط مرده خط یا استرینر) است. باید مشخص شود که فرد چگونه بین توقف بیش از حد کار (اتلاف زمان) و پذیرش زودهنگام یک خط ناپاک (ریسک آسیب به تجهیزات دوار پایین‌دست) تعادل برقرار کرده است.","key_points":["شرح دقیق روش تست پاکیزگی مورد استفاده و معیار پذیرش آن","روش تشخیص عدم انطباق (مثلاً بازرسی پلیت هدف)","اقدام اصلاحی مشخص (تکرار فرآیند، رفع نقاط مرده/استرینر مسدود)","توجه به ریسک آسیب به تجهیزات دوار پایین‌دست در صورت پذیرش زودهنگام","نتیجه نهایی و تاثیر بر برنامه کمیسیونینگ"],"excellent_answer_indicators":["تسلط دقیق به معیارهای فنی پذیرش پاکیزگی (اندازه و تعداد ذرات مجاز روی پلیت)","شناسایی علت ریشه‌ای آلودگی (مثلاً استرینر موقت نصب‌نشده، نقطه مرده در خط)","نشان‌دادن تعادل درست بین فشار زمان‌بندی کمیسیونینگ و ریسک فنی پذیرش زودهنگام"],"common_mistakes":["پذیرش خط بدون معیار مشخص صرفاً بر اساس مشاهده ظاهری آب/هوای خروجی","عدم اشاره به علت ریشه‌ای آلودگی","روایت کلی بدون ذکر روش دقیق تست پاکیزگی"],"standard_reference":""},{"category":"EXPERIENCE_BASED","sub_category":"Preservation","difficulty":"L4","question_text":"یک تجربه واقعی را شرح دهید که در آن به دلیل توقف طولانی پروژه یا تاخیر بین نصب و راه‌اندازی، مشکلی ناشی از حفاظت نامناسب (Preservation) تجهیزات یا لوله‌کشی (مانند خوردگی، ورود رطوبت، یا آسیب به یاتاقان) کشف شد. چگونه متوجه شدید و چه اقدامی انجام دادید؟","reference_answer":"این سوال تجربه‌محور است؛ ارزیابی بر اساس واقعی بودن تجربه، شناخت صحیح ریسک‌های ناشی از حفاظت نامناسب در دوره توقف، و کیفیت اقدام اصلاحی/پیشگیرانه است. پاسخ قوی شامل شرح مشخص نوع مشکل حفاظتی (مثلاً خوردگی داخل لوله‌های کربن استیل به دلیل عدم نیتروژن‌پرژ یا خشک نگه‌داشتن، زنگ‌زدگی یاتاقان پمپ به دلیل عدم چرخش دوره‌ای شفت یا فقدان روغن‌کاری حفاظتی)، روش کشف مشکل (بازرسی دوره‌ای طبق برنامه حفاظت، یا کشف اتفاقی هنگام راه‌اندازی)، و اقدام اصلاحی (تمیزکاری، تعویض قطعه آسیب‌دیده، یا اصلاح برنامه حفاظت پروژه) است. یک پاسخ عالی همچنین باید نشان دهد که فرد پیش از وقوع مشکل، برنامه حفاظت دوره‌ای (بازدید، ثبت رطوبت‌سنج داخل تجهیزات دوار، چرخش شفت) را می‌شناسد و آن را اجرا یا پیگیری کرده است.","key_points":["شرح دقیق نوع آسیب ناشی از حفاظت نامناسب و علت آن","روش کشف مشکل (بازرسی دوره‌ای طبق برنامه Preservation یا کشف در راه‌اندازی)","اقدام اصلاحی مشخص برای رفع آسیب","آشنایی با اقدامات پیشگیرانه حفاظتی (نیتروژن‌پرژ، چرخش دوره‌ای شفت، دسیکانت)","اصلاح یا تقویت برنامه حفاظت پروژه پس از این تجربه"],"excellent_answer_indicators":["تسلط فنی به روش‌های استاندارد حفاظت تجهیزات دوار و استاتیک در دوره توقف طولانی","نشان دادن رویکرد پیشگیرانه و نه صرفاً واکنشی","کمی‌سازی تاثیر مشکل (هزینه تعویض قطعه، تاخیر ایجادشده) و درس‌آموخته نهایی"],"common_mistakes":["نداشتن اطلاع از برنامه حفاظت پروژه و اهمیت آن","روایت بدون ذکر اقدام پیشگیرانه یا اصلاحی مشخص","کم‌اهمیت جلوه دادن دوره توقف پروژه به عنوان منبع ریسک کیفیت"],"standard_reference":""}]'::jsonb) as x(
  category text, sub_category text, difficulty text, question_text text, reference_answer text,
  key_points jsonb, excellent_answer_indicators jsonb, common_mistakes jsonb, standard_reference text
)
where not exists (select 1 from comp_question_bank where job_role = 'mechanical_piping_inspector');

-- ---- pipeline_inspector (23 questions) ----
insert into comp_question_bank (job_role, category, sub_category, difficulty, question_text, reference_answer, key_points, excellent_answer_indicators, common_mistakes, standard_reference)
select 'pipeline_inspector', x.category, x.sub_category, x.difficulty, x.question_text, x.reference_answer,
       coalesce(x.key_points, '[]'::jsonb), coalesce(x.excellent_answer_indicators, '[]'::jsonb), coalesce(x.common_mistakes, '[]'::jsonb), coalesce(x.standard_reference, '')
from jsonb_to_recordset('[{"category":"GENERAL","sub_category":"تعامل با کارفرما/مشاور/پیمانکار","difficulty":"L2","question_text":"سناریو: به عنوان ناظر خط لوله، در جلسه هماهنگی هفتگی، پیمانکار مدعی است که یک آیتم کار (مثلاً Lowering-in در یک بخش) مطابق نقشه انجام شده ولی مشاور (Consultant) نظر متفاوتی دارد و کارفرما هم منتظر جمع‌بندی شماست. نقش و مسئولیت شما در این تعامل سه‌جانبه چیست و چگونه به جمع‌بندی فنی و مستند می‌رسید؟","reference_answer":"ناظر خط لوله در چنین شرایطی باید نقش داور فنی بی‌طرف را ایفا کند که تصمیمش صرفاً بر مبنای مدارک مرجع باشد، نه ترجیح یک طرف. اولین قدم مراجعه به توالی مرجع فنی است: مشخصات فنی پروژه و نقشه‌های تاییدشده (Approved for Construction)، سپس قرارداد، سپس Alignment Sheet مصوب و در نهایت استانداردهای مرتبط مانند ASME B31.8. باید با اندازه‌گیری میدانی مستقل (بازدید حضوری، متره، عکس و در صورت نیاز نقشه‌برداری) واقعیت اجرا را راستی‌آزمایی کند و نتیجه را به صورت مکتوب (گزارش بازرسی یا Site Instruction) به هر دو طرف اعلام کند. در صورت وجود مغایرت، باید NCR صادر شود و اقدام اصلاحی با جدول زمانی مشخص تعریف گردد؛ اگر ابهام فنی باقی بماند، موضوع باید رسماً به مهندس پروژه یا کارفرما ارجاع شود نه اینکه به صورت شفاهی حل و فصل شود.","key_points":["مرجعیت مستندات فنی و نقشه مصوب بر ادعای شفاهی هر طرف","راستی‌آزمایی میدانی مستقل قبل از اظهارنظر","مستندسازی رسمی تصمیم (گزارش/Site Instruction/NCR)","حفظ بی‌طرفی بین پیمانکار و مشاور","ارجاع رسمی موارد مبهم به سطح بالاتر","زمان‌بندی مشخص برای اقدام اصلاحی"],"excellent_answer_indicators":["اشاره به توالی مرجعیت مدارک (مشخصات فنی، قرارداد، نقشه، استاندارد)","تاکید بر مستندسازی مکتوب به جای توافق شفاهی","پیش‌بینی اثر تاخیر تصمیم بر برنامه زمانی و تلاش برای حل سریع و مستند","آگاهی به نقش خود به عنوان چشم کارفرما و نه داور طرفدار پیمانکار"],"common_mistakes":["پذیرفتن ادعای پیمانکار بدون بازدید میدانی","حل غیررسمی و شفاهی اختلاف بدون مستندسازی","نادیده گرفتن نقش مشاور و تصمیم یک‌جانبه"],"standard_reference":""},{"category":"GENERAL","sub_category":"مدیریت مستندات و گزارش‌دهی","difficulty":"L1","question_text":"در پروژه خط لوله، مستندات و گزارش‌های روزانه/هفتگی ناظر چه نقشی در زنجیره کیفیت و As-built پروژه دارند و شما به عنوان ناظر چه اطلاعاتی را حتماً باید در گزارش روزانه بازرسی ثبت کنید؟","reference_answer":"گزارش روزانه ناظر مبنای اصلی ردیابی پیشرفت، کیفیت اجرا و مستندات As-built پروژه است و در صورت بروز اختلاف یا ادعا (Claim) در آینده، تنها مرجع مستند و قابل استناد محسوب می‌شود. گزارش باید شامل موقعیت دقیق کار بر اساس KP/Chainage، شرح فعالیت انجام‌شده و پیمانکار مربوطه، نتایج بازرسی‌ها و تست‌های کیفی (مانند NDE، Coating Holiday Test)، هرگونه مغایرت یا NCR صادرشده، شرایط آب‌وهوایی و ایمنی، و منابع/تجهیزات به‌کاررفته باشد. عکس‌های مستند با مختصات و تاریخ نیز باید ضمیمه شود تا قابل ردیابی در پرونده فنی خط باشد. کیفیت این مستندسازی مستقیماً بر صحت نقشه‌های As-built نهایی و پرونده تحویل (Handover Package) اثر دارد.","key_points":["ثبت دقیق KP/Chainage و موقعیت کار","ثبت نتایج تست‌های کیفی و NDE","ثبت مغایرت‌ها و NCR","مستندسازی عکسی با تاریخ و مختصات","ارتباط مستقیم گزارش با As-built و Handover","ثبت شرایط HSE"],"excellent_answer_indicators":["اشاره به نقش گزارش در حل ادعاهای قراردادی آینده","تاکید بر قابلیت ردیابی (Traceability) تا سطح جوش/لوله","آگاهی از ارتباط گزارش با سیستم مدیریت کیفیت پروژه (QMS)"],"common_mistakes":["اکتفا به توصیف کلی بدون ذکر KP یا شماره جوش/لوله","عدم ثبت مغایرت‌های جزئی به این بهانه که بعداً رفع می‌شود","نگاه به گزارش‌دهی به عنوان کار اداری صرف"],"standard_reference":""},{"category":"GENERAL","sub_category":"مدیریت تغییرات (Change Management)","difficulty":"L3","question_text":"فرض کنید در میانه اجرای یک بخش از خط لوله، به دلیل تغییر مالکیت اراضی، مسیر ROW مصوب در یک قطعه ۲ کیلومتری باید جابه‌جا شود. به عنوان ناظر، چه فرآیندی را برای مدیریت این تغییر طی می‌کنید تا هم کیفیت و هم مستندات پروژه دچار خدشه نشود؟","reference_answer":"تغییر مسیر ROW یک تغییر مهندسی (Design Change) محسوب می‌شود و نباید صرفاً بر اساس توافق میدانی با پیمانکار یا مالک زمین اجرا شود. ابتدا باید موضوع را به صورت رسمی به تیم مهندسی/مشاور گزارش داد تا مسیر جدید طراحی و از نظر HSE، تداخل با کراسینگ‌ها، شعاع خمش و فاصله ایمنی بررسی و تایید شود. صدور Field Change Request یا Deviation Request و دریافت نقشه بازنگری‌شده (Revised Alignment Sheet) پیش از شروع اجرا الزامی است. در طول اجرا باید اطمینان حاصل شود که KPها و مارکرهای مسیر متناسب با تغییر به‌روزرسانی می‌شوند و در نهایت نقشه As-built و مدارک تحویل باید مسیر واقعی اجراشده را منعکس کنند، نه مسیر اولیه. بدون این فرآیند، ریسک عدم انطباق با مجوزهای محیط‌زیستی یا حقوقی ROW و همچنین اختلاف در تحویل نهایی وجود دارد.","key_points":["تغییر ROW به عنوان تغییر مهندسی رسمی، نه توافق میدانی","الزام تایید مهندسی/مشاور و بازبینی نقشه Alignment Sheet","بررسی تداخل با کراسینگ‌ها و الزامات ایمنی/محیط‌زیست","به‌روزرسانی KP و مارکرهای مسیر","انعکاس تغییر در As-built و مدارک تحویل","توجه به مجوزهای حقوقی/محیط‌زیستی ROW جدید"],"excellent_answer_indicators":["اشاره به ریسک حقوقی و مجوزهای محیط‌زیستی مسیر جدید","تاکید بر ردیابی کامل تغییر از درخواست تا As-built","پیش‌بینی اثر تغییر بر برنامه زمانی و هماهنگی با سایر پیمانکاران/سرویس‌ها"],"common_mistakes":["اجرای تغییر مسیر صرفاً با توافق شفاهی با پیمانکار یا مالک زمین","فراموش کردن به‌روزرسانی KP/مارکرها پس از تغییر","عدم بررسی تداخل مسیر جدید با کراسینگ‌های موجود"],"standard_reference":""},{"category":"GENERAL","sub_category":"تصمیم‌گیری تحت فشار زمانی","difficulty":"L3","question_text":"در شرایطی که پروژه به شدت عقب افتاده و مدیریت پروژه فشار می‌آورد که تست هیدرواستاتیک یک بخش زودتر از موعد و پیش از تکمیل تمام بازرسی‌های بصری جوش انجام شود، شما به عنوان ناظر چه تصمیمی می‌گیرید و چگونه با فشار مدیریتی برخورد می‌کنید؟","reference_answer":"توالی صحیح کنترل کیفیت (بازرسی بصری، NDE، تایید Field Joint Coating) پیش‌نیاز ورود به مرحله هیدروتست است و فشار زمانی نباید باعث حذف یا دور زدن این توالی شود، چرا که ریسک آسیب به یکپارچگی خط و هزینه تکرار تست بسیار بیشتر از هزینه تاخیر کوتاه‌مدت است. ناظر باید موضع خود را با استناد به مشخصات فنی پروژه و رویه تایید‌شده QC به صورت مکتوب به مدیریت اعلام کند و ریسک‌های فنی و ایمنی (به‌ویژه ریسک ترکیدگی حین تست در صورت وجود جوش معیوب پنهان) را شفاف توضیح دهد. در صورت اصرار مدیریت، باید موضوع را از طریق زنجیره گزارش‌دهی رسمی (مثلاً به مهندس ارشد پروژه یا کارفرما) escalate کند و تصمیم نهایی و مسئولیت آن را مستند نماید. هدف، نه لجبازی بلکه محافظت از ایمنی و کیفیت با ابزار مستندسازی و ارتباط رسمی است.","key_points":["عدم پذیرش حذف توالی QC به دلیل فشار برنامه","استناد به مشخصات فنی و رویه تایید شده","توضیح شفاف ریسک ایمنی هیدروتست با جوش بازرسی‌نشده","مستندسازی موضع فنی و escalation رسمی","عدم تصمیم‌گیری شفاهی یا غیرمستند تحت فشار"],"excellent_answer_indicators":["تمایز روشن بین انعطاف در برنامه‌ریزی و انعطاف در کیفیت/ایمنی","ارائه راه‌حل جایگزین برای جبران تاخیر بدون افت کیفیت (مثل موازی‌سازی منابع NDE)","اشاره به مسئولیت حرفه‌ای و قانونی ناظر در صورت وقوع حادثه"],"common_mistakes":["پذیرش فشار مدیریتی و رد شدن از بازرسی برای جلوگیری از تنش","برخورد صرفاً احساسی/تقابلی بدون مستندسازی و escalation رسمی","عدم توضیح ریسک فنی واقعی هیدروتست بدون بازرسی کامل"],"standard_reference":""},{"category":"GENERAL","sub_category":"ایمنی و توقف کار (Stop Work Authority)","difficulty":"L2","question_text":"در حین گشت میدانی، مشاهده می‌کنید که تیم پیمانکار در حال Lowering-in یک اسپول لوله بدون رعایت فاصله ایمنی کرین و بدون استفاده از تجهیزات حفاظتی مناسب برای کارگران داخل ترانشه است. اولین اقدام شما چیست و چه مسیری را برای پیگیری طی می‌کنید؟","reference_answer":"اولین و فوری‌ترین اقدام، توقف بی‌درنگ عملیات (Stop Work) و دور کردن پرسنل از منطقه خطر است، چرا که ایمنی جان افراد بر هر ملاحظه برنامه زمانی یا روابط کاری اولویت دارد. پس از رفع خطر آنی، باید موضوع را با مسئول HSE و سرپرست پیمانکار در محل مطرح کرد و علت ریشه‌ای (کمبود آموزش، نبود دستورالعمل Lifting Plan، یا عدم رعایت آن) بررسی شود. این رخداد باید به صورت مکتوب گزارش شود (گزارش نزدیک به حادثه/عدم انطباق ایمنی) و پیش از از سرگیری کار، اطمینان حاصل شود که اقدامات اصلاحی (بازآموزی، اصلاح Lifting Plan، حضور Banksman) اجرا شده است. ناظر باید این موضوع را در سیستم گزارش‌دهی HSE پروژه نیز ثبت و پیگیری کند تا از تکرار آن جلوگیری شود.","key_points":["توقف فوری کار و اولویت ایمنی جان افراد","دور کردن کارگران از منطقه خطر","گزارش مکتوب و بررسی علت ریشه‌ای","الزام اقدام اصلاحی قبل از از سرگیری کار","هماهنگی با تیم HSE پروژه","پیگیری برای جلوگیری از تکرار"],"excellent_answer_indicators":["تاکید بر اختیار توقف کار (Stop Work Authority) به عنوان مسئولیت هر ناظر صرف‌نظر از سلسله‌مراتب","اشاره به بررسی Lifting Plan و صلاحیت اپراتور کرین","پیگیری سیستمی برای جلوگیری از تکرار در سایر جبهه‌های کاری"],"common_mistakes":["ادامه دادن مشاهده بدون توقف فوری کار","صرفاً تذکر شفاهی بدون گزارش مکتوب","نادیده گرفتن موضوع به دلیل روابط کاری با پیمانکار"],"standard_reference":""},{"category":"TECHNICAL","sub_category":"Route / ROW","difficulty":"L1","question_text":"عرض ROW (Right of Way) در پروژه‌های خط لوله انتقال گاز معمولاً بر چه اساسی تعیین می‌شود و چرا کنترل تجاوز به حریم (Encroachment) در حین ساخت اهمیت دارد؟ اگر متوجه شوید پیمانکار در بخشی از مسیر خارج از محدوده ROW مصوب دپوی مصالح ایجاد کرده، چه می‌کنید؟","reference_answer":"عرض ROW بر اساس مشخصات فنی پروژه، قطر و فشار خط، نیاز به دسترسی ماشین‌آلات حین ساخت و الزامات ایمنی/فاصله از سازه‌های مجاور تعیین می‌شود و در نقشه‌های مصوب (Alignment Sheet) مشخص شده است. کنترل تجاوز به حریم اهمیت دارد چون هرگونه تصرف خارج از محدوده مجاز می‌تواند منجر به مسائل حقوقی با مالکان زمین، نقض مجوزهای محیط‌زیستی و آسیب به اراضی کشاورزی یا طبیعی شود که همگی هزینه و ریسک پروژه را افزایش می‌دهند. در صورت مشاهده چنین تخلفی، ناظر باید فوراً موضوع را ثبت و به پیمانکار برای جمع‌آوری و انتقال دپو به داخل محدوده مجاز اطلاع دهد، موضوع را در گزارش روزانه و در صورت لزوم به صورت NCR مستند کند و در صورت بروز خسارت به زمین مجاور، هماهنگی با واحد امور اراضی/محیط‌زیست پروژه برای جبران خسارت انجام شود.","key_points":["مبنای تعیین عرض ROW از مشخصات فنی و نقشه مصوب","ریسک حقوقی و محیط‌زیستی تجاوز به حریم","الزام ثبت و اصلاح فوری تخلف دپو خارج از ROW","هماهنگی با واحد اراضی/محیط‌زیست در صورت خسارت","مستندسازی از طریق گزارش/NCR"],"excellent_answer_indicators":["اشاره به تفاوت عرض ROW دائم و موقت (Temporary Work Space)","توجه به الزامات محیط‌زیستی و بازگرداندن زمین به وضعیت اولیه (Reinstatement)","پیش‌بینی مسائل حقوقی آینده با مالکان زمین"],"common_mistakes":["نادیده گرفتن تجاوز جزئی به حریم به دلیل کم‌اهمیت پنداشتن آن","عدم تفکیک ROW دائم از فضای کاری موقت","عدم مستندسازی و صرفاً تذکر شفاهی"],"standard_reference":""},{"category":"TECHNICAL","sub_category":"Survey / KP-Chainage","difficulty":"L2","question_text":"در حین بازرسی میدانی متوجه می‌شوید که KP ثبت‌شده روی یک مارکر موقت با KP محاسبه‌شده بر اساس نقشه Alignment Sheet حدود ۱۵ متر اختلاف دارد. این موضوع چه اهمیتی دارد و چه اقداماتی برای ریشه‌یابی و اصلاح آن انجام می‌دهید؟","reference_answer":"سیستم KP/Chainage مرجع اصلی موقعیت‌یابی تمام اجزای خط لوله از جمله جوش‌ها، کراسینگ‌ها، شیرها و نقاط تعمیر است، بنابراین هرگونه خطا در آن می‌تواند در آینده باعث اشتباه در عملیات نگهداری، ابزار هوشمند خط‌لوله (Pigging/ILI) و مدیریت یکپارچگی خط شود. ابتدا باید با تیم نقشه‌برداری هماهنگ شود تا موقعیت واقعی با GPS/توتال‌استیشن مجدداً برداشت و با مبدأ مسیر (Start KP) و نقشه Alignment Sheet تطبیق داده شود تا مشخص شود اختلاف ناشی از خطای برداشت اولیه، جابجایی فیزیکی مسیر، یا اشتباه در نصب مارکر است. در صورت تایید خطا، مارکر و مستندات مرتبط (گزارش‌های روزانه، نقشه‌های As-built) باید اصلاح شوند و اگر اختلاف ناشی از تغییر واقعی مسیر بوده، باید فرآیند مدیریت تغییر و تایید مهندسی طی شود. این موضوع باید به صورت مکتوب ثبت و به تیم مهندسی گزارش شود تا از تکرار در سایر بخش‌های مسیر جلوگیری شود.","key_points":["اهمیت KP به عنوان مرجع موقعیت‌یابی برای عملیات و نگهداری آینده","نیاز به راستی‌آزمایی مجدد با نقشه‌برداری دقیق","ریشه‌یابی علت اختلاف (خطای برداشت، جابجایی مسیر، خطای نصب)","اصلاح مارکر و به‌روزرسانی مستندات/As-built","گزارش به تیم مهندسی و بررسی سایر بخش‌های مسیر برای خطای مشابه"],"excellent_answer_indicators":["اشاره به تاثیر خطای KP بر عملیات ILI/Pigging و مدیریت یکپارچگی آینده","بررسی سیستماتیک سایر مارکرهای مجاور برای اطمینان از عدم تکرار خطا","تفکیک دقیق بین خطای اداری/نقشه‌برداری و تغییر واقعی مسیر"],"common_mistakes":["اصلاح مارکر بدون بررسی علت ریشه‌ای","نادیده گرفتن اختلاف کوچک به این بهانه که تاثیر عملیاتی ندارد","عدم اطلاع‌رسانی به تیم مهندسی/نقشه‌برداری"],"standard_reference":""},{"category":"TECHNICAL","sub_category":"Stringing","difficulty":"L1","question_text":"در عملیات Stringing (چیدمان لوله در طول مسیر)، چه نکات کنترلی باید توسط ناظر رعایت شود تا از آسیب به پوشش خارجی لوله (Coating) و کیفیت لوله جلوگیری شود؟","reference_answer":"در مرحله Stringing، ناظر باید اطمینان حاصل کند که جابجایی و بارگذاری/تخلیه لوله‌ها تنها با تجهیزات مجاز مانند Side Boom یا Pipe Sling‌های غیرفلزی و لایه‌گذاری مناسب (Padded Slings) انجام می‌شود تا از خراش و ضربه به پوشش جلوگیری شود. لوله‌ها باید روی Skid‌های چوبی یا لاستیکی و با فاصله مناسب از سطح زمین و از یکدیگر چیده شوند تا هم از تماس مستقیم با سنگ و اجسام تیز جلوگیری شود و هم دسترسی برای جوشکاری و بازرسی بعدی فراهم باشد. همچنین باید کنترل شود که پوشش دو سر لوله (Bevel end) با درپوش محافظت شده و شماره هیت/لوله و گواهی متریال قابل ردیابی باقی بماند. هرگونه آسیب دیده‌شده به پوشش در این مرحله باید فوراً ثبت و طبق رویه تعمیر پوشش یا رد لوله معیوب تصمیم‌گیری شود.","key_points":["استفاده از تجهیزات و اسلینگ مناسب برای جلوگیری از آسیب پوشش","چیدمان روی Skid با فاصله مناسب از زمین و سنگ","حفظ ردیابی شماره لوله/هیت و گواهی متریال","محافظت از Bevel end دو سر لوله","بازرسی و مستندسازی آسیب احتمالی پوشش در این مرحله"],"excellent_answer_indicators":["اشاره به اثر آسیب پوشش نادیده‌گرفته‌شده در این مرحله بر خوردگی بلندمدت و کاتدیک پروتکشن","توجه به ترتیب چیدمان متناسب با توالی جوشکاری برای کاهش جابجایی مجدد","تاکید بر ردیابی کامل متریال تا سطح گزارش تحویل"],"common_mistakes":["توجه فقط به سرعت اجرا و نادیده گرفتن نحوه چیدمان روی زمین","عدم بازرسی پوشش بعد از هر جابجایی","نادیده گرفتن ردیابی شماره لوله/هیت"],"standard_reference":""},{"category":"TECHNICAL","sub_category":"Bending","difficulty":"L2","question_text":"پیمانکار برای عبور از یک تغییر جهت افقی در مسیر، به جای استفاده از فیتینگ خمی (Elbow) پیش‌ساخته، قصد دارد از خم سرد میدانی (Cold Field Bending) استفاده کند. به عنوان ناظر چه پارامترهایی را برای تایید این روش کنترل می‌کنید و در چه شرایطی خم انجام‌شده را رد می‌کنید؟","reference_answer":"ابتدا باید بررسی شود که شعاع خم درخواستی در محدوده مجاز مشخصات فنی پروژه (معمولاً بر اساس قطر اسمی لوله، مانند حداقل شعاع خم چند برابر قطر) و ظرفیت دستگاه خم‌کن تاییدشده باشد و عملیات توسط اپراتور و رویه (Bending Procedure) تاییدشده انجام شود. حین اجرا باید از عدم بروز چین‌خوردگی (Wrinkle)، تخت‌شدگی مقطع (Ovality) بیش از حد مجاز، و آسیب به پوشش در ناحیه خم اطمینان حاصل شود؛ معمولاً ovality بیش از حد مشخصات فنی (رایج بین ۲.۵ تا ۳ درصد بسته به پروژه) و هرگونه چین‌خوردگی قابل مشاهده دلیل رد قطعه است. همچنین باید فاصله خم از درز جوش طولی لوله (Seam) و از انتهای لوله برای امکان جوشکاری بعدی رعایت شود. در صورت عدم انطباق با هر یک از این معیارها، قطعه باید کنار گذاشته شده و از قطعه جدید استفاده شود، چون تلاش برای اصلاح خم معیوب معمولاً مجاز نیست.","key_points":["تایید شعاع خم مطابق مشخصات فنی و قطر لوله","کنترل Ovality و عدم وجود چین‌خوردگی (Wrinkle)","رعایت فاصله خم از درز جوش طولی و انتهای لوله","استفاده از رویه و اپراتور تاییدشده","رد قطعه معیوب به‌جای تلاش برای اصلاح آن"],"excellent_answer_indicators":["ذکر محدوده عددی تقریبی Ovality مجاز و آگاهی به تفاوت آن بین پروژه‌ها/مشخصات فنی","اشاره به بازرسی پوشش پس از خم و لزوم ترمیم یا رد","تاکید بر عدم مجاز بودن اصلاح خم معیوب"],"common_mistakes":["عدم بررسی Ovality و تمرکز فقط بر ظاهر خم","قبول قطعه دارای چین‌خوردگی جزئی به این بهانه که در فشار کارکرد مشکلی ایجاد نمی‌کند","نادیده گرفتن فاصله مجاز خم از درز جوش لوله"],"standard_reference":"ASME B31.8"},{"category":"TECHNICAL","sub_category":"جوشکاری خط لوله / API 1104","difficulty":"L3","question_text":"در حین بازرسی چشمی جوش‌های مسیر، مشاهده می‌کنید که یک جوشکار به طور مکرر عیب Undercut در ناحیه Cap ایجاد می‌کند. به عنوان ناظر چه فرآیندی را برای پذیرش/رد جوش، تصمیم درباره تعمیر یا برش، و مدیریت صلاحیت جوشکار طی می‌کنید؟","reference_answer":"ابتدا باید ابعاد Undercut (عمق و طول) با معیارهای پذیرش مشخصات فنی پروژه و استاندارد مرجع (معمولاً API 1104) مقایسه شود تا مشخص گردد جوش قابل تعمیر است یا باید برش و مجدداً جوش شود؛ معمولاً Undercut‌های سطحی و محدود قابل تعمیر با سنگ‌زنی و جوش ترمیمی هستند اما اگر عمق از حد مجاز فراتر رود یا طول تجمعی زیاد باشد، برش الزامی است. پس از هر تعمیر، جوش باید مجدداً از نظر بصری و NDE (معمولاً RT یا UT) بازرسی و تایید شود و نمی‌توان بدون این بازرسی مجدد قطعه را به مرحله بعد فرستاد. از آنجا که این عیب به صورت تکرارشونده از یک جوشکار مشاهده شده، ناظر باید موضوع را به مسئول کنترل کیفیت پیمانکار اطلاع دهد تا صلاحیت و تکنیک جوشکار (احتمالاً تنظیم آمپراژ/زاویه الکترود) بازبینی و در صورت لزوم جوشکار موقتاً از خط تولید کنار گذاشته و بازآموزی/تست مجدد صلاحیت (WPQ) انجام شود؛ این اقدام از تکرار سیستماتیک عیب در کل مسیر جلوگیری می‌کند.","key_points":["مقایسه ابعاد Undercut با معیار پذیرش مشخصات فنی/استاندارد مرجع","تصمیم بین تعمیر (سنگ‌زنی و جوش ترمیمی) یا برش کامل بر اساس شدت عیب","الزام بازرسی مجدد بصری و NDE پس از هر تعمیر","برخورد سیستمی با تکرار عیب از یک جوشکار خاص","بازبینی صلاحیت جوشکار (WPQ) در صورت تکرار عیب","ثبت و پیگیری روند از طریق مستندات کیفیت"],"excellent_answer_indicators":["اشاره دقیق به مفهوم محدودیت تعداد تعمیر مجاز روی یک جوش","تشخیص علت ریشه‌ای احتمالی (پارامتر جوشکاری، زاویه) نه فقط برخورد با نتیجه","تاکید بر جلوگیری از اثر سیستمی با بازآموزی/توقف موقت جوشکار به جای برخورد مورد به مورد"],"common_mistakes":["پذیرش جوش با Undercut بدون اندازه‌گیری دقیق صرفاً بر اساس مشاهده ظاهری","تعمیر مکرر یک جوش بدون محدودیت","عدم اطلاع به کنترل کیفیت درباره تکرار عیب از یک جوشکار خاص"],"standard_reference":"API 1104"},{"category":"TECHNICAL","sub_category":"NDE","difficulty":"L3","question_text":"گزارش رادیوگرافی (RT) یک جوش، عیب Lack of Fusion با طول محدود را نشان می‌دهد اما پیمانکار استدلال می‌کند که چون طول عیب کمتر از حد بحرانی جدول پذیرش است، جوش باید پذیرفته شود. شما به عنوان ناظر چگونه این ادعا را بررسی و تصمیم‌گیری می‌کنید؟","reference_answer":"نکته کلیدی این است که Lack of Fusion برخلاف برخی عیوب حجمی مانند تخلخل، به دلیل ماهیت تخت و لبه‌تیز آن به عنوان یک عیب برنامه‌ای (Planar Defect) با ریسک بالای تمرکز تنش شناخته می‌شود و معیارهای پذیرش آن در استانداردهایی مانند API 1104 معمولاً محدودتر و حساس‌تر از عیوب حجمی است. ناظر باید ابتدا فیلم RT را با پرسنل واجد صلاحیت NDE Level II/III بازبینی کند تا نوع دقیق عیب (Lack of Fusion به جای مثلاً Slag) و طول واقعی آن با دقت تایید شود، سپس آن را دقیقاً با جدول پذیرش مشخصات فنی پروژه (که ممکن است سخت‌گیرانه‌تر از حداقل استاندارد باشد) مقایسه کند، نه صرفاً استدلال کلی پیمانکار. تصمیم نهایی باید بر اساس این تطبیق دقیق و مکتوب باشد؛ اگر طول واقعی عیب واقعاً کمتر از حد مجاز مشخصات پروژه باشد، پذیرش قابل توجیه است، اما این تایید باید توسط مسئول کیفیت/NDE مستند و امضا شود، نه بر اساس ادعای شفاهی پیمانکار.","key_points":["تشخیص ماهیت بحرانی‌تر عیوب برنامه‌ای (Planar) مانند Lack of Fusion نسبت به عیوب حجمی","لزوم بازبینی مستقل فیلم RT توسط پرسنل واجد صلاحیت NDE","تطبیق دقیق طول عیب با جدول پذیرش مشخصات فنی پروژه، نه استدلال کلی","امکان سخت‌گیرتر بودن مشخصات پروژه نسبت به حداقل استاندارد","مستندسازی و امضای رسمی تصمیم پذیرش/رد"],"excellent_answer_indicators":["تمایز فنی روشن بین عیوب برنامه‌ای و حجمی و دلیل حساسیت بیشتر به تمرکز تنش","تاکید بر اینکه مشخصات فنی پروژه می‌تواند سخت‌گیرتر از استاندارد پایه باشد و مرجع اصلی است","عدم تصمیم‌گیری صرفاً بر اساس عدد طول بدون توجه به نوع عیب و موقعیت آن"],"common_mistakes":["پذیرش جوش صرفاً بر اساس مقایسه طول عیب بدون توجه به نوع آن","پذیرفتن استدلال شفاهی پیمانکار بدون بازبینی مستقل فیلم","عدم توجه به این‌که مشخصات فنی پروژه ممکن است سخت‌گیرتر از استاندارد پایه باشد"],"standard_reference":"API 1104"},{"category":"TECHNICAL","sub_category":"Field Joint Coating","difficulty":"L2","question_text":"پس از انجام پوشش محل اتصال جوش‌ها (Field Joint Coating) و پیش از Lowering-in، چه آزمون‌هایی باید انجام شود و اگر در تست هولیدی دیتکتور (Holiday Detection) نشتی الکتریکی پیدا کنید، چه اقدامی انجام می‌دهید؟","reference_answer":"پیش از Lowering-in، تمام سطح پوشش خط از جمله محل اتصالات جوش باید با دستگاه Holiday Detector با ولتاژ تنظیم‌شده مطابق نوع و ضخامت پوشش (بر اساس مشخصات فنی پروژه یا استاندارد سازنده پوشش) بازرسی شود تا حفره‌ها یا نقاط ضعیف پوشش (Holiday) که می‌توانند مسیر نفوذ رطوبت و خوردگی باشند شناسایی شوند. همچنین دمای سطح لوله و شرایط آب‌وهوایی (رطوبت، دمای محیط) باید در محدوده مجاز اجرای پوشش کنترل شده باشد. در صورت شناسایی Holiday، محل دقیق باید علامت‌گذاری، تعمیر پوشش طبق رویه تاییدشده (سنگ‌زنی سطح، تمیزکاری و اعمال پچ پوشش) انجام و سپس مجدداً تست هولیدی تکرار شود تا از رفع کامل عیب اطمینان حاصل شود. عبور از این مرحله بدون رفع کامل Holiday ریسک خوردگی زودهنگام و آسیب به عملکرد بلندمدت سیستم کاتدیک پروتکشن را در پی دارد.","key_points":["الزام تست Holiday Detection روی کل پوشش پیش از Lowering","کنترل ولتاژ تست متناسب با نوع/ضخامت پوشش","کنترل شرایط محیطی حین اجرای پوشش","تعمیر Holiday طبق رویه تاییدشده و تکرار تست پس از تعمیر","ارتباط پوشش سالم با عملکرد بلندمدت کاتدیک پروتکشن"],"excellent_answer_indicators":["اشاره به ارتباط مستقیم کیفیت پوشش با بار مصرفی سیستم CP در آینده (Current Demand)","تاکید بر ممنوعیت Lowering قبل از تایید نهایی رفع Holiday","آگاهی به تنظیم صحیح ولتاژ تست بر اساس ضخامت پوشش برای جلوگیری از آسیب کاذب به پوشش سالم"],"common_mistakes":["انجام تست هولیدی با ولتاژ ثابت بدون توجه به نوع/ضخامت پوشش","تعمیر Holiday بدون تکرار تست برای تایید رفع کامل عیب","اجازه Lowering قبل از تکمیل و تایید تست پوشش"],"standard_reference":""},{"category":"TECHNICAL","sub_category":"Crossing (Road / River)","difficulty":"L3","question_text":"در عبور خط لوله از یک رودخانه فصلی با روش حفاری هدایت‌شده افقی (HDD)، چه ریسک‌ها و نقاط کنترلی کلیدی از دید ناظر وجود دارد که این روش را از یک عبور معمولی روباز (Open Cut) متمایز می‌کند؟","reference_answer":"در روش HDD، ریسک اصلی از دید ناظر شامل کنترل مسیر حفاری Pilot Bore مطابق پروفیل عمقی طراحی‌شده (برای عبور ایمن از زیر بستر رودخانه با پوشش کافی)، کنترل فشار و بازگشت دوغاب حفاری (Drilling Mud) برای جلوگیری از پدیده Frac-out (نشت دوغاب به بستر یا اطراف رودخانه که آسیب محیط‌زیستی دارد)، و بازرسی کامل پوشش لوله پیش از Pull-back است، چون در این روش برخلاف Open Cut امکان بازرسی یا تعمیر پوشش پس از عبور لوله از داخل زمین عملاً وجود ندارد. بنابراین پیش از Pull-back باید تست هولیدی کامل پوشش و اتصال صحیح لوله‌ها (که معمولاً به صورت یک قطعه پیوسته جوش و تست شده‌اند) تایید شود. همچنین باید مانیتورینگ لحظه‌ای نیروی کشش (Pulling Force) در حین Pull-back کنترل شود تا از تنش بیش از حد مجاز روی لوله جلوگیری شود. در مقابل، در Open Cut ریسک‌ها بیشتر حول کنترل جریان آب، Dewatering ترانشه، پایداری دیواره و هماهنگی زمانی اجرا با فصل کم‌آبی رودخانه متمرکز است.","key_points":["کنترل پروفیل عمقی Pilot Bore برای پوشش کافی زیر بستر رودخانه","کنترل دوغاب حفاری و ریسک Frac-out","ضرورت بازرسی کامل پوشش پیش از Pull-back به دلیل عدم امکان تعمیر پس از آن","مانیتورینگ نیروی کشش حین Pull-back","تفاوت ریسک‌های Open Cut (کنترل جریان آب، Dewatering، پایداری ترانشه)"],"excellent_answer_indicators":["اشاره دقیق به Frac-out و اثرات محیط‌زیستی/مجوزی آن","تاکید بر غیرقابل‌برگشت بودن آسیب پوشش پس از Pull-back در HDD","توجه به هماهنگی زمانی عبور رودخانه با فصل کم‌آبی و مجوزهای محیط‌زیستی/آبی مربوطه"],"common_mistakes":["یکسان دانستن الزامات کنترلی HDD و Open Cut","نادیده گرفتن اهمیت بازرسی پوشش پیش از Pull-back","عدم توجه به ریسک محیط‌زیستی Frac-out"],"standard_reference":""},{"category":"TECHNICAL","sub_category":"Cathodic Protection (تحویل ساخت)","difficulty":"L4","question_text":"پیش از تحویل نهایی یک بخش از خط لوله به تیم بهره‌برداری، چه بررسی‌هایی باید در ارتباط با آمادگی خط برای سیستم حفاظت کاتدیک (Cathodic Protection) از دید ناظر ساخت انجام شود تا از عملکرد صحیح CP پس از راه‌اندازی اطمینان حاصل شود؟","reference_answer":"از آنجا که اثربخشی سیستم CP به شدت به یکپارچگی پوشش لوله وابسته است، ناظر ساخت باید اطمینان حاصل کند که تمام سوابق تست Holiday Detection (روی بدنه لوله و به‌ویژه محل اتصالات جوش) به صورت کامل و بدون نقطه رفع‌نشده در پرونده تحویل موجود است، چون هر Holiday باقی‌مانده به عنوان یک نقطه پرمصرف جریان کاتدیک عمل کرده و می‌تواند توزیع حفاظت را در کل خط مختل کند. همچنین باید بررسی شود که نقاط تست (Test Point) و اتصالات الکتریکی (Bond Wire) طبق نقشه در فواصل مشخص نصب و به لوله جوش (Cadweld) شده و مقاومت اتصال تایید شده باشد، و این نقاط در نقشه As-built به درستی مکان‌یابی شده باشند. عایق‌بندی الکتریکی در محل عبور از کراسینگ‌ها یا اتصال به تجهیزات دیگر (Isolation Joint/Kit) باید تست مقاومت عایق شده و نتیجه مستند باشد. در نهایت، هماهنگی با مهندس CP پروژه برای انجام تست پیش‌راه‌اندازی (Pre-commissioning Survey) و ثبت پتانسیل اولیه لوله نسبت به زمین باید پیش از تحویل رسمی انجام و در پرونده Handover درج شود.","key_points":["کامل بودن سوابق Holiday Detection بدون نقطه رفع‌نشده","بررسی نصب و اتصال صحیح Test Point و Bond Wire طبق نقشه","تست و مستندسازی مقاومت عایق در Isolation Joint/Kit","هماهنگی با مهندس CP برای Pre-commissioning Survey","درج کامل مستندات CP در پرونده Handover"],"excellent_answer_indicators":["توضیح روشن رابطه علّی بین آسیب پوشش رفع‌نشده و افزایش بار مصرفی/ناکارآمدی سیستم CP","اشاره به تست مقاومت عایق Isolation Joint به عنوان نقطه بحرانی اغلب فراموش‌شده","تاکید بر لزوم انجام Pre-commissioning Survey پیش از تحویل رسمی، نه پس از آن"],"common_mistakes":["محدود کردن بررسی CP فقط به نصب فیزیکی تجهیزات بدون تایید عملکرد الکتریکی","نادیده گرفتن اثر Holiday‌های رفع‌نشده بر عملکرد آینده CP","عدم هماهنگی با مهندس CP پیش از تحویل و واگذاری این مسئولیت کامل به بعد از بهره‌برداری"],"standard_reference":""},{"category":"SCENARIO","sub_category":"Lowering-in / Backfilling / عمق دفن","difficulty":"L3","question_text":"در یک کیلومتر مشخص از مسیر (مثلاً KP 45+300)، پس از انجام Lowering-in و پیش از تکمیل Backfilling، متوجه می‌شوید که عمق دفن روی تاج لوله (Depth of Cover) کمتر از مقدار مشخص‌شده در نقشه و مشخصات فنی پروژه است. به عنوان ناظر چه اقداماتی انجام می‌دهید؟","reference_answer":"اولین اقدام، توقف ادامه Backfilling در آن قطعه و اندازه‌گیری دقیق و مستند عمق واقعی دفن با ابزار نقشه‌برداری در چند نقطه طول قطعه است تا مشخص شود انحراف موضعی است یا در طول قابل توجهی از مسیر تکرار شده. سپس مقدار اندازه‌گیری‌شده باید با حداقل عمق مجاز مندرج در مشخصات فنی پروژه و نقشه (که معمولاً بسته به نوع منطقه عبور مانند زراعی، جاده یا کراسینگ متفاوت است) مقایسه و مغایرت به صورت رسمی از طریق NCR ثبت شود. اقدام اصلاحی بسته به علت انحراف (کف‌بری ناکافی ترانشه یا خطای نقشه‌برداری) تعیین می‌شود؛ معمول‌ترین راه‌حل، خارج کردن لوله از ترانشه (Uncover/Re-lower) و عمیق‌تر کردن کف ترانشه تا رسیدن به عمق مجاز است، مگر اینکه به دلایل فنی (مثل وجود سنگ بستر) این کار ممکن نباشد که در آن صورت راه‌حل جایگزین مانند افزایش پوشش با روکش بتنی یا صفحه محافظ پس از تایید طراح قابل بررسی است، نه تصمیم یک‌جانبه ناظر یا پیمانکار. پس از اجرای اصلاح، عمق باید مجدداً اندازه‌گیری و تایید شود، نتیجه در نقشه As-built ثبت گردد و با توجه به اهمیت این پارامتر برای یکپارچگی و ایمنی بلندمدت خط، بستن ترانشه فقط پس از تایید نهایی مجاز است.","key_points":["توقف فوری ادامه Backfilling تا رفع ابهام","اندازه‌گیری دقیق و مستند عمق واقعی در چند نقطه","مقایسه با حداقل عمق مجاز مشخصات فنی/نقشه بر اساس نوع منطقه عبور","ثبت مغایرت به صورت NCR رسمی","اقدام اصلاحی مهندسی‌شده (Re-lower/عمیق‌تر کردن یا راه‌حل جایگزین تاییدشده)","تایید مجدد و ثبت در As-built پیش از تکمیل Backfill","توجه به اثر بلندمدت بر یکپارچگی و ایمنی خط"],"excellent_answer_indicators":["تاکید بر عدم تصمیم یک‌جانبه و لزوم تایید طراح/مهندسی برای هر راه‌حل جایگزین غیر از عمیق‌تر کردن ترانشه","بررسی سیستماتیک طول مسیر برای اطمینان از عدم تکرار مشکل در قطعات مجاور","اشاره به ریسک بلندمدت آسیب مکانیکی به لوله در صورت عدم رفع مغایرت","ثبت کامل در As-built برای مرجع عملیات و نگهداری آینده"],"common_mistakes":["نادیده گرفتن انحراف جزئی عمق بدون مستندسازی رسمی","تکمیل Backfill قبل از تایید نهایی رفع مغایرت","انتخاب راه‌حل جایگزین (مثل روکش اضافه) بدون تایید مهندسی/طراح","عدم بررسی سایر قطعات مسیر برای مشکل مشابه"],"standard_reference":""},{"category":"PROBLEM_SOLVING","sub_category":"Hydrotest","difficulty":"L4","question_text":"در حین تست هیدرواستاتیک یک قطعه بین دو شیر مسدودکننده، افت فشار بیش از حد مجاز در طول دوره پایداری (Stabilization/Test Period) مشاهده می‌شود اما هیچ نشتی قابل مشاهده در سطح زمین وجود ندارد. به عنوان ناظر چگونه این وضعیت را ریشه‌یابی و مدیریت می‌کنید؟","reference_answer":"ابتدا باید بررسی شود که افت فشار مشاهده‌شده واقعی است یا ناشی از عوامل غیرمرتبط با نشتی مانند تغییرات دمای آب/محیط طی دوره تست است، چرا که رویه استاندارد معمولاً اصلاح فشار بر اساس دما (Temperature Correction) را الزامی می‌داند و باید ابتدا این تصحیح روی داده‌ها اعمال شود. اگر پس از تصحیح دمایی همچنان افت فشار غیرمجاز باقی بماند، باید احتمال نشتی پنهان (مثلاً از یک اتصال زیرزمینی، شیر End Cap، یا حتی ترک ریز در جوش) در نظر گرفته شود و بازرسی از نقاط اتصال قابل دسترس (End Closures، Tie-in‌های موقت، شیرهای test manifold) شروع شود، سپس در صورت عدم یافتن مورد مشهود، ممکن است نیاز به تقسیم قطعه به بخش‌های کوچک‌تر (Sectionalizing) با استفاده از پیگ‌های جداکننده یا شیرهای موقت برای مکان‌یابی دقیق‌تر بخش دارای نشتی باشد. تمام این فرآیند باید مستند شود و تحت هیچ شرایطی نباید بدون ریشه‌یابی و تایید رفع علت، تست به عنوان قبول‌شده اعلام یا فشار به صورت غیرمجاز جبران/دستکاری شود، چون این کار مستقیماً یکپارچگی و ایمنی بهره‌برداری آینده خط را به خطر می‌اندازد.","key_points":["بررسی و اعمال تصحیح دمایی روی داده‌های افت فشار پیش از هر نتیجه‌گیری","عدم پذیرش تست بدون ریشه‌یابی کامل حتی در نبود نشتی قابل مشاهده","بازرسی نقاط اتصال و End Closures به عنوان اولین مظنون","استفاده از تکنیک Sectionalizing برای مکان‌یابی دقیق‌تر در صورت نیاز","مستندسازی کامل فرآیند ریشه‌یابی","ممنوعیت قطعی دستکاری/جبران فشار برای قبولاندن تست"],"excellent_answer_indicators":["دانش دقیق از مفهوم Temperature Correction و لزوم اعمال آن پیش از قضاوت درباره افت فشار","رویکرد سیستماتیک Sectionalizing برای مکان‌یابی نشتی نامرئی","تاکید صریح بر ممنوعیت اکید هرگونه دستکاری داده یا فشار تست","آگاهی به ریسک ایمنی/یکپارچگی ناشی از پذیرش نسنجیده تست"],"common_mistakes":["نتیجه‌گیری فوری که چون نشتی دیده نمی‌شود پس تست قابل قبول است","نادیده گرفتن نیاز به تصحیح دمایی داده‌های فشار","پیشنهاد یا پذیرش دستکاری فشار برای گذراندن تست تحت فشار زمانی"],"standard_reference":"ASME B31.8"},{"category":"SCENARIO","sub_category":"Road Crossing","difficulty":"L3","question_text":"در نزدیکی یک بزرگراه اصلی، پیمانکار برای عبور خط لوله مجوز بستن موقت یک باند جاده را از اداره راه دریافت کرده، اما هنگام اجرا مشخص می‌شود که روش اجرای واقعی (حفاری روباز به‌جای Casing/Boring پیش‌بینی‌شده در مجوز) با آنچه در مجوز و نقشه تاییدشده آمده، مغایرت دارد. شما به عنوان ناظر چه تصمیمی می‌گیرید؟","reference_answer":"ناظر باید فوراً عملیات را متوقف کند، چون اجرای روشی متفاوت از آنچه در مجوز رسمی اداره راه و نقشه مهندسی تاییدشده آمده، هم ریسک حقوقی (نقض مجوز) و هم ریسک ایمنی (پایداری روسازی جاده، بار ترافیکی) و هم ریسک فنی (عدم انطباق با عمق پوشش و نوع محافظت پیش‌بینی‌شده برای عبور جاده) به همراه دارد. باید موضوع فوراً به تیم مهندسی و مدیریت پروژه اطلاع داده شود تا مشخص گردد آیا روش جدید از نظر فنی قابل قبول است یا خیر؛ در صورت تمایل به تغییر روش اجرا، باید ابتدا با اداره راه هماهنگی مجدد و اصلاح مجوز انجام شود و نقشه مهندسی نیز به‌روزرسانی و تایید گردد، پیش از آنکه اجرا با روش جدید ادامه یابد. تحت هیچ شرایطی ناظر نباید صرفاً بر اساس توجیه پیمانکار (مثل سرعت یا هزینه کمتر Open Cut) اجازه ادامه کار مغایر با مجوز رسمی را بدهد، چون مسئولیت حقوقی و ایمنی این تصمیم متوجه پروژه و کارفرما خواهد بود.","key_points":["توقف فوری کار به دلیل مغایرت با مجوز رسمی و نقشه تاییدشده","شناسایی ریسک‌های حقوقی، ایمنی و فنی ناشی از تغییر روش بدون تایید","الزام هماهنگی مجدد با اداره راه و اصلاح رسمی مجوز پیش از ادامه کار","به‌روزرسانی و تایید نقشه مهندسی متناسب با روش جدید","عدم پذیرش توجیهات هزینه/زمان پیمانکار به عنوان دلیل کافی برای تخطی"],"excellent_answer_indicators":["تشخیص روشن تفاوت ریسک فنی/ایمنی بین Open Cut و Boring/Casing زیر جاده با ترافیک فعال","تاکید بر مسئولیت حقوقی پروژه/کارفرما در قبال نقض مجوز رسمی مقام ذی‌صلاح","مدیریت فعال ارتباط بین اداره راه، مهندسی و پیمانکار برای حل سریع بدون توقف طولانی غیرضروری"],"common_mistakes":["اجازه ادامه کار با توجیه صرفه‌جویی در زمان یا هزینه","عدم اطلاع‌رسانی فوری به مهندسی/مدیریت پروژه","نادیده گرفتن ریسک ایمنی روسازی جاده و ترافیک عبوری"],"standard_reference":""},{"category":"SCENARIO","sub_category":"Field Joint Coating / بازرسی پس از Lowering","difficulty":"L2","question_text":"بلافاصله پس از Lowering-in یک قطعه لوله و پیش از شروع Backfilling، بازرسی نهایی نشان می‌دهد در یک نقطه از بدنه لوله (نه محل جوش) آسیب فیزیکی به پوشش (خراشیدگی عمیق) در اثر تماس با سنگ کف ترانشه ایجاد شده است. چه تصمیمی می‌گیرید؟","reference_answer":"باید بلافاصله ادامه Backfilling در آن قطعه متوقف شود تا آسیب بررسی و ترمیم شود، چون دفن پوشش آسیب‌دیده بدون ترمیم مستقیماً منجر به نقطه شروع خوردگی زودهنگام خواهد شد. ابتدا محل و ابعاد آسیب (طول، عمق نفوذ در ضخامت پوشش، و اینکه آیا به فلز پایه لوله رسیده یا خیر) دقیق ثبت و عکس‌برداری می‌شود، سپس طبق رویه تعمیر پوشش تاییدشده پروژه (تمیزکاری، آماده‌سازی سطح و اعمال پچ پوشش هم‌نوع یا سازگار) ترمیم انجام و بلافاصله تست Holiday Detection مجدد بر روی ناحیه ترمیم‌شده انجام می‌شود. علاوه بر این، باید علت ریشه‌ای (وجود سنگ در بستر ترانشه یا کافی نبودن لایه شن/ماسه Padding زیر لوله) بررسی و اصلاح شود، زیرا در غیر این صورت ممکن است سایر نقاط قطعه نیز آسیب مشابه دیده باشند که باید بازرسی شوند. تنها پس از تایید ترمیم و تست هولیدی موفق، اجازه ادامه Backfilling صادر می‌شود.","key_points":["توقف Backfilling تا ترمیم و تایید کامل آسیب پوشش","ثبت دقیق ابعاد و شدت آسیب پیش از ترمیم","ترمیم طبق رویه تاییدشده و تست هولیدی مجدد پس از ترمیم","بررسی علت ریشه‌ای (کمبود Padding یا وجود سنگ در بستر ترانشه)","بازرسی سایر نقاط قطعه برای آسیب مشابه احتمالی"],"excellent_answer_indicators":["اشاره به لزوم بررسی کافی بودن لایه Padding/بستر شنی زیر و اطراف لوله برای جلوگیری از تکرار آسیب","تاکید بر تست هولیدی الزامی پس از هر ترمیم پیش از تایید نهایی","رویکرد پیشگیرانه با بازرسی کامل بقیه طول قطعه، نه فقط نقطه مشاهده‌شده"],"common_mistakes":["نادیده گرفتن خراش سطحی به این بهانه که عمق نفوذ کم است","ترمیم پوشش بدون تست هولیدی مجدد پس از ترمیم","عدم بررسی علت ریشه‌ای (کیفیت بستر ترانشه) و تکرار مشکل در ادامه مسیر"],"standard_reference":""},{"category":"PROBLEM_SOLVING","sub_category":"MLV / Tie-in","difficulty":"L4","question_text":"در حین نصب یک شیر مسدودکننده اصلی (MLV) در یک ایستگاه، هنگام Tie-in نهایی به خط لوله مشخص می‌شود که محور فلنج ورودی شیر با محور لوله موجود حدود ۱.۵ درجه زاویه دارد (Misalignment) که باعث ایجاد تنش هنگام جفت‌کردن فلنج‌ها شده است. شما به عنوان ناظر چه تصمیمی می‌گیرید و چرا اجباری کردن اتصال با نیروی مکانیکی (Forcing) روش قابل قبولی نیست؟","reference_answer":"هرگونه اتصال فلنج با استفاده از نیروی مکانیکی (Forcing) برای جبران عدم هم‌محوری روش غیرقابل قبولی است، چون تنش پسماند حاصل می‌تواند در بلندمدت باعث نشتی از گسکت، شکست خستگی در پیچ‌ها یا حتی ترک در جوش‌های مجاور و اتصالات شیر شود که با توجه به نقش حیاتی MLV در ایمنی خط (توانایی قطع اضطراری جریان)، ریسک بسیار بالایی محسوب می‌شود. ناظر باید ابتدا کار Tie-in را متوقف کرده و با اندازه‌گیری دقیق (با استفاده از لیزر یا ابزار Alignment) میزان و جهت واقعی عدم هم‌محوری را مستند و علت آن (خطای نصب پایه شیر، خطای نقشه‌برداری در موقعیت لوله، یا تلرانس تجمعی جوش‌های قبلی) را ریشه‌یابی کند. راه‌حل مهندسی‌شده باید توسط تیم طراحی ارائه شود، که می‌تواند شامل استفاده از یک قطعه اسپول اصلاحی (Swage/Spool Piece) با زاویه مناسب، یا اصلاح موقعیت پایه شیر باشد؛ انتخاب راه‌حل نهایی و تایید آن باید مستند و پیش از ادامه Tie-in دریافت شود.","key_points":["ممنوعیت اتصال با نیروی مکانیکی به دلیل ریسک تنش پسماند و شکست خستگی","توقف کار و اندازه‌گیری دقیق میزان/جهت Misalignment","ریشه‌یابی علت (نصب پایه، نقشه‌برداری، تلرانس تجمعی جوش‌ها)","نیاز به راه‌حل مهندسی‌شده (اسپول اصلاحی یا اصلاح پایه) با تایید طراحی","توجه ویژه به نقش حیاتی MLV در ایمنی و قطع اضطراری خط"],"excellent_answer_indicators":["توضیح دقیق مکانیزم شکست ناشی از تنش پسماند (خستگی پیچ، نشتی گسکت)","تاکید بر اهمیت ویژه دقت در تراز MLV به دلیل نقش ایمنی حیاتی آن","ارائه راه‌حل مشخص فنی (Swage/Spool اصلاحی) به‌جای صرفاً گفتن باید بررسی شود"],"common_mistakes":["پذیرش استفاده از جک یا کشش مکانیکی برای نزدیک کردن فلنج‌ها","دست کم گرفتن ۱.۵ درجه انحراف به این دلیل که عدد کوچکی است","عدم ریشه‌یابی علت انحراف و اکتفا به رفع موضعی"],"standard_reference":""},{"category":"EXPERIENCE_BASED","sub_category":"جوشکاری/NDE - تجربه واقعی","difficulty":"L3","question_text":"یک تجربه واقعی از پروژه‌ای که در آن با نرخ رد جوش (Weld Rejection Rate) غیرعادی بالا در یک جبهه کاری مواجه شدید را شرح دهید. مشکل چه بود، چگونه ریشه‌یابی کردید و نتیجه نهایی چه شد؟","reference_answer":"این پاسخ باید بر اساس معیارهای ارزیابی زیر سنجیده شود، نه تطبیق با یک داستان مشخص: آیا کاندیدا شرح دقیق و واقعی از یک تجربه عینی (نه فرضی) ارائه می‌دهد که شامل جزئیات قابل تایید مانند نوع خط، مرحله پروژه و نقش خودش باشد؛ آیا در تشخیص علت ریشه‌ای مشکل (مثلاً پارامتر جوشکاری، کیفیت WPS/WPQ، تجهیزات، شرایط محیطی یا کیفیت متریال) رویکرد سیستماتیک و مبتنی بر داده (بررسی گزارش‌های NDE، الگوی عیوب) نشان می‌دهد؛ آیا اقدام اصلاحی متخذشده بر اساس رویه‌های استاندارد (مانند بازآموزی، اصلاح WPS، تعویض تجهیزات) و مستندسازی صحیح (NCR، گزارش کیفیت) بوده است؛ آیا نتیجه نهایی و اثر کمی آن (مثلاً کاهش درصد رد از X به Y) به وضوح بیان می‌شود؛ و در نهایت آیا کاندیدا درس گرفته‌شده (Lesson Learned) و اقدام پیشگیرانه برای پروژه‌های بعدی را نیز مطرح می‌کند.","key_points":["واقعی و قابل جزئیات بودن تجربه (نه پاسخ کلی/فرضی)","رویکرد سیستماتیک و مبتنی بر داده در ریشه‌یابی","اقدام اصلاحی مستند و منطبق با رویه‌های استاندارد کیفیت","بیان نتیجه نهایی قابل‌سنجش","استخراج درس آموخته و اقدام پیشگیرانه","آگاهی به مسیر مستندسازی (NCR/گزارش کیفیت)"],"excellent_answer_indicators":["ارائه اعداد/درصد مشخص برای نشان دادن بهبود حاصل‌شده","نشان دادن تفکر سیستمی (اثر اصلاح بر کل پروژه، نه فقط یک جوش)","تسلط به استاندارد مرجع مرتبط هنگام توضیح معیار پذیرش/رد","نشان دادن نقش فعال و ابتکار شخصی، نه صرفاً گزارش‌دهنده منفعل"],"common_mistakes":["ارائه پاسخ کلی/تئوریک بدون جزئیات واقعی از یک پروژه مشخص","نسبت دادن کل مسئولیت حل مشکل به تیم کیفیت بدون نشان دادن نقش شخصی","عدم ذکر نتیجه نهایی یا درس آموخته‌شده"],"standard_reference":""},{"category":"EXPERIENCE_BASED","sub_category":"Crossing - تجربه واقعی","difficulty":"L2","question_text":"یک چالش واقعی که در حین اجرای یک کراسینگ (رودخانه، جاده، راه‌آهن یا خط لوله/کابل دیگر) با آن مواجه شدید را شرح دهید. چه اتفاقی افتاد و شما چه نقشی در حل آن ایفا کردید؟","reference_answer":"پاسخ باید بر مبنای معیارهای ارزیابی زیر سنجیده شود، نه یک داستان ثابت: آیا کاندیدا یک موقعیت واقعی و مشخص (نوع کراسینگ، ذی‌نفعان درگیر مانند مالک تاسیسات مجاور یا مقام صادرکننده مجوز) را شرح می‌دهد؛ آیا چالش واقعی (فنی، هماهنگی مجوز، تداخل تاسیسات زیرزمینی ناشناخته، یا محدودیت زمانی) به‌درستی تشخیص داده شده؛ آیا اقدام کاندیدا مبتنی بر هماهنگی صحیح با ذی‌نفعان، رعایت مجوزها و نقشه‌های تاییدشده بوده، نه دور زدن رویه‌ها برای سرعت بخشیدن به کار؛ آیا مستندسازی و تاییدیه‌های لازم (نقشه As-built، تاییدیه صاحب تاسیسات مجاور) دریافت شده؛ و آیا نتیجه نهایی و درسی که از این تجربه گرفته (مثلاً اهمیت استعلام زودهنگام تاسیسات زیرزمینی) بیان می‌شود.","key_points":["شرح موقعیت واقعی و مشخص با ذی‌نفعان قابل تشخیص","تشخیص درست ماهیت چالش (فنی/مجوز/هماهنگی)","اقدام مبتنی بر رویه و هماهنگی رسمی، نه دور زدن مقررات","دریافت و ثبت تاییدیه‌ها و مستندات لازم","بیان نتیجه نهایی و درس آموخته"],"excellent_answer_indicators":["نشان دادن مدیریت فعال چند ذی‌نفع همزمان (کارفرما، مقام مجوزدهنده، مالک تاسیسات مجاور)","اشاره به اقدام پیشگیرانه اتخاذشده در پروژه‌های بعدی بر اساس این تجربه","کمی‌سازی نتیجه (مثلاً کاهش تاخیر، عدم بروز حادثه)"],"common_mistakes":["پاسخ کلی و بدون جزئیات مشخص از یک پروژه واقعی","توصیف حل مشکل با دور زدن مجوز یا رویه رسمی به عنوان راه‌حل موفق","عدم ذکر نتیجه یا درس آموخته‌شده از تجربه"],"standard_reference":""},{"category":"EXPERIENCE_BASED","sub_category":"Launcher/Receiver - تجربه واقعی","difficulty":"L4","question_text":"تجربه واقعی خود را از نصب، بازرسی یا Pre-commissioning یک ایستگاه توپک‌رانی (Launcher/Receiver) شرح دهید؛ چه مشکل یا ریسکی شناسایی کردید و چگونه مدیریت شد؟","reference_answer":"این پاسخ باید بر اساس معیارهای زیر سنجیده شود، نه یک داستان ثابت: آیا کاندیدا تجربه دست‌اول و مشخص از کار روی سیستم Launcher/Receiver (نصب مکانیکی، تست فشار محفظه، بازرسی درزبندی Closure Door، یا هماهنگی عملیات پیگ‌رانی) دارد؛ آیا ریسک یا مشکل شناسایی‌شده به‌درستی تشخیص داده شده (مثلاً نشتی از Closure، عدم انطباق فشار طراحی محفظه با خط اصلی، یا مسائل ایمنی مرتبط با فشار بالای محفظه هنگام باز کردن)؛ آیا اقدام مدیریتی/فنی متخذشده منطبق بر رویه‌های ایمنی و کیفیت بوده (مانند تخلیه کامل فشار و قفل/برچسب‌گذاری Lockout-Tagout پیش از باز کردن Closure)؛ آیا مستندسازی و بازرسی نهایی (تست فشار، تایید کارکرد صحیح Closure) انجام و ثبت شده؛ و آیا نتیجه و درس آموخته از این تجربه به وضوح بیان می‌شود.","key_points":["تجربه عینی و مشخص روی سیستم Launcher/Receiver","تشخیص درست ریسک فنی/ایمنی (نشتی، فشار، Closure Door)","اقدام منطبق بر رویه‌های ایمنی مانند تخلیه فشار و Lockout-Tagout","بازرسی و تست نهایی مستند","بیان نتیجه و درس آموخته"],"excellent_answer_indicators":["تسلط به جزئیات فنی سیستم Closure Door و ریسک ایمنی فشار بالا هنگام باز کردن","نشان دادن رویکرد پیشگیرانه (چک‌لیست پیش از عملیات، تاییدیه مضاعف فشار صفر)","اشاره به هماهنگی با تیم بهره‌برداری برای Pre-commissioning موفق"],"common_mistakes":["پاسخ کلی بدون تجربه عینی و مشخص","نادیده گرفتن اهمیت ایمنی فشار بالا در باز کردن Closure Door","عدم ذکر مستندسازی یا تست نهایی سیستم"],"standard_reference":""},{"category":"EXPERIENCE_BASED","sub_category":"Pipeline Integrity - تجربه واقعی","difficulty":"L3","question_text":"تجربه‌ای واقعی را شرح دهید که در آن پس از تکمیل ساخت (یا نزدیک به تحویل)، مسئله‌ای مرتبط با یکپارچگی خط لوله (Pipeline Integrity) کشف شد -- مانند آسیب پوشش نادیده‌مانده، مغایرت عمق دفن، یا نتیجه غیرمنتظره از یک بازرسی هوشمند اولیه (ILI Baseline). چگونه با آن برخورد کردید؟","reference_answer":"این پاسخ باید بر این اساس ارزیابی شود، نه یک داستان ثابت: آیا کاندیدا یک مورد واقعی و مشخص (نوع مسئله، مرحله پروژه) را شرح می‌دهد؛ آیا فرآیند تشخیص و ارزیابی ریسک مسئله به‌درستی و بر مبنای استاندارد/مشخصات فنی انجام شده (نه دست کم گرفتن یا نادیده‌انگاری)؛ آیا اقدام اصلاحی به‌موقع و مبتنی بر رویه صحیح (NCR، هماهنگی با تیم مهندسی/یکپارچگی) اتخاذ شده؛ آیا این موضوع پیش از تحویل نهایی به‌طور کامل بسته (Closeout) و در پرونده Handover مستند شده؛ و آیا کاندیدا نشان می‌دهد که این تجربه چگونه دیدگاه او را نسبت به اهمیت کنترل کیفیت در مراحل پیشین (پیشگیری از بروز مشکل مشابه) تغییر داده است.","key_points":["شرح مورد واقعی و مشخص از مسئله یکپارچگی کشف‌شده","ارزیابی ریسک صحیح و مبتنی بر استاندارد/مشخصات فنی","اقدام اصلاحی به‌موقع از طریق مسیر رسمی (NCR، هماهنگی مهندسی)","بستن کامل موضوع پیش از تحویل و ثبت در Handover","استخراج درس پیشگیرانه برای کاهش ریسک مشابه در آینده"],"excellent_answer_indicators":["نشان دادن ارتباط دادن یافته موضعی به ریسک سیستمی در کل مسیر خط","تسلط به فرآیند مدیریت یکپارچگی خط (Integrity Management) فراتر از رفع نقطه‌ای مشکل","بیان اقدام پیشگیرانه اعمال‌شده در پروژه‌های بعدی بر اساس این تجربه"],"common_mistakes":["توصیف مسئله بدون ذکر نحوه بسته شدن رسمی آن (Closeout)","دست‌کم گرفتن اهمیت یافته با استدلال که در نهایت مشکلی پیش نیامد","عدم ارتباط تجربه با بهبود فرآیند کیفیت در آینده"],"standard_reference":""}]'::jsonb) as x(
  category text, sub_category text, difficulty text, question_text text, reference_answer text,
  key_points jsonb, excellent_answer_indicators jsonb, common_mistakes jsonb, standard_reference text
)
where not exists (select 1 from comp_question_bank where job_role = 'pipeline_inspector');

-- ---- coating_cp_inspector (23 questions) ----
insert into comp_question_bank (job_role, category, sub_category, difficulty, question_text, reference_answer, key_points, excellent_answer_indicators, common_mistakes, standard_reference)
select 'coating_cp_inspector', x.category, x.sub_category, x.difficulty, x.question_text, x.reference_answer,
       coalesce(x.key_points, '[]'::jsonb), coalesce(x.excellent_answer_indicators, '[]'::jsonb), coalesce(x.common_mistakes, '[]'::jsonb), coalesce(x.standard_reference, '')
from jsonb_to_recordset('[{"category":"GENERAL","sub_category":"نقش و مسئولیت‌ها در چرخه پروژه","difficulty":"L1","question_text":"به عنوان مهندس ناظر پوشش و حفاظت کاتدیک، جایگاه شما در چرخه اجرای پروژه خط لوله (از طراحی تا راه‌اندازی) کجاست و در هر مرحله چه مسئولیت‌های کلیدی بر عهده دارید؟ فرض کنید در پروژه‌ای هستید که هم‌زمان عملیات پوشش‌کاری در کارگاه لوله و هم نصب سیستم CP در خط در حال انجام است؛ چگونه بین این دو فعالیت اولویت‌بندی می‌کنید؟","reference_answer":"نقش ناظر شامل بازبینی مدارک مهندسی و مشخصات فنی پوشش/CP قبل از اجرا، نظارت بر آماده‌سازی سطح و اعمال پوشش در کارخانه/کارگاه (line pipe coating و field joint)، بازرسی نصب آندها، رکتیفایر و تست‌استیشن‌ها، شرکت در پیش‌راه‌اندازی و اندازه‌گیری پتانسیل لوله-خاک، و تایید نهایی قبل از خاک‌ریزی و تحویل است. اولویت‌بندی بین فعالیت‌های هم‌زمان باید بر اساس مسیر بحرانی پروژه و ریسک برگشت‌ناپذیری انجام شود؛ فعالیت‌هایی که پس از دفن یا پوشانده شدن دیگر قابل بازرسی مجدد نیستند در اولویت بازرسی حضوری قرار می‌گیرند. در سایر موارد می‌توان از بازرسی نمونه‌ای یا تفویض بخشی از نظارت به دستیار واجد صلاحیت استفاده کرد.","key_points":["بازبینی مدارک و مشخصات فنی پیش از اجرا","نظارت مرحله‌ای مطابق ITP (holdpoint/witness point)","اولویت با فعالیت‌هایی که پس از پوشانده شدن غیرقابل بازرسی مجدد می‌شوند","هماهنگی بین تیم پوشش و تیم CP برای جلوگیری از تداخل برنامه بازرسی","مستندسازی هر مرحله برای ردیابی بعدی"],"excellent_answer_indicators":["اشاره صریح به سیستم ITP و تفاوت holdpoint و witness point","برنامه‌ریزی منابع بازرسی برای پوشش دو جبهه کاری هم‌زمان بدون افت کیفیت","درک ریسک عدم دسترسی مجدد به لوله دفن‌شده به عنوان معیار اصلی اولویت‌بندی"],"common_mistakes":["پاسخ کلی و تئوریک بدون اشاره به مراحل واقعی پروژه","ندادن اولویت مشخص و بیان اینکه هر دو به یک اندازه مهم‌اند بدون تصمیم عملی","نادیده گرفتن مفهوم برگشت‌ناپذیری کار دفن‌شده"],"standard_reference":""},{"category":"GENERAL","sub_category":"مدیریت عدم انطباق (NCR)","difficulty":"L2","question_text":"در بازرسی پوشش خارجی لوله متوجه می‌شوید که ضخامت پوشش (DFT) در چند نقطه پراکنده کمتر از حداقل مشخصه پروژه است، اما پیمانکار مدعی است این مقدار در محدوده تلورانس قابل قبول استاندارد است. اولین اقدام شما چیست و فرآیند صدور و بستن NCR را برای این مورد چگونه پیش می‌برید؟","reference_answer":"ابتدا باید با دستگاه کالیبره‌شده و افزایش تعداد نقاط اندازه‌گیری اطراف نقاط مشکوک، وسعت واقعی مشکل (نقطه‌ای یا سیستماتیک) به‌طور مستقل تایید شود. سپس داده‌ها مستند شده و NCR صادر می‌شود؛ در تعیین مرجع پذیرش، مشخصات فنی پروژه بر استاندارد عمومی اولویت دارد، مگر آنکه اسپک صراحتاً به استاندارد ارجاع داده باشد. پیمانکار موظف به ارائه ریشه‌یابی علت و اقدام اصلاحی طبق رویه تعمیر تایید‌شده است که باید توسط ناظر و در صورت نیاز مهندسی/کارفرما تایید شود. NCR تنها پس از بازرسی مجدد و تطبیق نتیجه با معیار پذیرش بسته می‌شود، نه با صرف وعده پیمانکار.","key_points":["تایید مستقل با اندازه‌گیری مجدد پیش از هرگونه قضاوت","مرجعیت مشخصات فنی پروژه بر استاندارد عمومی","تعیین وسعت واقعی مشکل (نمونه‌برداری گسترده‌تر) پیش از نتیجه‌گیری","الزام ریشه‌یابی و اقدام اصلاحی مستند از پیمانکار","بستن NCR فقط پس از بازرسی مجدد و تایید انطباق"],"excellent_answer_indicators":["تحلیل روند در سایر اسپول‌های مشابه برای پیشگیری از تکرار","ردیابی مدرک بر اساس شماره لوله/اسپول","درخواست بازبینی رویه اعمال پوشش در صورت مشاهده الگوی سیستماتیک"],"common_mistakes":["پذیرش توجیه پیمانکار بدون اندازه‌گیری مستقل","بستن NCR صرفاً با وعده تعمیر بدون بازرسی مجدد","ارجاع مستقیم به استاندارد عمومی بدون توجه به سخت‌گیرتر بودن اسپک پروژه"],"standard_reference":""},{"category":"GENERAL","sub_category":"مدیریت اینترفیس فنی","difficulty":"L3","question_text":"در پروژه‌ای، تیم مهندسی CP (طراحی‌شده توسط مشاور) با تیم اجرای پوشش پیمانکار خط لوله بر سر سازگاری پوشش انتخابی با سیستم حفاظت کاتدیک اختلاف‌نظر دارند؛ نگرانی این است که مقاومت پوشش می‌تواند باعث افت ولتاژ غیرقابل قبول در نقاط دور از ایستگاه تزریق جریان شود. به عنوان ناظر پوشش و CP، چگونه این اینترفیس فنی را مدیریت می‌کنید؟","reference_answer":"ابتدا باید داده‌های فنی هر دو طرف (مقاومت پوشش، فاصله بین ایستگاه‌های تخلیه جریان، نتایج طراحی CP) جمع‌آوری و به‌صورت مستند مقایسه شود. سپس با برگزاری جلسه هماهنگی فنی رسمی بین طراح CP و مهندسی پوشش، فرض کلیدی طراحی یعنی ضریب شکست پوشش (coating breakdown factor) بازبینی می‌شود تا اطمینان حاصل شود این فرض با کیفیت واقعی پوشش اعمال‌شده هم‌خوانی دارد. هرگونه تغییر در طراحی یا اجرا باید از طریق فرآیند مدیریت تغییر (MOC) مستند و توسط مهندسی/کارفرما تایید شود، نه با تصمیم یک‌جانبه در سطح سایت.","key_points":["شناسایی ضریب شکست پوشش به عنوان فرض کلیدی طراحی CP","جمع‌آوری و مقایسه داده مستند از هر دو تیم فنی","برگزاری جلسه اینترفیس رسمی بین طراح CP و مهندسی پوشش","عدم تصمیم یک‌جانبه در سطح سایت","مسیر مدیریت تغییر (MOC) برای هرگونه اصلاح طراحی یا اجرا"],"excellent_answer_indicators":["درک اینکه کیفیت پایین پوشش نیاز جریان CP و مصرف آند را افزایش و عمر سیستم را کاهش می‌دهد","پیشنهاد نظارت مضاعف بر DFT و تست هالیدی در نقاط دورتر از ایستگاه تزریق","مستندسازی کامل تصمیم نهایی برای دفاع در برابر اختلافات آتی"],"common_mistakes":["نادیده گرفتن ارتباط مستقیم کیفیت پوشش با طراحی CP","حل مسئله صرفاً در سطح کارگاه بدون بازگشت به تیم طراحی","عدم مستندسازی تصمیم نهایی اینترفیس"],"standard_reference":""},{"category":"GENERAL","sub_category":"تصمیم‌گیری تحت فشار برنامه زمانی","difficulty":"L3","question_text":"پیمانکار تحت فشار شدید برنامه زمانی است و درخواست می‌کند عملیات پوشش‌کاری فیلد جوینت در شرایطی که رطوبت نسبی هوا کمی بالاتر از حد مجاز رویه است ادامه یابد، با این استدلال که تاخیر باعث از دست رفتن پنجره کاری بعدی می‌شود. به عنوان ناظر، چه تصمیمی می‌گیرید و چگونه آن را به پیمانکار و کارفرما ابلاغ می‌کنید؟","reference_answer":"تصمیم فنی نباید تحت فشار برنامه‌ای قربانی شود، زیرا کیفیت پوشش مستقیماً بر عمر خط لوله اثر دارد و هزینه تعمیر بعدی به‌مراتب بیشتر از هزینه توقف کوتاه است. باید شرایط محیطی (دمای سطح فلز، رطوبت نسبی، نقطه شبنم) دقیقاً اندازه‌گیری و ثبت شود و طبق رویه تایید‌شده تصمیم گرفته شود؛ در صورت خارج بودن از محدوده مجاز، کار متوقف می‌شود. سپس موضوع به‌صورت مکتوب (site instruction) به پیمانکار و هم‌زمان به کارفرما/مشاور اطلاع داده می‌شود و راهکارهای جایگزین مانند استفاده از خیمه، گرمایش موضعی یا تغییر ساعت کاری برای بازگرداندن شرایط به محدوده مجاز پیشنهاد می‌شود.","key_points":["عدم قربانی کردن کیفیت پوشش برای فشار برنامه زمانی","مرجعیت رویه/مشخصات تایید‌شده در تصمیم فنی","ثبت مستند شرایط محیطی در لحظه تصمیم","ابلاغ کتبی تصمیم به پیمانکار و کارفرما","پیشنهاد راه‌حل جایگزین عملیاتی (خیمه، گرمایش، تغییر شیفت)"],"excellent_answer_indicators":["پیشنهاد برنامه‌ریزی کاری بر اساس پیش‌بینی هواشناسی برای پیشگیری از تکرار موضوع","آگاهی از پیامد بلندمدت دیسباندینگ زودرس ناشی از رطوبت زیر پوشش","آمادگی قبلی تجهیزات کنترل محیطی به عنوان اقدام پیشگیرانه"],"common_mistakes":["تسلیم شدن به فشار برنامه بدون مستندسازی","تصمیم شفاهی بدون ابلاغ کتبی رسمی","عدم اطلاع‌رسانی به کارفرما و پنهان کردن انحراف از شرایط مجاز"],"standard_reference":""},{"category":"GENERAL","sub_category":"مستندسازی و ارتباط با کنترل کیفیت","difficulty":"L1","question_text":"چه مدارک و سوابقی باید توسط ناظر پوشش و CP برای هر اسپول لوله یا هر بخش از خط لوله در طول اجرا تهیه و بایگانی شود تا در پکیج مستندات نهایی (Final Dossier/Data Book) قابل ارائه و ردیابی باشد؟","reference_answer":"مجموعه مدارک باید شامل گزارش‌های بازرسی مرحله‌ای (آماده‌سازی سطح، پروفیل سطح، شرایط محیطی، DFT، تست هالیدی، تست چسبندگی)، گواهی کالیبراسیون تجهیزات اندازه‌گیری، گزارش‌های عدم انطباق (NCR) و اقدامات اصلاحی، و مدارک ردیابی مواد مصرفی (شماره بچ/heat number) باشد. برای بخش CP نیز گزارش نصب و تست آندها، رکتیفایر و تست‌استیشن‌ها به همراه قرائت‌های پتانسیل لوله-خاک باید بایگانی شود. تمامی مدارک باید با شماره شناسایی لوله/اسپول یا کیلومتراژ خط قابل ردیابی و توسط ناظر و نماینده پیمانکار امضا شده باشند.","key_points":["گزارش بازرسی مرحله‌به‌مرحله برای هر اسپول","گواهی کالیبراسیون تجهیزات اندازه‌گیری","ردیابی شماره بچ مواد مصرفی پوشش","مستندات NCR و اقدام اصلاحی مرتبط","مستندات نصب و تست سیستم CP (آند، رکتیفایر، تست‌استیشن)","قابلیت ردیابی بر اساس شماره لوله یا کیلومتراژ"],"excellent_answer_indicators":["استفاده از سیستم ردیابی دیجیتال (بارکد/QR) پیوندخورده به Data Book دیجیتال","تاکید بر امضای مشترک ناظر و پیمانکار برای جلوگیری از اختلاف آتی","پیش‌بینی الزامات صاحب دارایی (asset owner) برای بازرسی‌های دوره‌ای آینده"],"common_mistakes":["ذکر فقط گزارش نهایی بدون سوابق مرحله‌ای","فراموش کردن گواهی کالیبراسیون تجهیزات","عدم اشاره به ردیابی مدارک بر اساس موقعیت یا شماره لوله"],"standard_reference":""},{"category":"TECHNICAL","sub_category":"آماده‌سازی سطح و بلاست ساچمه‌ای","difficulty":"L2","question_text":"فرض کنید در حال بازرسی عملیات بلاست‌کاری سطح لوله برای اعمال پوشش FBE هستید و مشاهده می‌کنید سطح از نظر بصری تمیز به نظر می‌رسد، اما پیمانکار نمونه استاندارد مرجع (comparator) را برای تطبیق درجه تمیزی ارائه نمی‌دهد. چه اقدامی انجام می‌دهید و چرا صرفاً بازرسی چشمی کافی نیست؟","reference_answer":"بازرسی چشمی بدون معیار تطبیقی مانند تصاویر استاندارد ISO 8501-1 ذهنی و غیرقابل دفاع است، بنابراین کار باید تا فراهم شدن نمونه مرجع و روشنایی کافی متوقف یا معلق شود. باید اطمینان حاصل شود درجه تمیزی مطابق اسپک پروژه، معمولاً Near-White Metal Blast طبق SSPC-SP10/NACE No.2 معادل Sa2.5، با نور کافی و در چند نقطه نماینده بررسی می‌شود. علاوه بر تمیزی بصری، وجود نمک‌های محلول و گرد و غبار باقیمانده باید با تست‌های جداگانه مانند Bresle test و dust test طبق ISO 8502 کنترل شود، زیرا این آلودگی‌ها با چشم دیده نمی‌شوند اما مستقیماً روی چسبندگی و ریسک دیسباندینگ اثر می‌گذارند. نتیجه نهایی باید مستند و امضا شود پیش از تایید ورود لوله به مرحله پوشش‌دهی.","key_points":["نیاز به نمونه مرجع/تصاویر استاندارد برای مقایسه عینی درجه تمیزی","توقف کار تا فراهم شدن ابزار مقایسه استاندارد","کنترل نور کافی حین بازرسی چشمی","کنترل نمک محلول و گرد و غبار به‌عنوان مکمل بازرسی بصری","مرجعیت اسپک پروژه در تعیین درجه تمیزی مورد نیاز"],"excellent_answer_indicators":["اشاره دقیق به SSPC-SP10/NACE No.2 و Sa2.5 و تفاوت آن با Sa3","ذکر حد مجاز رایج آلودگی کلراید در تست Bresle","طراحی پلن نمونه‌برداری تصادفی از نقاط بازرسی طبق پلن کیفیت"],"common_mistakes":["قبول تمیزی صرفاً بر اساس ظاهر بدون تست‌های تکمیلی","ندانستن تفاوت بین درجه‌های مختلف تمیزی بلاست","نادیده گرفتن آلودگی نمکی که با چشم قابل تشخیص نیست"],"standard_reference":"SSPC-SP10/NACE No.2 و ISO 8501-1"},{"category":"TECHNICAL","sub_category":"پروفیل سطح (Surface Profile)","difficulty":"L2","question_text":"چرا صرفاً رسیدن به درجه تمیزی مناسب برای تضمین چسبندگی پوشش کافی نیست و پروفیل سطح چه نقشی ایفا می‌کند؟ به‌عنوان ناظر چگونه و با چه ابزاری این پارامتر را اندازه‌گیری و تایید می‌کنید؟","reference_answer":"درجه تمیزی فقط عاری بودن سطح از آلودگی و زنگ‌زدگی را نشان می‌دهد، در حالی که پروفیل سطح (زبری و عمق آنکور) سطح تماس مکانیکی بین فلز و پوشش را ایجاد می‌کند و برای قفل مکانیکی و چسبندگی پوشش‌هایی مانند FBE و 3LPE ضروری است. پروفیل خیلی کم چسبندگی ضعیف و پروفیل خیلی زیاد باعث عدم پوشش کامل نوک زبری‌ها و خوردگی نقطه‌ای زیر پوشش می‌شود. اندازه‌گیری معمولاً با نوار کپی رپلیکا طبق ASTM D4417 روش B یا با پروفیلومتر سطح انجام می‌شود و نتیجه باید در محدوده مشخص‌شده در اسپک پوشش، مثلاً پنجاه تا صد میکرون برای FBE، باشد. باید در چند نقطه نماینده روی هر بخش لوله اندازه‌گیری و ثبت شود، نه فقط یک نقطه.","key_points":["تفاوت درجه تمیزی با پروفیل سطح","نقش پروفیل در قفل مکانیکی و چسبندگی پوشش","روش اندازه‌گیری با نوار رپلیکا طبق ASTM D4417 یا پروفیلومتر","محدوده مجاز پروفیل مطابق اسپک پوشش نه یک عدد ثابت جهانی","ریسک پروفیل بیش از حد کم یا بیش از حد زیاد"],"excellent_answer_indicators":["ارتباط نوع ساچمه (angular grit در برابر steel shot) با شکل و عمق پروفیل","کنترل مستمر پروفیل هم‌زمان با کنترل اندازه و فشار ساچمه در طول عملیات","دانستن اثر پروفیل نامناسب روی نتیجه تست هالیدی و چسبندگی"],"common_mistakes":["یکسان دانستن درجه تمیزی و پروفیل سطح","ندانستن ابزار استاندارد اندازه‌گیری پروفیل","نداشتن محدوده مشخص و پاسخ کلی مانند هرچه بیشتر بهتر"],"standard_reference":"ASTM D4417"},{"category":"TECHNICAL","sub_category":"نقطه شبنم و رطوبت نسبی","difficulty":"L2","question_text":"قانون کلی که دمای سطح فلز باید حداقل سه درجه سانتی‌گراد بالاتر از نقطه شبنم باشد را توضیح دهید. اگر در سایت دمای هوا بیست‌وهشت درجه، رطوبت نسبی هشتادوپنج درصد و دمای سطح لوله به دلیل تابش مستقیم آفتاب در یک طرف ناهمگن باشد، چه اقداماتی برای تصمیم‌گیری صحیح انجام می‌دهید؟","reference_answer":"رطوبت نسبی بالا باعث نزدیک شدن نقطه شبنم به دمای هوا می‌شود؛ اگر دمای سطح فلز به نقطه شبنم نزدیک یا کمتر از آن باشد، رطوبت میعان کرده و لایه نامرئی آب روی سطح باعث بروز حفرات، عدم چسبندگی و خوردگی زیرسطحی پوشش می‌شود، به همین دلیل حاشیه ایمنی حداقل سه درجه سانتی‌گراد در رویه‌های رایج صنعت الزامی است. با توجه به ناهمگنی دما در اثر تابش آفتاب، اندازه‌گیری باید در چند نقطه از جمله سردترین نقطه لوله با ترمومتر تماسی کالیبره‌شده و رطوبت‌سنج انجام شود، نه فقط یک قرائت میانگین. در صورتی که هر نقطه از شرایط مجاز خارج باشد، اعمال پوشش در آن ناحیه خاص باید متوقف یا به زمان مناسب‌تر موکول شود.","key_points":["توضیح علت فیزیکی میعان و اثر آن بر چسبندگی پوشش","حاشیه ایمنی سه درجه سانتی‌گراد بین دمای سطح و نقطه شبنم","لزوم اندازه‌گیری چندنقطه‌ای در نواحی با دمای ناهمگن","کالیبراسیون ابزار اندازه‌گیری دما و رطوبت","تصمیم موضعی نه بر اساس یک میانگین کلی سایت"],"excellent_answer_indicators":["اشاره به استفاده از دستگاه دیجیتال یا نمودار سایکرومتریک برای محاسبه نقطه شبنم","برنامه‌ریزی کاری بر اساس روند پیش‌بینی‌شده دما و رطوبت در طول روز","ثبت مستمر شرایط محیطی هر دو تا چهار ساعت در طول شیفت کاری"],"common_mistakes":["استفاده از یک قرائت متوسط برای کل سطح لوله","نادیده گرفتن تفاوت دمای سطح در نواحی سایه و آفتاب","ندانستن رابطه بین رطوبت نسبی بالا و نزدیک شدن نقطه شبنم به دمای هوا"],"standard_reference":""},{"category":"TECHNICAL","sub_category":"اندازه‌گیری ضخامت پوشش خشک (DFT)","difficulty":"L1","question_text":"برای اندازه‌گیری ضخامت پوشش خشک (DFT) روی لوله فولادی، چه نوع دستگاهی استفاده می‌کنید، چگونه آن را قبل از استفاده کالیبره می‌کنید و طرح نمونه‌برداری (تعداد نقاط اندازه‌گیری در هر طول مشخص لوله) معمولاً چگونه است؟","reference_answer":"برای پوشش‌های روی فلز فرومغناطیسی از ضخامت‌سنج مغناطیسی یا الکترومغناطیسی استفاده می‌شود که باید قبل از شروع کار روی صفحه استاندارد کالیبراسیون (shim) و با در نظر گرفتن انحنای سطح لوله صفر و تنظیم شود. طرح نمونه‌برداری معمولاً بر اساس رویه‌ای شناخته‌شده مانند SSPC-PA2 تعریف می‌شود که هر لوله را به مناطق مشخص تقسیم کرده و در هر منطقه چند قرائت گرفته و میانگین آن با حداقل و حداکثر مجاز اسپک مقایسه می‌شود. نتایج باید ثبت و در صورت وجود نقاط زیر حداقل مجاز، ناحیه مشخص برای تعمیر یا اعمال پوشش اضافه علامت‌گذاری شود.","key_points":["نوع دستگاه اندازه‌گیری مغناطیسی/الکترومغناطیسی","کالیبراسیون با shim قبل و در حین کار","تقسیم لوله به مناطق نمونه‌برداری مطابق رویه شناخته‌شده","مقایسه با محدوده حداقل و حداکثر مجاز اسپک نه فقط میانگین","ثبت و علامت‌گذاری نقاط زیر حد مجاز برای تعمیر"],"excellent_answer_indicators":["اشاره دقیق به SSPC-PA2 و مفهوم spot reading و gauge reading","توجه به اثر انحنای لوله بر دقت دستگاه و لزوم صفر کردن روی سطح مشابه","اهمیت کنترل حداکثر مجاز به‌ویژه برای جلوگیری از ترک در پوشش‌های سخت مانند FBE"],"common_mistakes":["گرفتن فقط یک قرائت در هر لوله","عدم کالیبراسیون منظم دستگاه در طول شیفت کاری","مقایسه فقط با حداقل مجاز بدون توجه به حداکثر مجاز"],"standard_reference":"SSPC-PA2"},{"category":"TECHNICAL","sub_category":"تست چسبندگی (Adhesion Test)","difficulty":"L2","question_text":"تفاوت بین تست چسبندگی مخرب مانند Pull-off Test طبق ASTM D4541 و تست‌های غیرمخرب چیست و در چه مرحله‌ای و با چه فرکانسی نمونه‌برداری برای تست چسبندگی روی پوشش خط لوله انجام می‌شود؟ اگر نتیجه یک تست Pull-off کمتر از حد مجاز باشد ولی محل شکست در چسب دستگاه (adhesive failure) باشد نه در پوشش، چه تصمیمی می‌گیرید؟","reference_answer":"تست‌های مخرب مانند Pull-off مقدار عددی نیروی چسبندگی بر حسب مگاپاسکال را با اعمال کشش مستقیم به یک دولی چسب‌خورده اندازه‌گیری می‌کنند و باید در نقاط محدود و قابل تعمیر و طبق فرکانس تعریف‌شده در ITP انجام شوند. اگر شکست در محل چسبیدن دولی (adhesive failure بین چسب و دولی یا دولی و سطح) رخ دهد نه در لایه پوشش یا سطح فلز، نتیجه تست نامعتبر تلقی می‌شود چون چسبندگی واقعی پوشش سنجیده نشده، بنابراین تست باید تکرار شود، نه اینکه به عنوان مردودی پوشش ثبت شود. علت رایج آن آماده‌سازی نامناسب سطح دولی یا کیورینگ ناقص چسب است که باید اصلاح شود.","key_points":["تعریف Pull-off Test و واحد اندازه‌گیری آن (MPa)","محدودیت انجام تست مخرب در نقاط قابل تعمیر و طبق فرکانس ITP","تشخیص نوع شکست (adhesive/cohesive/glue failure) پیش از اعتبار دادن به نتیجه","تکرار تست در صورت شکست چسب دستگاه نه رد پوشش","لزوم تعمیر محل تست پس از انجام آزمون مخرب"],"excellent_answer_indicators":["اشاره به الگوهای استاندارد گزارش‌دهی شکست (درصد adhesive/cohesive failure)","دانستن جایگزینی تست‌های غیرمخرب مانند knife adhesion طبق ASTM D3359 برای بازرسی گسترده‌تر","ارائه رویکرد سیستماتیک برای تحلیل الگوی نتایج شکست در طول پروژه"],"common_mistakes":["ثبت نتیجه پایین به‌عنوان مردودی پوشش بدون بررسی نوع شکست","انجام بی‌رویه تست مخرب روی سطح گسترده بدون طرح تعمیر مشخص","ندانستن تفاوت انواع شکست در تست چسبندگی"],"standard_reference":"ASTM D4541"},{"category":"TECHNICAL","sub_category":"پوشش اپوکسی پیوند ذوبی (FBE)","difficulty":"L3","question_text":"فرآیند صحیح اعمال پوشش FBE با روش گرمایش القایی از پیش‌گرم کردن لوله تا کیورینگ نهایی را شرح دهید و توضیح دهید کنترل دمای پیش‌گرم چرا برای کیفیت نهایی پوشش FBE حیاتی است.","reference_answer":"فرآیند شامل بلاست‌کاری سطح تا درجه مورد نیاز، پیش‌گرم لوله با کویل القایی تا دمای مشخص‌شده در رویه که معمولاً بین دویست تا دویست‌وپنجاه درجه سانتی‌گراد بسته به نوع پودر است، پاشش الکترواستاتیک پودر FBE روی سطح داغ که باعث ذوب و چسبیدن یکنواخت پودر می‌شود، و سپس خنک‌سازی کنترل‌شده معمولاً با آب برای تکمیل واکنش کیورینگ می‌شود. دمای پیش‌گرم حیاتی است زیرا دمای پایین‌تر از حد باعث ذوب ناقص پودر و چسبندگی ضعیف یا تخلخل می‌شود، در حالی که دمای بیش از حد می‌تواند باعث پخت بیش از حد، شکنندگی و کاهش مقاومت به دیسباندینگ کاتدیک شود. بنابراین دمای سطح لوله باید در چند نقطه طولی و محیطی با دماسنج تماسی یا اینفراردی کالیبره‌شده، دقیقاً پیش از ورود به ایستگاه پاشش پودر کنترل و ثبت شود.","key_points":["مراحل کامل فرآیند: بلاست، پیش‌گرم القایی، پاشش الکترواستاتیک، کیورینگ/خنک‌سازی","محدوده دمای پیش‌گرم مطابق دیتاشیت پودر مصرفی","ریسک دمای کم (چسبندگی ضعیف/تخلخل) و دمای زیاد (overcure/شکنندگی)","کنترل دما در چند نقطه لوله نه فقط یک نقطه","ارتباط کنترل فرآیند با کیفیت نهایی چسبندگی و مقاومت دیسباندینگ کاتدیک"],"excellent_answer_indicators":["اشاره به تاثیر ضخامت پودر بر زمان ژل شدن به‌عنوان ابزار کنترل کیفیت فرآیند","آگاهی از رابطه بین آزمایش‌های آزمایشگاهی کیورینگ و پارامترهای فرآیند تولید","تاکید بر کنترل مداوم دما در طول تولید نه فقط بازرسی نمونه‌ای"],"common_mistakes":["ندانستن ترتیب صحیح مراحل فرآیند FBE","تصور اینکه فقط ضخامت پوشش مهم است و دمای پیش‌گرم اهمیت ندارد","عدم آگاهی از پیامد پخت بیش از حد روی مقاومت دیسباندینگ کاتدیک"],"standard_reference":"ISO 21809-2"},{"category":"TECHNICAL","sub_category":"طراحی پایه سیستم حفاظت کاتدیک","difficulty":"L4","question_text":"اصول اولیه محاسبه نیاز جریان حفاظت کاتدیک برای یک خط لوله مدفون و نحوه انتخاب بین سیستم آند فداشونده و جریان اعمالی (ICCP) را توضیح دهید. در چه شرایطی طراح ترجیح می‌دهد به‌جای آند فداشونده از ICCP استفاده کند؟","reference_answer":"نیاز جریان CP از حاصل‌ضرب مساحت سطح لوله در چگالی جریان حفاظتی مورد نیاز، که به مقاومت خاک و کیفیت پوشش بستگی دارد، و ضریب شکست پوشش که در طول عمر پروژه افزایش می‌یابد، محاسبه می‌شود؛ هرچه پوشش با کیفیت‌تر باشد، نیاز جریان و اندازه سیستم CP کوچک‌تر خواهد بود. انتخاب بین آند فداشونده و ICCP معمولاً بر اساس مقاومت مخصوص خاک، طول خط و نیاز جریان کل، دسترسی به برق در مسیر، و هزینه چرخه عمر انجام می‌شود؛ برای خطوط طولانی با نیاز جریان بالا یا مقاومت خاک بالا، ICCP با رکتیفایر و آندهای بستر عمیق یا سطحی اقتصادی‌تر و قابل تنظیم‌تر است، در حالی که برای سازه‌های کوچک‌تر یا مناطق فاقد دسترسی به برق، آند فداشونده ساده‌تر و مطمئن‌تر است. همچنین در نواحی با ریسک تداخل با سازه‌های مجاور، طراح باید اثر متقابل سیستم ICCP بر خطوط لوله دیگر را نیز بررسی کند.","key_points":["فرمول مفهومی نیاز جریان (مساحت × چگالی جریان × ضریب شکست پوشش)","ارتباط مستقیم کیفیت پوشش با اندازه سیستم CP","معیارهای انتخاب ICCP در برابر آند فداشونده (مقاومت خاک، طول خط، دسترسی برق، هزینه چرخه عمر)","ریسک تداخل با سازه‌های مجاور در طراحی ICCP","در نظر گرفتن پایان عمر طراحی پروژه در محاسبات"],"excellent_answer_indicators":["اشاره به محدوده واقعی چگالی جریان بر اساس نوع خاک","بحث درباره افزایش تدریجی ضریب شکست پوشش و طراحی برای بدترین حالت پایان عمر","اشاره به مدل‌سازی کامپیوتری توزیع پتانسیل برای خطوط طولانی"],"common_mistakes":["ندانستن رابطه کیفیت پوشش با اندازه سیستم CP","انتخاب نوع سیستم صرفاً بر اساس هزینه اولیه بدون در نظر گرفتن هزینه چرخه عمر","نادیده گرفتن اثر تداخل با سازه‌های مجاور در طراحی"],"standard_reference":"AMPP/NACE SP0169"},{"category":"TECHNICAL","sub_category":"رکتیفایر","difficulty":"L3","question_text":"در بازدید دوره‌ای از یک ایستگاه رکتیفایر سیستم ICCP مشاهده می‌کنید که ولتاژ و جریان خروجی نسبت به مقادیر کموزیشن اولیه، بدون تغییر عمدی تنظیمات، به‌تدریج در طول چند ماه افزایش یافته است. این روند چه دلایل احتمالی دارد و چگونه بررسی می‌کنید؟","reference_answer":"افزایش تدریجی ولتاژ و جریان خروجی رکتیفایر بدون تغییر عمدی تنظیمات معمولاً نشان‌دهنده افزایش مقاومت مدار است که می‌تواند ناشی از مصرف‌شدن و کاهش سطح موثر آندهای بستر زمینی، خشک شدن یا افزایش مقاومت بک‌فیل اطراف آندها، اتصال شل یا خورده‌شده در کابل‌ها و ترمینال‌ها، یا افزایش فصلی مقاومت خاک باشد. برای بررسی باید ابتدا اتصالات و ترمینال‌های رکتیفایر و جعبه اتصال آند از نظر خوردگی و شلی بازدید شود، سپس با اندازه‌گیری جریان هر آند به‌طور مجزا در صورت وجود جعبه توزیع جریان، آند یا آندهای دارای افت عملکرد شناسایی شوند. در نهایت باید روند تاریخی داده‌های رکتیفایر و قرائت‌های پتانسیل لوله-خاک بررسی شود تا مشخص شود آیا این افزایش مقاومت همچنان سطح حفاظت کافی را تامین می‌کند یا نیاز به بازسازی بستر آندی وجود دارد.","key_points":["تشخیص افزایش مقاومت مدار به‌عنوان علت اصلی پدیده","دلایل احتمالی: مصرف آند، خشک شدن بک‌فیل، اتصال شل یا خورده","بررسی جریان تک‌تک آندها در صورت وجود جعبه توزیع جریان","بررسی روند تاریخی داده به‌جای تکیه بر یک قرائت لحظه‌ای","ارتباط نهایی یافته با کفایت پتانسیل حفاظتی لوله"],"excellent_answer_indicators":["پایش و trending منظم داده‌های رکتیفایر برای پیش‌بینی پایان عمر بستر آندی پیش از افت حفاظت","پیشنهاد بازرسی حفاری نمونه (test pit) روی بستر آندی مشکوک","ارائه برنامه اقدام مرحله‌ای بر اساس شدت افزایش مقاومت"],"common_mistakes":["تصور اینکه افزایش ولتاژ لزوماً نشانه خرابی خود رکتیفایر است","عدم بررسی جریان تک‌تک آندها","نادیده گرفتن اثر فصلی رطوبت خاک بر مقاومت مدار"],"standard_reference":""},{"category":"TECHNICAL","sub_category":"پتانسیل لوله-خاک","difficulty":"L3","question_text":"معیار رایج منفی هشتصدوپنجاه میلی‌ولت نسبت به الکترود مرجع مس/سولفات مس برای ارزیابی کفایت حفاظت کاتدیک را توضیح دهید و بگویید چرا اندازه‌گیری صحیح این پتانسیل نیازمند حذف افت ولتاژ IR است. چگونه در میدان این افت را حذف یا کمینه می‌کنید؟","reference_answer":"معیار منفی هشتصدوپنجاه میلی‌ولت به این معناست که پتانسیل واقعی فلز-الکترولیت لوله باید حداقل به این مقدار منفی‌تر برسد تا نرخ خوردگی فولاد در آن نقطه عملاً متوقف شود؛ اما قرائت خام ولت‌متر بین لوله و الکترود مرجع شامل جزء اضافی به نام افت IR است که ناشی از عبور جریان حفاظتی از مقاومت خاک بین لوله و الکترود است و باعث نمایش پتانسیل منفی‌تر از واقعیت می‌شود. برای حذف این خطا معمولاً از روش قطع لحظه‌ای جریان با سوییچ همزمان روی تمام منابع جریان در ناحیه تحت تاثیر استفاده می‌شود و قرائت بلافاصله پس از قطع، پیش از افت طبیعی پلاریزاسیون، به‌عنوان پتانسیل بدون IR ثبت می‌شود؛ روش جایگزین قرار دادن الکترود مرجع مستقیماً نزدیک سطح لوله در صورت دسترسی (مانند حفاری) است. بدون این تصحیح، ممکن است لوله‌ای که واقعاً حفاظت کافی ندارد به اشتباه قابل قبول تلقی شود.","key_points":["تعریف و منطق معیار منفی هشتصدوپنجاه میلی‌ولت CSE","تعریف افت IR و منشا آن در مقاومت خاک","خطای خوش‌بینانه ناشی از عدم حذف افت IR","روش instant-off با قطع همزمان تمام منابع جریان","روش جایگزین قرار دادن الکترود نزدیک سطح لوله"],"excellent_answer_indicators":["اشاره به معیار جایگزین صد میلی‌ولت پلاریزاسیون برای شرایط دشوار","دانستن اهمیت هماهنگی زمانی دقیق قطع تمام منابع جریان از جمله جریان‌های سرگردان مجاور","درک محدودیت‌های عملی instant-off در سیستم‌های پیچیده با چند رکتیفایر"],"common_mistakes":["ثبت مستقیم قرائت خام (on-potential) به‌عنوان نتیجه نهایی بدون تصحیح IR","ندانستن روش instant-off","توجه فقط به رکتیفایر مربوط به همان خط بدون در نظر گرفتن منابع مجاور"],"standard_reference":"AMPP/NACE SP0169"},{"category":"SCENARIO","sub_category":"شرایط محیطی اعمال پوشش","difficulty":"L3","question_text":"بعد از اتمام شیفت شب، هنگام بازبینی مستندات متوجه می‌شوید که رکوردهای شرایط محیطی (دما، رطوبت، نقطه شبنم) برای سه ساعت از فعالیت پوشش‌کاری فیلد جوینت ثبت نشده و آن قسمت پوشش هم‌اکنون کیور شده است. با توجه به اینکه امکان اندازه‌گیری مستقیم شرایط آن لحظه دیگر وجود ندارد، چه تصمیمی می‌گیرید؟","reference_answer":"نبود مستندات شرایط محیطی به معنای عدم اثبات انطباق است، نه لزوماً انطباق یا عدم انطباق واقعی، بنابراین باید موضوع فوراً به‌صورت NCR یا Observation ثبت و مستند شود. باید داده‌های محیطی جایگزین از نزدیک‌ترین ایستگاه هواشناسی یا لاگر خودکار سایت و شرایط ثبت‌شده شیفت‌های مشابه در همان بازه بررسی شود تا ریسک واقعی برآورد شود، اما این جایگزین برای اثبات قطعی کافی نیست. سپس باید بازرسی کامل کیفیت پوشش کیورشده در آن قطعات مشخص، شامل تست هالیدی، چسبندگی، DFT و بازرسی چشمی برای حباب یا تاول، با تمرکز ویژه انجام و نتیجه مستند و به کارفرما گزارش شود. در نهایت رویه ثبت داده باید اصلاح شود، مثلاً با استفاده از لاگر خودکار، تا این خلأ تکرار نشود.","key_points":["نبود مدرک به معنای عدم اثبات انطباق است، نه لزوما وجود مشکل","ثبت فوری موضوع به‌صورت NCR یا Observation","بررسی داده‌های جایگزین بدون تکیه صرف بر آن به‌عنوان مدرک قطعی","بازرسی تشدیدشده کیفیت پوشش کیورشده (هالیدی، چسبندگی، DFT، بازرسی چشمی)","اقدام اصلاحی سیستمی (لاگر خودکار) برای جلوگیری از تکرار"],"excellent_answer_indicators":["پیشنهاد الزام لاگر دیجیتال دائمی با هشدار خودکار خروج از محدوده به‌جای ثبت دستی","برخورد با یافته به‌عنوان مسئله سیستمی و بررسی سایر شیفت‌های همان اپراتور برای الگوی مشابه","مستندسازی کامل مسیر تصمیم برای دفاع در برابر ادعای آتی"],"common_mistakes":["نادیده گرفتن موضوع با این توجیه که احتمالاً مشکلی نبوده","پذیرش گزارش شفاهی اپراتور به‌عنوان مدرک کافی","عدم انجام بازرسی تشدیدشده روی پوشش کیورشده"],"standard_reference":""},{"category":"SCENARIO","sub_category":"تست هالیدی و پوشش فیلد جوینت","difficulty":"L4","question_text":"در حین تست هالیدی روی پوشش‌های حرارت‌انقباضی فیلد جوینت‌ها، مشاهده می‌کنید که نرخ ردی (failure rate) در چند فیلد جوینت متوالی به‌طور غیرعادی بالاست، در حالی که فیلد جوینت‌های قبل و بعد از آن‌ها مشکلی ندارند. چگونه علت ریشه‌ای را تشخیص می‌دهید و چه اقداماتی به ترتیب انجام می‌دهید؟","reference_answer":"ابتدا باید ولتاژ تست هالیدی و کالیبراسیون دستگاه spark tester تایید شود، زیرا ولتاژ نادرست بیش از حد مجاز بر اساس ضخامت پوشش می‌تواند باعث شکست کاذب حتی در پوشش سالم شود. در صورت تایید صحت دستگاه، باید بررسی شود آیا فیلد جوینت‌های مردود همگی مربوط به یک اپراتور، یک بچ از sleeve، یا یک بازه زمانی خاص مانند افت دمای پیش‌گرم لوله یا شرایط جوی نامساعد هستند تا الگوی سیستماتیک شناسایی شود. علل رایج شامل پیش‌گرم ناکافی سطح لوله یا پوشش مجاور که مانع چسبیدن کامل sleeve و ایجاد حباب هوا زیر آن می‌شود، آسیب مکانیکی حین نصب، یا بچ معیوب ماده است. پس از شناسایی علت، تمام فیلد جوینت‌های مشکوک نه فقط موارد مردود باید با روش تعمیر تایید‌شده اصلاح و مجدداً تست هالیدی و در صورت لزوم بازرسی برشی (cut test) شوند.","key_points":["تایید کالیبراسیون و ولتاژ صحیح spark tester پیش از هر نتیجه‌گیری","جستجوی الگوی مشترک بین موارد مردود (اپراتور، بچ، زمان، شرایط جوی)","علل رایج: پیش‌گرم ناکافی، حباب هوا، آسیب مکانیکی، بچ معیوب","گسترش بازرسی فراتر از موارد صرفاً مردود شده","تعمیر طبق رویه تایید‌شده و تست مجدد کامل"],"excellent_answer_indicators":["اشاره به فرمول محاسبه ولتاژ تست هالیدی بر اساس ضخامت پوشش و ریسک آسیب پوشش سالم با ولتاژ بیش از حد","پیشنهاد cut test برای بررسی کیفیت اتصال زیر sleeve به‌عنوان مکمل هالیدی","مستندسازی به‌عنوان یافته سیستمی و اطلاع‌رسانی به تامین‌کننده sleeve در صورت مشکوک بودن بچ"],"common_mistakes":["تعمیر موضعی فقط سوراخ‌های شناسایی‌شده بدون بررسی علت ریشه‌ای","عدم بررسی کالیبراسیون دستگاه تست پیش از قضاوت درباره پوشش","نادیده گرفتن الگوی زمانی یا بچی بین موارد مردود"],"standard_reference":"AMPP/NACE SP0188"},{"category":"PROBLEM_SOLVING","sub_category":"افت پتانسیل پس از راه‌اندازی و تداخل AC/DC","difficulty":"L4","question_text":"چند ماه پس از راه‌اندازی و کموزیشن موفق سیستم CP، در یک بازرسی دوره‌ای متوجه می‌شوید پتانسیل لوله-خاک در بخشی از مسیر که از نزدیکی یک خط انتقال برق فشار قوی و همچنین یک خط لوله دیگر دارای CP فعال عبور می‌کند، به‌طور غیرمنتظره پایین‌تر از معیار حفاظتی افت کرده است، هرچند رکتیفایر مربوطه به‌درستی کار می‌کند. چه فرضیه‌هایی را بررسی می‌کنید و چگونه هرکدام را تایید یا رد می‌کنید؟","reference_answer":"فرضیه اول تداخل AC ناشی از القای خط انتقال فشار قوی مجاور است که با اندازه‌گیری ولتاژ AC روی لوله در نقاط تست‌استیشن و مقایسه با آستانه‌های خطر خوردگی AC قابل بررسی است. فرضیه دوم تداخل DC ناشی از سیستم CP خط لوله مجاور است که با هماهنگی و انجام survey قطع/وصل هم‌زمان بین دو سیستم CP و مشاهده تغییرات متقابل پتانسیل قابل تایید است؛ اگر با قطع سیستم CP همسایه پتانسیل لوله ما بهبود یابد، تداخل DC تایید می‌شود. باید همچنین بررسی شود آیا تغییری در مقاومت خاک منطقه به دلیل فصل یا آسیب فیزیکی به پوشش که منطقه را به نقطه تخلیه جریان تبدیل کرده رخ داده است. راه‌حل نهایی بسته به علت می‌تواند نصب سیستم کاهش تداخل مانند bond مقاومتی یا آند مصرفی محلی، یا هماهنگی عملیاتی بین دو اپراتور خط لوله باشد.","key_points":["فرضیه تداخل AC از خط برق فشار قوی و روش اندازه‌گیری آن","فرضیه تداخل DC از CP خط لوله مجاور و روش تایید با survey هم‌زمان قطع/وصل","بررسی تغییر مقاومت خاک یا آسیب پوشش به‌عنوان علت مستقل","هماهنگی رسمی بین اپراتورها برای تست مشترک","راه‌حل‌های کاهش تداخل (bond مقاومتی، آند تخلیه)"],"excellent_answer_indicators":["اشاره به آستانه استاندارد ولتاژ AC خطرناک که معمولاً بالای پانزده ولت AC نیازمند بررسی است","دانستن اینکه تداخل DC می‌تواند در یک نقطه لوله همسایه را بیش از حد کاتدیک و در نقطه دیگر آندی و خورنده کند","تاکید بر توافق رسمی بین دو مالک خط برای survey مشترک دوره‌ای"],"common_mistakes":["تمرکز صرف بر عملکرد رکتیفایر خودی بدون بررسی عوامل خارجی","ندانستن تفاوت تداخل AC و DC و نحوه تشخیص هرکدام","عدم هماهنگی با اپراتور خط مجاور برای تست مشترک"],"standard_reference":"NACE SP0177"},{"category":"SCENARIO","sub_category":"دیسباندینگ پوشش و تشخیص خرابی","difficulty":"L4","question_text":"در حین یک حفاری تعمیراتی روی خط لوله مدفون که چند سال از عمر آن می‌گذرد، مشاهده می‌کنید پوشش 3LPE در ناحیه‌ای به شکل حباب بزرگ از فلز جدا شده اما زیر آن هیچ خوردگی قابل توجهی دیده نمی‌شود و آب یا رطوبتی هم بین پوشش و فلز جمع نشده است. چگونه بین علل احتمالی (دیسباندینگ کاتدیک، آسیب مکانیکی نصب، کیفیت ضعیف چسب اولیه) افتراق می‌دهید؟","reference_answer":"نبود خوردگی زیر ناحیه دیسباند نشان می‌دهد سیستم CP همچنان در حال محافظت از فلز است، که دیسباندینگ کاتدیک کلاسیک را محتمل‌تر می‌کند، اما باید سایر علل هم سیستماتیک رد شوند. بررسی سطح داخلی حباب پوشش برای وجود اثر قلیایی با کاغذ pH یا معرف شیمیایی، تشخیص دیسباندینگ کاتدیک را تایید می‌کند؛ اگر سطح چسبنده به نظر برسد و شکست تمیز آدهزیو بدون علائم شیمیایی دیده شود، آسیب مکانیکی هنگام حمل یا نصب یا خنک‌سازی نامناسب حین اکستروژن پوشش کارخانه‌ای محتمل‌تر است. باید همچنین سابقه پتانسیل لوله-خاک آن ناحیه و هرگونه سابقه اضافه‌ولتاژ (over-protection) بررسی شود، زیرا پتانسیل بیش از حد منفی عامل شناخته‌شده تشدید دیسباندینگ کاتدیک در پوشش‌های پلی‌اتیلنی است. نتیجه باید با نمونه‌برداری و در صورت نیاز آزمایش آزمایشگاهی تکمیل و به‌صورت گزارش خرابی کامل مستند شود.","key_points":["تفسیر نبود خوردگی به‌عنوان نشانه عملکرد صحیح CP نه لزوماً سلامت پوشش","بررسی pH زیر پوشش برای تشخیص دیسباندینگ کاتدیک","افتراق از آسیب مکانیکی از طریق نوع سطح شکست","بررسی سابقه پتانسیل لوله-خاک به‌ویژه ریسک over-protection","تکمیل تشخیص با تست آزمایشگاهی و مستندسازی کامل"],"excellent_answer_indicators":["دانستن مکانیزم شیمیایی دیسباندینگ کاتدیک از طریق تولید یون هیدروکسیل در نقاط ضعف اولیه پوشش","پیشنهاد حفاری نمونه‌ای بیشتر در نقاط مشابه پروفیل خط برای ارزیابی وسعت مشکل","ارتباط یافته با بازبینی نقطه تنظیم رکتیفایر برای پیشگیری از over-protection"],"common_mistakes":["نتیجه‌گیری فوری که پوشش بد بوده بدون بررسی سیستماتیک علل","ندانستن رابطه over-protection با دیسباندینگ کاتدیک در پلی‌اتیلن","عدم مستندسازی و نمونه‌برداری برای تحلیل ریشه‌ای"],"standard_reference":"ASTM G8 / ASTM G95"},{"category":"PROBLEM_SOLVING","sub_category":"تعمیر پوشش با پروفیل سطح خارج از اسپک","difficulty":"L3","question_text":"پس از اعمال کامل پوشش 3LPE روی چند صد متر لوله، در بازبینی سوابق آرشیوشده متوجه می‌شوید پروفیل سطح ثبت‌شده برای بلاست‌کاری آن بچ به‌طور مکرر پایین‌تر از حداقل مورد نیاز اسپک بوده، اما در آن زمان بدون توقف کار تایید شده بود. اکنون که پوشش کامل و کیور شده، چه رویکردی برای ارزیابی ریسک و تصمیم‌گیری درباره پذیرش یا رد این بچ اتخاذ می‌کنید؟","reference_answer":"ابتدا باید NCR گذشته‌نگر بر اساس مدارک موجود صادر و علت عدم توقف کار در زمان وقوع بررسی شود تا از تکرار جلوگیری گردد. از آنجا که پروفیل سطح دیگر قابل اندازه‌گیری مستقیم نیست، ارزیابی باید بر اساس آزمون‌های غیرمستقیم انجام شود: تست چسبندگی در نمونه‌های متعدد از همان بچ برای سنجش کیفیت واقعی باند، بازرسی هالیدی کامل برای رد وجود حفره، و در صورت امکان تست دیسباندینگ کاتدیک روی نمونه کنترل مشابه در صورت وجود نمونه شاهد از همان بچ. تصمیم نهایی پذیرش، تعمیر موضعی، یا حذف کامل پوشش و اعمال مجدد باید بر اساس نتایج این آزمون‌ها و در چارچوب مشخصات پروژه اتخاذ و توسط مهندسی/کارفرما تایید شود؛ صرف اینکه پروفیل کم بوده ولی الان دیر شده پاسخ قابل قبولی برای پذیرش ریسک بلندمدت خوردگی نیست.","key_points":["صدور NCR گذشته‌نگر و بررسی علت عدم توقف کار در زمان وقوع","وابستگی ارزیابی به تست‌های غیرمستقیم چون پروفیل زیر پوشش پنهان است","تست چسبندگی روی نمونه‌های متعدد از همان بچ","بازرسی هالیدی کامل و در صورت امکان تست نمونه کنترل","تصمیم نهایی طبق مشخصات پروژه با تایید مهندسی/کارفرما"],"excellent_answer_indicators":["پیشنهاد نگهداری نمونه شاهد (control coupon) از هر بچ به‌عنوان اقدام پیشگیرانه سیستمی","تحلیل ریسک بر اساس موقعیت آن بخش لوله در خط، مانند عبور از خاک با خورندگی بالا","مستندسازی کامل تصمیم برای دفاع در برابر ادعای آتی"],"common_mistakes":["پذیرش بدون آزمون به دلیل اینکه کار تمام شده و کاری نمی‌شود کرد","رد کامل و اعمال مجدد بدون تحلیل داده یا برعکس پذیرش بدون هیچ بررسی","عدم صدور NCR برای علت ریشه‌ای عدم توقف در زمان وقوع"],"standard_reference":""},{"category":"EXPERIENCE_BASED","sub_category":"تجربه واقعی تشخیص خرابی پوشش/CP","difficulty":"L3","question_text":"یک مورد واقعی از پروژه‌های قبلی خود را شرح دهید که در آن با یک خرابی یا ناهنجاری در پوشش یا سیستم حفاظت کاتدیک مواجه شدید، مانند پتانسیل نامناسب، شکست هالیدی مکرر یا دیسباندینگ. چگونه آن را تشخیص دادید، چه مسیری برای حل آن طی کردید و نتیجه نهایی و درسی که از آن گرفتید چه بود؟","reference_answer":"این سوال تجربه‌محور است و پاسخ صحیح واحد ندارد؛ ارزیابی باید بر اساس معیارهای زیر انجام شود، نه تطبیق با یک داستان از پیش تعیین‌شده. پاسخ قوی باید یک مورد واقعی و مشخص، نه فرضی یا عمومی، با جزئیات فنی قابل تایید مانند نوع پوشش، نوع مشکل و اعداد واقعی ارائه دهد. باید مسیر تشخیصی منطقی و مبتنی بر داده نه حدس را نشان دهد، مسیر مستندسازی و اقدام اصلاحی طبق رویه یا استاندارد را ذکر کند، نتیجه نهایی و پیامد قابل اندازه‌گیری را بیان کند و در پایان یک درس عملی یا تغییر رویه‌ای که از آن تجربه گرفته را مطرح کند.","key_points":["مورد واقعی و مشخص با جزئیات فنی قابل راستی‌آزمایی","فرآیند تشخیصی مبتنی بر داده و اندازه‌گیری","ارجاع به مستندسازی رسمی (NCR) و مرجع تصمیم (اسپک/رویه/استاندارد)","بیان نتیجه نهایی مشخص و قابل اندازه‌گیری","درس گرفته‌شده یا تغییر رویه‌ای پس از رویداد"],"excellent_answer_indicators":["کمی‌سازی نتیجه، مانند تعداد نقاط تعمیر یا درصد کاهش نرخ خرابی پس از اقدام اصلاحی","نشان دادن ابتکار عمل فراتر از وظیفه تعریف‌شده، مانند پیشنهاد بهبود رویه به کل پروژه","تسلط به نام استاندارد یا رویه مرتبط بدون نیاز به یادآوری","نگاه سیستمی و بررسی سایر نقاط مشابه پس از یافتن یک مورد"],"common_mistakes":["پاسخ کاملاً عمومی و تئوریک بدون مثال واقعی مشخص","ناتوانی در ذکر جزئیات فنی هنگام پرسش تکمیلی که نشانه عدم تجربه دست اول است","عدم ذکر نتیجه نهایی یا مسیر مستندسازی"],"standard_reference":""},{"category":"EXPERIENCE_BASED","sub_category":"تجربه واقعی مدیریت NCR","difficulty":"L2","question_text":"یک NCR واقعی که خودتان در حوزه پوشش یا CP در یکی از پروژه‌های گذشته صادر یا مدیریت کرده‌اید را توضیح دهید. موضوع NCR چه بود، چه کسانی درگیر بودند، و فرآیند تا بسته شدن آن چگونه طی شد؟","reference_answer":"این سوال تجربه‌محور است و معیار ارزیابی زیر برای هر داستان واقعی به کار می‌رود. پاسخ قوی باید موضوع مشخص و واقعی NCR، طرف‌های درگیر مانند پیمانکار، مشاور و کارفرما و نقش دقیق کاندیدا در فرآیند را شرح دهد. باید مسیر رسمی مستندسازی شامل فرم NCR و مرجع فنی استفاده‌شده برای رد یا پذیرش، اقدام اصلاحی درخواست‌شده از پیمانکار، و روش راستی‌آزمایی پیش از بستن NCR را توضیح دهد. در پایان باید بگوید NCR با چه نتیجه‌ای، مانند پذیرش مشروط، تعمیر یا حذف و اعمال مجدد بسته شد.","key_points":["موضوع مشخص و واقعی NCR","طرف‌های درگیر و نقش دقیق کاندیدا در فرآیند","مرجع فنی استفاده‌شده برای تصمیم (اسپک/استاندارد)","اقدام اصلاحی و بازرسی مجدد پیش از بستن NCR","نتیجه نهایی مشخص و زمان بسته شدن"],"excellent_answer_indicators":["اشاره به زمان‌بندی واقعی طول فرآیند تا بسته شدن NCR","نشان دادن مهارت مذاکره و ارتباط با پیمانکار بدون تنازل در کیفیت","بیان یادگیری سیستمی که از این NCR به رویه پروژه اضافه شد"],"common_mistakes":["توصیف کلی و تئوریک فرآیند NCR بدون مثال شخصی واقعی","نداشتن اطلاع از نتیجه نهایی یا زمان بسته شدن NCR","نسبت دادن کل کار به تیم بدون توضیح نقش شخصی خود"],"standard_reference":""},{"category":"EXPERIENCE_BASED","sub_category":"تجربه واقعی اختلاف فنی با پیمانکار","difficulty":"L3","question_text":"زمانی را به یاد بیاورید که با پیمانکار یا نماینده فنی او بر سر روش انجام یک تست، مانند هالیدی، چسبندگی یا اندازه‌گیری پتانسیل، یا تفسیر نتیجه آن اختلاف‌نظر داشتید. موضوع اختلاف چه بود، چگونه آن را حل کردید و در نهایت چه کسی درست می‌گفت؟","reference_answer":"این سوال تجربه‌محور است و معیار ارزیابی زیر برای هر داستان واقعی به کار می‌رود. پاسخ قوی باید ماهیت فنی دقیق اختلاف، نه اختلاف شخصیتی صرف، را شرح دهد و نشان دهد کاندیدا برای حل آن به مرجع عینی مانند اسپک پروژه، رویه تایید‌شده، استاندارد یا کالیبراسیون مجدد تجهیزات رجوع کرده، نه صرفاً به قدرت مقام. باید توضیح دهد چگونه بدون تنش غیرضروری و با حفظ رابطه کاری، تصمیم فنی نهایی مستند و به هر دو طرف ابلاغ شد. صداقت در بیان نتیجه، حتی اگر در نهایت خودش اشتباه کرده باشد، نشانه مهمی از واقعی بودن تجربه است.","key_points":["ماهیت فنی مشخص اختلاف بین دو طرف","ارجاع به مرجع عینی مانند اسپک، رویه، استاندارد یا کالیبراسیون برای حل اختلاف","حفظ حرفه‌ای‌گری و رابطه کاری در حین اختلاف","مستندسازی و ابلاغ رسمی تصمیم نهایی","صداقت در بیان نتیجه واقعی حتی در صورت اشتباه از سوی کاندیدا"],"excellent_answer_indicators":["توانایی اذعان به اشتباه خود در صورت وقوع بدون توجیه‌تراشی","نشان دادن حل مسئله مبتنی بر داده و آزمون به‌جای بحث کلامی صرف","ذکر پیامد بلندمدت مثبت رابطه کاری با پیمانکار پس از حل اختلاف"],"common_mistakes":["پاسخ‌هایی که کاندیدا را همیشه قهرمان حق‌به‌جانب نشان می‌دهند بدون هیچ ابهام یا اذعان","عدم اشاره به مرجع فنی عینی برای حل اختلاف","حل مسئله صرفاً با اعمال قدرت سلسله‌مراتبی به‌جای استدلال فنی"],"standard_reference":""},{"category":"EXPERIENCE_BASED","sub_category":"تجربه واقعی راه‌اندازی سیستم CP","difficulty":"L2","question_text":"تجربه واقعی خود از انرژیزه‌کردن و کموزیشن یک سیستم حفاظت کاتدیک شامل رکتیفایر، آند و تست‌استیشن را شرح دهید. چه مراحلی طی شد، چه مشکلی در صورت وجود در حین راه‌اندازی مشاهده کردید و چگونه رفع شد؟","reference_answer":"این سوال تجربه‌محور است و معیار ارزیابی زیر برای هر داستان واقعی به کار می‌رود. پاسخ قوی باید مراحل واقعی کموزیشن شامل بازرسی پیش از انرژیزه‌کردن اتصالات و مقاومت مدار، انرژیزه‌کردن تدریجی و تنظیم خروجی، اندازه‌گیری پتانسیل لوله-خاک در تست‌استیشن‌های مختلف و مقایسه با معیار پذیرش را با جزئیات واقعی شرح دهد. اگر مشکلی رخ داده، مانند اینکه یک تست‌استیشن پتانسیل کافی نشان نمی‌داد، باید فرآیند عیب‌یابی واقعی شامل بررسی اتصال کابل، فاصله از آند و مقاومت خاک محلی و راه‌حل نهایی را بیان کند. باید در پایان نتیجه مشخص شامل تایید نهایی سیستم توسط کارفرما یا مشاور و هرگونه درس گرفته‌شده را ذکر کند.","key_points":["توضیح مراحل واقعی کموزیشن با جزئیات فنی","ذکر معیار پذیرش استفاده‌شده برای تایید سیستم","توضیح یک مشکل واقعی و مسیر عیب‌یابی آن","نتیجه نهایی و تایید رسمی راه‌اندازی","درس گرفته‌شده یا بهبود رویه پس از تجربه"],"excellent_answer_indicators":["ذکر اعداد واقعی ولتاژ، جریان یا پتانسیل از تجربه واقعی","نشان دادن درک ارتباط بین طراحی و نتیجه واقعی راه‌اندازی، مانند علت نیاز تنظیم بیشتر در یک ناحیه خاص","مستندسازی کامل کموزیشن به‌عنوان مرجع بهره‌برداری آینده"],"common_mistakes":["پاسخ کاملاً تئوریک بدون تجربه دست اول در راه‌اندازی واقعی","عدم ذکر هیچ چالش یا مشکل واقعی که نشان‌دهنده تجربه محدود یا عدم صداقت است","ندانستن معیار پذیرش عددی استفاده‌شده در کموزیشن"],"standard_reference":"AMPP/NACE SP0169"}]'::jsonb) as x(
  category text, sub_category text, difficulty text, question_text text, reference_answer text,
  key_points jsonb, excellent_answer_indicators jsonb, common_mistakes jsonb, standard_reference text
)
where not exists (select 1 from comp_question_bank where job_role = 'coating_cp_inspector');

-- ---- radiography_interpreter (23 questions) ----
insert into comp_question_bank (job_role, category, sub_category, difficulty, question_text, reference_answer, key_points, excellent_answer_indicators, common_mistakes, standard_reference)
select 'radiography_interpreter', x.category, x.sub_category, x.difficulty, x.question_text, x.reference_answer,
       coalesce(x.key_points, '[]'::jsonb), coalesce(x.excellent_answer_indicators, '[]'::jsonb), coalesce(x.common_mistakes, '[]'::jsonb), coalesce(x.standard_reference, '')
from jsonb_to_recordset('[{"category":"GENERAL","sub_category":"نقش مفسر RT در چرخه پروژه","difficulty":"L1","question_text":"در یک پروژه EPC خط لوله انتقال گاز، جایگاه و مسئولیت‌های مفسر فیلم‌های رادیوگرافی را در تعامل با واحدهای جوشکاری، کنترل کیفیت (QC) و بازرسی شخص ثالث (TPI) شرح دهید. مفسر در چه نقاطی از فرآیند ساخت باید وارد عمل شود و مرز مسئولیت او با بازرس جوش (Welding Inspector) کجاست؟","reference_answer":"مفسر فیلم رادیوگرافی مسئول ارزیابی فنی فیلم‌های گرفته‌شده از جوش‌های تولیدی و تشخیص، طبقه‌بندی و گزارش ناپیوستگی‌ها بر اساس معیارهای پذیرش مشخصات پروژه و استاندارد مرجع است، در حالی که بازرس جوش مسئول کنترل کلی فرآیند جوشکاری، تأیید WPS/PQR، نظارت بر پارامترهای جوشکاری و هماهنگی کلی کیفیت است. مفسر باید هم قبل از عملیات (تأیید تکنیک، IQI، چیدمان فیلم) و هم پس از ظهور فیلم برای تفسیر نهایی درگیر باشد و نتیجه را در قالب گزارش رسمی RT Report به بازرس جوش و QC اعلام کند. در صورت رد یک جوش، مفسر مسئول صدور NCR اولیه یا اطلاع‌رسانی به QC برای صدور NCR است، اما تصمیم نهایی تعمیر/برش/تعویض معمولاً با هماهنگی واحد جوشکاری و مهندسی کیفیت انجام می‌شود. مرز مسئولیت مشخص است: مفسر تنها ارزیابی رادیوگرافیک انجام می‌دهد و درباره علت متالورژیکی یا اصلاح WPS اظهار نظر نمی‌کند مگر به عنوان اطلاعات کمکی.","key_points":["تعریف نقش مفسر در برابر بازرس جوش","ورود در مراحل پیش و پس از تصویربرداری","صدور گزارش RT رسمی","ارتباط با فرآیند NCR","عدم دخالت در اصلاح WPS/پارامتر جوشکاری","هماهنگی با TPI/کارفرما"],"excellent_answer_indicators":["تفکیک دقیق مسئولیت‌ها با ذکر مستندات (WPS, ITP, NCR)","اشاره به نقش در Pre-job و Post-weld","تاکید بر بی‌طرفی و استقلال مفسر","ذکر تعامل با کارفرما/مشاور در بازرسی‌های Hold Point"],"common_mistakes":["خلط مسئولیت مفسر با بازرس جوش","نادیده گرفتن نقش گزارش رسمی","پاسخ کلی مانند فقط گفتن فیلم را نگاه می‌کنم و رد یا قبول می‌کنم"],"standard_reference":""},{"category":"GENERAL","sub_category":"مدیریت مستندات و بایگانی فیلم","difficulty":"L2","question_text":"فرض کنید در پایان یک پروژه احداث خط لوله، مشاور کارفرما درخواست تحویل کامل آرشیو فیلم‌های رادیوگرافی و گزارش‌های RT را می‌دهد، اما متوجه می‌شوید بخشی از فیلم‌های مربوط به جوش‌های تعمیری قدیمی گم شده یا شماره‌گذاری‌شان با گزارش‌ها همخوانی ندارد. به عنوان مفسر مسئول، چه اقداماتی برای کنترل و اصلاح این وضعیت انجام می‌دهید و چگونه از تکرار آن جلوگیری می‌کنید؟","reference_answer":"ابتدا باید دامنه مشکل را با تطبیق سیستماتیک بین لیست جوش‌های تعمیری (Repair Log)، شماره‌های شناسایی روی فیلم (Weld ID markers) و گزارش‌های RT مشخص کرد تا معلوم شود چه تعداد فیلم واقعاً مفقود است یا صرفاً اشتباه شماره‌گذاری شده. سپس باید موضوع را رسماً و شفاف به مدیریت QC/پروژه و کارفرما گزارش داد زیرا فیلم رادیوگرافی سند تضمین کیفیت (Quality Record) با الزام نگهداری طولانی‌مدت است. برای فیلم‌های واقعاً مفقود، در صورت امکان باید ری‌شوت (تصویربرداری مجدد) با هماهنگی کارفرما در نظر گرفته شود، در غیر این صورت باید عدم انطباق (NCR) ثبت و ریسک آن ارزیابی شود. برای پیشگیری از تکرار، باید سیستم بایگانی دیجیتال با کد یکتا برای هر فیلم، چک‌لیست تطبیق روزانه بین فیلم گرفته‌شده و گزارش صادره، و ممیزی دوره‌ای آرشیو ایجاد شود.","key_points":["تطبیق سیستماتیک weld ID با گزارش‌ها","شفافیت و گزارش‌دهی به کارفرما/QC","ثبت NCR برای فیلم مفقود","بررسی امکان ری‌شوت","ایجاد سیستم بایگانی و کنترل روزانه","اهمیت فیلم به عنوان Quality Record با الزام نگهداری بلندمدت"],"excellent_answer_indicators":["اشاره به الزامات نگهداری بلندمدت فیلم (retention period) طبق مشخصات پروژه","تاکید بر ریشه‌یابی علت مانند نبود کنترل ورودی/خروجی فیلم به آزمایشگاه","پیشنهاد سیستم دیجیتال با پشتیبان‌گیری"],"common_mistakes":["پنهان کردن یا نادیده گرفتن مشکل","صرفاً گفتن فیلم را دوباره می‌گیریم بدون ثبت NCR یا اطلاع کارفرما","عدم توجه به الزام قراردادی نگهداری فیلم"],"standard_reference":""},{"category":"GENERAL","sub_category":"مدیریت عدم انطباق و رابط با واحدهای دیگر","difficulty":"L3","question_text":"در جوشی که تفسیر شما نشان‌دهنده Lack of Fusion در طول قابل توجهی است، سرپرست جوشکاری با مراجعه حضوری اصرار دارد که فیلم دوباره گرفته شود چون معتقد است تکنیک تصویربرداری اشتباه بوده و عیب واقعی نیست. به عنوان مفسر، فرآیند تصمیم‌گیری و مستندسازی شما در این شرایط چگونه است؟","reference_answer":"ابتدا باید فیلم را از نظر کیفیت (چگالی، حساسیت IQI، وضوح تصویر) بازبینی کرد تا مشخص شود آیا واقعاً نقص تکنیکی وجود دارد یا خیر؛ این کار باید بر اساس شواهد فنی مستند انجام شود نه فشار کلامی. اگر فیلم از نظر کیفیت قابل قبول باشد، تفسیر باید بر اساس همان فیلم ثابت بماند و درخواست ری‌شوت بدون دلیل فنی مستند رد شود، در غیر این صورت مفسر تحت فشار غیرفنی تصمیم گرفته و استقلال حرفه‌ای خود را زیر سوال برده است. اگر واقعاً شواهدی از خطای تکنیک مانند SFD نادرست یا هم‌راستا نبودن IQI با محل مشکوک وجود دارد، درخواست ری‌شوت با مستندسازی دلیل فنی و تایید مسئول QC پذیرفته می‌شود. در هر صورت، کل فرآیند باید مکتوب شود: نتیجه اولیه، اعتراض دریافتی، بررسی مجدد کیفیت فیلم، تصمیم نهایی و امضای طرفین، تا در صورت بروز اختلاف بعدی مستند رسمی وجود داشته باشد.","key_points":["بازبینی کیفیت فیلم بر اساس شواهد فنی نه فشار","استقلال حرفه‌ای مفسر در برابر فشار غیرفنی","شرایط پذیرفتنی برای ری‌شوت","نقش QC در تایید نهایی","مستندسازی کامل فرآیند تصمیم‌گیری","تفکیک خطای تکنیک از عیب واقعی جوش"],"excellent_answer_indicators":["تفکیک روشن بین خطای فیلم/تکنیک و خطای جوش واقعی","تاکید بر اینکه تصمیم صرفاً بر مبنای معیار فنی گرفته می‌شود نه رده سازمانی درخواست‌کننده","اشاره به ثبت مستندات برای زنجیره ردیابی و حفاظت حرفه‌ای مفسر"],"common_mistakes":["پذیرش ری‌شوت صرفاً برای رضایت سرپرست جوشکاری بدون بررسی فنی","تغییر نتیجه تفسیر بدون مستندسازی","برخورد تدافعی و غیرحرفه‌ای بدون ارائه شواهد فنی"],"standard_reference":""},{"category":"GENERAL","sub_category":"ایمنی پرتوی (Radiation Safety)","difficulty":"L1","question_text":"به عنوان مفسر فیلم که معمولاً در محیط تاریک‌خانه یا نزدیک منطقه رادیوگرافی فعالیت می‌کند، چه سطحی از آگاهی و مسئولیت در قبال ایمنی پرتوی (Radiation Safety) دارید و در صورت مشاهده عدم رعایت الزامات ایمنی توسط تیم تصویربرداری چه اقدامی می‌کنید؟","reference_answer":"مفسر فیلم، حتی اگر مسئول مستقیم عملیات‌گر منبع پرتو نباشد، باید آگاهی کافی از اصول ایمنی پرتوی از جمله محدوده‌بندی منطقه کنترل‌شده (Controlled Area)، استفاده از دوزیمتر شخصی و علائم هشداردهنده داشته باشد تا در تعامل با تیم RT ایمنی خود و دیگران را به خطر نیندازد. در صورت مشاهده تخلف ایمنی مانند نبود محدوده‌بندی مناسب، نبود علائم هشدار، یا فاصله ناایمن افراد از منبع، مفسر باید بلافاصله موضوع را به مسئول ایمنی پرتوی (RSO) یا سرپرست RT اطلاع دهد و در صورت لزوم کار را متوقف کند، حتی اگر این کار باعث تاخیر در برنامه شود. مسئولیت نهایی ایمنی پرتوی با اپراتور رادیوگرافی و RSO است، اما گزارش‌دهی و عدم چشم‌پوشی از تخلف بخشی از مسئولیت حرفه‌ای هر فردی است که در محیط کار حضور دارد.","key_points":["آگاهی از منطقه کنترل‌شده و دوزیمتری","مسئولیت گزارش‌دهی تخلف ایمنی","اختیار توقف کار در شرایط پرخطر","تفکیک مسئولیت RSO از مفسر","اولویت ایمنی بر برنامه زمانی"],"excellent_answer_indicators":["اشاره صریح به Stop Work Authority بدون توجه به فشار زمانی","تاکید بر فرهنگ ایمنی و گزارش‌دهی بدون سرزنش"],"common_mistakes":["بی‌تفاوتی نسبت به ایمنی پرتوی با این توجیه که مسئولیت من نیست","ادامه کار بدون گزارش تخلف مشاهده‌شده"],"standard_reference":""},{"category":"EXPERIENCE_BASED","sub_category":"تجربه اختلاف تفسیری با همکار یا جوشکار","difficulty":"L3","question_text":"بزرگ‌ترین اختلاف‌نظر تفسیری که تاکنون با یک همکار مفسر، بازرس جوش یا جوشکار درباره پذیرش/رد یک فیلم رادیوگرافی داشته‌اید را شرح دهید. موضوع اختلاف چه بود، چگونه حل شد و در نهایت چه نتیجه‌ای گرفتید؟","reference_answer":"این سوال تجربه‌محور است و پاسخ صحیح واحد ندارد؛ ارزیابی باید بر اساس معیارهای زیر انجام شود. پاسخ قوی باید یک تجربه واقعی و مشخص، نه کلی‌گویی، شامل نوع ناپیوستگی مورد اختلاف، دلیل فنی هر طرف، و مرجع نهایی تصمیم‌گیری مانند مشخصات پروژه، استاندارد یا بازبینی مجدد فیلم توسط شخص سوم را ارائه دهد. فرد باتجربه معمولاً نشان می‌دهد که اختلاف را با رجوع به معیار فنی مانند اندازه‌گیری دقیق طول یا عمق اندیکاسیون و بازبینی چگالی فیلم، نه با اقتدار سازمانی، حل کرده است. باید مشخص شود که نتیجه نهایی مستند شده و در صورت لزوم به سطح بالاتر مانند Level III یا QC Manager ارجاع شده است. یک درس آموخته یا تغییر رویه مانند بهبود روش اندازه‌گیری یا آموزش، نشانه بلوغ حرفه‌ای است.","key_points":["واقعی و مشخص بودن تجربه نه پاسخ کلی","مبنای فنی حل اختلاف","رجوع به استاندارد یا مشخصات پروژه","مستندسازی نتیجه","ارجاع به سطح بالاتر در صورت نیاز","درس آموخته یا تغییر رویه"],"excellent_answer_indicators":["نشان دادن استقلال حرفه‌ای بدون تعارض غیرسازنده","ارجاع به فرآیند رسمی Level III review در صورت عدم توافق","تاثیر مثبت بلندمدت بر فرآیند کار"],"common_mistakes":["پاسخ کاملاً فرضی، غیرواقعی و مبهم","حل اختلاف صرفاً با تکیه بر مقام سازمانی نه شواهد فنی","نبود مستندسازی نهایی"],"standard_reference":""},{"category":"TECHNICAL","sub_category":"IQI و حساسیت تصویر (Sensitivity)","difficulty":"L2","question_text":"در حین بازبینی یک فیلم رادیوگرافی، مشاهده می‌کنید که سیم قابل مشاهده IQI با ضخامت کمتر از حد مورد نیاز مشخصات پروژه به وضوح دیده می‌شود، اما سیم استاندارد مورد نیاز دیده نمی‌شود. این فیلم را قبول می‌کنید یا رد؟ استدلال فنی خود را بر مبنای مفهوم حساسیت تصویر توضیح دهید.","reference_answer":"اگر سیم مرجع الزامی بر اساس درصد حساسیت تعیین‌شده در مشخصات دیده نشود اما سیمی نازک‌تر و نشان‌دهنده حساسیت بهتر دیده شود، این وضعیت از نظر منطقی غیرمعمول و نیازمند بررسی دقیق است، چون معمولاً اگر سیم نازک‌تر دیده شود باید سیم ضخیم‌تر مرجع هم به‌وضوح دیده شود. باید احتمال خطای خواندن، اشتباه در شناسایی نوع یا مدل IQI، یا آرتیفکت فیلم را بررسی کرد. در صورتی که پس از بازبینی دقیق مشخص شود سیم مورد نیاز واقعاً غیرقابل مشاهده است، فیلم باید بر اساس عدم احراز حساسیت الزامی رد و تکرار شود، چون IQI صرفاً نشان‌دهنده کیفیت تصویر است نه تضمین‌کننده دیدن عیب واقعی، و عدم احراز حساسیت به معنی عدم اطمینان از توانایی فیلم در نشان دادن ناپیوستگی‌های کوچک است. تصمیم باید همیشه بر اساس معیار مشخص‌شده در مشخصات پروژه گرفته شود، نه قضاوت شخصی.","key_points":["مفهوم حساسیت تصویر و رابطه سیم‌های IQI","تشخیص ناسازگاری غیرمعمول در خوانش IQI","لزوم بازبینی خطای احتمالی قبل از نتیجه‌گیری","معیار رد فیلم در صورت عدم احراز حساسیت الزامی","نقش مشخصات پروژه در تعیین سیم مرجع"],"excellent_answer_indicators":["اشاره به علل احتمالی مانند نوع نادرست IQI یا خطای شماره‌گذاری سیم پیش از رد قطعی","تاکید بر اینکه IQI ابزار کنترل کیفیت فرآیند است نه معیار پذیرش عیب"],"common_mistakes":["قبول بی‌قید فیلم فقط چون یک سیم دیده شده بدون توجه به الزام دقیق مشخصات","عدم توجه به احتمال خطای شناسایی IQI"],"standard_reference":"ASME Section V"},{"category":"TECHNICAL","sub_category":"چگالی فیلم (Film Density)","difficulty":"L1","question_text":"هنگام کنترل چگالی یک فیلم رادیوگرافی با دانسیتومتر، عدد قرائت‌شده در ناحیه مورد بررسی (Area of Interest) 1.4 است در حالی که محدوده الزامی پروژه بین 2.0 تا 4.0 است. چه تصمیمی می‌گیرید و چرا این محدوده چگالی اهمیت دارد؟","reference_answer":"چگالی 1.4 پایین‌تر از حداقل الزام است و فیلم باید رد شود، زیرا چگالی ناکافی به معنای کنتراست و وضوح پایین تصویر است که می‌تواند باعث عدم تشخیص ناپیوستگی‌های واقعی موجود در جوش شود. محدوده چگالی استاندارد برای تضمین حساسیت کافی چشم انسان یا دستگاه نمایش در تشخیص تفاوت‌های ظریف در جذب پرتو تعیین شده است؛ چگالی بسیار پایین ناشی از کم‌بودن اکسپوژر بوده و چگالی بسیار بالا نیز باعث نیاز به نورافکن قوی و کاهش وضوح می‌شود. در این حالت باید علت کم بودن چگالی مانند کاهش زمان اکسپوژر، ولتاژ نامناسب، فاصله نادرست یا مشکل ظهور بررسی و پارامترهای تصویربرداری اصلاح و فیلم تکرار شود.","key_points":["تشخیص خارج از محدوده بودن چگالی","دلیل فنی اهمیت محدوده چگالی برای کنتراست و حساسیت تشخیص","رد فیلم و نیاز به تکرار","بررسی علل ریشه‌ای مانند اکسپوژر، ظهور و فاصله"],"excellent_answer_indicators":["اشاره به محدوده چگالی متفاوت برای تکنیک تک‌فیلم و دوفیلم و منابع نوری مختلف","ذکر ابزار کنترل مانند دانسیتومتر با کالیبراسیون معتبر"],"common_mistakes":["قبول فیلم به این دلیل که ایرادی در تصویر دیده نمی‌شود بدون توجه به الزام عددی چگالی","ندانستن اینکه چگالی پایین باعث کاهش قابلیت تشخیص عیب می‌شود"],"standard_reference":"ASME Section V"},{"category":"TECHNICAL","sub_category":"فاصله منبع تا فیلم و عدم وضوح هندسی","difficulty":"L3","question_text":"در یک پروژه با ضخامت جداری لوله 19 میلی‌متر و اندازه منبع f=3mm، تیم تصویربرداری به دلیل محدودیت فضای اجرایی SFD را کاهش داده است. به عنوان مفسر، چگونه بررسی می‌کنید که آیا این کاهش SFD قابل قبول است یا باعث افت کیفیت فیلم شده، و چه پارامتری را محاسبه یا کنترل می‌کنید؟","reference_answer":"پارامتر کلیدی برای کنترل، عدم وضوح هندسی یا Ug است که با رابطه Ug برابر با f ضربدر b تقسیم بر d محاسبه می‌شود، که در آن f اندازه منبع، b فاصله شیء تا فیلم و d فاصله منبع تا شیء است. با کاهش SFD، در صورت ثابت ماندن سایر پارامترها، Ug افزایش می‌یابد و ممکن است از حداکثر مقدار مجاز طبق مشخصات پروژه فراتر رود که باعث تاری لبه‌ها و کاهش توانایی تشخیص ناپیوستگی‌های ریز مانند ترک یا لک آو فیوژن می‌شود. به عنوان مفسر باید SFD واقعی مورد استفاده، فاصله شیء تا فیلم و اندازه منبع را از گزارش تکنیک دریافت و Ug را محاسبه و با حد مجاز مقایسه کرد؛ اگر Ug از حد مجاز فراتر رفته باشد، فیلم باید رد و تکرار با SFD اصلاح‌شده یا کاهش فاصله شیء تا فیلم انجام شود، مگر اینکه بتوان با کاهش اندازه منبع یا این فاصله جبران کرد.","key_points":["فرمول Ug و اجزای آن شامل اندازه منبع و فواصل هندسی","تاثیر کاهش SFD بر افزایش Ug","حد مجاز Ug طبق مشخصات پروژه و ضخامت","اثر Ug بالا بر توانایی تشخیص عیوب ریز","راهکار جبران با کاهش فاصله شیء تا فیلم یا اندازه منبع","نیاز به تکرار فیلم در صورت عدم انطباق"],"excellent_answer_indicators":["محاسبه عددی نمونه با اعداد فرضی برای نشان دادن درک کمی","اشاره به حداقل SFD مطابق کد بر اساس نسبت فاصله به ضخامت","تفکیک بین این پارامتر و پارامترهای دیگر مانند چگالی و IQI"],"common_mistakes":["خلط بین SFD و Ug به عنوان یک مفهوم واحد","نادیده گرفتن تاثیر فاصله شیء تا فیلم در محاسبه","پاسخ کلی بدون اشاره به فرمول یا رابطه کمی"],"standard_reference":"ASME Section V"},{"category":"TECHNICAL","sub_category":"انتخاب تکنیک رادیوگرافی","difficulty":"L2","question_text":"برای بازرسی جوش‌های حلقوی یک خط لوله با قطر 12 اینچ در شرایطی که دسترسی به داخل لوله ممکن نیست، بین تکنیک‌های Double Wall Single Image و Double Wall Double Image کدام را انتخاب می‌کنید و بر چه اساسی این تصمیم را می‌گیرید؟","reference_answer":"انتخاب بین این دو تکنیک عمدتاً به قطر لوله و امکان جداسازی تصویر دو دیواره از هم بستگی دارد؛ برای قطرهای بزرگ‌تر که با قرار دادن منبع کنار لوله و آفست مناسب می‌توان تصویر دیواره سمت منبع و دیواره سمت فیلم را از هم جدا کرد بدون تداخل، تکنیک تک‌تصویر دو دیواره ترجیح داده می‌شود چون فقط دیواره نزدیک به فیلم برای تفسیر عیب مورد ارزیابی دقیق قرار می‌گیرد و امکان تفسیر واضح‌تر و پوشش کامل با تعداد اکسپوژر منطقی وجود دارد. برای قطرهای کوچک‌تر که امکان جداسازی تصویر دو دیواره کافی نیست، از تکنیک دوتصویر دو دیواره با منبع و فیلم هم‌مرکز یا آفست کم استفاده می‌شود که در آن هر دو دیواره روی هم قرار گرفته و جوش به صورت بیضی دیده می‌شود و برای پوشش کامل معمولاً به دو اکسپوژر با چرخش نود درجه نیاز است. بنابراین باید قطر لوله، ضخامت جداری، امکان دسترسی و الزام مشخصات پروژه بررسی و تکنیک طبق آن‌ها تایید شود نه صرفاً بر اساس عادت یا سهولت اجرا.","key_points":["معیار قطر لوله برای انتخاب تکنیک تک‌تصویر یا دوتصویر","تعریف صحیح هر تکنیک","نیاز به اکسپوژرهای متعدد با چرخش برای پوشش کامل در دوتصویر","ملاحظه ضخامت و امکان دسترسی","رجوع به مشخصات پروژه و روش تاییدشده"],"excellent_answer_indicators":["ذکر آستانه تقریبی قطر برای انتخاب تکنیک","اشاره به الزام آفست منبع در تکنیک تک‌تصویر برای جداسازی تصاویر","توجه به پوشش کامل محیط جوش با تعداد شات کافی"],"common_mistakes":["پاسخ کلی بدون معیار قطر یا آفست","ندانستن نیاز تکنیک دوتصویر به دو اکسپوژر متعامد برای پوشش کامل"],"standard_reference":"ASME Section V"},{"category":"TECHNICAL","sub_category":"پارامترهای اکسپوژر","difficulty":"L3","question_text":"فیلمی از یک جوش با ضخامت یکنواخت تهیه شده اما در بازبینی متوجه می‌شوید که یک انتهای فیلم چگالی مناسب دارد ولی انتهای دیگر بیش از حد تیره است، در حالی که ضخامت ماده در کل طول یکسان بوده. علت احتمالی این پدیده چیست و چگونه تفسیر آن را ادامه می‌دهید؟","reference_answer":"با توجه به یکسان بودن ضخامت ماده در طول جوش، تغییر چگالی از یک انتها به انتهای دیگر معمولاً ناشی از عوامل هندسی اکسپوژر است نه ضخامت قطعه؛ محتمل‌ترین علت اثر قانون عکس مجذور فاصله در تکنیک‌هایی با منبع نامناسب مانند پانوراما با منبع خارج از مرکز یا تکنیک تک‌دیواره با فاصله منبع نامساوی نسبت به طول فیلم است که باعث می‌شود بخشی از فیلم به منبع نزدیک‌تر و بخشی دورتر باشد و در نتیجه اکسپوژر و چگالی غیریکنواخت شود. علت دیگر می‌تواند مشکل ظهور نامتوازن، افت ولتاژ منبع در طول اکسپوژر طولانی، یا خطای قرارگیری فیلم باشد. باید ابتدا با دانسیتومتر چگالی چند نقطه در طول فیلم اندازه‌گیری و مقایسه شود؛ اگر بخشی از فیلم خارج از محدوده چگالی مجاز باشد، آن بخش نمی‌تواند برای تفسیر مورد قبول قرار گیرد و باید یا فیلم تکرار شود یا فقط بخش دارای چگالی قابل قبول تفسیر و بقیه طول جوش با اکسپوژر جداگانه پوشش داده شود.","key_points":["تشخیص علت هندسی مانند فاصله نامساوی منبع به عنوان علت محتمل اصلی","احتمال خطای ظهور یا افت ولتاژ منبع","لزوم اندازه‌گیری چگالی چندنقطه‌ای","رد بخش خارج از محدوده چگالی","تصمیم برای تکرار یا پوشش تکمیلی"],"excellent_answer_indicators":["اشاره دقیق به قانون عکس مجذور فاصله و نحوه تاثیر آن در تکنیک‌های پانوراما یا آفست","تفکیک بین علل هندسی و علل شیمیایی مربوط به ظهور فیلم"],"common_mistakes":["نسبت دادن اشتباه تغییر چگالی به تغییر ضخامت قطعه با وجود تصریح یکنواختی ضخامت","نادیده گرفتن نیاز به اندازه‌گیری کمی چگالی قبل از تصمیم‌گیری"],"standard_reference":""},{"category":"TECHNICAL","sub_category":"روش‌شناسی تفسیر فیلم","difficulty":"L3","question_text":"رویکرد سیستماتیک خود را برای تفسیر یک فیلم رادیوگرافی از جوش لوله، از لحظه دریافت فیلم تا صدور نتیجه نهایی، مرحله به مرحله شرح دهید. چه مواردی را قبل از قضاوت درباره وجود یا عدم وجود عیب بررسی می‌کنید؟","reference_answer":"ابتدا باید کیفیت پذیرش فیلم بررسی شود، شامل شناسایی صحیح جوش، عدم وجود آرتیفکت‌های پردازشی مانند خط، لکه یا خش، چگالی در محدوده مجاز در ناحیه مورد بررسی، و وضوح و قابلیت مشاهده IQI مطابق حساسیت الزامی؛ اگر فیلم این معیارها را برآورده نکند، تفسیر متوقف و درخواست تکرار می‌شود. سپس با استفاده از منبع نور مناسب و در محیط کم‌نور، فیلم به صورت سیستماتیک از یک انتها به انتهای دیگر و با پوشش کامل عرض جوش بررسی می‌شود تا اندیکاسیون‌های احتمالی شناسایی شوند. برای هر اندیکاسیون، باید موقعیت نسبت به مرکز جوش، شکل، اندازه تقریبی، تراکم و الگوی توزیع ثبت شود تا نوع ناپیوستگی طبقه‌بندی گردد. در نهایت اندازه و نوع اندیکاسیون‌ها با معیار پذیرش مشخصات پروژه یا استاندارد مرجع مقایسه شده و نتیجه به همراه مستندات کامل در گزارش RT ثبت می‌شود؛ در موارد مبهم، بازبینی توسط نفر دوم یا سطح بالاتر توصیه می‌شود.","key_points":["کنترل کیفیت پذیرش فیلم قبل از تفسیر","بررسی سیستماتیک کامل عرض و طول جوش","ثبت موقعیت، شکل، اندازه و الگوی هر اندیکاسیون","طبقه‌بندی نوع ناپیوستگی بر اساس ویژگی‌های مشاهده‌شده","مقایسه با معیار پذیرش مشخصات یا استاندارد","مستندسازی و بازبینی مضاعف در موارد مبهم"],"excellent_answer_indicators":["اشاره به شرایط محیطی تفسیر مانند نور محیط و روشنایی صفحه نمایش","تاکید بر رویکرد یکسان و قابل تکرار در همه فیلم‌ها","ذکر اهمیت مقایسه با فیلم‌های مرجع یا کاتالوگ عیوب برای طبقه‌بندی دقیق"],"common_mistakes":["شروع تفسیر بدون کنترل کیفیت فیلم","پاسخ کلی بدون ذکر گام‌های مشخص","نادیده گرفتن ثبت مستند ویژگی‌های اندیکاسیون"],"standard_reference":""},{"category":"TECHNICAL","sub_category":"تمایز Lack of Fusion از Lack of Penetration","difficulty":"L4","question_text":"در فیلم یک جوش شیاری با پاس ریشه، دو نوع اندیکاسیون خطی تیره در امتداد محور جوش دیده می‌شود: یکی دقیقاً در مرکز عرض جوش با لبه‌های نسبتاً منظم و پیوسته، و دیگری کمی به سمت یکی از لبه‌های ذوب با ظاهر نامنظم و متناوب. چگونه این دو را از نظر Lack of Penetration و Lack of Fusion تمایز می‌دهید و چه عاملی در تصمیم شما نقش تعیین‌کننده دارد؟","reference_answer":"اندیکاسیون خطی تیره که دقیقاً در مرکز عرض جوش و منطبق بر محور ریشه با لبه‌های صاف و پیوسته قرار دارد و نشان‌دهنده عدم ذوب کامل فلزات پایه در ریشه است، معمولاً Lack of Penetration تلقی می‌شود، زیرا موقعیت آن دقیقاً روی خط مرکزی ریشه جوش و معمولاً با عرض نسبتاً ثابت است. در مقابل، اندیکاسیونی که در امتداد یکی از خطوط ذوب بین فلز جوش و فلز پایه یا بین دو پاس متوالی قرار دارد و اغلب ظاهر نامنظم یا متناوب دارد، بیشتر با Lack of Fusion به‌ویژه Sidewall LOF یا Inter-run LOF مطابقت دارد چون در محل اتصال ناقص بین لایه‌ها یا دیواره شیار رخ می‌دهد. عامل تعیین‌کننده اصلی، موقعیت دقیق اندیکاسیون نسبت به هندسه جوش و دانش از طراحی شیار جوش و توالی پاس‌ها است؛ در موارد مبهم، بررسی زاویه تصویربرداری و مقایسه با محل واقعی خط فیوژن به تمایز کمک می‌کند. این تمایز اهمیت زیادی دارد چون Lack of Fusion معمولاً در بیشتر استانداردها با تلورانس بسیار کمتر یا رد کامل مواجه است در حالی که Lack of Penetration بسته به سرویس و کد ممکن است طول محدودی مجاز باشد.","key_points":["تشخیص LOP بر اساس موقعیت مرکزی روی خط ریشه","تشخیص LOF بر اساس موقعیت روی خط فیوژن یا دیواره شیار با ظاهر نامنظم","اهمیت دانش طراحی شیار و توالی پاس‌ها","نقش زاویه تصویربرداری در تمایز دقیق‌تر","تفاوت شدت برخورد پذیرشی بین LOF و LOP در استانداردها","توصیه بررسی تکمیلی در موارد مبهم"],"excellent_answer_indicators":["اشاره دقیق به Sidewall LOF در برابر Inter-run LOF","ذکر اینکه LOF می‌تواند سیگنال ضعیف‌تر یا کم‌کنتراست‌تر از LOP نشان دهد به دلیل هندسه نازک نقص","تاکید بر ریسک بحرانی‌تر LOF از نظر تمرکز تنش و رشد ترک"],"common_mistakes":["تشخیص صرفاً بر اساس تیرگی اندیکاسیون بدون توجه به موقعیت هندسی","عدم آگاهی از تفاوت شدت پذیرش بین این دو عیب در استانداردهای مختلف","خلط این دو عیب با ترک"],"standard_reference":"API 1104"},{"category":"TECHNICAL","sub_category":"تمایز تخلخل از انکلوژن سرباره","difficulty":"L2","question_text":"در یک فیلم، اندیکاسیونی به شکل نقاط گرد و تیره با لبه‌های نرم و پراکنده به صورت خوشه‌ای در یک ناحیه از جوش دیده می‌شود. اندیکاسیون دیگری در همان فیلم به صورت خطی، کشیده و با لبه‌های نامنظم و چگالی غیریکنواخت دیده می‌شود. این دو را چگونه تفسیر و طبقه‌بندی می‌کنید؟","reference_answer":"اندیکاسیون اول با شکل گرد، لبه‌های نرم و توزیع خوشه‌ای معمولاً معرف تخلخل است که ناشی از به‌دام‌افتادن گاز در حین انجماد فلز جوش است؛ اگر توزیع پراکنده و منفرد باشد تخلخل پراکنده و اگر متمرکز در یک ناحیه کوچک باشد تخلخل خوشه‌ای نامیده می‌شود. اندیکاسیون دوم با شکل خطی کشیده، لبه‌های نامنظم و چگالی غیریکنواخت در طول آن، مشخصه انکلوژن سرباره است که ناشی از به‌دام‌افتادن سرباره غیرفلزی از الکترود یا پاس قبلی است که به دلیل عدم تمیزکاری کامل بین پاس‌ها در جوش باقی مانده است. تفاوت کلیدی تشخیصی، یکنواختی شکل و تیرگی و همچنین الگوی توزیع است. هر دو معمولاً نسبت به ترک و لک آو فیوژن از نظر ریسک ساختاری کم‌خطرتر تلقی می‌شوند، اما اندازه، تعداد و تجمع آن‌ها باید طبق جدول پذیرش مشخصات پروژه یا استاندارد مقایسه شود.","key_points":["شناسایی تخلخل بر اساس شکل گرد و لبه نرم","شناسایی سرباره بر اساس شکل خطی نامنظم و چگالی متغیر","علت تشکیل هرکدام یعنی گاز محبوس در برابر سرباره غیرفلزی از عدم تمیزکاری","اهمیت الگوی توزیع در طبقه‌بندی","نیاز به مقایسه اندازه و تجمع با جدول پذیرش"],"excellent_answer_indicators":["اشاره به زیرشاخه‌های تخلخل مانند خوشه‌ای، خطی، پراکنده و لوله‌ای","تفکیک اصطلاح سرباره کشیده و ارتباط آن با پاس‌های چندلایه","تاکید بر عدم قضاوت صرف بر اساس یک اندیکاسیون بلکه بررسی کل الگو"],"common_mistakes":["خلط سرباره با لک آو فیوژن به دلیل شکل خطی مشابه بدون توجه به موقعیت","نادیده گرفتن الگوی توزیع در طبقه‌بندی"],"standard_reference":"API 1104"},{"category":"CASE_STUDY","sub_category":"مطالعه موردی خوشه تخلخل","difficulty":"L2","question_text":"فیلم رادیوگرافی یک جوش حلقوی خط لوله را در حال تفسیر هستید. چگالی فیلم در ناحیه مورد بررسی 2.3 است و سیم IQI الزامی به‌وضوح قابل مشاهده است، یعنی کیفیت فیلم قابل قبول است. در فاصله تقریبی 40 میلی‌متری از یک نقطه مرجع روی جوش، مجموعه‌ای شامل 9 نقطه گرد تیره با قطرهای بین 0.5 تا 1.5 میلی‌متر در یک ناحیه به طول تقریبی 12 میلی‌متر و عرض تقریبی 6 میلی‌متر مشاهده می‌شود؛ نقاط لبه نرم دارند و در سایر نقاط جوش اندیکاسیون مشابه دیده نمی‌شود. با فرض ضخامت جداری 9.5 میلی‌متر و استفاده از API 1104 به عنوان استاندارد پذیرش پروژه: این اندیکاسیون را چگونه طبقه‌بندی می‌کنید، علت احتمالی وقوع آن چیست، و برای پذیرش/رد آن به چه مواردی نیاز دارید؟","reference_answer":"با توجه به شکل گرد، لبه نرم، اندازه کوچک زیر 1.5 میلی‌متر و تجمع در یک ناحیه محدود بدون توزیع در سایر بخش‌های جوش، این اندیکاسیون به وضوح تخلخل خوشه‌ای است. علت احتمالی این عیب معمولاً آلودگی موضعی سطح جوش مانند رطوبت، روغن یا زنگ‌زدگی در آن ناحیه خاص، نوسان لحظه‌ای در محافظت گازی در فرآیندهای قوس تنگستن یا قوس فلزی گازی، یا مشکل موضعی الکترود در فرآیندهای دیگر است. برای تصمیم پذیرش/رد باید طبق جدول پذیرش API 1104 برای تخلخل خوشه‌ای، اندازه تجمعی منطقه معیوب نسبت به سطح مقطع جوش در آن طول محاسبه و با حداکثر مجاز که به ضخامت دیواره و طول جوش مورد بررسی وابسته است مقایسه شود. در صورتی که اندازه تجمعی خوشه از حد مجاز مشخصات یا استاندارد فراتر رود، جوش رد و باید طبق روش تعمیر تاییدشده بازسازی و مجدداً رادیوگرافی شود؛ در غیر این صورت با ثبت در گزارش به عنوان قابل قبول تلقی می‌شود.","key_points":["طبقه‌بندی صحیح به عنوان تخلخل خوشه‌ای بر اساس شکل و توزیع","ذکر علل احتمالی مانند آلودگی یا اختلال گاز محافظ","نیاز به محاسبه و مقایسه اندازه تجمعی با جدول پذیرش","رجوع به API 1104 به عنوان استاندارد پذیرش مشخص‌شده","تصمیم رد و نیاز به تعمیر با روش تاییدشده در صورت عبور از حد مجاز"],"excellent_answer_indicators":["اشاره به اینکه تصمیم نهایی نیازمند دسترسی به جدول دقیق پذیرش API 1104 برای آن ضخامت است نه حدس","تفکیک صریح تخلخل خوشه‌ای از پراکنده یا خطی","ذکر لزوم بررسی محدودیت طول موثر طبق کد"],"common_mistakes":["رد فوری جوش صرفاً بر اساس تعداد نقاط بدون محاسبه اندازه تجمعی نسبت به معیار","خلط این عیب با انکلوژن سرباره"],"standard_reference":"API 1104"},{"category":"CASE_STUDY","sub_category":"مطالعه موردی لک آو فیوژن دیواره‌ای","difficulty":"L4","question_text":"در یک جوش چندپاسه لوله با ضخامت 14.3 میلی‌متر، فیلم رادیوگرافی کیفیت قابل قبول دارد. یک اندیکاسیون خطی کم‌کنتراست به طول 55 میلی‌متر مشاهده می‌شود که موازی با محور جوش و در فاصله ثابتی از مرکز جوش منطبق با موقعیت تقریبی خط ذوب دیواره شیار قرار دارد؛ عرض اندیکاسیون بسیار باریک و یکنواخت است و لبه‌های آن کاملاً صاف و پیوسته‌اند، بدون هیچ انشعاب یا شاخه فرعی. این اندیکاسیون را چگونه تفسیر می‌کنید، محتمل‌ترین علت آن چیست، و اقدام شما چیست؟","reference_answer":"با توجه به موقعیت دقیق روی خط ذوب دیواره شیار، شکل خطی باریک با عرض یکنواخت، کنتراست پایین و لبه‌های صاف و پیوسته بدون انشعاب، این الگو کاملاً مشخصه لک آو فیوژن دیواره‌ای است که ناشی از عدم ذوب کافی بین فلز جوش و فلز پایه در حین جوشکاری است، معمولاً به دلیل آمپراژ ناکافی، سرعت پیشروی بالا، زاویه یا تکنیک نادرست الکترود، یا وجود اکسید روی سطح شیار قبل از رسوب پاس. کنتراست پایین این عیب به دلیل هندسه نازک و صاف شکاف عدم‌ذوب است که باعث تفاوت جذب پرتو کمتر نسبت به ترک یا تخلخل می‌شود، به همین دلیل این نوع عیب یکی از دشوارترین عیوب برای تشخیص در رادیوگرافی است. از نظر پذیرش، لک آو فیوژن در اکثر استانداردهای معتبر برای خطوط لوله فشار بالا عمدتاً غیرقابل قبول یا با تلورانس بسیار محدود در نظر گرفته می‌شود، به‌ویژه به دلیل ریسک بالای تمرکز تنش و رشد ترک خستگی. اقدام صحیح رد جوش و ارجاع به تعمیر طبق روش تاییدشده شامل برداشت کامل ناحیه معیوب، بازرسی بصری قبل از جوشکاری مجدد و رادیوگرافی مجدد پس از تعمیر است، همراه با ثبت NCR و اطلاع به واحد جوشکاری برای بررسی پارامترهای فرآیند.","key_points":["تشخیص صحیح Sidewall LOF بر اساس موقعیت روی خط ذوب و شکل خطی کم‌کنتراست","توضیح علت متالورژیکی یا فرآیندی احتمالی","توضیح دلیل کنتراست پایین این عیب در فیلم","رد جوش با توجه به سختگیری بالای استانداردها نسبت به LOF","لزوم تعمیر طبق روش تاییدشده و رادیوگرافی مجدد","ثبت NCR و بازخورد به فرآیند جوشکاری"],"excellent_answer_indicators":["تاکید ویژه بر دشواری تشخیص LOF کم‌کنتراست و لزوم کیفیت فیلم بالا","اشاره به ریسک بحرانی این عیب از نظر مکانیک شکست","ذکر اهمیت بازخورد به مهندسی جوشکاری برای اصلاح پارامتر یا تکنیک"],"common_mistakes":["اشتباه گرفتن این عیب با انکلوژن سرباره به دلیل شکل خطی بدون توجه به کنتراست و موقعیت","دست کم گرفتن اهمیت این عیب و پیشنهاد پذیرش با توجیه طول کوتاه"],"standard_reference":"API 1104"},{"category":"CASE_STUDY","sub_category":"مطالعه موردی بریدگی کناره جوش","difficulty":"L2","question_text":"در فیلم یک جوش لوله رویه‌ای، یک اندیکاسیون خطی کم‌عمق و کم‌کنتراست دقیقاً در امتداد و روی خط ذوب بیرونی جوش دیده می‌شود که طول آن 65 میلی‌متر است و با اندازه‌گیری روی خود لوله پس از رویت، عمق آن حدود 1 میلی‌متر گزارش شده است. ضخامت جداری لوله 9.5 میلی‌متر و مشخصات پروژه حداکثر عمق مجاز undercut را 0.5 میلی‌متر یا 12.5 درصد ضخامت، هرکدام کمتر، با حداکثر طول تجمعی مشخص تعیین کرده است. اقدام شما چیست؟","reference_answer":"با توجه به موقعیت اندیکاسیون دقیقاً روی خط ذوب بیرونی و ماهیت آن، این عیب Undercut است که ناشی از ذوب بیش‌ازحد فلز پایه در کنار جوش رویه‌ای بدون پرشدن کافی توسط فلز جوش است، معمولاً به دلیل آمپراژ بالا، زاویه نادرست الکترود یا سرعت پیشروی نامناسب در پاس رویه. از آنجا که عمق اندازه‌گیری‌شده یک میلی‌متر از حداکثر مجاز مشخصات پروژه یعنی نیم میلی‌متر فراتر رفته است، این جوش باید رد شود، حتی اگر طول آن به‌تنهایی در محدوده مجاز طول تجمعی بود؛ عمق تعیین‌کننده اصلی پذیرش undercut است. باید توجه داشت که رادیوگرافی به‌تنهایی برای اندازه‌گیری دقیق عمق undercut کافی نیست چون یک عیب سطحی و هندسی است و ارزیابی نهایی معمولاً باید با بازرسی بصری و گیج مخصوص روی خود قطعه تایید شود، بنابراین هماهنگی با بازرس بصری ضروری است. اقدام نهایی رد جوش، ثبت NCR، و ارجاع به تعمیر مانند سنگ‌زنی کنترل‌شده در صورت باقی ماندن ضخامت کافی یا جوشکاری ترمیمی طبق روش تاییدشده است.","key_points":["تشخیص صحیح Undercut بر اساس موقعیت روی خط ذوب بیرونی","درک اینکه رادیوگرافی به تنهایی کافی برای اندازه‌گیری دقیق عمق نیست و نیاز به تایید بصری دارد","تصمیم رد بر اساس عبور عمق از حد مجاز حتی با طول قابل قبول","علت فرآیندی احتمالی مانند آمپراژ یا زاویه نامناسب پاس رویه","اقدام اصلاحی مانند سنگ‌زنی یا ترمیم طبق روش تاییدشده"],"excellent_answer_indicators":["تاکید صریح بر محدودیت ذاتی رادیوگرافی در سنجش دقیق عیوب سطحی و لزوم تکمیل با بازرسی بصری","اشاره به اینکه معیار هرکدام کمتر باید هر دو محاسبه و کمتر آن‌ها ملاک باشد"],"common_mistakes":["تکیه صرف بر رادیوگرافی برای تعیین عمق دقیق undercut بدون اشاره به نیاز تایید بصری","پذیرش جوش صرفاً بر اساس طول قابل قبول بدون توجه به عبور عمق از حد مجاز"],"standard_reference":""},{"category":"CASE_STUDY","sub_category":"مطالعه موردی ترک","difficulty":"L4","question_text":"در فیلم یک جوش با کیفیت مطلوب که چگالی 2.6 و IQI مطلوب دارد، یک اندیکاسیون بسیار باریک، تیز و پرکنتراست به شکل زیگزاگی نامنظم با انشعابات کوچک در چند نقطه مشاهده می‌شود که تقریباً به صورت عرضی نسبت به محور جوش و در ناحیه‌ای که پاس ریشه به پاس پرکننده متصل می‌شود کشیده شده است؛ طول کلی اندیکاسیون حدود 8 میلی‌متر است. با وجود طول کوتاه، این اندیکاسیون چه اهمیتی دارد و تصمیم شما چیست؟ چرا این عیب با وجود طول کوتاه نسبت به عیوبی مانند تخلخل با طول مشابه، برخورد کاملاً متفاوتی می‌طلبد؟","reference_answer":"ویژگی‌های توصیف‌شده شامل باریکی شدید، کنتراست بالا به دلیل هندسه بسیار نازک و عمیق شکاف، شکل زیگزاگی و نامنظم با انشعاب، و جهت عرضی نسبت به محور جوش، کاملاً مشخصه یک ترک است، به‌ویژه احتمال ترک عرضی که می‌تواند ناشی از تنش‌های انقباضی حین سرد شدن، هیدروژن تله‌افتاده، یا تنش پسماند بالا در نقطه اتصال پاس‌ها باشد. برخلاف تخلخل یا سرباره که عیوب حجمی نسبتاً کروی یا نامنظم با نوک صاف هستند، ترک یک عیب صفحه‌ای با نوک بسیار تیز است که تحت بار سرویس به شدت باعث تمرکز تنش شده و مستعد رشد سریع و شکست ناگهانی یا خستگی است؛ به همین دلیل تقریباً در تمام استانداردهای معتبر هرگونه ترک صرف‌نظر از طول یا اندازه کاملاً غیرقابل قبول است، برخلاف تخلخل که تا حدی مشخص و بر اساس تجمع و طول قابل قبول است. تصمیم قطعی رد جوش، توقف کار تا بررسی کامل علت ریشه‌ای توسط مهندسی جوشکاری، برش کامل ناحیه معیوب و نه صرفاً تعمیر موضعی سطحی، و در صورت لزوم بازرسی ترک‌های مشابه در جوش‌های مجاور با همان پارامتر جوشکاری خواهد بود، همراه با ثبت فوری NCR و اطلاع‌رسانی به کارفرما یا مدیر QC با توجه به حساسیت بالای این نوع عیب.","key_points":["شناسایی صحیح به عنوان ترک بر اساس شکل زیگزاگی، انشعاب، کنتراست بالا و نوک تیز","توضیح ماهیت عیب صفحه‌ای در برابر عیوب حجمی و پیامد تمرکز تنش","رد قطعی و بدون تلورانس طول در استانداردهای معتبر","لزوم بررسی ریشه‌ای علت مانند هیدروژن یا تنش نه فقط تعمیر موضعی","ضرورت بررسی جوش‌های مشابه و اطلاع‌رسانی فوری به سطوح بالا"],"excellent_answer_indicators":["اشاره دقیق به نوع احتمالی ترک بر اساس موقعیت و شکل","تاکید بر عدم تلورانس صفر برای ترک در همه کدهای اصلی صرف نظر از سرویس","تاکید بر اقدام سیستمی مانند بررسی سایر جوش‌های مشابه نه فقط رفع مورد منفرد"],"common_mistakes":["مقایسه نادرست طول کوتاه با محدودیت طول عیوب حجمی و نتیجه‌گیری غلط قابل قبول بودن به دلیل کوتاهی","عدم تاکید بر ضرورت بررسی ریشه‌ای و توقف کار"],"standard_reference":"API 1104"},{"category":"CASE_STUDY","sub_category":"مطالعه موردی نقص فیلم ناشی از خطای تکنیک","difficulty":"L3","question_text":"فیلمی از یک جوش دریافت می‌کنید که در نگاه اول در بخش مرکزی روی جوش چگالی حدود 2.8 و قابل قبول است، اما در حاشیه فیلم نزدیک به لبه‌ها، در ناحیه‌ای که باید IQI و علائم شناسایی دیده شوند، افتادگی شدید چگالی و نیز یک الگوی مبهم و تار در کل تصویر دیده می‌شود، طوری که خواندن شماره‌های سربی شناسایی دشوار است. تصمیم شما چیست و چه عواملی را برای علت‌یابی این وضعیت بررسی می‌کنید؟","reference_answer":"مه‌آلودگی همراه با افت چگالی در حاشیه، حتی اگر ناحیه مرکزی روی جوش قابل قبول به نظر برسد، فیلم را از نظر کیفیت کلی نامعتبر می‌کند چون فاگینگ نشان‌دهنده اکسپوژر پرتوی ناخواسته مانند پرتو پراکنده، نشتی نور در تاریک‌خانه، نگهداری نامناسب فیلم یا نور اضافی کاست است که کنتراست کلی تصویر را کاهش داده و ممکن است اندیکاسیون‌های کم‌کنتراست مانند لک آو فیوژن را بپوشاند حتی در ناحیه‌ای که چگالی عددی قابل قبول نشان می‌دهد. علاوه بر این، عدم توانایی خواندن واضح علائم شناسایی سربی به معنای عدم قابلیت ردیابی جوش است که به‌تنهایی برای رد فیلم کافی است، صرف‌نظر از وضعیت ناحیه جوش. علل احتمالی که باید بررسی شود شامل نشتی نور در تاریک‌خانه یا کاست، نگهداری نامناسب فیلم از نظر دما و رطوبت، پرتو پراکنده ناشی از نبود یا ناکافی بودن صفحات سربی پشت فیلم، و مشکل در محلول ظهور است. این فیلم باید رد و تصویربرداری تکرار شود و همزمان علت ریشه‌ای با تیم رادیوگرافی و تاریک‌خانه بررسی و رفع شود.","key_points":["تشخیص فاگینگ به عنوان معیار رد مستقل از چگالی ناحیه اصلی","اهمیت خوانایی شناسایی به عنوان معیار پذیرش فیلم","فهرست علل احتمالی مانند نشتی نور، پرتو پراکنده، فیلم منقضی و محلول ظهور","تصمیم رد و تکرار تصویربرداری","لزوم ریشه‌یابی با تیم تاریک‌خانه و رادیوگرافی"],"excellent_answer_indicators":["اشاره مشخص به آزمون کنترل پرتو پراکنده با حرف سربی پشت کاست به عنوان روش استاندارد بررسی","تفکیک علل شیمیایی مرتبط با ظهور یا نگهداری فیلم از علل نوری یا پرتویی"],"common_mistakes":["قبول فیلم صرفاً بر اساس چگالی قابل قبول ناحیه جوش بدون توجه به فاگینگ و خوانایی شناسه","عدم توجه به اینکه فاگینگ می‌تواند عیوب کم‌کنتراست را مخفی کند"],"standard_reference":"ASME Section V"},{"category":"PROBLEM_SOLVING","sub_category":"اختلاف بین دو مفسر در تصمیم پذیرش یا رد","difficulty":"L3","question_text":"شما و یک مفسر همکار که هر دو دارای گواهینامه معتبر هستید، درباره یک فیلم به توافق نمی‌رسید: شما اندیکاسیون را Lack of Fusion و قابل رد ارزیابی می‌کنید، همکارتان آن را Slag Inclusion قابل قبول می‌داند. هیچ‌کدام مافوق دیگری نیست. چه فرآیندی را برای حل این اختلاف دنبال می‌کنید؟","reference_answer":"اولین گام، بازبینی مشترک فیلم روی یک view screen با بحث درباره شواهد فنی مشخص مانند موقعیت نسبت به خط ذوب، شکل، کنتراست و الگوی توزیع است تا مشخص شود اختلاف ناشی از خوانش متفاوت داده یکسان است یا برداشت متفاوت از معیار طبقه‌بندی. اگر اختلاف پس از بحث فنی حل نشد، باید طبق رویه کیفیت پروژه به شخص ثالث مستقل و دارای صلاحیت بالاتر، معمولاً بازرس رادیوگرافی سطح سه، ارجاع داده شود تا نظر نهایی و مستند بدهد، چون تصمیم پذیرش یا رد جوش نباید بر اساس رای اکثریت غیرفنی یا مصالحه بین دو نظر متفاوت گرفته شود. در حین این فرآیند، جوش باید در وضعیت معلق باقی بماند و در مستندات پروژه به وضوح ذکر شود که این جوش در حال بازبینی سطح بالاتر است. پس از دریافت نظر نهایی، آن به عنوان تصمیم قطعی ثبت و به هر دو مفسر بازخورد داده می‌شود، و در صورت وجود الگوی تکراری چنین اختلافاتی، بازآموزی یا کالیبراسیون بین مفسران توصیه می‌شود.","key_points":["بازبینی مشترک بر مبنای شواهد فنی نه رای‌گیری","ارجاع به مرجع بالاتر مانند بازرس سطح سه در صورت عدم توافق","نگه‌داشتن وضعیت جوش معلق تا تصمیم نهایی","مستندسازی کامل فرآیند اختلاف و تصمیم","بازخورد و بهبود مانند کالیبراسیون بین مفسران در صورت تکرار"],"excellent_answer_indicators":["تاکید بر عدم مصالحه مانند تعمیر جزئی برای رضایت هر دو به عنوان راه‌حل غیرقابل قبول","اشاره به اهمیت رویه مستند پروژه برای چنین شرایطی"],"common_mistakes":["حل اختلاف با رای‌گیری یا مصالحه غیرفنی","ادامه دادن با نظر شخصی بدون ارجاع رسمی به سطح بالاتر","عدم مستندسازی فرآیند اختلاف"],"standard_reference":""},{"category":"SCENARIO","sub_category":"درخواست تکرار تصویربرداری با توجیه مورد اختلاف","difficulty":"L3","question_text":"پیمانکار جوشکاری پس از رد یک جوش توسط شما با استناد به وجود Lack of Penetration به طول قابل توجه، درخواست می‌کند فیلم دوباره گرفته شود با این استدلال که زاویه تصویربرداری اشتباه بوده و باعث دیده شدن سایه کاذب شده است، بدون ارائه مستندات فنی مشخص. با توجه به فشار زمانی پروژه، چگونه با این درخواست برخورد می‌کنید؟","reference_answer":"درخواست ری‌شوت باید بر اساس شواهد فنی مستند ارزیابی شود نه صرفاً ادعای کلامی؛ بنابراین از پیمانکار می‌خواهم دلیل فنی مشخص مانند اینکه کدام پارامتر تکنیک اشتباه بوده را مستند ارائه دهد و آن را با گزارش تکنیک اصلی مقایسه می‌کنم. اگر بازبینی نشان دهد فیلم اصلی از نظر کیفیت کاملاً قابل قبول بوده و اندیکاسیون مطابق ویژگی‌های واقعی Lack of Penetration است، درخواست ری‌شوت بدون شواهد فنی معتبر رد می‌شود، چون قبول چنین درخواستی بدون مبنا به معنای نادیده گرفتن استقلال فنی فرآیند تفسیر برای رفع فشار زمانی یا تجاری است. تصمیم فقط بر اساس شواهد فنی گرفته می‌شود، نه فشار برنامه زمانی. تمام مکاتبات و دلایل رد درخواست باید مستند و به مدیریت QC یا پروژه گزارش شود تا در صورت تشدید موضوع توسط پیمانکار، سابقه شفاف وجود داشته باشد؛ در صورتی که پیمانکار همچنان معترض باشد، مسیر رسمی ارجاع به بازرس سطح سه یا کارفرما طی می‌شود، نه تصمیم یک‌جانبه مفسر برای رضایت پیمانکار.","key_points":["نیاز به شواهد فنی مستند برای پذیرش درخواست ری‌شوت","بازبینی گزارش تکنیک و کیفیت فیلم اصلی به عنوان مرجع تصمیم","رد درخواست بدون مبنای فنی حتی تحت فشار زمانی","مستندسازی کامل تعامل و تصمیم","مسیر ارجاع رسمی در صورت تشدید اختلاف"],"excellent_answer_indicators":["تاکید صریح بر استقلال حرفه‌ای مفسر در برابر فشار تجاری یا زمانی پیمانکار","اشاره به ریسک پیامد منفی که پذیرش بدون مبنا باعث تکرار الگوی مشابه در آینده می‌شود"],"common_mistakes":["پذیرش درخواست ری‌شوت صرفاً برای کاهش تنش یا فشار برنامه بدون بررسی فنی","نداشتن مستندسازی از تعامل و تصمیم"],"standard_reference":""},{"category":"PROBLEM_SOLVING","sub_category":"عدم تطابق فرمت گزارش RT با الزامات ITP","difficulty":"L2","question_text":"در بازبینی مستندات پیش از تحویل بخشی از پروژه، متوجه می‌شوید که فرمت گزارش‌های RT مورد استفاده تیم شما فاقد یک ستون الزامی مانند نوع و درصد حساسیت IQI به تفکیک هر فیلم است که در ITP مصوب پروژه به صراحت خواسته شده، در حالی که صدها فیلم قبلاً با این فرمت ناقص گزارش شده‌اند. چگونه با این وضعیت برخورد می‌کنید؟","reference_answer":"ابتدا باید بررسی شود که آیا اطلاعات مورد نیاز واقعاً برای هر فیلم ثبت و در دسترس است اما صرفاً در قالب گزارش درج نشده، یا اینکه اصلاً این کنترل به صورت مستند برای فیلم‌های گذشته انجام نشده که تفاوت بسیار مهمی در شدت مشکل ایجاد می‌کند. اگر داده‌ها موجود اما ثبت‌نشده در فرمت هستند، باید فرمت گزارش فوراً اصلاح و داده‌های موجود از یادداشت‌های تکنیک یا خود فیلم استخراج و گزارش‌های قبلی به‌روزرسانی و تکمیل شود. اگر داده به صورت واقعی موجود نیست، باید موضوع به عنوان یک ریسک کیفی جدی به مدیریت QC و کارفرما گزارش شود، چون ممکن است نیاز به بازبینی مجدد فیلم‌های موجود برای تایید حساسیت واقعی از طریق خود فیلم که IQI روی آن قابل مشاهده است، باشد نه لزوماً تکرار تصویربرداری. در هر دو حالت، باید یک اقدام اصلاحی مستند شامل اصلاح فرمت، آموزش تیم گزارش‌نویسی و ممیزی نمونه‌ای از گزارش‌های گذشته تدوین و اجرا شود.","key_points":["تفکیک بین کمبود فرمت با داده موجود و کمبود محتوا با داده واقعاً ثبت نشده","اقدام اصلاحی فوری در فرمت گزارش","بازبینی و تکمیل گزارش‌های قبلی از روی فیلم اصلی در صورت امکان","گزارش شفاف به QC و کارفرما در صورت مشکل جدی‌تر","تدوین اقدام اصلاحی سیستمی شامل آموزش و ممیزی نمونه‌ای"],"excellent_answer_indicators":["تاکید بر اینکه چون IQI روی خود فیلم موجود است امکان بازیابی اطلاعات بدون نیاز به تصویربرداری مجدد وجود دارد","اشاره به لزوم هماهنگی با کارفرما پیش از هرگونه تصمیم یک‌جانبه درباره حجم زیاد گزارش‌های قبلی"],"common_mistakes":["نادیده گرفتن مشکل با این توجیه که همه فیلم‌ها قبلاً تایید شده‌اند","اصلاح فقط گزارش‌های آینده بدون توجه به گزارش‌های قبلی که ممکن است مورد ممیزی کارفرما قرار گیرند"],"standard_reference":""},{"category":"SCENARIO","sub_category":"اندیکاسیون مرزی نزدیک به حد پذیرش","difficulty":"L4","question_text":"در حال اندازه‌گیری طول یک اندیکاسیون Slag Inclusion هستید که طبق معیار پذیرش مشخصات پروژه حداکثر طول مجاز 6 میلی‌متر است. اندازه‌گیری اولیه شما با خط‌کش شفاف روی فیلم عدد 5.8 میلی‌متر نشان می‌دهد، اما با توجه به کیفیت لبه‌های نه‌چندان کاملاً واضح اندیکاسیون، مطمئن نیستید که اندازه‌گیری دقیقاً درست باشد و ممکن است واقعی 6.2 یا 6.3 میلی‌متر باشد. با این عدم قطعیت نزدیک به مرز پذیرش چگونه برخورد می‌کنید؟","reference_answer":"در مواجهه با اندیکاسیون‌های مرزی نزدیک به حد پذیرش، اولین اقدام تکرار اندازه‌گیری با ابزار دقیق‌تر مانند بزرگنمایی یا ابزار اندازه‌گیری کالیبره‌شده مخصوص فیلم و در شرایط نوری بهینه است تا خطای اندازه‌گیری کاهش یابد؛ صرف استفاده از خط‌کش ساده برای تصمیم‌گیری مرزی کافی نیست. سپس توصیه می‌شود یک نفر دوم مانند مفسر مستقل یا سطح بالاتر به صورت مستقل همان اندازه‌گیری را انجام دهد تا از عینیت نتیجه اطمینان حاصل شود؛ اگر دو اندازه‌گیری مستقل هر دو زیر حد مجاز باشند با اطمینان معقول می‌توان پذیرفت، اما اگر حتی یکی از اندازه‌گیری‌ها به یا بالای حد برسد، اصل احتیاط مهندسی حکم می‌کند که جوش رد شود، چون هدف رادیوگرافی اطمینان از ایمنی سازه است نه یافتن راهی برای رد نکردن یک مورد مشکوک. تصمیم نباید هرگز بر اساس گرد کردن به نفع پذیرش یا فشار برنامه زمانی گرفته شود؛ در موارد واقعاً غیرقطعی، توصیه به رد و تعمیر یا در صورت مجاز بودن طبق رویه، ارزیابی تکمیلی مانند فراصوت است.","key_points":["نیاز به اندازه‌گیری دقیق‌تر با ابزار و شرایط بهتر قبل از تصمیم نهایی","بازبینی مستقل توسط نفر دوم برای موارد مرزی","اصل احتیاط مهندسی یعنی ترجیح رد در ابهام به جای گرد کردن به نفع پذیرش","عدم تاثیرپذیری تصمیم از فشار زمانی یا تجاری","امکان استفاده از روش تکمیلی مانند فراصوت در صورت مجاز بودن طبق رویه"],"excellent_answer_indicators":["تاکید صریح بر اینکه شک در اندازه‌گیری مرزی باید همیشه به نفع ایمنی و نه به نفع برنامه تفسیر شود","اشاره به مستندسازی کامل هر دو اندازه‌گیری و نام مفسر دوم برای شفافیت"],"common_mistakes":["تصمیم‌گیری قطعی بر اساس یک اندازه‌گیری ساده بدون تکرار یا تایید مستقل","گرد کردن عدد به نفع پذیرش تحت فشار برنامه","نادیده گرفتن عدم قطعیت ابزار اندازه‌گیری"],"standard_reference":""},{"category":"EXPERIENCE_BASED","sub_category":"تجربه مدیریت تعارض تحت فشار برنامه‌زمانی","difficulty":"L3","question_text":"یک نمونه واقعی از تجربه خود را شرح دهید که در آن مجبور شدید تصمیم رد یک جوش را در شرایطی که تیم پروژه تحت فشار شدید زمانی یا برنامه‌ای بود، به مدیریت پروژه یا کارفرما اطلاع و اصرار کنید. چگونه این موضوع را مطرح کردید و نتیجه چه شد؟","reference_answer":"این سوال تجربه‌محور است؛ ارزیابی باید بر اساس معیارهای زیر روی هر داستان واقعی انجام شود. پاسخ قوی باید یک موقعیت مشخص و واقعی شامل نوع عیب، پروژه و طرف مقابل را با جزئیات کافی توصیف کند، نه پاسخی کلی و بی‌جزئیات. باید نشان داده شود که تصمیم فنی برای رد جوش صرفاً بر مبنای شواهد و معیار پذیرش گرفته شده و تحت فشار زمانی تغییر نکرده است. فرد باید نحوه اطلاع‌رسانی حرفه‌ای مانند گزارش مکتوب، جلسه با مدیریت و ارائه شواهد فنی به جای برخورد احساسی، و در صورت لزوم مسیر تشدید به سطح بالاتر سازمانی یا کارفرما را توضیح دهد. نتیجه نهایی و پیامد آن و درسی که از آن گرفته مانند بهبود ارتباط پیشگیرانه با تیم برنامه‌ریزی، نشانه بلوغ حرفه‌ای است.","key_points":["توصیف موقعیت واقعی و مشخص","حفظ استقلال تصمیم فنی در برابر فشار برنامه","نحوه ارتباط حرفه‌ای و مستند با مدیریت یا کارفرما","مسیر تشدید در صورت نیاز","نتیجه نهایی و پیامد واقعی","درس آموخته یا بهبود فرآیندی"],"excellent_answer_indicators":["نشان دادن تعادل بین قاطعیت فنی و مدیریت رابطه کاری سازنده","ارجاع به مستندات یا رویه رسمی به جای تصمیم شخصی صرف","تاثیر مثبت بلندمدت بر فرهنگ کیفیت پروژه"],"common_mistakes":["پاسخ کاملاً فرضی و کلی بدون جزئیات واقعی","بیان تسلیم شدن در برابر فشار زمانی و تغییر نتیجه فنی بدون مبنا","نبود مستندسازی یا مسیر رسمی گزارش‌دهی"],"standard_reference":""}]'::jsonb) as x(
  category text, sub_category text, difficulty text, question_text text, reference_answer text,
  key_points jsonb, excellent_answer_indicators jsonb, common_mistakes jsonb, standard_reference text
)
where not exists (select 1 from comp_question_bank where job_role = 'radiography_interpreter');

-- ---- civil_engineer (23 questions) ----
insert into comp_question_bank (job_role, category, sub_category, difficulty, question_text, reference_answer, key_points, excellent_answer_indicators, common_mistakes, standard_reference)
select 'civil_engineer', x.category, x.sub_category, x.difficulty, x.question_text, x.reference_answer,
       coalesce(x.key_points, '[]'::jsonb), coalesce(x.excellent_answer_indicators, '[]'::jsonb), coalesce(x.common_mistakes, '[]'::jsonb), coalesce(x.standard_reference, '')
from jsonb_to_recordset('[{"category":"GENERAL","sub_category":"مستندسازی و گزارش‌دهی","difficulty":"L1","question_text":"به عنوان مهندس Civil در یک پروژه خط لوله انتقال گاز، در طول اجرای عملیات خاکی و ابنیه چه مستنداتی باید به صورت روزانه/هفتگی تهیه و به مشاور/کارفرما ارائه کنید و این مستندات چه نقشی در زنجیره کنترل کیفیت و تسویه حساب پیمانکار دارند؟","reference_answer":"باید گزارش روزانه پیشرفت (Daily Progress Report) شامل حجم خاکبرداری/بکفیل/تراکم انجام‌شده، گزارش‌های QC (نتایج تست تراکم، اسلامپ، مقاومت بتن)، چک‌لیست‌های بازرسی (ITP) امضاشده توسط پیمانکار و ناظر، درخواست بازرسی (Inspection Request/IR)، و به‌روزرسانی نقشه‌های as-built تهیه شود. این مستندات باید بر اساس برنامه کنترل کیفیت پروژه (ITP/Quality Plan) ردیابی و بایگانی شوند تا در صورت بروز اختلاف یا NCR قابل استناد باشند. همچنین این سوابق مبنای تایید صورت‌وضعیت (Interim Payment Certificate) پیمانکار و ارزیابی پیشرفت واقعی در برابر برنامه زمان‌بندی هستند. عدم مستندسازی صحیح می‌تواند در ادعاهای تاخیر یا کیفیت بعداً مشکل‌ساز شود.","key_points":["گزارش روزانه/هفتگی پیشرفت","چک‌لیست ITP و درخواست بازرسی (IR)","سوابق تست‌های کیفی (تراکم، بتن)","ارتباط با صورت‌وضعیت و تایید پرداخت","بایگانی برای رفع اختلاف/ادعا","به‌روزرسانی نقشه as-built"],"excellent_answer_indicators":["اشاره به سیستم مدیریت اسناد (DCC) و traceability","پیوند مستقیم بین مستندسازی و کاهش ریسک ادعا (claim)","اشاره به فرمت استاندارد گزارش‌دهی پروژه‌های EPC","تاکید بر امضای همزمان پیمانکار/ناظر برای جلوگیری از اختلاف بعدی"],"common_mistakes":["ذکر فقط گزارش پیشرفت بدون اشاره به سوابق کیفی","عدم اشاره به ارتباط مستندات با صورت‌وضعیت مالی","نگاه کردن به مستندسازی به عنوان کار اداری صرف و نه ابزار مدیریت ریسک"],"standard_reference":""},{"category":"GENERAL","sub_category":"مدیریت NCR","difficulty":"L2","question_text":"اگر در حین بازرسی متوجه شوید که یک بخش از خط لوله بکفیل شده بدون آنکه تست تراکم لازم روی آن انجام یا مستند شده باشد، چه اقدامی انجام می‌دهید و فرآیند رسمی NCR را چگونه طی می‌کنید؟","reference_answer":"اولین اقدام، توقف کار بعدی در آن بخش (Hold Point) و اطلاع کتبی به پیمانکار و ثبت موضوع به عنوان یک عدم انطباق (Non-Conformance Report) است. باید بررسی کرد که آیا امکان تست غیرمخرب (مانند سوند یا حفر test pit) در همان لایه یا لایه‌های بالایی وجود دارد یا خیر، و در صورت عدم امکان اثبات تراکم کافی، درخواست بازگشایی (excavate back) و اجرای مجدد بکفیل با تست مرحله‌ای صادر می‌شود. NCR باید شامل شرح مشکل، ریشه‌یابی علت (چرا تست انجام نشده)، اقدام اصلاحی، اقدام پیشگیرانه (مثلاً بازنگری روش اجرایی/witness point) و مسئول پیگیری با مهلت زمانی باشد. در نهایت باید تا بسته شدن کامل NCR با تایید کیفیت (QC/QA) و امضای مشاور، وضعیت آن باز بماند.","key_points":["توقف کار و Hold Point","ثبت رسمی NCR با شرح دقیق","بررسی امکان اثبات تراکم با روش جایگزین یا حفر مجدد","ریشه‌یابی علت وقوع (چرا witness point رعایت نشد)","اقدام اصلاحی و پیشگیرانه","پیگیری تا بسته شدن رسمی NCR"],"excellent_answer_indicators":["اشاره به بازنگری ITP برای افزودن hold/witness point","تاکید بر مستندسازی دقیق برای جلوگیری از ادعای بعدی پیمانکار","پیشنهاد اقدام سیستمی مانند آموزش یا تغییر روش نظارت به جای فقط رفع مورد نقطه‌ای"],"common_mistakes":["نادیده گرفتن موضوع چون بکفیل ظاهراً خوب به نظر می‌رسد","صدور NCR بدون ریشه‌یابی یا اقدام پیشگیرانه","اجازه ادامه کار در بخش‌های بعدی قبل از حل مسئله"],"standard_reference":""},{"category":"GENERAL","sub_category":"مدیریت رابط کاری (Interface)","difficulty":"L3","question_text":"در پروژه خط لوله، عملیات حفر ترانشه، پایین‌انداختن لوله (lowering-in) و بکفیل باید با فعالیت‌های گروه مکانیکال/جوشکاری هماهنگ شود. اگر برنامه جوشکاری عقب بیفتد و ترانشه‌های حفرشده برای مدت طولانی باز بمانند، به عنوان مهندس Civil چه ریسک‌هایی را شناسایی کرده و چه اقداماتی برای مدیریت رابط کاری با تیم مکانیکال انجام می‌دهید؟","reference_answer":"ریسک‌های اصلی شامل ریزش دیواره ترانشه، جمع‌شدن آب باران در ترانشه، خطر ایمنی برای عبور و مرور، تخریب شیب‌بندی و نیاز به لایروبی مجدد، و تداخل با فعالیت‌های کشاورزی/تردد محلی در حریم است. باید در جلسات هماهنگی روزانه (interface meeting) بین گروه‌های Civil و مکانیکال، برنامه زمان‌بندی به‌روز جوشکاری را پیگیری کرده و طول باز ترانشه (open trench length) را طبق مشخصات فنی و مجوزهای زیست‌محیطی محدود نگه دارد. در صورت تاخیر قابل توجه، می‌توان بخش‌هایی از ترانشه را موقتاً پوشش یا محافظت کرد (پلیت‌گذاری یا حصارکشی) و زهکشی موقت برای جلوگیری از آب‌گرفتگی تعبیه کرد. مستندسازی این هماهنگی و اطلاع‌رسانی رسمی به مدیریت پروژه در صورت تاثیر بر برنامه زمان‌بندی کلی نیز ضروری است.","key_points":["شناسایی ریسک ریزش/آب‌گرفتگی ترانشه باز","رعایت محدودیت طول مجاز ترانشه باز طبق مشخصات/HSE","جلسات هماهنگی interface روزانه با تیم مکانیکال","اقدامات موقت حفاظتی (شیب‌بندی، پوشش، حصار، زهکشی)","مستندسازی تاخیر و اطلاع‌رسانی به مدیریت پروژه","توجه به ایمنی عمومی و حریم"],"excellent_answer_indicators":["اشاره صریح به محدودیت مجاز طول ترانشه باز طبق مشخصات پروژه یا مجوز HSE","پیشنهاد بازنگری توالی کاری (sequencing) برای کاهش طول باز به جای فقط واکنش","در نظر گرفتن اثر بر تاخیر پیمانکار و ادعای احتمالی"],"common_mistakes":["نادیده گرفتن مسئله تا زمانی که مشکل ایمنی رخ دهد","عدم هماهنگی رسمی و صرفاً حل موردی و شفاهی","تمرکز فقط بر جنبه فنی بدون توجه به تاثیر برنامه‌ای و ایمنی"],"standard_reference":""},{"category":"GENERAL","sub_category":"تصمیم‌گیری تحت فشار زمانی/جوی","difficulty":"L3","question_text":"پیش‌بینی هواشناسی نشان می‌دهد ظرف ۴۸ ساعت آینده بارش شدید در منطقه رخ خواهد داد، در حالی که چند بخش از ترانشه باز است و یک پیمانکار زیرمجموعه فشار می‌آورد که برای رعایت برنامه زمان‌بندی، بکفیل بدون تکمیل تست‌های تراکم مرحله‌ای انجام شود. تصمیم شما چیست و چگونه توجیه می‌کنید؟","reference_answer":"تصمیم درست، اولویت‌دادن به کیفیت و ایمنی بر فشار زمان‌بندی است؛ نباید اجازه بکفیل بدون تست‌های الزامی داده شود، اما باید هم‌زمان اقدامات کاهش ریسک بارش انجام شود مانند تسریع تکمیل بخش‌هایی که تست‌هایشان تمام شده، ایجاد شیب و زهکشی موقت روی ترانشه‌های باز، و در صورت امکان پوشاندن موقت. باید به پیمانکار به صورت مکتوب اعلام شود که هرگونه بکفیل بدون تست مورد قبول نیست و در صورت انجام، مشمول NCR و احتمال بازگشایی خواهد بود. اگر فشار زمان‌بندی واقعی است، باید موضوع فوراً به مدیریت پروژه/کارفرما اطلاع داده شود تا منابع اضافی (تیم تست بیشتر، شیفت اضافه) تامین گردد یا برنامه به‌طور رسمی بازنگری شود. تصمیم نهایی و دلایل آن باید مستند شود تا در صورت خسارت ناشی از بارش، مسئولیت روشن باشد.","key_points":["عدم پذیرش بکفیل بدون تست تراکم مرجع","اقدامات مدیریت ریسک بارش (شیب‌بندی، زهکشی موقت، پوشش)","اطلاع‌رسانی مکتوب و رسمی به پیمانکار و مدیریت پروژه","درخواست منابع اضافی به جای دور زدن کیفیت","مستندسازی تصمیم برای شفافیت مسئولیت"],"excellent_answer_indicators":["پیشنهاد راه‌حل عملیاتی موازی به جای فقط رد درخواست","درک تعادل بین ریسک ایمنی/کیفیت و ریسک برنامه‌ای","اشاره به مسئولیت قراردادی پیمانکار در صورت خسارت ناشی از تصمیم غلط"],"common_mistakes":["پذیرش فشار پیمانکار برای حفظ روابط کاری","تصمیم‌گیری بدون اطلاع‌رسانی به بالادست","توجه فقط به برنامه زمانی و نادیده گرفتن ریسک کیفیت/ایمنی"],"standard_reference":""},{"category":"GENERAL","sub_category":"مدیریت تعارض و تشدید (Escalation)","difficulty":"L2","question_text":"پیمانکار جزء با نظر شما درباره رد یک قسمت از کار (مثلاً شیب بستر ترانشه که خارج از تلورانس مجاز است) مخالف است و ادعا می‌کند که کار قابل قبول است. اگر بحث در سطح سرپرست کارگاه به نتیجه نرسد، چگونه این تعارض را مدیریت و در صورت لزوم به سطح بالاتر ارجاع می‌کنید؟","reference_answer":"ابتدا باید اختلاف را بر مبنای معیار عینی (نقشه اجرایی، مشخصات فنی، نتایج اندازه‌گیری/تست) و نه نظر شخصی حل کرد؛ اندازه‌گیری مجدد مشترک با حضور نماینده پیمانکار می‌تواند اختلاف را شفاف کند. اگر توافق حاصل نشد، موضوع باید به صورت مکتوب (مثلاً از طریق site instruction یا NCR) ثبت و به سطح بالاتر پروژه (مهندس مقیم/مدیر پروژه مشاور) ارجاع شود، بدون آنکه کار تا حل موضوع تایید یا ادامه یابد. باید از برخورد احساسی یا شخصی پرهیز و بر روی مستندات فنی تمرکز شود؛ در صورت لزوم می‌توان نظر مهندس ژئوتکنیک یا واحد کیفیت کارفرما را نیز جویا شد. مهم است که کل روند گفتگو و تصمیم نهایی مستند و به هر دو طرف ابلاغ شود تا از تکرار اختلاف مشابه جلوگیری شود.","key_points":["تمرکز بر معیار عینی (نقشه/مشخصات/تست) نه نظر شخصی","اندازه‌گیری مجدد مشترک با پیمانکار","ارجاع مکتوب به سطح بالاتر در صورت عدم توافق","عدم تایید کار مورد اختلاف تا حل نهایی","مستندسازی و ابلاغ تصمیم نهایی به طرفین"],"excellent_answer_indicators":["حفظ رابطه کاری حرفه‌ای علی‌رغم اختلاف فنی","درخواست نظر تخصصی شخص ثالث در موارد پیچیده","جلوگیری از توقف کلی کار با تفکیک بخش مورد اختلاف از سایر کار"],"common_mistakes":["اصرار بر نظر شخصی بدون استناد مستند","پذیرش کار برای اجتناب از تنش با پیمانکار","عدم مستندسازی روند اختلاف و تصمیم نهایی"],"standard_reference":""},{"category":"TECHNICAL","sub_category":"Excavation / Dewatering","difficulty":"L2","question_text":"در حین خاکبرداری ترانشه در منطقه‌ای با سطح آب زیرزمینی بالا، آب داخل ترانشه جمع می‌شود و مانع ادامه کار و کنترل کیفیت بستر می‌گردد. چه روش‌های dewatering را می‌شناسید و انتخاب روش مناسب به چه عواملی بستگی دارد؟","reference_answer":"روش‌های رایج dewatering شامل پمپاژ مستقیم از چاهک جمع‌آوری (sump pumping)، استفاده از well-pointing برای پایین آوردن سطح آب زیرزمینی قبل از حفاری، و در موارد خاص دیوار موقت آب‌بند (sheet piling) است. انتخاب روش به نوع خاک (شن و ماسه در برابر رس)، عمق و شدت نفوذ آب، حساسیت سازه‌های مجاور به افت سطح آب، و محدودیت‌های زیست‌محیطی برای دفع آب پمپاژشده بستگی دارد. باید اطمینان حاصل شود که آب خروجی طبق مجوز محیط‌زیستی و بدون آسیب به اراضی کشاورزی یا مسیرهای آبی مجاور دفع می‌شود. همچنین کیفیت بستر ترانشه پس از dewatering باید مجدداً بازرسی و در صورت نرم شدن (softening)، لایه ناپایدار جایگزین گردد.","key_points":["sump pumping در برابر well-pointing","ارتباط انتخاب روش با نوع خاک و شدت نفوذ آب","توجه به مجوز محیط‌زیستی برای دفع آب","بازرسی و اصلاح بستر پس از dewatering","توجه به سازه‌های مجاور و افت سطح آب"],"excellent_answer_indicators":["اشاره به ریسک boiling/piping در خاک‌های ماسه‌ای هنگام dewatering نامناسب","در نظر گرفتن اثر بر پایداری شیب ترانشه","پیشنهاد پایش مستمر سطح آب و کیفیت بستر به جای اقدام یک‌باره"],"common_mistakes":["ذکر فقط پمپاژ ساده بدون توجه به نوع خاک","نادیده گرفتن الزامات زیست‌محیطی دفع آب","عدم بازرسی مجدد بستر پس از خشک شدن"],"standard_reference":""},{"category":"TECHNICAL","sub_category":"Backfilling / Compaction","difficulty":"L2","question_text":"مشخصات فنی پروژه، بکفیل منطقه لوله (pipe zone) را در لایه‌های حداکثر ۲۰ سانتی‌متری با تراکم حداقل ۹۵ درصد پروکتور استاندارد الزام کرده است. اگر پیمانکار بخواهد برای تسریع کار، ضخامت لایه را به ۴۰ سانتی‌متر افزایش دهد، چه پاسخی می‌دهید و چرا این موضوع اهمیت دارد؟","reference_answer":"این درخواست باید رد شود مگر آنکه پیمانکار بتواند با آزمایش تراکم واقعی (نه صرفاً ادعا) ثابت کند که با تجهیز فعلی می‌تواند در لایه ضخیم‌تر هم به تراکم مشخصات برسد و مشاور/کارفرما آن را به صورت رسمی از طریق trial section تایید کند. ضخامت لایه مستقیماً بر یکنواختی انرژی تراکم در تمام عمق لایه اثر می‌گذارد؛ در لایه‌های ضخیم، بخش زیرین لایه معمولاً به تراکم کافی نمی‌رسد که می‌تواند باعث نشست بعدی روی لوله و آسیب به پوشش یا اتصالات آن شود. بنابراین بدون trial section تایید‌شده و بدون تغییر رسمی مشخصات فنی از طریق فرآیند تغییر (variation)، نباید ضخامت لایه تغییر کند. تاکید بر اینکه هرگونه انحراف از مشخصات باید مستند و توسط طراح/کارفرما تایید شود.","key_points":["رد درخواست تا اثبات با trial section","ریسک عدم تراکم کافی در عمق لایه ضخیم","خطر نشست بعدی و آسیب به لوله/پوشش","نیاز به تایید رسمی از طریق فرآیند تغییر مشخصات","اهمیت یکنواختی انرژی تراکم در تمام عمق لایه"],"excellent_answer_indicators":["پیشنهاد trial section با تجهیزات واقعی پیمانکار به عنوان راه‌حل عملی","درک رابطه بین انرژی تراکم غلتک و عمق موثر تراکم","توجه به ریسک بلندمدت روی خط لوله نه فقط تخلف مقطعی"],"common_mistakes":["پذیرش درخواست پیمانکار برای تسریع کار بدون آزمایش","عدم توجه به تاثیر بر لوله مدفون","ندانستن مفهوم trial section به عنوان روش اثبات"],"standard_reference":"ASTM D698 / ASTM D1557"},{"category":"TECHNICAL","sub_category":"Soil Classification","difficulty":"L3","question_text":"در گزارش ژئوتکنیک پروژه، خاک مسیر خط لوله در برخی قطعات به عنوان CL (رس با خاصیت خمیری کم) و در قطعات دیگر SP (ماسه بد دانه‌بندی) طبقه‌بندی شده است. این تفاوت طبقه‌بندی چه تاثیری بر روش اجرای ترانشه، بستر لوله (bedding) و روش تراکم باید داشته باشد؟","reference_answer":"در خاک‌های رسی (CL) به دلیل چسبندگی بالا و حساسیت به رطوبت، ترانشه ممکن است در کوتاه‌مدت پایدار به نظر برسد اما مستعد ریزش تاخیری و تورم/انقباض است، بنابراین این خاک معمولاً برای بستر لوله مناسب نیست و باید با مصالح دانه‌ای انتخابی جایگزین شود؛ تراکم آن نیز باید نزدیک به رطوبت بهینه با غلتک پاچه‌بزی (sheepsfoot) انجام شود. در خاک‌های ماسه‌ای بددانه‌بندی (SP)، دیواره ترانشه بیشتر مستعد ریزش ناگهانی و نیاز به شیب‌بندی ملایم‌تر یا حائل (shoring/trench box) دارد، اما به عنوان بستر و بکفیل منطقه لوله می‌تواند با تراکم مناسب (غلتک ویبره یا صفحه ویبره) و کنترل رطوبت، عملکرد خوبی داشته باشد. در هر دو حالت، طبقه‌بندی خاک باید مبنای انتخاب شیب ترانشه طبق کلاس ایمنی خاک، نوع مصالح بستر و روش/تجهیز تراکم قرار گیرد نه یک روش یکسان برای کل مسیر.","key_points":["رفتار متفاوت رس (CL) و ماسه (SP) در پایداری دیواره ترانشه","لزوم جایگزینی خاک رسی نامناسب با بستر انتخابی برای لوله","انتخاب تجهیز تراکم متناسب با نوع خاک (پاچه‌بزی در برابر ویبره)","ارتباط طبقه‌بندی خاک با کلاس ایمنی ترانشه و شیب مجاز","کنترل رطوبت خاک رسی به عنوان عامل حیاتی"],"excellent_answer_indicators":["اشاره دقیق به سیستم USCS و رفتار مهندسی هر گروه خاک","پیوند مستقیم بین طبقه‌بندی ژئوتکنیکی و انتخاب شیب/حائل ترانشه طبق استاندارد ایمنی","توجه به ریسک تورم/انقباض رس بر عملکرد بلندمدت پوشش لوله"],"common_mistakes":["استفاده از یک روش تراکم و شیب یکسان برای همه انواع خاک","نادیده گرفتن نیاز به بستر انتخابی در خاک رسی","عدم آگاهی از رفتار متفاوت خاک‌ها در پایداری ترانشه"],"standard_reference":"ASTM D2487"},{"category":"TECHNICAL","sub_category":"Access Road / Road Construction","difficulty":"L2","question_text":"برای احداث جاده دسترسی دائمی به یکی از ایستگاه‌های خط لوله، آزمایش CBR بستر (subgrade) خاکی محل عددی پایین (مثلاً کمتر از ۳ درصد) نشان می‌دهد. این موضوع چه تاثیری بر طراحی روسازی دارد و چه راهکارهای اجرایی برای بهبود آن پیشنهاد می‌کنید؟","reference_answer":"CBR پایین بستر نشان‌دهنده ظرفیت باربری ضعیف است که در صورت عدم اصلاح، منجر به نشست، ترک خوردگی و شکست زودرس روسازی زیر بار ترافیک سنگین (کامیون‌های تجهیزات) خواهد شد. راهکارها شامل تعویض خاک نامناسب تا عمق مشخص با مصالح دانه‌ای مناسب (subbase)، تثبیت خاک با آهک یا سیمان در صورت رسی بودن خاک، یا استفاده از ژئوتکستایل/ژئوگرید برای جداسازی و توزیع بار در سطح مشترک بستر و لایه زیراساس است. ضخامت روسازی نیز باید بر اساس CBR بازنگری و افزایش یابد تا با ظرفیت باربری واقعی بستر تطابق داشته باشد. در هر صورت باید طراح/مهندس ژئوتکنیک پروژه، طراحی روسازی را بر اساس نتیجه واقعی CBR بازنگری و تایید کند، نه اینکه صرفاً طبق طراحی اولیه ادامه یابد.","key_points":["اثر CBR پایین بر ریسک نشست و شکست روسازی","گزینه تعویض خاک نامناسب یا تثبیت با آهک/سیمان","استفاده از ژئوتکستایل/ژئوگرید برای جداسازی و تسلیح","لزوم بازطراحی ضخامت روسازی متناسب با CBR واقعی","تایید طراح/ژئوتکنیک قبل از اجرای اصلاح"],"excellent_answer_indicators":["مقایسه فنی-اقتصادی گزینه‌های تثبیت در برابر تعویض خاک","اشاره به روش طراحی ضخامت روسازی بر اساس CBR","توجه به اثر بار ترافیکی ساخت (کامیون‌های سنگین) به عنوان بار طراحی بحرانی"],"common_mistakes":["ادامه اجرا طبق طراحی اولیه بدون بازنگری","پیشنهاد راه‌حل بدون در نظر گرفتن نوع خاک محلی","نادیده گرفتن نیاز به تایید مهندس طراح"],"standard_reference":""},{"category":"TECHNICAL","sub_category":"Rebar","difficulty":"L1","question_text":"هنگام بازرسی آرماتوربندی فونداسیون یک ساپورت لوله، متوجه می‌شوید که طول پوشش بتنی (concrete cover) در برخی نقاط کمتر از حد مشخصات است. چرا این موضوع مهم است و چه اقدامی قبل از بتن‌ریزی انجام می‌دهید؟","reference_answer":"پوشش بتنی کافی برای محافظت آرماتور در برابر خوردگی، مقاومت در برابر آتش، و انتقال صحیح تنش بین بتن و آرماتور ضروری است؛ کاهش پوشش می‌تواند در بلندمدت باعث زنگ‌زدگی آرماتور، ترک خوردگی بتن و کاهش عمر سازه شود. قبل از بتن‌ریزی باید بازرسی و اصلاح فاصله‌گذارها (spacer/chair) در تمام نقاط انجام شود تا پوشش طبق نقشه و مشخصات فنی تامین گردد. این مورد باید در چک‌لیست بازرسی آرماتوربندی ثبت و تا اصلاح کامل، مجوز بتن‌ریزی صادر نشود. در صورت تکرار این مشکل، باید روش نصب فاصله‌گذارها با پیمانکار بازنگری شود تا از تکرار جلوگیری شود.","key_points":["اهمیت پوشش بتنی برای حفاظت در برابر خوردگی و انتقال تنش","لزوم اصلاح فاصله‌گذارها قبل از بتن‌ریزی","عدم صدور مجوز بتن‌ریزی تا رفع کامل مغایرت","ثبت در چک‌لیست بازرسی آرماتور","بازنگری روش کار برای جلوگیری از تکرار"],"excellent_answer_indicators":["اشاره به تفاوت پوشش مجاز بر اساس شرایط مواجهه (تماس با خاک، هوای آزاد و غیره)","تاکید بر پیشگیری سیستمی (کنترل کیفیت فاصله‌گذار) نه فقط رفع نقطه‌ای","اشاره به تاثیر روی عمر بهره‌برداری سازه"],"common_mistakes":["نادیده گرفتن مغایرت جزئی پوشش بتن","اجازه بتن‌ریزی با وعده اصلاح بعدی","عدم ثبت مستند مغایرت"],"standard_reference":"ACI 318"},{"category":"TECHNICAL","sub_category":"Formwork","difficulty":"L3","question_text":"برای قالب‌بندی یک فونداسیون بتنی حجیم با ارتفاع ریزش بالا، پیمانکار از قالب‌های سبک معمولی بدون محاسبه فشار جانبی بتن تازه استفاده کرده است. چه ریسک‌هایی را شناسایی می‌کنید و بازرسی قالب‌بندی قبل از بتن‌ریزی باید شامل چه مواردی باشد؟","reference_answer":"ریسک اصلی، عدم کفایت مقاومت و مهاربندی قالب در برابر فشار جانبی بتن تازه است که به سرعت بتن‌ریزی، دمای بتن، اسلامپ و ارتفاع ریزش بستگی دارد؛ در صورت عدم طراحی صحیح، احتمال ترکیدگی قالب (blowout)، خمیدگی بیش از حد یا نشتی شیره بتن وجود دارد که می‌تواند باعث حادثه ایمنی و عیب سطحی/ساختاری بتن شود. بازرسی قبل از بتن‌ریزی باید شامل بررسی محاسبات طراحی قالب یا حداقل تاییدیه مهندسی برای فشار جانبی مورد انتظار، استحکام و فاصله مناسب مهاربندها، آب‌بندی درزها برای جلوگیری از نشت شیره، ابعاد و تراز قالب مطابق نقشه، و تمیزی و روغن‌کاری مناسب قالب باشد. در صورت مشکوک بودن طراحی قالب، باید محدودیت سرعت و ارتفاع ریزش بتن به پیمانکار ابلاغ و تا ارائه محاسبات یا تقویت قالب، بتن‌ریزی متوقف یا کنترل‌شده انجام شود.","key_points":["ریسک فشار جانبی بتن تازه و ترکیدگی قالب","لزوم محاسبه/تاییدیه طراحی قالب متناسب با سرعت ریزش و ارتفاع","بازرسی مهاربندی، آب‌بندی درز و تراز قالب","کنترل سرعت/ارتفاع ریزش در صورت عدم اطمینان از طراحی","توقف کار تا رفع نگرانی ایمنی/کیفی"],"excellent_answer_indicators":["اشاره به عوامل موثر بر فشار جانبی بتن (دما، اسلامپ، سرعت ریزش، ارتفاع)","پیشنهاد راه‌حل عملیاتی (کاهش سرعت ریزش یا ریزش لایه‌ای) به جای توقف کامل کار","توجه هم‌زمان به جنبه ایمنی کارگران و کیفیت بتن"],"common_mistakes":["تمرکز فقط بر ظاهر قالب بدون توجه به محاسبات فشار جانبی","غفلت از ریسک ایمنی جانی در حین بتن‌ریزی","عدم درخواست تاییدیه مهندسی برای قالب غیرمتعارف"],"standard_reference":"ACI 347"},{"category":"TECHNICAL","sub_category":"Foundation","difficulty":"L4","question_text":"چند ماه پس از تکمیل فونداسیون‌های بتنی ساپورت‌های لوله در یک بخش از مسیر، مشاهده می‌کنید که برخی فونداسیون‌ها نسبت به یکدیگر دچار نشست نسبی (differential settlement) شده‌اند و همین موضوع باعث ایجاد تنش غیرمجاز روی لوله شده است. به عنوان مهندس Civil چگونه علت را ریشه‌یابی می‌کنید و چه اقدامات اصلاحی/پیشگیرانه پیشنهاد می‌دهید؟","reference_answer":"ریشه‌یابی باید با مرور گزارش ژئوتکنیک منطقه (لایه‌بندی خاک، سطح آب زیرزمینی، وجود لایه‌های تراکم‌پذیر یا خاک آلی)، سوابق اجرایی فونداسیون (عمق واقعی حفاری، تراکم بستر، کیفیت بتن) و داده‌های survey/monitoring آغاز شود. باید بررسی شود که آیا نشست به دلیل عدم رسیدن به لایه باربری مناسب، تحکیم درازمدت خاک رسی زیر بار، یا تغییر رطوبت (مانند نشت آب) رخ داده است. اقدام اصلاحی می‌تواند شامل تزریق زیر پی (underpinning/grouting)، طراحی مجدد فونداسیون با پی عمیق‌تر یا گسترده‌تر در ادامه مسیر، و در صورت لزوم، افزودن ساپورت اضافی برای کاهش تنش موضعی روی لوله باشد. مهم‌تر از آن، باید یک برنامه پایش نشست برای کل مسیر با فونداسیون‌های مشابه در همان شرایط خاک راه‌اندازی شود تا از تکرار مشکل در سایر نقاط جلوگیری و ریسک به مهندس تنش لوله (pipe stress engineer) گزارش شود.","key_points":["بررسی سیستماتیک گزارش ژئوتکنیک و سوابق اجرایی فونداسیون","تشخیص علت (لایه باربری نامناسب، تحکیم، تغییر رطوبت)","راه‌حل اصلاحی مانند underpinning یا بازطراحی فونداسیون","هماهنگی با مهندس تنش لوله (pipe stress) به دلیل اثر مستقیم روی لوله","راه‌اندازی برنامه پایش نشست برای پیشگیری در سایر نقاط مشابه"],"excellent_answer_indicators":["رویکرد ریشه‌یابی ساختاریافته (داده محور) به جای حدس","درک ارتباط مستقیم بین نشست فونداسیون Civil و تنش مکانیکی روی خط لوله","پیشنهاد اقدام سیستمی/پیشگیرانه برای کل مسیر نه فقط نقطه معیوب","آگاهی از گزینه‌های فنی متنوع اصلاح (تزریق، پی عمیق، مانیتورینگ)"],"common_mistakes":["اصلاح فقط فونداسیون معیوب بدون بررسی علت ریشه‌ای","عدم اطلاع‌رسانی به تیم مکانیکال/تنش لوله درباره اثر روی خط لوله","نادیده گرفتن نیاز به پایش مستمر در سایر نقاط مشابه"],"standard_reference":""},{"category":"TECHNICAL","sub_category":"Survey","difficulty":"L1","question_text":"قبل از شروع عملیات خاکی مسیر خط لوله، چرا کنترل و تایید نقاط مبنا (control points/benchmarks) نقشه‌برداری اهمیت حیاتی دارد و اگر متوجه شوید که یکی از این نقاط جابه‌جا یا آسیب دیده، چه اقدامی انجام می‌دهید؟","reference_answer":"نقاط مبنا اساس تمام پیاده‌سازی مسیر، تراز و ابعاد اجرایی هستند و هرگونه خطا یا جابه‌جایی در آن‌ها به صورت تجمعی در طول مسیر منتقل شده و می‌تواند باعث انحراف کل مسیر لوله، تداخل با موانع یا عدم انطباق با مجوزهای عبور (ROW) شود. در صورت مشاهده آسیب یا جابه‌جایی احتمالی یک نقطه مبنا، باید بلافاصله کار پیاده‌سازی متکی به آن نقطه متوقف و موضوع به تیم نقشه‌برداری اطلاع داده شود. باید با مقایسه چند نقطه مبنای دیگر و در صورت لزوم مختصات‌برداری مجدد با دستگاه GPS/توتال استیشن، صحت نقطه بررسی و در صورت تایید آسیب، نقطه جدید با مرجعیت رسمی جایگزین و تمام کارهای اجراشده بر اساس آن نقطه راستی‌آزمایی شود. این موضوع باید مستند و به مشاور/کارفرما اطلاع داده شود تا ریسک انحراف احتمالی مدیریت گردد.","key_points":["نقش نقاط مبنا به عنوان اساس پیاده‌سازی مسیر","ریسک انتقال خطا در طول مسیر خطی","توقف کار متکی به نقطه مشکوک تا راستی‌آزمایی","راستی‌آزمایی با نقاط مبنای دیگر و مختصات‌برداری مجدد","اطلاع‌رسانی رسمی و مستندسازی"],"excellent_answer_indicators":["درک ماهیت تجمعی خطای نقشه‌برداری در پروژه خطی طولانی","پیشنهاد راستی‌آزمایی متقاطع (cross-check) با چند نقطه مرجع","توجه به اثر احتمالی بر ROW و مالکیت اراضی مجاور"],"common_mistakes":["ادامه کار با فرض درست بودن نقطه مشکوک","عدم اطلاع فوری به تیم نقشه‌برداری","کم‌اهمیت جلوه دادن جابه‌جایی جزئی نقطه مبنا"],"standard_reference":""},{"category":"TECHNICAL","sub_category":"Culvert / Drainage","difficulty":"L3","question_text":"در طراحی یک کالورت برای عبور آب‌راهه فصلی از زیر جاده دسترسی خط لوله، چه پارامترهایی را برای تعیین قطر و نوع کالورت در نظر می‌گیرید و اگر بعد از اجرا مشاهده کنید که در اولین بارندگی شدید، آب از روی جاده سرریز می‌کند، چه چیزی احتمالاً اشتباه بوده است؟","reference_answer":"پارامترهای اصلی طراحی شامل دبی سیل طراحی (بر اساس دوره بازگشت مشخص‌شده در مشخصات پروژه)، شیب و سرعت جریان مجاز برای جلوگیری از فرسایش دهانه، سطح آب بالادست مجاز (headwater)، رسوب و بار شناور احتمالی، و ارتفاع پوشش خاک روی کالورت برای تحمل بار ترافیکی هستند. سرریز آب از روی جاده در اولین بارندگی معمولاً نشان‌دهنده کم‌برآورد دبی طراحی (مثلاً استفاده از داده هیدرولوژیک ناکافی یا دوره بازگشت نامناسب)، انسداد ورودی کالورت با رسوب/آوار، یا اجرای نادرست شیب کالورت (عدم تخلیه کامل) است. باید بلافاصله ورودی/خروجی کالورت از نظر انسداد بازرسی و پاکسازی شود و محاسبات هیدرولیکی اولیه با داده‌های واقعی بارندگی/حوضه آبریز بازبینی گردد. در صورت اثبات کمبود ظرفیت، باید کالورت با قطر بزرگ‌تر یا افزودن کالورت موازی جایگزین و طراحی برای کل مسیر مشابه بازنگری شود.","key_points":["دبی طراحی بر اساس دوره بازگشت و مساحت حوضه آبریز","توجه به شیب، سرعت جریان و فرسایش دهانه","بررسی انسداد ورودی/خروجی به عنوان علت رایج سرریز","احتمال کم‌برآورد هیدرولوژیک یا خطای اجرایی شیب","نیاز به بازنگری طراحی برای کالورت‌های مشابه در مسیر"],"excellent_answer_indicators":["اشاره به روش‌های محاسبه دبی طراحی (مانند روش عقلانی/Rational Method)","پیوند بین یک شکست موضعی و بازنگری سیستمی طراحی سایر سازه‌های مشابه در مسیر","توجه هم‌زمان به علل طراحی و علل اجرایی به جای فرض یک‌طرفه"],"common_mistakes":["فرض قطعی که علت فقط انسداد است بدون بررسی محاسبات طراحی","نادیده گرفتن اثر فرسایش و رسوب در دهانه کالورت","عدم بازنگری سایر کالورت‌های مشابه پس از یک شکست"],"standard_reference":""},{"category":"PROBLEM_SOLVING","sub_category":"Compaction Testing","difficulty":"L3","question_text":"در یک بخش از بکفیل ترانشه، نتایج تست تراکم صحرایی سه بار پیاپی زیر حد مجاز مشخصات (مثلاً کمتر از ۹۵٪ پروکتور استاندارد) گزارش شده، در حالی که پیمانکار مدعی است دستگاه و روش کار مطابق روال قبلی است که همیشه جواب داده. علت‌یابی و اقدام شما چیست؟","reference_answer":"ابتدا باید صحت خود آزمایش بررسی شود؛ شامل کالیبراسیون دستگاه تراکم‌سنج (مانند دستگاه هسته‌ای یا مخروط ماسه)، صحت مرجع پروکتور استفاده‌شده (آیا برای نوع خاک فعلی و نه خاک قبلی است)، و مهارت اپراتور تست. اگر آزمایش صحیح تایید شد، باید عوامل اجرایی بررسی شود: تغییر نوع/رطوبت خاک منبع قرضه، عدم کنترل رطوبت نسبت به رطوبت بهینه، ضخامت لایه بیش از حد مجاز، یا کاهش تعداد پاس غلتک/انرژی تراکم به دلیل عجله در کار. راه‌حل شامل انجام یک trial section کنترل‌شده با تغییر یک متغیر در هر بار (تعداد پاس، رطوبت، ضخامت لایه) برای یافتن ترکیب موثر، و تا رفع مشکل نباید بکفیل بیشتر روی این لایه یا لایه‌های بعدی انجام شود. تمام این فرآیند باید مستند و به عنوان اقدام اصلاحی NCR ثبت شود.","key_points":["بررسی صحت و کالیبراسیون دستگاه/روش تست","بررسی تطابق منحنی پروکتور مرجع با خاک واقعی","بررسی عوامل اجرایی (رطوبت، ضخامت لایه، تعداد پاس غلتک)","استفاده از trial section برای یافتن روش موثر","توقف بکفیل بیشتر تا رفع مشکل و مستندسازی به عنوان NCR"],"excellent_answer_indicators":["رویکرد سیستماتیک و مرحله‌ای عیب‌یابی به جای حدس فوری","شناخت اهمیت رطوبت بهینه (OMC) در دستیابی به تراکم هدف","طراحی trial section با تغییر یک متغیر در هر مرحله برای جداسازی علت"],"common_mistakes":["پذیرش ادعای پیمانکار بدون بررسی مستقل","تغییر مشخصات تراکم به جای اصلاح روش اجرا","نادیده گرفتن احتمال تغییر منبع قرضه خاک"],"standard_reference":"ASTM D1557"},{"category":"SCENARIO","sub_category":"Trenching / Geotechnical Issues","difficulty":"L3","question_text":"در حین حفر ترانشه در بخشی از مسیر که گزارش ژئوتکنیک آن را خاک متراکم قابل اعتماد پیش‌بینی کرده بود، به طور غیرمنتظره به یک لایه خاک نرم و اشباع با ظرفیت باربری بسیار پایین برخورد می‌کنید که برای بستر لوله مناسب نیست. اولین اقدام شما چیست و فرآیند رسمی برخورد با این شرایط غیرمنتظره زمین (unforeseen ground condition) را چگونه طی می‌کنید؟","reference_answer":"اولین اقدام، توقف کار در همان قطعه و ایمن‌سازی محل و اطلاع فوری به مهندس ژئوتکنیک/مشاور برای بازدید و ارزیابی میدانی است. باید حدود طولی و عمقی ناحیه نامناسب با آزمایش‌های ساده یا در صورت نیاز آزمایش تکمیلی مشخص شود. بسته به شرایط، راه‌حل‌های فنی می‌تواند شامل تعویض خاک نامناسب با مصالح دانه‌ای درشت (over-excavation and replacement)، استفاده از ژئوتکستایل/ژئوگرید برای پایداری بستر، یا در موارد شدید تثبیت خاک باشد که باید توسط طراح تایید شود. از نظر قراردادی، این شرایط باید به عنوان unforeseen ground condition مستند شود (عکس، مختصات، توصیف، مقایسه با گزارش ژئوتکنیک اصلی) زیرا می‌تواند مبنای درخواست تغییر مقادیر یا تمدید زمان توسط پیمانکار باشد، بنابراین مستندسازی همزمان و دقیق برای هر دو طرف کارفرما و پیمانکار حیاتی است.","key_points":["توقف کار و ایمن‌سازی محل قبل از هر اقدام دیگر","اطلاع فوری به مهندس ژئوتکنیک/مشاور برای ارزیابی","تعیین حدود طولی/عمقی ناحیه نامناسب","راه‌حل فنی (تعویض خاک، ژئوگرید/ژئوتکستایل، تثبیت) با تایید طراح","مستندسازی به عنوان unforeseen ground condition برای جنبه قراردادی"],"excellent_answer_indicators":["تشخیص هم‌زمان بعد فنی و بعد قراردادی/ادعای احتمالی پیمانکار","مستندسازی دقیق و به‌موقع (عکس، مختصات GPS، توصیف) به عنوان مدرک","پیشنهاد بررسی سایر قطعات مشابه مسیر برای پیشگیری از تکرار غافلگیری"],"common_mistakes":["ادامه اجرای بستر روی خاک نامناسب بدون توقف","عدم مستندسازی همزمان که بعداً به ادعای پیمانکار منجر می‌شود","تصمیم‌گیری فنی بدون مشورت با ژئوتکنیک/طراح"],"standard_reference":""},{"category":"SCENARIO","sub_category":"Slope Stability / Erosion Control / Crossing Works","difficulty":"L4","question_text":"پیش‌بینی هواشناسی، بارش شدید و غیرمعمول را برای منطقه‌ای اعلام کرده که خط لوله از یک شیب طبیعی نزدیک به عبور رودخانه (river crossing) عبور می‌کند و کار خاکی و تثبیت شیب هنوز به طور کامل تکمیل نشده است. چه اقدامات فوری پیشگیرانه‌ای انجام می‌دهید و پس از بارش، ارزیابی پایداری شیب را چگونه انجام می‌دهید؟","reference_answer":"اقدامات فوری پیش از بارش شامل تکمیل یا تقویت موقت سیستم زهکشی سطحی برای هدایت آب دور از ترانشه و شیب، نصب موانع فرسایش موقت (سیلت فنس، بلوک‌های سنگی/بگ‌های شنی) در پایین‌دست، و در صورت امکان پوشاندن سطوح خاک لخت با ژئوممبرین یا مالچ موقت است. باید همچنین وضعیت اضطراری به تیم HSE و مدیریت پروژه اطلاع داده شود و در صورت خطر جانی، دسترسی/کار در آن ناحیه محدود یا متوقف شود. پس از بارش، ارزیابی باید شامل بازدید بصری برای علائم ترک کششی، جابه‌جایی خاک، یا رطوبت غیرعادی در بالای شیب، بررسی هرگونه فرسایش یا رسوب‌گذاری در پای شیب و نزدیکی رودخانه، و در صورت مشاهده علائم نگران‌کننده، توقف کار و درخواست ارزیابی رسمی مهندس ژئوتکنیک با احتمال نیاز به ابزار پایش (inclinometer/piezometer) باشد. تصمیم نهایی ادامه کار باید بر اساس تایید ایمنی پایداری شیب از سوی متخصص ژئوتکنیک باشد نه فقط ظاهر بصری.","key_points":["اقدامات پیشگیرانه پیش از بارش (زهکشی موقت، کنترل فرسایش، پوشش خاک لخت)","اطلاع‌رسانی HSE و محدودیت دسترسی در صورت خطر","بازرسی بصری پس از بارش برای علائم ناپایداری (ترک، جابه‌جایی)","بررسی ویژه نزدیکی به رودخانه/عبور و ریسک فرسایش کناره","نیاز به تایید مهندس ژئوتکنیک قبل از ازسرگیری کار، احتمالاً با ابزار پایش"],"excellent_answer_indicators":["رویکرد پیشگیرانه فعال قبل از وقوع بارش نه صرفاً واکنش پس از آن","توجه ویژه به حساسیت crossing رودخانه‌ای (ریسک زیست‌محیطی و ایمنی بالاتر)","پیشنهاد ابزار پایش مهندسی برای موارد مشکوک","تصمیم‌گیری مبتنی بر تایید تخصصی نه قضاوت شخصی"],"common_mistakes":["اقدام فقط واکنشی بعد از بارش بدون آماده‌سازی پیشین","ارزیابی صرفاً بصری بدون در نظر گرفتن نیاز به ابزار دقیق در موارد مشکوک","نادیده گرفتن ریسک ویژه نزدیکی به رودخانه (فرسایش/آلودگی)"],"standard_reference":""},{"category":"PROBLEM_SOLVING","sub_category":"Concrete","difficulty":"L4","question_text":"نتایج تست مقاومت فشاری نمونه‌های استوانه‌ای بتن ۲۸ روزه برای یک فونداسیون مهم (مثلاً پایه یک تجهیز سنگین) حدود ۱۵ درصد کمتر از مقاومت مشخصه طراحی گزارش شده است. به عنوان مهندس Civil چه مراحلی را برای ارزیابی و تصمیم‌گیری درباره پذیرش، تعمیر یا تخریب طی می‌کنید؟","reference_answer":"ابتدا باید نتایج تست‌های زودتر، روند رشد مقاومت، شرایط عمل‌آوری (curing) نمونه‌ها و صحت روش نمونه‌گیری/آزمایش بررسی شود تا از صحت خود نتیجه اطمینان حاصل شود. در صورت تایید کمبود مقاومت واقعی، باید طبق رویه استاندارد از خود سازه هسته‌گیری و آزمایش شود (core testing) تا مقاومت واقعی درجا مشخص گردد، زیرا نمونه استوانه‌ای همیشه نماینده دقیق مقاومت واقعی سازه نیست. نتایج core test باید توسط مهندس سازه/طراح ارزیابی و بر اساس آن، یکی از گزینه‌های پذیرش مشروط (در صورت کفایت برای بار طراحی با ضریب اطمینان کاهش‌یافته)، تقویت/ترمیم سازه‌ای، یا در بدترین حالت تخریب و بازسازی تعیین شود. تمام این فرآیند باید به عنوان NCR رسمی با تحلیل ریشه‌ای (مانند نسبت آب به سیمان نامناسب، عمل‌آوری ناکافی، یا دمای بالای بتن‌ریزی) مستند و اقدام پیشگیرانه برای بتن‌ریزی‌های بعدی تعریف شود.","key_points":["بررسی صحت نتیجه تست (روند رشد مقاومت، عمل‌آوری نمونه، کالیبراسیون دستگاه)","استفاده از core testing درجا برای تعیین مقاومت واقعی سازه","ارزیابی توسط مهندس سازه/طراح برای تصمیم نهایی","گزینه‌های پذیرش مشروط، تعمیر/تقویت، یا تخریب بر اساس نتیجه","مستندسازی NCR با ریشه‌یابی و اقدام پیشگیرانه برای آینده"],"excellent_answer_indicators":["دانش دقیق از تفاوت مقاومت نمونه استوانه‌ای و مقاومت درجای سازه","رویکرد مبتنی بر داده و مهندسی به جای تصمیم احساسی (تخریب فوری یا پذیرش بدون بررسی)","تحلیل ریشه‌ای علت کاهش مقاومت برای پیشگیری آینده","آگاهی از گزینه‌های تقویت سازه‌ای به عنوان جایگزین تخریب کامل"],"common_mistakes":["تصمیم فوری به تخریب یا پذیرش بدون core testing","اعتماد کامل به نمونه استوانه‌ای بدون بررسی شرایط نمونه‌گیری/عمل‌آوری","عدم مشورت با مهندس طراح سازه قبل از تصمیم‌گیری"],"standard_reference":"ACI 318 / ASTM C42"},{"category":"SCENARIO","sub_category":"ROW Restoration","difficulty":"L2","question_text":"پس از تکمیل بکفیل و بازسازی حریم (ROW restoration) در یک قطعه کشاورزی، مالک زمین ادعا می‌کند که کیفیت خاک سطحی (topsoil) بازگردانده‌شده نامناسب است و محصول او را تحت تاثیر قرار داده است، در حالی که پیمانکار مدعی است طبق روش اجرایی مصوب عمل کرده. چگونه این اختلاف را بررسی و حل می‌کنید؟","reference_answer":"ابتدا باید مستندات اجرایی بازسازی (روش جداسازی و بازگرداندن topsoil طبق روش اجرایی مصوب، عکس‌های قبل/حین/بعد از کار) بررسی شود تا مشخص گردد که آیا واقعاً توالی صحیح (جداسازی topsoil در ابتدای کار، بازگرداندن آن به عنوان لایه سطحی نهایی) رعایت شده یا خاک زیرین با سطحی مخلوط شده است. بازدید میدانی مشترک با حضور مالک زمین، پیمانکار و در صورت نیاز کارشناس کشاورزی/محیط‌زیست برای ارزیابی واقعی وضعیت خاک ضروری است. اگر مغایرت با روش مصوب یا تعهدات حریم اثبات شود، باید اقدام اصلاحی (اضافه کردن topsoil مناسب، شخم سبک برای کاهش تراکم) در قالب یک برنامه اصلاحی مشخص با پیمانکار تعیین و اجرا شود. تمام روند بررسی، توافق و اقدام اصلاحی باید مستند و در صورت لزوم با واحد امور اراضی/community relations هماهنگ شود تا از تشدید اختلاف اجتماعی و ریسک شهرت پروژه جلوگیری شود.","key_points":["بررسی مستندات و توالی صحیح اجرای بازسازی topsoil","بازدید میدانی مشترک با مالک زمین و پیمانکار","ارزیابی فنی واقعی وضعیت خاک (ضخامت، تراکم، آلودگی)","اقدام اصلاحی مشخص در صورت اثبات مغایرت","هماهنگی با واحد امور اراضی/روابط اجتماعی برای مدیریت ریسک اجتماعی"],"excellent_answer_indicators":["توجه هم‌زمان به جنبه فنی (خاک) و جنبه اجتماعی/روابط عمومی پروژه","استفاده از مستندات عکس/ویدئو قبل از کار به عنوان مبنای اثبات","پیشنهاد راه‌حل عملی اصلاحی به جای صرفاً رد یا پذیرش ادعا"],"common_mistakes":["رد فوری ادعای مالک زمین بدون بررسی میدانی","پذیرش ادعا بدون استناد به مستندات اجرایی","برخورد صرفاً فنی بدون توجه به حساسیت روابط اجتماعی/محلی"],"standard_reference":""},{"category":"EXPERIENCE_BASED","sub_category":"As-built / Survey","difficulty":"L2","question_text":"یک تجربه واقعی از پروژه‌های قبلی خود را شرح دهید که در آن پس از بکفیل یا تکمیل یک بخش از کار، متوجه مغایرت بین وضعیت اجراشده واقعی و نقشه as-built/اجرایی شدید. چگونه متوجه موضوع شدید، چه اقدامی انجام دادید و نتیجه نهایی چه بود؟","reference_answer":"این سوال تجربه‌محور است و پاسخ صحیح واحد ندارد؛ ارزیابی باید بر اساس واقعی و ملموس بودن مثال ارائه‌شده باشد، نه یک پاسخ تئوریک عمومی. پاسخ قوی باید نشان دهد که کاندیدا چگونه مغایرت را تشخیص داده (بازرسی میدانی، مقایسه survey، گزارش شخص ثالث)، چه فرآیند رسمی (NCR، گزارش مغایرت، هماهنگی با تیم نقشه‌برداری/طراح) را طی کرده، و چگونه نقشه as-built یا اجرا را اصلاح کرده است. باید مشخص شود که آیا کاندیدا نتیجه نهایی و درسی که از این تجربه گرفته را نیز بیان می‌کند یا خیر. عدم وجود جزئیات مشخص (نام پروژه، زمان تقریبی، نوع مغایرت، نتیجه) نشانه ضعف تجربه واقعی است.","key_points":["واقعی و مشخص بودن مثال (پروژه، زمان، نوع مغایرت)","روش تشخیص مغایرت","فرآیند رسمی طی‌شده (NCR/گزارش/هماهنگی نقشه‌برداری)","نحوه اصلاح وضعیت اجرا یا نقشه","نتیجه نهایی و درس آموخته‌شده"],"excellent_answer_indicators":["ذکر جزئیات کمی‌شده (مثلاً میزان انحراف، طول مسیر متاثر)","اشاره به اقدام پیشگیرانه سیستمی برای پروژه‌های بعدی","نشان‌دادن مالکیت شخصی بر حل مسئله نه صرفاً گزارش‌دهی منفعلانه"],"common_mistakes":["پاسخ کلی و غیراختصاصی بدون جزئیات واقعی","توصیف مشکل بدون بیان اقدام یا نتیجه مشخص","نسبت دادن کامل مسئولیت به دیگران بدون نقش شخصی روشن"],"standard_reference":""},{"category":"EXPERIENCE_BASED","sub_category":"Erosion Control","difficulty":"L3","question_text":"یک تجربه واقعی را بیان کنید که در آن سیستم کنترل فرسایش (erosion control) اجراشده در پروژه (مانند سیلت فنس، پوشش شیب، زهکش موقت) پس از یک رویداد بارندگی دچار شکست یا ناکارآمدی شد. چه اتفاقی افتاد، چگونه واکنش نشان دادید و چه تغییری در طراحی/اجرا برای آینده اعمال شد؟","reference_answer":"این سوال تجربه‌محور است؛ ارزیابی باید بر اساس این باشد که آیا کاندیدا واقعاً یک رویداد واقعی و مشخص (نه فرضی) را با جزئیات کافی شرح می‌دهد. پاسخ قوی باید شامل توصیف دقیق نوع شکست (مثلاً پارگی سیلت فنس، رسوب‌گذاری در آب‌راهه، فرسایش شیار روی شیب)، اقدام فوری برای کنترل خسارت (پاکسازی رسوب، تعمیر فوری سیستم)، و تحلیل علت ریشه‌ای (طراحی ناکافی برای شدت بارندگی واقعی، نصب نامناسب، عدم نگهداری دوره‌ای) باشد. باید مشخص شود که آیا نتیجه این تجربه به تغییر واقعی در روش اجرایی یا طراحی کنترل فرسایش منجر شده است. عدم آگاهی از تفاوت انواع روش‌های کنترل فرسایش یا نداشتن تجربه دستی واقعی در این زمینه، نشانه ضعف است.","key_points":["توصیف دقیق و واقعی رویداد شکست","اقدام فوری کنترل خسارت","تحلیل علت ریشه‌ای شکست","تغییر واقعی در طراحی/اجرا برای پیشگیری آینده","آشنایی عملی با انواع روش‌های کنترل فرسایش"],"excellent_answer_indicators":["ذکر جزئیات کمی (حجم رسوب، مساحت آسیب‌دیده، زمان واکنش)","پیوند تجربه به بهبود مستندی مانند به‌روزرسانی روش اجرایی HSE/محیط‌زیست","نشان‌دادن یادگیری فراپروژه‌ای (اعمال درس در پروژه بعدی)"],"common_mistakes":["پاسخ کلی درباره اهمیت کنترل فرسایش بدون مثال واقعی","عدم بیان اقدام اصلاحی مشخص","ندانستن تفاوت علت طراحی و علت اجرایی شکست"],"standard_reference":""},{"category":"EXPERIENCE_BASED","sub_category":"Crossing Works","difficulty":"L4","question_text":"یک تجربه واقعی از هماهنگی اجرای یک عبور (crossing) خط لوله از یک جاده، راه‌آهن یا رودخانه را شرح دهید که در آن با چند ذی‌نفع (مالک زیرساخت، مجوزدهنده، پیمانکار، جامعه محلی) هم‌زمان سروکار داشتید. بزرگ‌ترین چالش هماهنگی چه بود و چگونه آن را مدیریت کردید؟","reference_answer":"این سوال تجربه‌محور است؛ ارزیابی باید بر اساس پیچیدگی واقعی موقعیت توصیف‌شده و نقش واقعی کاندیدا باشد. پاسخ قوی مشخص می‌کند که چه نوع crossing بوده، چه مجوزها و ذی‌نفعانی درگیر بودند، و چه محدودیت‌های عملیاتی خاصی (مانند پنجره زمانی محدود برای بستن جاده، یا فصل کم‌آبی رودخانه) وجود داشت. باید توضیح دهد چگونه برنامه‌ریزی و هماهنگی بین‌رشته‌ای (Civil با مکانیکال/HDD در صورت وجود، ایمنی ترافیک، ارتباطات محلی) را مدیریت و ریسک‌های تاخیر یا ایمنی را کاهش داده است. نتیجه نهایی (تکمیل به‌موقع، رعایت ایمنی، رضایت ذی‌نفعان) و درس آموخته باید به وضوح بیان شود؛ فقدان جزئیات واقعی یا نقش مبهم کاندیدا نشانه تجربه محدود است.","key_points":["مشخص بودن نوع crossing و ذی‌نفعان واقعی درگیر","شناخت محدودیت‌های عملیاتی خاص (پنجره زمانی، مجوز)","نقش واقعی کاندیدا در هماهنگی بین‌رشته‌ای و ذی‌نفعان","مدیریت ریسک تاخیر/ایمنی در طول اجرای عبور","نتیجه نهایی و درس آموخته‌شده"],"excellent_answer_indicators":["توصیف هماهنگی چندذی‌نفعی پیچیده با جزئیات واقعی (زمان‌بندی، مجوزها)","نشان‌دادن ابتکار شخصی در حل تعارض بین ذی‌نفعان","کمی‌سازی نتیجه (مثلاً تکمیل زودتر از پنجره مجاز، بدون حادثه ایمنی)"],"common_mistakes":["پاسخ کلی درباره اهمیت هماهنگی بدون مثال مشخص","نداشتن اطلاع از فرآیند مجوزدهی واقعی برای crossing","نقش کاندیدا نامشخص یا صرفاً ناظر بدون مشارکت واقعی در تصمیم‌گیری"],"standard_reference":""},{"category":"EXPERIENCE_BASED","sub_category":"Access Road","difficulty":"L2","question_text":"یک تجربه واقعی را شرح دهید که در آن اجرای یک جاده دسترسی موقت یا دائمی در فصل بارندگی/فصل نامساعد با چالش جدی مواجه شد (مثلاً گل‌آلود شدن مسیر، توقف تردد تجهیزات). چه تصمیمی برای ادامه کار گرفتید و نتیجه چه بود؟","reference_answer":"این سوال تجربه‌محور است؛ ارزیابی بر اساس واقعی بودن مثال و کیفیت تصمیم‌گیری میدانی کاندیدا انجام می‌شود. پاسخ قوی باید مشخص کند که مشکل دقیقاً چه بود (مثلاً از بین رفتن باربری بستر جاده در اثر اشباع شدن، گیر کردن تجهیزات سنگین)، و چه گزینه‌های فنی (مانند استفاده از ژئوتکستایل/مصالح سنگی درشت، مسیر جایگزین موقت، توقف موقت ترافیک سنگین تا بهبود شرایط جوی) بررسی و انتخاب شده است. باید توضیح دهد چگونه تصمیم بین ادامه کار با ریسک آسیب بیشتر یا توقف موقت با هزینه تاخیر را گرفته و این تصمیم را با چه کسانی هماهنگ کرده است. نتیجه نهایی و درس آموخته برای برنامه‌ریزی جاده‌های آینده باید بیان شود.","key_points":["توصیف واقعی مشکل جاده دسترسی در فصل نامساعد","گزینه‌های فنی بررسی‌شده (ژئوتکستایل، مصالح درشت، مسیر جایگزین)","منطق تصمیم بین ادامه کار در برابر توقف موقت","هماهنگی تصمیم با ذی‌نفعان پروژه","نتیجه نهایی و درس آموخته برای برنامه‌ریزی آینده"],"excellent_answer_indicators":["تحلیل هزینه-فایده واقعی بین ریسک آسیب مسیر و هزینه تاخیر","ذکر جزئیات کمی (روز تاخیر، حجم مصالح اضافی مصرفی)","پیشنهاد بهبود برنامه‌ریزی فصلی جاده‌های دسترسی برای پروژه‌های بعدی به عنوان درس آموخته"],"common_mistakes":["پاسخ کلی درباره اهمیت زهکشی جاده بدون مثال واقعی","عدم بیان معیار مشخص برای تصمیم ادامه/توقف کار","نداشتن نتیجه یا درس آموخته مشخص از تجربه"],"standard_reference":""}]'::jsonb) as x(
  category text, sub_category text, difficulty text, question_text text, reference_answer text,
  key_points jsonb, excellent_answer_indicators jsonb, common_mistakes jsonb, standard_reference text
)
where not exists (select 1 from comp_question_bank where job_role = 'civil_engineer');

-- ---- project_control_specialist (23 questions) ----
insert into comp_question_bank (job_role, category, sub_category, difficulty, question_text, reference_answer, key_points, excellent_answer_indicators, common_mistakes, standard_reference)
select 'project_control_specialist', x.category, x.sub_category, x.difficulty, x.question_text, x.reference_answer,
       coalesce(x.key_points, '[]'::jsonb), coalesce(x.excellent_answer_indicators, '[]'::jsonb), coalesce(x.common_mistakes, '[]'::jsonb), coalesce(x.standard_reference, '')
from jsonb_to_recordset('[{"category":"GENERAL","sub_category":"نقش کارشناس کنترل پروژه","difficulty":"L1","question_text":"نقش کارشناس کنترل پروژه را در چرخه عمر یک پروژه EPC (از مرحله مهندسی پایه تا تحویل نهایی) و نحوه تعامل او با مدیر پروژه، مشاور و کارفرما را توضیح دهید.","reference_answer":"کارشناس کنترل پروژه در تمام فازهای پروژه از تدوین برنامه پایه (WBS و بیس‌لاین) تا پایش، گزارش‌دهی و پیش‌بینی روند نقش دارد و در واقع منبع اطلاعات عینی برای تصمیم‌گیری مدیریت است. او داده‌های پیشرفت را از واحدهای اجرایی جمع‌آوری و صحت‌سنجی می‌کند، شاخص‌های عملکردی مانند SPI و CPI را محاسبه می‌کند و روند آینده پروژه را پیش‌بینی می‌نماید. با مدیر پروژه در تحلیل انحرافات و تصمیم‌گیری اصلاحی، و با مشاور و کارفرما در تأیید پیشرفت و صورت‌وضعیت‌ها همکاری می‌کند. این نقش باید مستقل و بی‌طرف باشد تا هشدارهای زودهنگام پروژه معتبر باقی بماند.","key_points":["تعریف WBS/برنامه پایه و به‌روزرسانی مستمر آن","جمع‌آوری و صحت‌سنجی داده‌های پیشرفت از واحدهای اجرایی","تهیه گزارش‌های دوره‌ای (هفتگی/ماهانه) برای مدیر پروژه و کارفرما","پیش‌بینی روند پروژه (Forecast) و هشدار زودهنگام انحرافات","تعامل با کارفرما/مشاور برای تأیید پیشرفت و صورت‌وضعیت","ارتباط با تیم‌های مهندسی، تدارکات و اجرا برای هماهنگی برنامه"],"excellent_answer_indicators":["اشاره به نقش کنترل پروژه به عنوان چشم و گوش عینی و مستقل مدیریت پروژه","تبیین تفاوت نقش در فازهای مختلف پروژه (مهندسی/تدارکات/ساخت)","تأکید بر زنجیره تصمیم‌گیری مبتنی بر داده به جای گزارش صرفاً اداری"],"common_mistakes":["محدود کردن نقش کنترل پروژه فقط به تهیه نمودار گانت","نادیده گرفتن نقش تعامل با کارفرما/مشاور در فرآیند تأیید پیشرفت"],"standard_reference":""},{"category":"GENERAL","sub_category":"گزارش‌دهی و مدیریت مستندات","difficulty":"L1","question_text":"چه نوع گزارش‌هایی (روزانه، هفتگی، ماهانه) باید توسط کارشناس کنترل پروژه تهیه شود و محتوای هرکدام چه تفاوتی با یکدیگر دارد؟ نحوه مستندسازی و بایگانی این گزارش‌ها برای ممیزی‌های آینده پروژه را نیز شرح دهید.","reference_answer":"گزارش روزانه معمولاً شامل نیروی انسانی، ماشین‌آلات، پیشرفت جزئی فعالیت‌ها و موانع اجرایی روز است. گزارش هفتگی بر مقایسه پیشرفت واقعی با برنامه و به‌روزرسانی برنامه Look-ahead دو تا شش هفته تمرکز دارد. گزارش ماهانه جامع‌تر است و شامل تحلیل EVM (SPI/CPI)، منحنی S، جریان نقدی، به‌روزرسانی ریسک و وضعیت تغییرات می‌شود. تمام این گزارش‌ها باید در سیستم کنترل اسناد با شماره‌گذاری، تاریخ و کنترل نسخه بایگانی شوند تا در صورت نیاز به دفاع از ادعاهای تأخیر یا ممیزی، قابل ردیابی و استناد باشند.","key_points":["گزارش روزانه: نیروی انسانی، ماشین‌آلات، پیشرفت جزئی و موانع اجرایی","گزارش هفتگی: به‌روزرسانی Look-ahead ۲ تا ۶ هفته و مقایسه با برنامه","گزارش ماهانه: تحلیل EVM (SPI/CPI)، منحنی S، جریان نقدی، ریسک و تغییرات","سیستم شماره‌گذاری و کنترل نسخه اسناد (Document Control)","بایگانی قابل ردیابی برای پشتیبانی از ادعاهای تأخیر (Claim) در آینده","توزیع گزارش بر اساس ماتریس ارتباطات پروژه (Communication Matrix)"],"excellent_answer_indicators":["اشاره به الزام ردپای مستندات (Audit Trail) برای دفاع در دعاوی قراردادی","پیوند گزارش‌دهی با تصمیم‌های مدیریتی نه صرفاً بایگانی اداری","استفاده از داشبورد یا سیستم نرم‌افزاری یکپارچه برای کاهش خطای انسانی"],"common_mistakes":["یکسان دانستن محتوای گزارش روزانه و هفتگی","نداشتن سیستم کنترل نسخه و امکان بازگشت به گزارش‌های قبلی"],"standard_reference":""},{"category":"GENERAL","sub_category":"کنترل کیفیت داده پیشرفت","difficulty":"L2","question_text":"فرض کنید متوجه می‌شوید که درصد پیشرفت گزارش‌شده توسط یکی از سرپرستان کارگاهی برای چند فعالیت، بدون پشتوانه مستند (مانند تأییدیه QC یا صورت‌وضعیت متره) ثبت شده است. به عنوان کارشناس کنترل پروژه چه اقدامی انجام می‌دهید؟","reference_answer":"ابتدا عدد گزارش‌شده را با مستندات فنی موجود مانند گزارش‌های QC، متره واقعی یا بازدید میدانی راستی‌آزمایی می‌کنم. سپس با سرپرست مربوطه گفتگو می‌کنم تا دلیل ثبت نادرست (اشتباه یا فشار زمانی) مشخص شود و در صورت نیاز عدد را در سیستم قبل از انتشار گزارش رسمی اصلاح می‌کنم. اگر این موضوع الگویی تکرارشونده باشد، آن را به مدیر پروژه اطلاع می‌دهم و پیشنهاد ایجاد یک رویه رسمی تأیید پیشرفت (Progress Verification Sign-off) بین کنترل پروژه، QC و اجرا را می‌دهم تا از تکرار آن جلوگیری شود.","key_points":["راستی‌آزمایی پیشرفت با مستندات فنی (QC، متره، نقشه as-built)","گفتگو با سرپرست برای شناسایی دلیل ثبت نادرست (اشتباه یا فشار)","اصلاح عدد در سیستم قبل از انتشار گزارش رسمی","اطلاع‌رسانی به مدیر پروژه در صورت الگوی تکرارشونده","پیشنهاد ایجاد رویه تأیید پیشرفت (Progress Verification Sign-off)","حفظ بی‌طرفی و عدم پذیرش داده بدون پشتوانه، حتی تحت فشار زمانی"],"excellent_answer_indicators":["طراحی یک چک‌لیست یا فرم تأیید پیشرفت مشترک بین کنترل پروژه، QC و اجرا","تفکر سیستمی: بررسی اینکه آیا مشکل فقط یک فعالیت است یا الگوی گسترده‌تر","مستندسازی موضوع برای جلوگیری از تکرار در آینده"],"common_mistakes":["پذیرش عدد پیشرفت بدون بررسی صرفاً برای تسریع در گزارش‌دهی","برخورد قهرآمیز یا گزارش فوری به سطح بالا بدون بررسی اولیه"],"standard_reference":""},{"category":"GENERAL","sub_category":"اخلاق حرفه‌ای در گزارش‌دهی","difficulty":"L3","question_text":"در پایان یک ماه، مدیر پروژه از شما می‌خواهد که در گزارش ماهانه، SPI را کمی بهتر از عدد واقعی نشان دهید تا در جلسه با کارفرما وضعیت پروژه سبز دیده شود. چه واکنشی نشان می‌دهید و چرا؟","reference_answer":"از دستکاری عدد SPI امتناع می‌کنم زیرا این کار ارزش هشداردهی زودهنگام داده‌های کنترل پروژه را از بین می‌برد و می‌تواند منجر به تصمیمات نادرست مدیریتی و کارفرما شود. به‌جای آن، عدد واقعی را همراه با تحلیل ریشه‌ای علت عقب‌ماندگی و یک برنامه بازیابی مشخص ارائه می‌دهم تا مدیر پروژه بتواند وضعیت را با راهکار به کارفرما ارائه دهد نه صرفاً پنهان کند. همچنین ریسک از دست رفتن اعتبار حرفه‌ای، بروز مشکلات قراردادی در صورت افشای بعدی داده نادرست، و لزوم مستندسازی این تعامل را در نظر می‌گیرم و در صورت تکرار فشار، موضوع را به سطح بالاتر اطلاع می‌دهم.","key_points":["امتناع از دستکاری عدد SPI و توضیح ریسک تصمیم‌گیری نادرست","تفکیک بین گزارش نامطلوب و گزارش نادرست برای مدیر پروژه","ارائه راهکار جایگزین: نمایش عدد واقعی همراه با برنامه بازیابی (Recovery Plan)","توضیح ریسک از دست رفتن اعتبار حرفه‌ای و اعتماد کارفرما در بلندمدت","احتمال بروز مشکل حقوقی/قراردادی در صورت افشای بعدی داده نادرست","مستندسازی درخواست و پاسخ خود در صورت تکرار فشار"],"excellent_answer_indicators":["پیشنهاد چارچوب گزارش‌دهی سطح‌بندی‌شده (رنگی) با معیار عینی به‌جای قضاوت شخصی","تسلط بر این‌که اعتبار داده کنترل پروژه پایه تصمیمات کلان قرارداد و پرداخت است","آمادگی برای بالا بردن موضوع به سطح بالاتر در صورت اصرار مدیر پروژه"],"common_mistakes":["پذیرش بی‌چون‌وچرای درخواست مدیر پروژه به بهانه دستور مافوق","واکنش تقابلی/غیرحرفه‌ای به‌جای ارائه راه‌حل جایگزین سازنده"],"standard_reference":""},{"category":"GENERAL","sub_category":"مدیریت تغییرات و اثر بر مسیر بحرانی","difficulty":"L2","question_text":"یک تغییر کارفرما (Change Order) در حین اجرا باعث توقف چند فعالیت مسیر بحرانی شده، اما تا زمان تصویب رسمی تغییر، تیم اجرا برای عقب نماندن از برنامه، فعالیت‌های دیگر را جلو انداخته و توالی اصلی برنامه را به هم زده است. به عنوان کارشناس کنترل پروژه چگونه این وضعیت را مدیریت و گزارش می‌کنید؟","reference_answer":"ابتدا اثر تغییر را بر فلوت و توالی فعالیت‌های مسیر بحرانی به‌طور جداگانه ثبت و کمی می‌کنم تا در صورت لزوم پشتوانه درخواست تمدید زمان (EOT) باشد. بیس‌لاین رسمی را تا تأیید نهایی تغییر دستکاری نمی‌کنم، اما برنامه Look-ahead را متناسب با توالی واقعی اجرا به‌روزرسانی می‌کنم. این انحراف از توالی برنامه را به‌صورت شفاف به مدیر پروژه و در صورت نیاز کارفرما گزارش می‌دهم و ردیابی بین وضعیت تأیید تغییر و اجرای واقعی سایت را حفظ می‌کنم تا در آینده قابل دفاع باشد.","key_points":["ثبت اثر تغییر بر مسیر بحرانی و فلوت فعالیت‌های مرتبط","عدم تغییر بیس‌لاین تا تصویب رسمی تغییر (کنترل تغییرات)","به‌روزرسانی برنامه Look-ahead متناسب با توالی واقعی اجرا","کمی‌سازی اثر تأخیر برای پشتیبانی از درخواست تمدید زمان (EOT)","اطلاع‌رسانی شفاف به مدیر پروژه و کارفرما درباره انحراف از توالی برنامه","حفظ ردیابی بین وضعیت تأیید تغییر و اجرای واقعی در سایت"],"excellent_answer_indicators":["استفاده از تحلیل Time Impact Analysis برای اثبات کمی تأخیر ناشی از تغییر","هماهنگی پیش‌دستانه با بخش قراردادها برای ثبت رسمی ادعا","پیشنهاد راهکار بازچینی توالی برای کاهش اثر تغییر بر مسیر بحرانی"],"common_mistakes":["ادغام اثر تغییر با تأخیرات دیگر بدون تفکیک علت","تغییر بی‌ضابطه بیس‌لاین بدون تأیید رسمی درخواست تغییر"],"standard_reference":""},{"category":"TECHNICAL","sub_category":"WBS/CBS/OBS","difficulty":"L1","question_text":"تفاوت WBS، CBS و OBS را توضیح دهید و بگویید چگونه این سه ساختار برای امکان‌پذیر کردن گزارش‌دهی یکپارچه هزینه و برنامه در یک پروژه EPC باید به هم مرتبط (Coded) شوند.","reference_answer":"WBS تجزیه محدوده پروژه به بسته‌های کاری قابل مدیریت است، CBS تفکیک هزینه‌ها منطبق بر بودجه و حساب‌های هزینه است و OBS مسئولیت سازمانی هر بسته کاری را مشخص می‌کند. برای گزارش‌دهی یکپارچه، این سه ساختار باید از طریق یک سیستم کدگذاری مشترک به هم متصل شوند به‌طوری‌که تقاطع WBS و OBS، حساب‌های کنترل (Control Account) را تشکیل دهد. این یکپارچگی پیش‌نیاز اجرای صحیح EVM است زیرا امکان می‌دهد پیشرفت فیزیکی، هزینه و مسئولیت هر بخش به‌طور هم‌زمان و قابل رول‌آپ پایش شود.","key_points":["WBS: تجزیه محدوده پروژه به بسته‌های کاری قابل مدیریت","CBS: تفکیک هزینه‌ها منطبق بر بودجه و حساب‌های هزینه","OBS: تعریف مسئولیت سازمانی/مالکیت هر بسته کاری","کدگذاری مشترک (Coding Structure) برای اتصال سه ساختار","ایجاد حساب‌های کنترل (Control Account) در تقاطع WBS و OBS","پیش‌نیاز بودن این یکپارچگی برای اجرای صحیح EVM و گزارش‌دهی رول‌آپ"],"excellent_answer_indicators":["اشاره به مفهوم Control Account Plan (CAP) به عنوان محل تلاقی WBS/CBS/OBS","تبیین اینکه عدم هم‌ترازی این سه ساختار باعث ناسازگاری گزارش هزینه و پیشرفت می‌شود","نمونه عملی از تجربه کدگذاری در یک پروژه واقعی"],"common_mistakes":["یکسان دانستن WBS و CBS","نادیده گرفتن نقش OBS در پاسخگویی مدیریتی"],"standard_reference":"PMI Practice Standard for Work Breakdown Structures"},{"category":"TECHNICAL","sub_category":"Baseline (Schedule/Cost)","difficulty":"L2","question_text":"بیس‌لاین برنامه و هزینه (Schedule & Cost Baseline) چیست، چه زمانی باید منجمد (Freeze) شود و در طول اجرای پروژه تحت چه شرایطی مجاز به تجدیدنظر (Re-baseline) است؟","reference_answer":"بیس‌لاین مرجع تأییدشده برنامه و هزینه است که پیشرفت و عملکرد پروژه نسبت به آن سنجیده می‌شود و اساس محاسبه PV در EVM قرار می‌گیرد. این بیس‌لاین معمولاً پس از تأیید ذی‌نفعان کلیدی و در ابتدای فاز اجرا منجمد می‌شود. تجدیدنظر در آن تنها از طریق فرآیند کنترل تغییر رسمی و در شرایطی مانند تغییر محدوده مصوب، دستور کارفرما یا تمدید زمان مصوب مجاز است و هرگز نباید برای پنهان کردن عملکرد ضعیف انجام شود. نسخه بیس‌لاین اصلی باید برای تحلیل روند و پشتیبانی احتمالی ادعاها حفظ شود.","key_points":["تعریف بیس‌لاین به عنوان مرجع سنجش عملکرد (PV) پروژه","انجماد بیس‌لاین پس از تأیید ذی‌نفعان کلیدی و ابتدای فاز اجرا","شرایط مجاز بازنگری: تغییر مصوب محدوده، دستور کارفرما، تمدید زمان مصوب","فرآیند کنترل تغییر رسمی برای هرگونه Re-baseline","حفظ نسخه بیس‌لاین اصلی برای تحلیل روند و پشتیبانی ادعاها","تفکیک انحراف واقعی عملکرد از تغییر مجاز بیس‌لاین"],"excellent_answer_indicators":["اشاره به نگهداری همزمان چند نسخه بیس‌لاین (اصلی/جاری/هدف)","تأکید بر اینکه Re-baseline بدون توجیه مستند، اعتبار داده EVM را از بین می‌برد","تجربه عملی از فرآیند تصویب Re-baseline در یک پروژه"],"common_mistakes":["اجازه دادن به تغییر مکرر بیس‌لاین برای پنهان کردن عقب‌ماندگی","عدم تفکیک بین بیس‌لاین اصلی و بیس‌لاین به‌روزشده در گزارش‌ها"],"standard_reference":""},{"category":"TECHNICAL","sub_category":"Schedule Development (Level 3/4)","difficulty":"L2","question_text":"تفاوت برنامه زمان‌بندی سطح ۳ (Level 3) و سطح ۴ (Level 4) در یک پروژه احداث خط لوله گاز چیست و هرکدام معمولاً برای چه مخاطب و چه هدفی تهیه می‌شوند؟","reference_answer":"برنامه سطح ۳ یک برنامه مدیریتی و کنترلی در سطح فعالیت‌های حساب کنترل است که برای مدیریت کلان پروژه، گزارش‌دهی به کارفرما، پایش نقاط عطف و اجرای EVM استفاده می‌شود. برنامه سطح ۴ یک برنامه اجرایی بسیار تفصیلی در سطح بسته کاری است که مخاطب اصلی آن سرپرستان کارگاهی و مسئولان رشته‌هاست و برای برنامه‌ریزی اجرایی روزانه و هفتگی و تهیه برنامه‌های Look-ahead به کار می‌رود. پیشرفت فعالیت‌های سطح ۴ باید به‌درستی به فعالیت‌های سطح ۳ رول‌آپ شود تا هم‌راستایی بین برنامه اجرایی و برنامه کنترلی حفظ گردد.","key_points":["سطح ۳: برنامه کنترل پروژه/مدیریتی با تفکیک تا سطح فعالیت‌های کنترلی","سطح ۴: برنامه اجرایی تفصیلی در سطح بسته کاری برای سرپرستان و نظارت روزانه","مخاطب سطح ۳: مدیریت پروژه و کارفرما؛ مخاطب سطح ۴: تیم اجرایی سایت","کاربرد سطح ۳ در EVM و گزارش‌دهی کلان پیشرفت","کاربرد سطح ۴ در برنامه‌ریزی Look-ahead و تخصیص منابع روزانه","الزام هم‌راستایی و رول‌آپ صحیح پیشرفت سطح ۴ به سطح ۳"],"excellent_answer_indicators":["اشاره به سطح ۱ (خلاصه اجرایی) و سطح ۵ (روزانه) برای تکمیل سلسله‌مراتب برنامه‌ریزی","تبیین ریسک ناهم‌راستایی بین برنامه اجرایی و برنامه کنترلی","نمونه واقعی از پروژه خط لوله با اشاره به تعداد فعالیت‌های هر سطح"],"common_mistakes":["معرفی سطح ۴ به عنوان صرفاً نسخه دقیق‌تر بدون تفاوت کاربردی","نادیده گرفتن الزام رول‌آپ و هم‌راستایی بین سطوح"],"standard_reference":""},{"category":"TECHNICAL","sub_category":"Critical Path و Float","difficulty":"L2","question_text":"مسیر بحرانی (Critical Path) و تفاوت فلوت کل (Total Float) با فلوت آزاد (Free Float) را با یک مثال از یک پروژه احداث تشریح کنید. چرا نظارت بر روند تغییرات فلوت کل مسیر بحرانی برای کارشناس کنترل پروژه اهمیت دارد؟","reference_answer":"مسیر بحرانی بلندترین زنجیره فعالیت‌های وابسته است که مدت زمان پروژه را تعیین می‌کند و فعالیت‌های آن معمولاً فلوت صفر یا حداقل دارند. فلوت کل مقدار تأخیر مجاز یک فعالیت بدون تأثیر بر تاریخ پایان پروژه است، در حالی که فلوت آزاد مقدار تأخیر مجاز بدون تأثیر بر شروع زودترین فعالیت جانشین است. پایش روند کاهش فلوت کل اهمیت دارد زیرا حتی قبل از اینکه یک فعالیت رسماً بحرانی شود یا در درصد پیشرفت کلی انحرافی دیده شود، کاهش فلوت هشدار زودهنگامی از فرسایش حاشیه امن برنامه و احتمال تأخیر آتی می‌دهد.","key_points":["تعریف مسیر بحرانی: بلندترین زنجیره فعالیت‌های وابسته با فلوت صفر/حداقل","فلوت کل: مقدار تأخیر مجاز فعالیت بدون تأثیر بر تاریخ پایان پروژه","فلوت آزاد: مقدار تأخیر مجاز بدون تأثیر بر شروع زودترین فعالیت جانشین","مثال عددی ساده برای نشان دادن تفاوت این دو فلوت","اهمیت پایش روند کاهش فلوت به عنوان هشدار زودهنگام","مفهوم مسیرهای نزدیک به بحرانی (Near-critical Path)"],"excellent_answer_indicators":["اشاره به آستانه فلوت (Float Threshold) برای تعریف فعالیت‌های نزدیک به بحرانی در رویه پروژه","تبیین اثر فلوت منفی پس از تحمیل محدودیت تاریخ قرارداد","تجربه عملی ردیابی روند فلوت در نرم‌افزار برنامه‌ریزی طی چند دوره گزارش"],"common_mistakes":["برابر دانستن فلوت کل و فلوت آزاد","توجه فقط به مسیر بحرانی فعلی بدون پایش مسیرهای نزدیک به بحرانی"],"standard_reference":""},{"category":"TECHNICAL","sub_category":"Progress Measurement / Weighting","difficulty":"L3","question_text":"روش‌های اندازه‌گیری پیشرفت فیزیکی (مانند Units Completed، Milestone Weight، 0/100 و 50/50) را نام ببرید و توضیح دهید برای فعالیت مهندسی تفصیلی و برای فعالیت نصب تجهیزات مکانیکال کدام روش را با چه توجیهی انتخاب می‌کنید. وزن‌دهی فعالیت‌ها (Weighting) بر چه مبنایی باید انجام شود؟","reference_answer":"روش‌های رایج عبارت‌اند از Units Completed، Milestone Weight، 0/100، 50/50 و Level of Effort. برای فعالیت مهندسی تفصیلی معمولاً روش نقاط عطف وزن‌دار (Milestone Weight) بر اساس مراحل تأیید مدرک مانند صدور برای بازبینی و صدور برای ساخت مناسب‌تر است. برای نصب تجهیزات مکانیکال، اندازه‌گیری بر مبنای واحد فیزیکی تکمیل‌شده مانند تعداد اتصال یا متر لوله نصب‌شده دقت بیشتری دارد. وزن‌دهی فعالیت‌ها باید بر اساس بودجه هزینه یا نفر-ساعت هر فعالیت انجام شود نه صرفاً مدت‌زمان، تا میزان تأثیر واقعی هر فعالیت بر ارزش کل پروژه به‌درستی منعکس شود.","key_points":["معرفی روش‌های رایج: Units Completed، Milestone Weight، 0/100، 50/50، Level of Effort","انتخاب روش مناسب برای مهندسی: نقاط عطف وزن‌دار بر اساس مراحل تأیید مدرک","انتخاب روش مناسب برای نصب مکانیکال: واحد فیزیکی تکمیل‌شده (Units Completed)","مبنای وزن‌دهی فعالیت‌ها: بودجه هزینه یا نفر-ساعت هر فعالیت/رشته","اجتناب از وزن‌دهی صرفاً بر مبنای مدت‌زمان فعالیت","لزوم ثبات روش انتخابی در طول پروژه برای قابل مقایسه بودن روند"],"excellent_answer_indicators":["اشاره به Rule of Credit به عنوان چارچوب رسمی وزن‌دهی زیرفعالیت‌ها","تبیین ریسک استفاده از 50/50 برای فعالیت‌های طولانی و پیشنهاد جایگزین دقیق‌تر","مثال عددی از محاسبه پیشرفت وزنی چند فعالیت با وزن متفاوت"],"common_mistakes":["استفاده از یک روش واحد مانند 50/50 برای همه انواع فعالیت بدون توجه به ماهیت آن‌ها","وزن‌دهی فعالیت‌ها صرفاً بر اساس تعداد یا مدت‌زمان به‌جای هزینه/نفر-ساعت"],"standard_reference":""},{"category":"TECHNICAL","sub_category":"EVM (PV/EV/AC)","difficulty":"L2","question_text":"تعاریف PV، EV و AC را با یک مثال عددی ساده بیان کنید: فعالیتی با بودجه ۲۰۰ میلیون تومان قرار بوده طبق برنامه تا امروز ۶۰ درصد پیش برود، اما پیشرفت واقعی ۴۵ درصد بوده و ۱۱۰ میلیون تومان هزینه صرف شده است. PV، EV و AC این فعالیت را محاسبه کنید.","reference_answer":"PV یا ارزش برنامه‌ریزی‌شده برابر است با بودجه کل فعالیت ضرب در درصد پیشرفت برنامه‌ریزی‌شده، یعنی ۲۰۰ در ۰.۶۰ که می‌شود ۱۲۰ میلیون تومان. EV یا ارزش کسب‌شده برابر است با بودجه کل ضرب در درصد پیشرفت واقعی، یعنی ۲۰۰ در ۰.۴۵ که می‌شود ۹۰ میلیون تومان. AC یا هزینه واقعی همان ۱۱۰ میلیون تومان است که در سؤال داده شده است. از مقایسه این سه عدد نتیجه می‌گیریم که چون EV کمتر از PV است فعالیت از برنامه عقب است و چون AC بیشتر از EV است هزینه بیشتری نسبت به ارزش واقعاً کسب‌شده صرف شده است.","key_points":["PV = بودجه کل فعالیت × درصد پیشرفت برنامه‌ریزی‌شده = ۱۲۰ میلیون تومان","EV = بودجه کل فعالیت × درصد پیشرفت واقعی = ۹۰ میلیون تومان","AC = هزینه واقعی گزارش‌شده = ۱۱۰ میلیون تومان (داده شده در سؤال)","نتیجه‌گیری: EV کمتر از PV یعنی عقب‌افتادگی از برنامه","نتیجه‌گیری: AC بیشتر از EV یعنی هزینه بیشتر از ارزش کسب‌شده صرف شده","تمایز روشن این سه مفهوم پایه از یکدیگر"],"excellent_answer_indicators":["محاسبه سریع و دقیق SPI=0.75 و CPI≈0.82 به عنوان تحلیل تکمیلی","تفسیر هم‌زمان علت احتمالی مانند بهره‌وری پایین یا برآورد نادرست هزینه","اشاره به اهمیت به‌روزرسانی منظم AC از سیستم مالی/حسابداری پروژه"],"common_mistakes":["جابجایی تعریف EV و AC با یکدیگر","محاسبه PV بر اساس درصد پیشرفت واقعی به‌جای درصد برنامه‌ریزی‌شده"],"standard_reference":"PMI Practice Standard for Earned Value Management"},{"category":"TECHNICAL","sub_category":"Forecasting (ETC/EAC)","difficulty":"L3","question_text":"روش‌های مختلف محاسبه EAC (Estimate at Completion) را نام ببرید و توضیح دهید در چه شرایطی از فرمول EAC = AC + (BAC − EV) و در چه شرایطی از فرمول EAC = BAC / CPI استفاده می‌کنید. کدام فرض در پس هرکدام نهفته است؟","reference_answer":"فرمول EAC = AC + (BAC − EV) زمانی استفاده می‌شود که انحراف هزینه ناشی از یک اتفاق موردی و غیرتکرارشونده باشد و فرض بر این است که کار باقیمانده طبق نرخ برنامه‌ریزی‌شده اصلی انجام خواهد شد. فرمول EAC = BAC / CPI زمانی مناسب است که انحراف هزینه سیستماتیک باشد و فرض بر ادامه روند فعلی عملکرد هزینه (CPI) تا پایان پروژه است. یک فرمول ترکیبی نیز وجود دارد که هم CPI و هم SPI را لحاظ می‌کند و برای شرایطی مناسب است که فشار زمانی نیز بر هزینه کار باقیمانده اثر می‌گذارد. انتخاب فرمول باید بر اساس تحلیل ریشه‌ای علت انحراف صورت گیرد نه به‌صورت پیش‌فرض ثابت.","key_points":["فرمول اول: EAC=AC+(BAC−EV) برای واریانس موردی/غیرتکرارشونده","فرمول دوم: EAC=BAC/CPI برای ادامه روند فعلی عملکرد هزینه","فرمول ترکیبی که SPI را نیز لحاظ می‌کند وقتی فشار زمانی بر هزینه باقیمانده اثر می‌گذارد","لزوم تحلیل ریشه‌ای علت انحراف قبل از انتخاب فرمول","کاربرد ETC = EAC − AC برای برآورد هزینه باقیمانده","اهمیت به‌روزرسانی دوره‌ای EAC و مقایسه با بودجه مصوب (BAC)"],"excellent_answer_indicators":["اشاره به امکان برآورد EAC از پایین به بالا (Bottom-up) توسط تیم فنی به‌عنوان روش تکمیلی/اعتبارسنجی","تبیین اینکه انتخاب فرمول نامناسب می‌تواند تصویر گمراه‌کننده‌ای از سلامت پروژه ارائه دهد","مثال عددی برای مقایسه نتایج متفاوت دو فرمول در یک سناریوی واحد"],"common_mistakes":["استفاده صرف از یک فرمول ثابت برای همه پروژه‌ها بدون تحلیل نوع انحراف","خلط بین EAC و ETC"],"standard_reference":"PMI Practice Standard for Earned Value Management"},{"category":"TECHNICAL","sub_category":"Delay Analysis","difficulty":"L4","question_text":"روش‌های اصلی تحلیل تأخیر (Delay Analysis) شامل As-Planned vs As-Built، Impacted As-Planned، Time Impact Analysis (TIA) و Windows Analysis را با هم مقایسه کنید. برای اثبات یک ادعای تمدید زمان (EOT) در میانه پروژه، با وجود برنامه به‌روزشده معتبر، کدام روش را ترجیح می‌دهید و چرا؟","reference_answer":"روش As-Planned vs As-Built ساده است اما تغییر مسیر بحرانی و هم‌زمانی تأخیرها را نادیده می‌گیرد. Impacted As-Planned رویداد تأخیر را در منطق برنامه اولیه تزریق می‌کند اما پیشرفت واقعی را لحاظ نمی‌کند و در صورت قدیمی بودن بیس‌لاین ضعیف عمل می‌کند. Time Impact Analysis رویداد تأخیر را در یک برنامه به‌روز و معتبر در همان زمان وقوع تزریق کرده و اثر آینده‌نگر آن را شبیه‌سازی می‌کند و به همین دلیل به‌طور گسترده پذیرفته‌شده است. Windows Analysis مسیر بحرانی را در بازه‌های زمانی متوالی با داده‌های واقعی بررسی می‌کند و در برابر تأخیرهای هم‌زمان مقاوم‌تر است. با وجود برنامه به‌روز معتبر در میانه پروژه، TIA یا Windows Analysis ترجیح داده می‌شود زیرا مبتنی بر داده‌های معاصر و پیشرفت واقعی هستند و مطابق رویکرد پذیرفته‌شده در پروتکل‌های تخصصی، اعتبار بیشتری برای دفاع از ادعا دارند.","key_points":["As-Planned vs As-Built: ساده اما نادیده‌گیرنده تغییر مسیر بحرانی و هم‌زمانی تأخیرها","Impacted As-Planned: تزریق تأخیر در برنامه اولیه، بدون لحاظ پیشرفت واقعی","TIA: تزریق رویداد تأخیر در برنامه به‌روز معتبر در زمان وقوع، مبتنی بر شبیه‌سازی آینده‌نگر","Windows Analysis: بررسی مسیر بحرانی در بازه‌های زمانی متوالی با داده‌های واقعی","ترجیح روش مبتنی بر داده معاصر (Contemporaneous) به‌جای روش صرفاً نظری","لزوم داشتن برنامه به‌روز و معتبر به‌عنوان پیش‌نیاز TIA/Windows","توجه به تأخیرات هم‌زمان (Concurrent Delay) در انتخاب روش"],"excellent_answer_indicators":["ارجاع به پروتکل SCL و رتبه‌بندی روش‌ها بر اساس کیفیت داده در دسترس","بحث درباره تأخیر هم‌زمان (Concurrency) و اثر آن بر رد یا پذیرش ادعا","تجربه عملی از انتخاب و دفاع از یک روش در مذاکره یا داوری قراردادی"],"common_mistakes":["انتخاب ساده‌ترین روش (As-Planned vs As-Built) صرفاً به دلیل سادگی بدون توجه به دقت مورد نیاز","نادیده گرفتن مفهوم تأخیر هم‌زمان در تحلیل"],"standard_reference":"SCL Delay and Disruption Protocol"},{"category":"TECHNICAL","sub_category":"Cash Flow / S-Curve / Resource Loading","difficulty":"L3","question_text":"منحنی S هزینه (Cost S-Curve) چگونه تهیه می‌شود و چه رابطه‌ای با بارگذاری منابع (Resource Loading) و پیش‌بینی جریان نقدی (Cash Flow Forecast) پروژه دارد؟ اگر منحنی S واقعی به‌طور مستمر زیر منحنی برنامه‌ریزی‌شده باشد ولی AC نیز کمتر از PV باشد، چه تفسیری دارید؟","reference_answer":"منحنی S از تجمیع ارزش وزنی هزینه یا نفر-ساعت فعالیت‌های برنامه‌ریزی‌شده در طول زمان ساخته می‌شود و این کار مستلزم داشتن یک برنامه بارگذاری‌شده با منابع است. بارگذاری منابع پایه تهیه هم منحنی S و هم پیش‌بینی جریان نقدی خروجی (هزینه‌ها) و ورودی (صورت‌وضعیت‌های تأییدشده) پروژه است. اگر منحنی واقعی زیر منحنی برنامه باشد اما AC نیز کمتر از PV باشد، تفسیر محتمل این است که پروژه صرفاً از برنامه عقب است و کار کمتری انجام شده، نه اینکه لزوماً مشکل هزینه‌ای وجود داشته باشد؛ برای تأیید این فرضیه باید CPI و SPI هم‌زمان بررسی شوند. این وضعیت هشداری برای اثر تأخیر بر زمان‌بندی آتی جریان نقدی و صورت‌وضعیت‌هاست.","key_points":["منحنی S از تجمیع ارزش وزنی (هزینه/نفرساعت) فعالیت‌های برنامه‌ریزی‌شده در طول زمان ساخته می‌شود","بارگذاری منابع (Resource Loading) پایه تهیه منحنی S و پیش‌بینی جریان نقدی است","جریان نقدی از هزینه‌های زمان‌بندی‌شده (خروجی) و صورت‌وضعیت‌های تأییدشده (ورودی) تشکیل می‌شود","تفسیر صحیح: AC کمتر از PV همراه با S-Curve پایین‌تر معمولاً یعنی تأخیر در انجام کار نه لزوماً مشکل هزینه‌ای","لزوم بررسی هم‌زمان CPI و SPI برای تأیید این فرضیه","هشدار درباره اثر تأخیر بر زمان‌بندی جریان نقدی آتی (تأخیر در صورت‌وضعیت و پرداخت)"],"excellent_answer_indicators":["تفکیک منحنی S هزینه از منحنی S پیشرفت فیزیکی و توضیح کاربرد متفاوت هرکدام","پیشنهاد اقدام اصلاحی مبتنی بر علت (تسریع اجرا) به‌جای واکنش صرفاً به عدد هزینه","مثال عملی از تهیه منحنی S در نرم‌افزار برنامه‌ریزی با بارگذاری منابع"],"common_mistakes":["تفسیر AC کمتر از PV به‌عنوان لزوماً صرفه‌جویی هزینه مثبت بدون بررسی علت","خلط بین منحنی S فیزیکی و منحنی S مالی"],"standard_reference":""},{"category":"SCENARIO","sub_category":"EVM (SPI/CPI)","difficulty":"L3","question_text":"پروژه‌ای در فاز اجرا ۷۰ درصد پیشرفت فیزیکی دارد، اما شاخص عملکرد زمانی SPI برابر ۰.۸۲ و شاخص عملکرد هزینه CPI برابر ۰.۹۱ محاسبه شده است. تحلیل شما از وضعیت پروژه چیست و چه اقداماتی پیشنهاد می‌کنید؟","reference_answer":"SPI برابر ۰.۸۲ نشان می‌دهد پروژه نسبت به آنچه طبق برنامه باید کسب می‌کرد، حدود ۱۸ درصد عقب‌تر است و CPI برابر ۰.۹۱ نشان می‌دهد به ازای هر واحد ارزش کسب‌شده، هزینه بیشتری نسبت به بودجه صرف شده است. عدد ۷۰ درصد پیشرفت مطلق به‌تنهایی گمراه‌کننده است چون نسبت به بیس‌لاین سنجیده نشده و ممکن است تأخیر عمدتاً در فعالیت‌های مسیر بحرانی متمرکز باشد. باید تحلیل ریشه‌ای انجام شود که آیا علت بهره‌وری پایین، کمبود منابع، مشکل تدارکات یا تغییرات مدیریت‌نشده است، سپس یک برنامه بازیابی (Recovery Plan) با اقدامات مشخص روی فعالیت‌های بحرانی تدوین و EAC/ETC به‌روزرسانی و به مدیریت گزارش شود.","key_points":["SPI=0.82 نشان‌دهنده عقب‌ماندگی حدود ۱۸٪ نسبت به برنامه در این مقطع","CPI=0.91 نشان‌دهنده مصرف بیشتر منابع/هزینه نسبت به ارزش کسب‌شده","۷۰٪ پیشرفت مطلق به‌تنهایی گمراه‌کننده است چون بر اساس بیس‌لاین سنجیده نشده","لزوم تفکیک اینکه تأخیر مربوط به فعالیت‌های مسیر بحرانی است یا غیربحرانی","تحلیل ریشه‌ای (بهره‌وری پایین، کمبود منابع، مشکل تدارکات، تغییرات) قبل از اقدام اصلاحی","تدوین برنامه بازیابی (Recovery Plan) و به‌روزرسانی پیش‌بینی EAC/ETC","افزایش دفعات پایش و گزارش‌دهی به مدیریت با اعداد کمی‌شده"],"excellent_answer_indicators":["پیشنهاد اقدام مشخص مانند بازچینی توالی یا تسریع هدفمند روی فعالیت‌های بحرانی به‌جای افزایش کلی نیرو","اشاره به بررسی هم‌زمان روند چند دوره اخیر SPI/CPI نه فقط عدد لحظه‌ای","محاسبه سریع EAC تخمینی برای کمی‌سازی ریسک مالی پروژه"],"common_mistakes":["توصیه صرف افزایش نیروی انسانی بدون تحلیل ریشه‌ای علت تأخیر/هزینه","اشتباه گرفتن تفسیر SPI و CPI با یکدیگر یا نادیده گرفتن یکی از آن‌ها"],"standard_reference":""},{"category":"SCENARIO","sub_category":"EVM (SPI/CPI)","difficulty":"L3","question_text":"در گزارش ماهانه پروژه، AC (هزینه واقعی) برابر ۵۰۰ میلیون تومان، EV (ارزش کسب‌شده) برابر ۵۵۰ میلیون تومان و PV (ارزش برنامه‌ریزی‌شده طبق بیس‌لاین) برابر ۶۵۰ میلیون تومان گزارش شده است. CPI و SPI را محاسبه و وضعیت پروژه را تحلیل کنید.","reference_answer":"CPI برابر است با EV تقسیم بر AC یعنی ۵۵۰ تقسیم بر ۵۰۰ که می‌شود ۱.۱۰ و نشان‌دهنده عملکرد هزینه‌ای مطلوب و کارآمد است. SPI برابر است با EV تقسیم بر PV یعنی ۵۵۰ تقسیم بر ۶۵۰ که تقریباً ۰.۸۵ می‌شود و نشان‌دهنده عقب‌ماندگی محسوس از برنامه زمانی است. این ترکیب نشان می‌دهد پروژه از نظر هزینه کارآمد است اما از نظر زمانی عقب است که می‌تواند ناشی از کمبود منابع تخصیص‌یافته، تأخیر در تأییدیه‌ها یا گلوگاه در تدارکات باشد نه لزوماً بهره‌وری پایین. باید بررسی شود آیا فعالیت‌های ارزان و ساده جلوتر رفته‌اند در حالی که فعالیت‌های بحرانی عقب مانده‌اند، و از حاشیه هزینه موجود برای تسریع هدفمند مسیر بحرانی استفاده شود.","key_points":["محاسبه صحیح: CPI=550/500=1.10 و SPI=550/650≈0.85","تفسیر: عملکرد هزینه‌ای خوب اما عقب‌ماندگی محسوس زمانی","علل احتمالی: کمبود منابع تخصیص‌یافته، تأخیر تدارکات/تأییدیه‌ها، گلوگاه رابط بین رشته‌ها","لزوم بررسی اینکه آیا فعالیت‌های ارزان و ساده جلوتر رفته‌اند و فعالیت‌های بحرانی/گران عقب مانده‌اند","استفاده از فضای مالی موجود (CPI مطلوب) برای سرمایه‌گذاری هدفمند در تسریع مسیر بحرانی","بررسی روند چند دوره‌ای برای تأیید الگو به‌جای اکتفا به عدد لحظه‌ای"],"excellent_answer_indicators":["پیشنهاد تسریع هدفمند (Targeted Crashing) فقط روی فعالیت‌های بحرانی با استفاده از حاشیه هزینه موجود","هشدار درباره خطر افت CPI در صورت تسریع نامنظم و لزوم پایش هم‌زمان هر دو شاخص","تفکیک SPI هزینه‌ای از SPI(t) زمانی برای تحلیل دقیق‌تر"],"common_mistakes":["نتیجه‌گیری که چون CPI خوب است، پروژه کلاً در وضعیت مطلوبی قرار دارد","محاسبه اشتباه فرمول‌ها (مثلاً تقسیم PV بر EV به‌جای EV بر PV)"],"standard_reference":""},{"category":"PROBLEM_SOLVING","sub_category":"فرسایش فلوت مسیر بحرانی","difficulty":"L4","question_text":"گزارش پیشرفت کلی پروژه ۶۵ درصد در برابر ۶۳ درصد برنامه‌ریزی‌شده است (به ظاهر کمی جلوتر از برنامه)، اما بررسی برنامه به‌روزشده در نرم‌افزار نشان می‌دهد فلوت کل مسیر بحرانی از ۲۵ روز در بیس‌لاین به ۲ روز کاهش یافته است. این وضعیت را چگونه تحلیل و به مدیریت گزارش می‌کنید؟","reference_answer":"درصد پیشرفت کلی یک میانگین وزنی از همه فعالیت‌هاست و می‌تواند وضعیت واقعی مسیر بحرانی را پنهان کند؛ در این مورد احتمالاً فعالیت‌های غیربحرانی جلوتر از برنامه پیش رفته‌اند و میانگین کلی را بهبود داده‌اند، در حالی‌که فعالیت‌های مسیر بحرانی فلوت خود را تقریباً به طور کامل مصرف کرده‌اند. کاهش فلوت از ۲۵ به ۲ روز هشدار جدی درباره قریب‌الوقوع بودن تأخیر واقعی در تاریخ اتمام پروژه است، حتی با وجود عدد ظاهراً مطلوب پیشرفت کلی. باید بلافاصله فعالیت‌های مصرف‌کننده فلوت را شناسایی، علل آن (تعارض منابع، تأخیر تأییدیه، مشکل رابط بین رشته‌ها) را بررسی و این ریسک را شفاف و فوری به مدیریت گزارش کرد، همراه با پیشنهاد اقدام اصلاحی مانند بازچینی توالی یا تخصیص منابع اضافی به این فعالیت‌ها.","key_points":["توضیح اینکه درصد پیشرفت کلی یک میانگین وزنی است و وضعیت مسیر بحرانی را پنهان می‌کند","تفسیر کاهش فلوت از ۲۵ به ۲ روز به‌عنوان هشدار جدی قریب‌الوقوع بودن تأخیر","احتمال وجود فعالیت‌های غیربحرانی جلوتر از برنامه که میانگین کلی را بهبود داده‌اند","لزوم شناسایی دقیق فعالیت‌های مصرف‌کننده فلوت روی مسیر بحرانی","گزارش این ریسک به مدیریت به‌صورت شفاف علی‌رغم عدد ظاهراً مثبت پیشرفت کلی","پیشنهاد اقدام اصلاحی فوری قبل از منفی شدن فلوت (بازچینی، تسریع، تأمین منابع)"],"excellent_answer_indicators":["ارائه روند فلوت طی چند دوره قبل به‌عنوان شاهد برای نشان دادن سرعت افت و پیش‌بینی زمان صفر شدن آن","تفکیک فعالیت‌های بحرانی/نزدیک‌به‌بحرانی از سایر فعالیت‌ها در گزارش به تفکیک","پیشنهاد بازنگری منطق برنامه یا افزودن منابع موازی برای فعالیت‌های خاص بحرانی"],"common_mistakes":["اکتفا به گزارش خوش‌بینانه صرفاً بر مبنای درصد کلی پیشرفت","نادیده گرفتن تحلیل مسیر بحرانی و تمرکز فقط بر شاخص‌های تجمعی"],"standard_reference":""},{"category":"SCENARIO","sub_category":"EVM (EAC/VAC)","difficulty":"L3","question_text":"در یک پروژه با بودجه کل (BAC) ۸۰۰ میلیارد ریال، هزینه واقعی تا کنون (AC) ۵۰۰ میلیارد ریال و ارزش کسب‌شده (EV) ۴۰۰ میلیارد ریال است. CPI، EAC (به روش آماری) و VAC را محاسبه کنید و نتیجه را برای مدیریت پروژه تفسیر کنید.","reference_answer":"CPI برابر است با EV تقسیم بر AC، یعنی ۴۰۰ تقسیم بر ۵۰۰ که می‌شود ۰.۸. با فرض ادامه همین روند عملکرد هزینه، EAC از فرمول BAC تقسیم بر CPI به‌دست می‌آید که می‌شود ۸۰۰ تقسیم بر ۰.۸ یعنی ۱۰۰۰ میلیارد ریال. VAC که برابر BAC منهای EAC است، ۸۰۰ منهای ۱۰۰۰ یعنی منفی ۲۰۰ میلیارد ریال می‌شود که نشان می‌دهد در صورت ادامه روند فعلی، پروژه حدود ۲۵ درصد بیش از بودجه مصوب هزینه خواهد داشت. این نتیجه باید به‌سرعت به مدیریت پروژه اطلاع داده شود تا علت ناکارآمدی هزینه بررسی و تصمیم درباره اقدام اصلاحی یا تأمین اعتبار اضطراری گرفته شود، و توصیه می‌شود این عدد آماری با یک برآورد از پایین به بالا نیز اعتبارسنجی شود.","key_points":["محاسبه CPI=400/500=0.8","محاسبه EAC=800/0.8=1000 میلیارد ریال","محاسبه VAC=800-1000=منفی ۲۰۰ میلیارد ریال (۲۵٪ بیش از بودجه)","تفسیر: ادامه روند فعلی به تجاوز محسوس از بودجه مصوب منجر می‌شود","لزوم اعتبارسنجی EAC آماری با برآورد از پایین به بالا (Bottom-up ETC) توسط تیم فنی","ضرورت اطلاع‌رسانی زودهنگام به مدیریت برای تصمیم درباره اقدام اصلاحی یا تأمین اعتبار اضطراری"],"excellent_answer_indicators":["پیشنهاد تفکیک علل انحراف هزینه (نرخ‌های واقعی بالاتر، اتلاف بهره‌وری، تغییرات بدون تأیید) پیش از نتیجه‌گیری نهایی","مقایسه EAC آماری با EAC محاسبه‌شده به روش ترکیبی (لحاظ SPI) برای اطمینان بیشتر","ارائه سناریوهای مختلف EAC (خوش‌بینانه/محتمل/بدبینانه) برای تصمیم‌گیری مدیریتی"],"common_mistakes":["استفاده از فرمول نامناسب بدون توجیه انتخاب آن","نادیده گرفتن نیاز به اعتبارسنجی فنی عدد آماری EAC"],"standard_reference":"PMI Practice Standard for Earned Value Management"},{"category":"PROBLEM_SOLVING","sub_category":"Schedule Risk (QSRA)","difficulty":"L4","question_text":"تحلیل ریسک کمی برنامه (QSRA) با شبیه‌سازی مونت‌کارلو روی برنامه پروژه انجام شده است. تاریخ اتمام قطعی طبق برنامه CPM برابر با تاریخ قراردادی است، اما تاریخ اتمام با اطمینان P80 (احتمال ۸۰ درصد) حدود ۴۵ روز دیرتر از تاریخ قراردادی به دست آمده است. این یافته چه معنایی دارد و چه اقداماتی پیشنهاد می‌کنید؟","reference_answer":"این‌که تاریخ قطعی CPM دقیقاً با تاریخ قرارداد یکسان است به این معنی است که برنامه هیچ ذخیره ریسک ندارد و عملاً یک سناریوی خوش‌بینانه با احتمال موفقیت حدود ۵۰ درصد یا کمتر است. عدد P80 برابر ۴۵ روز دیرتر نشان می‌دهد که تنها ۸۰ درصد احتمال وجود دارد پروژه تا آن تاریخ جدید تمام شود، یعنی احتمال قابل‌توجهی برای عبور از تاریخ قراردادی وجود دارد که در برنامه قطعی دیده نمی‌شود. باید عوامل محرک این پراکندگی را از طریق تحلیل حساسیت (نمودار Tornado) شبیه‌سازی استخراج و اقدامات کاهش ریسک را روی مهم‌ترین آن‌ها اولویت‌بندی کرد، ذخیره زمانی ریسک را در گزارش به مدیریت و کارفرما لحاظ نمود و در صورت لزوم موضوع را با واحد قرارداد هماهنگ کرد.","key_points":["توضیح اینکه تاریخ قطعی CPM بدون احتساب ریسک صرفاً یک سناریوی خوش‌بینانه (معمولاً حدود ۵۰٪ اطمینان یا کمتر) است","تفسیر P80: فقط ۸۰٪ احتمال وجود دارد که پروژه تا این تاریخ (۴۵ روز دیرتر) تمام شود","شکاف ۴۵ روزه نشان‌دهنده ریسک قابل‌توجه عدم دستیابی به تاریخ قراردادی است","لزوم استخراج عوامل محرک ریسک از تحلیل حساسیت (نمودار Tornado) شبیه‌سازی","اولویت‌بندی اقدامات کاهش ریسک روی فعالیت‌ها/ریسک‌های با بیشترین سهم در پراکندگی نتایج","پیشنهاد درنظرگرفتن ذخیره زمانی ریسک (Schedule Contingency) در گزارش به کارفرما","هماهنگی با واحد قرارداد در صورت نیاز به اطلاع‌رسانی رسمی ریسک تأخیر"],"excellent_answer_indicators":["تسلط بر مفهوم توزیع احتمال و تفاوت P50/P80/P90 در تفسیر نتایج مونت‌کارلو","پیوند مستقیم نتایج QSRA به ثبت ریسک (Risk Register) و برنامه پاسخ به ریسک","پیشنهاد اقدام پیشگیرانه زودهنگام به‌جای انتظار برای بروز تأخیر واقعی"],"common_mistakes":["تفسیر نادرست که چون تاریخ CPM با تاریخ قرارداد یکی است پروژه در مسیر درست قرار دارد","نادیده گرفتن تحلیل حساسیت و تمرکز فقط بر عدد نهایی P80"],"standard_reference":""},{"category":"EXPERIENCE_BASED","sub_category":"Recovery Plan (تجربه واقعی)","difficulty":"L3","question_text":"یک نمونه واقعی از تدوین و اجرای یک برنامه بازیابی (Recovery Plan) که شخصاً در آن نقش داشتید را شرح دهید: چه عقب‌ماندگی‌ای وجود داشت، چه تحلیلی انجام دادید، چه راهکارهایی پیشنهاد شد و نتیجه نهایی چه بود؟","reference_answer":"این سؤال معیار محور است و باید بر اساس هر روایت واقعی که کاندیدا ارائه می‌دهد ارزیابی شود، نه یک داستان ثابت از پیش تعیین‌شده. پاسخ قوی شامل یک موقعیت واقعی و مشخص با اعداد قابل استناد (مثلاً میزان تأخیر یا SPI اولیه) است، فرآیند تشخیص ریشه‌ای علت عقب‌ماندگی را پیش از ارائه راهکار نشان می‌دهد، تکنیک‌های واقعی بازیابی (مانند بازچینی توالی، Fast-track یا Crashing) را با آگاهی از تبعات هزینه‌ای و ریسکی آن‌ها توضیح می‌دهد، مسیر تأیید برنامه توسط مدیر پروژه یا کارفرما را بیان می‌کند و در نهایت یک نتیجه قابل‌سنجش و یک درس آموخته ارائه می‌دهد.","key_points":["روایت یک تجربه واقعی و مشخص (نه پاسخ کلی/تئوریک)","توصیف روش تشخیص علت ریشه‌ای عقب‌ماندگی قبل از اقدام","ذکر تکنیک‌های واقعی بازیابی به‌کاررفته (بازچینی، Fast-track، Crashing، شیفت اضافه)","آگاهی از تبعات/ترید-آف هر راهکار (هزینه، ریسک، کیفیت)","اشاره به مسیر تأیید و ارتباط با مدیر پروژه/کارفرما برای این برنامه","بیان نتیجه قابل‌سنجش (مقدار روز بازیابی‌شده یا نتیجه واقعی، حتی اگر ناموفق بوده)","استخراج درس آموخته از تجربه"],"excellent_answer_indicators":["ارائه اعداد و شاخص‌های مشخص (روزهای تأخیر، SPI قبل و بعد) برای اثبات نتیجه","نشان دادن ابتکار شخصی در طراحی راهکار نه فقط اجرای دستور دیگران","تعمیم درس آموخته به بهبود رویه‌های آینده پروژه"],"common_mistakes":["پاسخ کاملاً کلی و تئوریک بدون جزئیات واقعی از یک پروژه مشخص","نبود هیچ عدد یا شاخصی برای اثبات میزان بازیابی واقعی"],"standard_reference":""},{"category":"EXPERIENCE_BASED","sub_category":"Delay Analysis / Claim (تجربه واقعی)","difficulty":"L4","question_text":"یک تجربه واقعی از انجام تحلیل تأخیر (Delay Analysis) برای پشتیبانی از یک ادعای تمدید زمان (EOT) یا دفاع در برابر ادعای کارفرما را شرح دهید. از چه روشی استفاده کردید، چه چالش‌هایی در جمع‌آوری شواهد داشتید و نتیجه نهایی (تأیید/رد/مذاکره) چه بود؟","reference_answer":"این سؤال نیز معیار محور است؛ پاسخ باید به‌عنوان چارچوب ارزیابی هر روایت واقعی کاندیدا به کار رود نه یک داستان ثابت. پاسخ قوی یک رویداد ادعای واقعی و مشخص با زمینه قراردادی روشن را بیان می‌کند، روش تحلیل تأخیر واقعاً استفاده‌شده و دلیل انتخاب آن را نام می‌برد، چالش‌های واقعی جمع‌آوری شواهد و مستندات معاصر و اختلاف بر سر تأخیر هم‌زمان را شرح می‌دهد، نحوه تعامل با کارفرما، مشاور یا واحد قراردادها را توضیح می‌دهد و نتیجه را صادقانه (چه موفق چه ناموفق یا مصالحه‌شده) همراه با یک درس آموخته بیان می‌کند.","key_points":["ذکر یک رویداد ادعای واقعی و مشخص با زمینه قراردادی روشن","نام‌بردن روش تحلیل تأخیر واقعاً استفاده‌شده و دلیل انتخاب آن","توصیف چالش‌های واقعی در جمع‌آوری شواهد و مستندات معاصر","نحوه تعامل با کارفرما/مشاور/واحد قراردادها در فرآیند ارائه یا دفاع از ادعا","بیان نتیجه صادقانه (تأیید کامل/جزئی، رد، یا مذاکره) نه لزوماً موفقیت کامل","درس آموخته درباره بهبود مستندسازی یا فرآیند برای آینده"],"excellent_answer_indicators":["تسلط فنی در توضیح چگونگی مدل‌سازی رویداد تأخیر در برنامه و برخورد با تأخیر هم‌زمان","نشان دادن نقش فعال در تقویت مبنای مستندسازی برای دفاع بهتر از ادعا","کمی‌سازی دقیق نتیجه (تعداد روز تأیید/رد شده)"],"common_mistakes":["پاسخ کاملاً تئوریک بدون اشاره به یک رویداد واقعی","اغراق در ادعای موفقیت بدون ذکر چالش‌ها یا جزئیات فرآیند"],"standard_reference":""},{"category":"EXPERIENCE_BASED","sub_category":"صحت‌سنجی گزارش پیشرفت (تجربه واقعی)","difficulty":"L3","question_text":"تجربه واقعی خود از شناسایی یک گزارش پیشرفت نادرست یا دستکاری‌شده (چه توسط پیمانکار جزء، چه توسط تیم داخلی) و نحوه برخورد شما با آن را شرح دهید. چگونه متوجه شدید، چه اقدامی انجام دادید و پیامد نهایی چه بود؟","reference_answer":"این سؤال باید بر اساس معیارهای ارزیابی زیر برای هر روایت واقعی که کاندیدا بیان می‌کند سنجیده شود. پاسخ قوی یک نمونه واقعی و مشخص را بیان می‌کند، روش کشف مغایرت (کراس‌چک با QC، بازدید میدانی، تناقض بین هزینه و پیشرفت) را توضیح می‌دهد، اقدام اصلاحی انجام‌شده مانند تصحیح عدد و اطلاع‌رسانی به سطح مناسب را شرح می‌دهد، برخورد حرفه‌ای به‌جای واکنش تنبیهی صرف را نشان می‌دهد و پیامد واقعی موضوع همراه با یک درس آموخته یا اقدام پیشگیرانه برای آینده را بیان می‌کند.","key_points":["ذکر یک نمونه واقعی و مشخص، نه فرضی","روش کشف مغایرت (کراس‌چک با QC، بازدید میدانی، تناقض هزینه-پیشرفت)","اقدام اصلاحی انجام‌شده (تصحیح عدد، گفتگو، اطلاع‌رسانی به سطح مناسب)","حفظ حرفه‌ای‌گری در برخورد به‌جای واکنش تنبیهی صرف","پیامد واقعی موضوع (اصلاح گزارش، بهبود رویه، تنش احتمالی)","درس آموخته و اقدام پیشگیرانه برای آینده (مانند رویه تأیید پیشرفت)"],"excellent_answer_indicators":["طراحی یا پیشنهاد یک کنترل سیستمی (فرم تأیید، ممیزی دوره‌ای) پس از این تجربه","نشان دادن حساسیت به الگوهای غیرعادی داده به‌عنوان مهارت تحلیلی","توازن بین قاطعیت در اصلاح داده و حفظ روابط کاری سازنده"],"common_mistakes":["پاسخ کلی بدون جزئیات نحوه کشف واقعی مغایرت","نبود اقدام پیشگیرانه یا درس آموخته پس از حادثه"],"standard_reference":""},{"category":"EXPERIENCE_BASED","sub_category":"راه‌اندازی سیستم کنترل پروژه (تجربه واقعی)","difficulty":"L2","question_text":"یک تجربه واقعی از راه‌اندازی سیستم کنترل پروژه (تدوین WBS، CBS و بیس‌لاین اولیه) برای یک پروژه جدید از ابتدا را شرح دهید. با چه چالش‌هایی در جمع‌آوری داده اولیه و همسو کردن ذی‌نفعان مواجه شدید؟","reference_answer":"این سؤال معیار محور است و باید بر اساس هر روایت واقعی کاندیدا سنجیده شود. پاسخ قوی زمینه واقعی راه‌اندازی یک پروژه از صفر را توصیف می‌کند، فرآیند واقعی تدوین WBS، CBS و OBS از طریق کارگاه با رشته‌های مختلف و استناد به محدوده قراردادی و برآورد را شرح می‌دهد، طراحی ساختار کدگذاری برای یکپارچگی هزینه و برنامه را بیان می‌کند، چالش‌های واقعی مانند داده مهندسی ناقص اولیه یا عدم توافق رشته‌ها بر سر سطح تفکیک فعالیت‌ها و هم‌ترازی با سیستم مالی را توضیح می‌دهد، فرآیند اخذ تأیید بیس‌لاین از مدیر پروژه یا کارفرما را بیان می‌کند و نتیجه و درس آموخته را ارائه می‌دهد.","key_points":["توصیف زمینه واقعی راه‌اندازی یک پروژه از صفر","فرآیند واقعی تدوین WBS/CBS/OBS (کارگاه با رشته‌ها، استناد به محدوده قراردادی و برآورد)","طراحی ساختار کدگذاری برای یکپارچگی هزینه-برنامه","چالش‌های واقعی مواجه‌شده (داده ناقص اولیه، عدم توافق رشته‌ها، هم‌ترازی با سیستم مالی)","فرآیند اخذ تأیید بیس‌لاین از مدیر پروژه/کارفرما","نتیجه و درس آموخته برای راه‌اندازی‌های آتی"],"excellent_answer_indicators":["مشارکت فعال در حل اختلاف بین رشته‌ها بر سر سطح تفکیک فعالیت‌ها","طراحی رویه‌ای که در پروژه‌های بعدی نیز قابل تکرار بوده است","اشاره به معیار انتخاب سطح تفصیل WBS متناسب با نیاز کنترل پروژه"],"common_mistakes":["پاسخ کاملاً نظری بدون تجربه عملی مشخص","نادیده گرفتن چالش‌های همسویی بین رشته‌ها/ذی‌نفعان در فرآیند راه‌اندازی"],"standard_reference":""}]'::jsonb) as x(
  category text, sub_category text, difficulty text, question_text text, reference_answer text,
  key_points jsonb, excellent_answer_indicators jsonb, common_mistakes jsonb, standard_reference text
)
where not exists (select 1 from comp_question_bank where job_role = 'project_control_specialist');

-- ---- hse_specialist (23 questions) ----
insert into comp_question_bank (job_role, category, sub_category, difficulty, question_text, reference_answer, key_points, excellent_answer_indicators, common_mistakes, standard_reference)
select 'hse_specialist', x.category, x.sub_category, x.difficulty, x.question_text, x.reference_answer,
       coalesce(x.key_points, '[]'::jsonb), coalesce(x.excellent_answer_indicators, '[]'::jsonb), coalesce(x.common_mistakes, '[]'::jsonb), coalesce(x.standard_reference, '')
from jsonb_to_recordset('[{"category":"GENERAL","sub_category":"نقش HSE در چرخه پروژه","difficulty":"L1","question_text":"نقش کارشناس HSE در طول چرخه عمر یک پروژه احداث خط لوله گاز (از مرحله مهندسی تا راه‌اندازی) را توضیح دهید و بگویید تعامل شما با کارفرما، مشاور و پیمانکار در هر مرحله چگونه باید باشد؟","reference_answer":"کارشناس HSE در مرحله مهندسی باید در بازنگری‌های HAZID/HAZOP و نقشه‌های فنی مشارکت کند تا خطرات از ابتدا در طراحی کاهش یابند. در مرحله تدارکات، ارزیابی صلاحیت HSE پیمانکاران و بررسی برگه‌های ایمنی مواد (MSDS) اهمیت دارد. در فاز اجرا، مسئولیت اصلی نظارت میدانی روزانه، تایید پرمیت‌های کار، ممیزی و آموزش تیم اجرایی است، و در فاز راه‌اندازی باید بر ایمنی آزمون‌های پیش‌راه‌اندازی و تحویل نظارت شود. تعامل با کارفرما باید از طریق خط گزارش‌دهی مستقل باشد، با مشاور هماهنگی فنی صورت گیرد و با پیمانکار نقش نظارت اجرایی و آموزش ایفا شود، بدون این‌که استقلال قضاوت HSE تحت‌تاثیر روابط اجرایی قرار گیرد.","key_points":["نقش در فاز مهندسی و بازنگری HAZID/HAZOP","نقش در فاز تدارکات و ارزیابی صلاحیت پیمانکار","نظارت اجرایی روزانه و تایید پرمیت در فاز ساخت","نقش در راه‌اندازی و آزمون‌های پیش‌راه‌اندازی","خط گزارش‌دهی مستقل به کارفرما","هماهنگی فنی با مشاور"],"excellent_answer_indicators":["تسلط به تفاوت نقش نظارتی کارفرما/مشاور در برابر نقش اجرایی پیمانکار","تاکید بر استقلال گزارش‌دهی HSE از فشار اجرایی پیمانکار","نگاه سیستمی به کل چرخه عمر پروژه نه فقط فاز اجرا","اشاره به مستندسازی متناسب با هر فاز"],"common_mistakes":["محدود کردن نقش HSE فقط به بازرسی میدانی در فاز اجرا","ندیدن نقش HSE در فاز مهندسی و طراحی","خلط نقش نظارتی HSE با نقش اجرایی پیمانکار"],"standard_reference":""},{"category":"GENERAL","sub_category":"مدیریت تغییر (MOC)","difficulty":"L2","question_text":"فرض کنید در حین اجرای پروژه، پیمانکار بدون هماهنگی قبلی، روش اجرایی حفاری ترانشه را برای عبور سریع‌تر تجهیزات تغییر می‌دهد. به‌عنوان کارشناس HSE چه فرآیندی را باید طی کنید و چرا مدیریت تغییر (MOC) در اینجا اهمیت دارد؟","reference_answer":"ابتدا باید اجرای روش تغییریافته را تا تکمیل ارزیابی متوقف یا محدود کنید، زیرا هر تغییر در روش اجرا، تجهیز، مواد یا توالی کار که می‌تواند بر ریسک ایمنی اثر بگذارد باید از مسیر رسمی مدیریت تغییر (MOC) عبور کند. فرآیند MOC شامل تکمیل فرم درخواست تغییر، ارزیابی ریسک جدید ناشی از تغییر، بازبینی و به‌روزرسانی JSA و پرمیت مرتبط، و تایید ذی‌صلاحان فنی و HSE پیش از اجرا است. بدون طی این فرآیند، تغییر حتی اگر به‌ظاهر جزئی و برای تسریع کار باشد، غیرمجاز تلقی می‌شود و نباید ادامه یابد.","key_points":["تشخیص تغییر روش اجرا به‌عنوان یک رویداد نیازمند MOC","توقف یا کنترل کار غیرمجاز تا تکمیل ارزیابی","تکمیل فرم رسمی MOC و ارزیابی ریسک مجدد","به‌روزرسانی JSA و پرمیت مرتبط","تایید ذی‌صلاحان فنی و HSE پیش از اجرا","اطلاع‌رسانی تغییر تاییدشده به تیم اجرایی"],"excellent_answer_indicators":["تاکید بر اینکه تغییر بدون تایید یعنی کار غیرمجاز و باید متوقف شود حتی برای تسریع کار","اشاره به ریسک پنهان تغییرات به‌ظاهر بی‌ضرر","درک MOC به‌عنوان یک فرآیند مستند و ردیابی‌پذیر نه یک تشریفات اداری"],"common_mistakes":["نادیده گرفتن تغییر جزئی و اجازه ادامه کار بدون MOC","فرض اینکه فقط تغییرات بزرگ نیاز به MOC دارند","عدم ثبت تغییر در مستندات پروژه"],"standard_reference":""},{"category":"GENERAL","sub_category":"نظارت HSE بر پیمانکار","difficulty":"L3","question_text":"شما به‌عنوان کارشناس HSE کارفرما/مشاور متوجه می‌شوید که پیمانکار به‌طور مستمر آمار Near Miss را کمتر از واقعیت گزارش می‌کند تا عملکرد HSE خود را بهتر نشان دهد. چه اقداماتی برای اصلاح این وضعیت انجام می‌دهید؟","reference_answer":"ابتدا باید موضوع را با شواهد عینی مانند مقایسه مشاهدات میدانی و نتایج بازرسی‌ها با آمار رسمی گزارش‌شده مستند کنید. سپس باید علت ریشه‌ای کم‌گزارشی را بررسی کنید که معمولاً ناشی از فرهنگ ترس از تنبیه یا سیستم انگیزشی نادرست پیمانکار است، نه صرفاً بی‌توجهی فردی. باید موضوع به‌صورت رسمی و مستند به مدیریت HSE پیمانکار و در صورت لزوم به کارفرما گزارش شود، ترویج فرهنگ گزارش‌دهی بدون تنبیه (Just Culture) پیگیری گردد و در صورت تکرار، این موضوع در ارزیابی عملکرد HSE پیمانکار و جلسات سطح بالا مطرح شود.","key_points":["شناسایی نشانه‌های کم‌گزارشی از طریق مقایسه داده‌ها","مستندسازی با شواهد عینی نه صرفاً حدس","بررسی علت ریشه‌ای فرهنگی/انگیزشی کم‌گزارشی","ترویج فرهنگ گزارش‌دهی بدون تنبیه (Just Culture)","گزارش رسمی به مدیریت پیمانکار و کارفرما","پیگیری از طریق ممیزی مستقل و ارزیابی عملکرد پیمانکار"],"excellent_answer_indicators":["درک این‌که شاخص‌های پیشرو مثل نرخ گزارش Near Miss باید رصد شوند نه فقط نرخ حادثه","نگاه سیستمی به فرهنگ ایمنی پیمانکار به‌جای برخورد تنبیهی فردی","توانایی مواجهه مستقیم و مستند با مدیریت پیمانکار بدون تعارف"],"common_mistakes":["برخورد صرفاً تنبیهی با کارگر گزارش‌دهنده به‌جای اصلاح سیستم","نادیده گرفتن موضوع چون آمار ظاهری خوب به‌نظر می‌رسد","اکتفا به تذکر شفاهی بدون مستندسازی رسمی"],"standard_reference":""},{"category":"GENERAL","sub_category":"اختیار توقف کار (Stop Work Authority)","difficulty":"L3","question_text":"در جلسه هفتگی HSE، مدیر پروژه از شما می‌خواهد که به دلیل تاخیر در برنامه زمان‌بندی، سخت‌گیری در تایید پرمیت‌های کار در ارتفاع را کمی کاهش دهید. با این درخواست چگونه برخورد می‌کنید؟","reference_answer":"باید صراحتاً و به‌صورت مستند اعلام کنید که معیارهای تایید پرمیت و اختیار توقف کار (Stop Work Authority) تحت هیچ شرایطی با فشار زمان‌بندی قابل مذاکره نیستند. باید دلایل فنی و ایمنی این تصمیم را برای مدیر پروژه شفاف توضیح دهید و در صورت اصرار، موضوع را به سطح بالاتر مانند مدیر HSE کارفرما یا کمیته HSE ارجاع دهید. تمام مکاتبات، درخواست و پاسخ باید مستند شود تا مسئولیت‌پذیری روشن بماند و در صورت امکان، راه‌حل جایگزینی برای جبران تاخیر بدون کاهش استاندارد ایمنی (مانند افزایش منابع بازرسی) پیشنهاد شود.","key_points":["عدم پذیرش کاهش استانداردهای ایمنی به هر بهانه‌ای","توضیح فنی و مستدل ریسک به مدیر پروژه","مستندسازی کتبی درخواست و پاسخ","ارجاع به سطح بالاتر سازمانی در صورت اصرار","حفظ استقلال خط گزارش‌دهی HSE","پیشنهاد راه‌حل جایگزین برای جبران تاخیر"],"excellent_answer_indicators":["قاطعیت حرفه‌ای بدون تقابل غیرسازنده با مدیر پروژه","آگاهی به مسئولیت حقوقی امضای تایید HSE","ارائه راه‌حل عملی جایگزین به‌جای صرفاً رد درخواست","مستندسازی کتبی تصمیم برای محافظت از خود و سازمان"],"common_mistakes":["پذیرش ضمنی کاهش سخت‌گیری برای همراهی با مدیر پروژه","برخورد احساسی یا تقابلی بدون مستندسازی","انجام خواسته به‌صورت سکوت‌آمیز بدون گزارش به رده بالاتر"],"standard_reference":""},{"category":"TECHNICAL","sub_category":"سیستم مدیریت HSE (HSE-MS)","difficulty":"L1","question_text":"عناصر اصلی یک سیستم مدیریت HSE (HSE-MS) در یک پروژه EPC خط لوله را نام ببرید و نقش هر یک را به‌طور خلاصه توضیح دهید.","reference_answer":"یک HSE-MS معمولاً شامل خط‌مشی و تعهد مدیریت ارشد، شناسایی خطر و ارزیابی ریسک، برنامه‌ریزی و تعیین اهداف، ساختار سازمانی و تعریف مسئولیت‌ها، آموزش و ارتقای شایستگی، کنترل عملیاتی از طریق رویه‌ها و پرمیت و JSA، آمادگی و واکنش اضطراری، پایش و اندازه‌گیری عملکرد، و ممیزی و بازنگری مدیریت است. این عناصر در قالب چرخه بهبود مستمر (Plan-Do-Check-Act) به هم متصل می‌شوند تا سیستم به‌مرور زمان ارتقا یابد.","key_points":["خط‌مشی و تعهد مدیریت ارشد","شناسایی خطر و ارزیابی ریسک","کنترل عملیاتی (رویه‌ها، پرمیت، JSA)","آموزش و ارتقای شایستگی پرسنل","آمادگی و واکنش اضطراری","پایش عملکرد، ممیزی و بازنگری مدیریت"],"excellent_answer_indicators":["درک صحیح چرخه PDCA و بهبود مستمر سیستم","تمایز شاخص‌های پیشرو (Leading) و پسرو (Lagging) در پایش عملکرد","اشاره به یکپارچگی HSE-MS با سایر سیستم‌های مدیریت پروژه"],"common_mistakes":["برشمردن HSE-MS صرفاً به‌عنوان مجموعه‌ای از فرم‌ها و چک‌لیست","ندیدن نقش بازنگری مدیریت و بهبود مستمر","خلط HSE-MS با یک دستورالعمل ایمنی واحد"],"standard_reference":"ISO 45001"},{"category":"TECHNICAL","sub_category":"روش‌شناسی ارزیابی ریسک","difficulty":"L2","question_text":"تفاوت روش‌های ارزیابی ریسک کیفی، نیمه‌کمی و کمی را توضیح دهید و بگویید برای یک عملیات پرخطر مانند ورود به فضای محصور در پروژه خط لوله، کدام رویکرد مناسب‌تر است و چرا؟","reference_answer":"ارزیابی کیفی بر پایه قضاوت تجربی و ماتریس احتمال-شدت انجام می‌شود، روش نیمه‌کمی از امتیازدهی عددی برای رتبه‌بندی نسبی ریسک‌ها استفاده می‌کند، و روش کمی مانند QRA بر داده‌های آماری و مدل‌سازی دقیق احتمال وقوع و پیامد مبتنی است. برای ورود به فضای محصور، معمولاً ترکیب کیفی/نیمه‌کمی از طریق ماتریس ریسک همراه با JSA برای شرایط معمول کافی است، مگر اینکه خطر خاصی مانند تجمع گاز سمی با سابقه حادثه پیشین وجود داشته باشد که در آن صورت تحلیل دقیق‌تری لازم است. در هر سطح، باید سلسله‌مراتب کنترل خطر (حذف، جایگزینی، کنترل مهندسی، کنترل اداری، PPE) به‌ترتیب اعمال شود.","key_points":["تعریف دقیق ارزیابی کیفی، نیمه‌کمی و کمی","کاربرد ماتریس احتمال-شدت در روش کیفی/نیمه‌کمی","کاربرد QRA در ریسک‌های پیچیده و پرتکرار","انتخاب روش متناسب با پیچیدگی و سابقه خطر","اعمال سلسله‌مراتب کنترل خطر پس از ارزیابی","بازنگری ارزیابی ریسک هنگام تغییر شرایط میدانی"],"excellent_answer_indicators":["توانایی تشخیص کِی تحلیل کمی واقعاً توجیه دارد در برابر اتلاف وقت غیرضروری","تسلط به اصل ALARP (کاهش ریسک تا حد معقول و عملی)","اشاره به بازنگری پویا و مستمر ریسک در حین اجرای کار"],"common_mistakes":["خلط ارزیابی ریسک با صرفاً پرکردن فرم بدون تحلیل واقعی","استفاده از یک روش ثابت برای تمام شرایط بدون تناسب با پیچیدگی خطر","نادیده گرفتن سلسله‌مراتب کنترل و رفتن مستقیم به سراغ PPE"],"standard_reference":"ISO 31000"},{"category":"TECHNICAL","sub_category":"JSA/JHA","difficulty":"L2","question_text":"مراحل تهیه یک JSA (تجزیه و تحلیل ایمنی شغلی) استاندارد برای یک فعالیت جدید در سایت پروژه خط لوله را شرح دهید و بگویید چه کسانی باید در تهیه و تایید آن مشارکت داشته باشند.","reference_answer":"مراحل تهیه JSA شامل تجزیه کار به گام‌های اجرایی مشخص، شناسایی خطرات بالقوه هر گام، تعیین کنترل‌های لازم بر اساس سلسله‌مراتب کنترل برای هر خطر، و مشخص‌کردن مسئول اجرای هر کنترل است. تیم تهیه باید شامل سرپرست اجرایی، کارگران واقعی انجام‌دهنده کار که تجربه میدانی مستقیم دارند، و کارشناس HSE باشد و تایید نهایی باید توسط ناظر و کارشناس HSE صورت گیرد. JSA باید پیش از هر شیفت در قالب Toolbox Talk با تیم مرور شود و در صورت تغییر شرایط میدانی یا روش اجرا، بازنگری گردد.","key_points":["تجزیه کار به گام‌های اجرایی مشخص","شناسایی خطر بالقوه برای هر گام","تعیین کنترل بر اساس سلسله‌مراتب کنترل","مشارکت واقعی کارگران انجام‌دهنده کار","تایید سرپرست اجرایی و کارشناس HSE","مرور در Toolbox Talk و بازنگری هنگام تغییر شرایط"],"excellent_answer_indicators":["تاکید بر مشارکت واقعی کارگران خط مقدم نه صرفاً امضای فرم از پیش نوشته‌شده","پیوند دادن JSA به سیستم پرمیت کار","دیدن JSA به‌عنوان سند زنده قابل بازنگری نه یک تشریفات اداری"],"common_mistakes":["تهیه JSA به‌صورت کپی از فعالیت مشابه بدون تطبیق با شرایط واقعی سایت","عدم مشارکت کارگران اجراکننده در تهیه سند","تلقی JSA به‌عنوان صرفاً یک فرم امضایی برای دریافت پرمیت"],"standard_reference":"OSHA 3071"},{"category":"TECHNICAL","sub_category":"سیستم پرمیت کار (PTW)","difficulty":"L2","question_text":"سلسله‌مراتب و ارتباط بین سیستم پرمیت کار (PTW)، گواهی ایزوله (Isolation Certificate) و مجوز ورود به فضای محصور را در یک عملیات نگهداری روی خط لوله گاز توضیح دهید.","reference_answer":"پرمیت کار سند اصلی مجوز انجام کار است که بر اساس نوع فعالیت مانند کار سرد، کار گرم، فضای محصور، حفاری یا کار در ارتفاع طبقه‌بندی می‌شود. گواهی ایزوله سندی مکمل است که تایید می‌کند منبع انرژی مانند گاز، برق یا فشار به‌طور فیزیکی قطع و قفل/برچسب‌گذاری شده و باید پیش از صدور پرمیت مرتبط تکمیل و به آن ضمیمه شود. مجوز ورود به فضای محصور نیز پرمیت تخصصی جداگانه‌ای است که علاوه بر پرمیت اصلی، نیازمند تست اتمسفر، حضور ناظر بیرونی صالح و برنامه نجات مدون است. تمامی این اسناد باید به یکدیگر ارجاع داده شوند و بدون تکمیل کامل هرکدام، کار نباید آغاز شود.","key_points":["تعریف پرمیت اصلی و انواع طبقه‌بندی آن","نقش گواهی ایزوله و قفل/برچسب‌گذاری (LOTO)","ارتباط زنجیره‌ای و ارجاع متقابل بین اسناد مجوز","الزامات اضافه فضای محصور شامل تست اتمسفر و ناظر و برنامه نجات","عدم آغاز کار بدون تکمیل کامل زنجیره مجوزها","مسئولیت مشخص تایید هر سند توسط فرد ذی‌صلاح"],"excellent_answer_indicators":["توضیح دقیق زنجیره تاییدیه‌ها و اینکه فقدان هرکدام یعنی توقف کار","آگاهی از نقش‌های مجزای صادرکننده پرمیت، دریافت‌کننده و تست‌گر مجاز گاز","اشاره به بازرسی دوره‌ای پرمیت در طول انجام کار نه فقط لحظه صدور"],"common_mistakes":["تصور اینکه پرمیت کار عمومی جایگزین گواهی ایزوله یا مجوز فضای محصور می‌شود","نادیده گرفتن نیاز به تست مجدد اتمسفر در کارهای طولانی‌مدت","عدم آگاهی از نقش‌های مجزای صادرکننده، دریافت‌کننده و تست‌گر گاز"],"standard_reference":""},{"category":"TECHNICAL","sub_category":"پرمیت کار گرم (Hot Work)","difficulty":"L3","question_text":"الزامات فنی و کنترلی صدور پرمیت کار گرم (Hot Work) در نزدیکی تاسیسات گازی را که باید پیش از تایید بررسی کنید، توضیح دهید.","reference_answer":"باید فاصله ایمن از منابع گاز و مواد قابل‌اشتعال احراز شود، تست گاز قابل‌اشتعال (LEL) پیش از شروع کار و در فواصل زمانی مشخص در طول کار انجام و نتایج مستند گردد، حضور Fire Watch مجهز به تجهیزات اطفای حریق مناسب الزامی است، مواد قابل‌اشتعال اطراف پوشانده یا ایزوله شوند، و وضعیت خطوط مجاور از نظر گازرسانی و ونتینگ بررسی شود. در صورت وجود هرگونه شرایط ناایمن مانند بوی گاز یا نتیجه تست LEL بالای حد مجاز، پرمیت نباید صادر شود یا باید بلافاصله متوقف گردد.","key_points":["تست LEL پیش از شروع و پایش مستمر در طول کار","حضور Fire Watch و تجهیزات اطفای حریق مناسب","فاصله ایمن و ایزوله‌سازی مواد قابل‌اشتعال","هماهنگی با وضعیت خطوط مجاور از نظر گازرسانی و ونتینگ","توقف فوری کار در صورت افزایش غلظت گاز","مستندسازی نتایج تست در پرمیت"],"excellent_answer_indicators":["تاکید بر پایش مستمر گاز نه فقط یک تست اولیه","آگاهی از تاثیر شرایط جوی مانند باد و دما بر پراکندگی گاز","قاطعیت در ابطال پرمیت به محض مشاهده شرایط ناایمن صرف‌نظر از فشار زمانی"],"common_mistakes":["اکتفا به یک تست گاز اولیه بدون پایش مستمر در طول کار","واگذاری نقش Fire Watch به فردی بدون آموزش لازم","ادامه کار گرم صرفاً بر اساس تجربه بدون تست عینی"],"standard_reference":"NFPA 51B"},{"category":"TECHNICAL","sub_category":"ایمنی برق و LOTO","difficulty":"L3","question_text":"روش صحیح ایزوله‌سازی و قفل/برچسب‌گذاری (LOTO) برای کار روی یک تابلوی برق یا موتور الکتریکی مرتبط با تجهیزات خط لوله را مرحله‌به‌مرحله شرح دهید.","reference_answer":"مراحل شامل شناسایی تمام منابع انرژی مرتبط، اطلاع‌رسانی به کاربران و بهره‌برداران، خاموش‌کردن تجهیز از طریق روش عملیاتی استاندارد، قطع فیزیکی منبع انرژی، نصب قفل و برچسب شخصی توسط هر فرد درگیر در کار به‌صورت مجزا، تخلیه انرژی‌های ذخیره‌شده مانند خازن‌ها، و تست صفر بودن ولتاژ پیش از شروع کار است. در پایان کار، بازگرداندن انرژی فقط پس از اطمینان از خروج همه افراد و برداشتن تمام قفل‌ها توسط صاحبان آن‌ها انجام می‌شود.","key_points":["شناسایی همه منابع انرژی مرتبط با تجهیز","قطع و ایزوله فیزیکی منبع انرژی","قفل و برچسب فردی برای هر نفر درگیر در کار","تخلیه انرژی‌های ذخیره‌شده مانند خازن یا فشار باقیمانده","تست صفر ولتاژ پیش از شروع کار","رویه ایمن بازگرداندن انرژی با هماهنگی کامل تیم"],"excellent_answer_indicators":["تاکید بر اصل قفل فردی برای هر نفر نه صرفاً یک قفل نماینده تیم","آگاهی از خطر انرژی‌های پنهان مانند باقیمانده، ذخیره‌شده یا گرانشی","الزام تست عملی صفر ولتاژ به‌جای اعتماد صرف به وضعیت کلید"],"common_mistakes":["بسنده‌کردن به خاموش‌کردن کلید بدون قفل فیزیکی","استفاده از یک قفل مشترک برای کل تیم به‌جای قفل فردی","فراموش‌کردن تخلیه انرژی‌های ذخیره‌شده مانند خازن یا فنر"],"standard_reference":"OSHA 1910.147"},{"category":"TECHNICAL","sub_category":"تست گاز (Gas Testing)","difficulty":"L2","question_text":"ترتیب صحیح تست گازهای مختلف مانند اکسیژن، گازهای قابل‌اشتعال، H2S و CO قبل از ورود به یک فضای محصور یا ترانشه در پروژه خط لوله را توضیح دهید و بگویید چرا این ترتیب اهمیت دارد.","reference_answer":"ترتیب استاندارد معمولاً ابتدا اکسیژن که باید بین ۱۹.۵ تا ۲۳.۵ درصد باشد، سپس گازهای قابل‌اشتعال (LEL) و سپس گازهای سمی مانند H2S و CO است. این ترتیب اهمیت دارد زیرا سطح غیرعادی اکسیژن می‌تواند دقت خوانش سایر سنسورها به‌ویژه سنسور قابل‌اشتعال را تحت‌تاثیر قرار دهد، و همچنین کمبود یا افزایش اکسیژن خود یک خطر فوری برای زندگی است که باید ابتدا شناسایی شود. دستگاه تست باید پیش از استفاده کالیبره و Bump Test شده باشد و تست باید در نقاط مختلف ارتفاعی فضا انجام شود، زیرا گازها بسته به وزن مولکولی در ارتفاعات متفاوتی تجمع می‌یابند.","key_points":["ترتیب تست: اکسیژن، سپس گازهای قابل‌اشتعال، سپس گازهای سمی","دلیل تقدم اکسیژن بر دقت خوانش سایر سنسورها","کالیبراسیون و Bump Test دستگاه پیش از استفاده","تست در نقاط مختلف ارتفاعی فضا","پایش مستمر گاز در طول کار نه فقط یک‌بار در ابتدا","ثبت نتایج تست در سند پرمیت"],"excellent_answer_indicators":["آگاهی از رفتار فیزیکی گازها بر اساس چگالی نسبی نسبت به هوا","تاکید بر پایش مستمر گاز در کارهای طولانی‌مدت","قاطعیت در توقف کار با هرگونه خوانش خارج از محدوده مجاز صرف‌نظر از فشار برنامه"],"common_mistakes":["انجام تست فقط یک‌بار در ابتدای ورود بدون پایش مستمر","استفاده از دستگاه بدون کالیبراسیون یا Bump Test مستند","عدم توجه به نقاط تجمع گاز بر اساس ارتفاع فضا"],"standard_reference":""},{"category":"TECHNICAL","sub_category":"تجهیزات حفاظت فردی (PPE)","difficulty":"L1","question_text":"اصل سلسله‌مراتب کنترل خطر (Hierarchy of Controls) را توضیح دهید و بگویید چرا PPE آخرین خط دفاعی محسوب می‌شود، نه اولین راه‌حل.","reference_answer":"سلسله‌مراتب کنترل از موثرترین به کم‌اثرترین شامل حذف خطر، جایگزینی با گزینه کم‌خطرتر، کنترل‌های مهندسی مانند حصارکشی و تهویه، کنترل‌های اداری مانند رویه‌ها و چرخش شیفت، و در نهایت تجهیزات حفاظت فردی است. PPE آخرین خط دفاعی است زیرا خودِ خطر را حذف نمی‌کند و فقط فرد را از پیامد آن محافظت می‌کند، و اثربخشی آن کاملاً وابسته به رفتار انسانی مانند استفاده مداوم، نگهداری صحیح و اندازه مناسب است که نسبت به کنترل‌های بالادستی قابلیت اطمینان کمتری دارد. یک برنامه ایمنی خوب ابتدا امکان حذف یا کاهش خطر در منبع را بررسی می‌کند و PPE را به‌عنوان مکمل نهایی در نظر می‌گیرد.","key_points":["ترتیب حذف، جایگزینی، کنترل مهندسی، کنترل اداری و PPE","توضیح چرایی کم‌اثر بودن نسبی PPE در راس این سلسله‌مراتب","وابستگی اثربخشی PPE به رفتار و انضباط انسانی","اهمیت بررسی گزینه‌های بالادستی پیش از تکیه بر PPE","ارائه مثال عملی برای هر سطح کنترل"],"excellent_answer_indicators":["ارائه مثال میدانی واقعی که کاربرد این اصل را در عمل نشان دهد","نقد فرهنگ سازمانی‌هایی که صرفاً روی الزام PPE تمرکز دارند بدون کنترل ریشه‌ای خطر"],"common_mistakes":["معرفی PPE به‌عنوان اولین یا تنها راه‌حل کنترل خطر","اکتفا به تعریف کتابی بدون ارائه مثال عملی","خلط کنترل اداری با کنترل مهندسی"],"standard_reference":"OSHA 1910.132"},{"category":"SCENARIO","sub_category":"پرمیت کار / Tie-in","difficulty":"L3","question_text":"در یک عملیات Tie-in روی خط لوله گاز فشار قوی، تیم اجرایی تمام تجهیزات را مستقر کرده و آماده شروع کار است، اما مشخص می‌شود که گواهی ایزوله یکی از شیرهای مجاور به‌طور کامل تکمیل و تایید نشده است. پیمانکار به دلیل فشار زمان‌بندی و هزینه توقف تجهیزات، درخواست شروع فوری کار را دارد. تصمیم شما به‌عنوان کارشناس HSE چیست و چرا؟","reference_answer":"پرمیت کار نباید تایید یا اجرا شود تا زمانی که گواهی ایزوله به‌طور کامل تکمیل، تایید و توسط فرد ذی‌صلاح راستی‌آزمایی شده باشد. این تصمیم صرف‌نظر از فشار زمانی یا هزینه توقف تجهیزات غیرقابل تغییر است، زیرا کار روی خط لوله گاز فشار قوی بدون ایزوله کامل می‌تواند به رهاسازی گاز، آتش‌سوزی یا انفجار با تلفات جانی منجر شود. اقدام صحیح، توقف رسمی کار، اطلاع کتبی به مدیر پروژه و سرپرست پیمانکار، پیگیری فوری تکمیل ایزوله با تیم فنی/بهره‌برداری، و مستندسازی کامل تصمیم در سیستم پرمیت است. تنها پس از راستی‌آزمایی و تکمیل مستندات، پرمیت جدید صادر و کار از سر گرفته می‌شود.","key_points":["عدم تایید پرمیت تا تکمیل کامل گواهی ایزوله","رد صریح درخواست شروع کار زیر فشار زمانی","توقف رسمی و مستند کار","اطلاع‌رسانی کتبی به سطوح مسئول پروژه","پیگیری فعال رفع نقص با تیم فنی/بهره‌برداری","صدور مجدد پرمیت فقط پس از راستی‌آزمایی کامل"],"excellent_answer_indicators":["قاطعیت فوری بدون تردید یا مذاکره بر سر اصل موضوع","توضیح دقیق پیامد فنی احتمالی رهاسازی گاز فشار قوی برای توجیه تصمیم","ارائه هم‌زمان یک مسیر سریع اما ایمن برای رفع نقص جهت کاهش تاخیر","مستندسازی که کارشناس را در برابر فشارهای بعدی محافظت کند"],"common_mistakes":["پذیرش شروع کار مشروط با وعده تکمیل مدارک بعداً","اجازه شروع بخشی از کار در حالی که ایزوله ناقص است","ارتباط صرفاً شفاهی و عدم مستندسازی تصمیم توقف"],"standard_reference":""},{"category":"SCENARIO","sub_category":"ورود به فضای محصور (Confined Space)","difficulty":"L3","question_text":"تیم اجرایی برای بازرسی داخلی یک مخزن (فضای محصور) در ایستگاه تقویت فشار آماده ورود است. نتیجه تست اولیه اتمسفر مطلوب بوده، اما شما متوجه می‌شوید فرد تعیین‌شده به‌عنوان Attendant (ناظر بیرونی) هیچ آموزش رسمی فضای محصور ندیده و برنامه نجات اضطراری نیز تدوین نشده است. چه تصمیمی می‌گیرید؟","reference_answer":"ورود به فضای محصور را متوقف و غیرمجاز اعلام می‌کنید تا زمانی که یک Attendant آموزش‌دیده و دارای صلاحیت جایگزین شود و یک برنامه نجات اضطراری مدون و قابل‌اجرا شامل تجهیزات نجات، مسیر ارتباطی و تیم واکنش تهیه گردد. صرف مطلوب‌بودن تست اتمسفر اولیه کافی نیست، زیرا بدون ناظر صالح و برنامه نجات، در صورت بروز اورژانس هیچ واکنش موثری ممکن نخواهد بود. این تصمیم باید مستند شود و پرمیت ورود فضای محصور تا رفع کامل هر دو نقص صادر نشود.","key_points":["توقف یا رد صدور پرمیت ورود تا رفع نقص","عدم کفایت تست اتمسفر مطلوب به‌تنهایی برای اجازه ورود","الزام Attendant آموزش‌دیده و دارای صلاحیت","الزام برنامه نجات مدون پیش از ورود","مستندسازی تصمیم توقف","هماهنگی برای جایگزینی سریع نیروی صالح"],"excellent_answer_indicators":["تسلط به این‌که فضای محصور یکی از پرخطرترین فعالیت‌ها با نرخ بالای مرگ در نجات ناشیانه است","تاکید بر اینکه تست گاز مطلوب فقط یک شرط از چند شرط الزامی است","ارائه راه‌حل عملی سریع مانند فراخوان نیروی آموزش‌دیده در دسترس"],"common_mistakes":["اجازه ورود چون تست گاز خوب بوده بدون توجه به کفایت ناظر و برنامه نجات","جایگزین‌کردن هر فرد در دسترس به‌عنوان ناظر بدون احراز آموزش","نادیده گرفتن ضرورت برنامه نجات مکتوب و اکتفا به وعده شفاهی"],"standard_reference":"OSHA 1910.146"},{"category":"SCENARIO","sub_category":"عملیات لیفت (Lifting)","difficulty":"L4","question_text":"برای جابه‌جایی یک اسپول لوله سنگین با جرثقیل در فضای محدود کنار یک ترانشه باز، طرح لیفت (Lift Plan) ارائه‌شده وزن دقیق بار و شعاع کاری واقعی جرثقیل را در نظر نگرفته و اپراتور جرثقیل گواهی صلاحیت معتبر ندارد. سرپرست اجرایی برای جبران تاخیر پروژه اصرار به شروع فوری عملیات لیفت دارد. تصمیم شما چیست؟","reference_answer":"عملیات لیفت باید متوقف شود و تا زمانی که طرح لیفت با محاسبات دقیق وزن بار، شعاع کاری واقعی، ظرفیت مجاز جرثقیل بر اساس نمودار بار و کنترل ریسک فضای محدود کنار ترانشه باز بازنویسی و تایید شود، و اپراتوری با گواهی صلاحیت معتبر جایگزین گردد، نباید اجازه شروع کار صادر شود. لیفت با محاسبات نادرست یا اپراتور فاقد صلاحیت می‌تواند به واژگونی جرثقیل، سقوط بار روی ترانشه باز یا پرسنل و حادثه فوتی منجر شود. تصمیم توقف باید فوری، مستند و بدون مذاکره بر سر جدول زمانی باشد و باید به مدیر پروژه و مسئول لیفتینگ گزارش گردد.","key_points":["توقف فوری عملیات لیفت","رد قاطع درخواست شروع کار زیر فشار زمانی","الزام بازنویسی طرح لیفت با محاسبات دقیق و نمودار بار","الزام اپراتور دارای گواهی صلاحیت معتبر","توجه به خطر مرکب فضای محدود کنار ترانشه باز","مستندسازی و گزارش‌دهی تصمیم توقف"],"excellent_answer_indicators":["تسلط فنی به مفاهیم شعاع کاری، ظرفیت نامی در برابر ظرفیت واقعی و نمودار بار جرثقیل","شناسایی خطر مرکب لیفت و ترانشه باز به‌عنوان یک ریسک تشدیدشده","قاطعیت کامل بدون هیچ مصالحه با اصرار سرپرست اجرایی","آگاهی به اینکه واژگونی جرثقیل یکی از حوادث فوتی پرتکرار در پروژه‌های EPC است"],"common_mistakes":["اجازه شروع کار با احتیاط بیشتر بدون رفع نواقص اصلی","پذیرش گواهی صلاحیت غیررسمی یا تجربه شفاهی اپراتور به‌جای مدرک معتبر","نادیده گرفتن ریسک ترکیبی فضای محدود کنار ترانشه باز"],"standard_reference":"ASME B30"},{"category":"SCENARIO","sub_category":"کار در ارتفاع (Working at Height)","difficulty":"L3","question_text":"تیم نصب روی یک سازه فلزی در ارتفاع حدود شش متری مشغول کار است. در بازدید میدانی متوجه می‌شوید که نقاط اتصال طناب مهار سقوط به یک لوله غیراستاندارد و بدون تایید مهندسی وصل شده‌اند. تیم اجرایی معتقد است چون تا کنون مشکلی پیش نیامده، کار می‌تواند ادامه یابد. واکنش شما چیست؟","reference_answer":"کار در ارتفاع باید فوراً متوقف شود، زیرا نقطه اتصال غیراستاندارد ممکن است ظرفیت لازم برای مهار سقوط را نداشته باشد و در صورت سقوط واقعی از کار بیفتد. سابقه نداشتن حادثه تا کنون هیچ تضمینی برای ایمنی سیستماتیک نیست و استدلالی مردود محسوب می‌شود. باید نقاط اتصال مطمئن و تاییدشده مهندسی شناسایی و جایگزین شوند، سیستم کامل مهار سقوط شامل هارنس، طناب و جاذب انرژی پیش از ادامه کار بازرسی و تایید مجدد گردد، و تا آن زمان اجازه ادامه کار در ارتفاع صادر نمی‌شود.","key_points":["توقف فوری کار در ارتفاع","رد استدلال «تا کنون مشکلی پیش نیامده»","الزام نقطه اتصال مهندسی‌شده و تاییدشده","بازرسی کامل سیستم مهار سقوط شامل هارنس، طناب و جاذب انرژی","آموزش و تذکر به تیم درباره ریسک واقعی","مستندسازی و تایید مجدد پیش از ازسرگیری کار"],"excellent_answer_indicators":["توضیح فنی این‌که نیروی وارده هنگام سقوط واقعی می‌تواند چندین برابر وزن استاتیک فرد باشد","رد قاطع منطق سابقه بدون حادثه به‌عنوان یک مغالطه شناختی رایج در ایمنی","اقدام فوری میدانی برای توقف کار نه صرفاً گزارش بعدی"],"common_mistakes":["پذیرش ادامه کار به دلیل نبود سابقه حادثه","اکتفا به تذکر شفاهی بدون توقف واقعی کار","بررسی فقط نقطه اتصال و نادیده گرفتن کل سیستم مهار سقوط"],"standard_reference":"OSHA 1926 Subpart M"},{"category":"SCENARIO","sub_category":"عملیات هم‌زمان (SIMOPS)","difficulty":"L4","question_text":"در یک سایت، هم‌زمان عملیات جوشکاری (کار گرم) در نزدیکی یک مخزن ذخیره و عملیات لیفت جرثقیل بالای سر همان منطقه در جریان است، بدون اینکه این دو فعالیت در قالب یک برنامه SIMOPS هماهنگ شده باشند. هنگام بازدید متوجه این هم‌پوشانی می‌شوید. اولین اقدام شما چیست؟","reference_answer":"باید بلافاصله یکی یا هر دو عملیات را متوقف کنید تا زمانی که ارزیابی ریسک SIMOPS رسمی انجام و کنترل‌های لازم مانند توالی زمانی جدا، فاصله ایمن یا ناظر هماهنگ‌کننده مشترک تعیین شود، زیرا هم‌پوشانی کار گرم و عملیات لیفت بالای سر بدون هماهنگی می‌تواند به سقوط جرقه یا جسم روی منطقه کار گرم یا مخزن منجر شود. باید ماتریس سازگاری فعالیت‌ها بررسی و تصمیم مستند شود، و کار فقط پس از تدوین طرح SIMOPS تاییدشده و ابلاغ به هر دو تیم اجرایی از سر گرفته می‌شود.","key_points":["توقف فوری عملیات ناهماهنگ","شناسایی خطر ترکیبی کار گرم و لیفت بالای سر","الزام ارزیابی ریسک و طرح SIMOPS رسمی","تعیین توالی زمانی یا فاصله ایمن به‌جای هم‌زمانی","ابلاغ هماهنگ تصمیم به هر دو تیم اجرایی","مستندسازی کامل تصمیم"],"excellent_answer_indicators":["تسلط به مفهوم ماتریس سازگاری فعالیت‌ها در SIMOPS","شناسایی سریع خطر ترکیبی نه صرفاً دو خطر مجزا","قاطعیت در توقف بدون معطلی برای بررسی بیشتر وقتی خطر بالقوه فوری است","ارائه راه‌حل عملی جداسازی زمانی به‌جای توقف کامل و طولانی هر دو فعالیت"],"common_mistakes":["اجازه ادامه هر دو فعالیت با صرفاً افزایش هشدار شفاهی","توقف فقط یکی از فعالیت‌ها بدون بررسی ریشه‌ای هماهنگی برنامه‌ریزی","برخورد موردی و سلیقه‌ای با هم‌پوشانی فعالیت‌ها به‌جای الزام رسمی SIMOPS"],"standard_reference":""},{"category":"SCENARIO","sub_category":"ایمنی H2S / گاز ترش","difficulty":"L4","question_text":"در حین انجام یک کار تحت پرمیت در نزدیکی یک چاهک بازرسی خط لوله در منطقه‌ای با احتمال گاز ترش (Sour Gas)، آلارم گازسنج قابل‌حمل یکی از اعضای تیم به‌طور ناگهانی برای H2S فعال می‌شود، هرچند تست اولیه محیط قبل از شروع کار نرمال بوده است. اولین اقدام شما و توالی صحیح واکنش چیست؟","reference_answer":"اولین اقدام، دستور فوری تخلیه محل توسط تمام پرسنل به سمت نقطه تجمع بادگیر و توقف کامل کار تحت پرمیت است، نه ادامه کار یا بررسی علت در محل. سپس باید حضور و سلامت همه افراد شمارش و تایید شود، منطقه ایزوله و علامت‌گذاری گردد، تیم واکنش اضطراری و HSE مطلع شوند، و علت افزایش ناگهانی غلظت مانند نشتی، تجمع موضعی یا خرابی سنسور بررسی شود. پرمیت باید باطل شود و کار فقط پس از اطمینان از ایمن‌بودن اتمسفر با تست مجدد و رفع علت ریشه‌ای از سر گرفته شود. با توجه به کشندگی H2S در غلظت‌های بالا، هیچ تعلل یا انتظار برای دیدن بدترشدن وضعیت مجاز نیست.","key_points":["تخلیه فوری و بی‌قید‌وشرط محل به سمت باد","توقف کامل کار و ابطال پرمیت","شمارش و تایید سلامت تمام پرسنل","ایزوله و علامت‌گذاری منطقه","اطلاع فوری تیم اضطراری و HSE","بررسی علت ریشه‌ای پیش از ازسرگیری کار","تست مجدد اتمسفر پیش از بازگشت به منطقه"],"excellent_answer_indicators":["واکنش فوری و بدون تاخیر با توجه به ماهیت کشنده H2S در غلظت بالا","آگاهی فنی به خطر Olfactory Fatigue که اتکا به بو را برای تشخیص خطر ناکارآمد می‌کند","مدیریت صحیح شمارش نفرات در نقطه تجمع","پیگیری سیستماتیک علت واقعی نشتی در برابر خرابی سنسور پیش از هرگونه ازسرگیری"],"common_mistakes":["تلاش برای شناسایی علت آلارم در محل به‌جای تخلیه فوری","ادامه کار با این توجیه که آلارم ممکن است اشتباه سنسور باشد","نادیده گرفتن نیاز به شمارش دقیق نفرات پس از تخلیه"],"standard_reference":""},{"category":"SCENARIO","sub_category":"ایمنی حفاری (Excavation)","difficulty":"L4","question_text":"در حین حفاری ترانشه برای عبور خط لوله جدید، اپراتور بیل مکانیکی گزارش می‌دهد که نقشه‌های مسیریابی تاسیسات زیرزمینی منطقه به‌روز نیستند و تیم اجرایی بدون احراز دقیق موقعیت خطوط لوله موجود یا کابل‌های برق مدفون، قصد ادامه حفاری مکانیزه دارد. به‌عنوان کارشناس HSE چه تصمیمی می‌گیرید؟","reference_answer":"باید حفاری مکانیزه بلافاصله متوقف شود تا زمانی که موقعیت دقیق تاسیسات زیرزمینی از طریق روش‌های قابل‌اتکا مانند نقشه‌برداری به‌روز، دستگاه ردیاب کابل و لوله، و حفاری اکتشافی دستی یا Vacuum Excavation در نزدیکی تاسیسات احتمالی تایید شود. ادامه حفاری مکانیزه بدون احراز موقعیت می‌تواند به آسیب به خط لوله گاز موجود با ریسک انفجار، برق‌گرفتگی یا قطع خدمات حیاتی منجر شود. تصمیم باید مستند شده و تا تایید ایمنی مسیر توسط مالکان تاسیسات مربوطه یا تیم فنی، کار مکانیزه در آن بخش نباید از سر گرفته شود؛ در نزدیکی تاسیسات شناسایی‌شده باید صرفاً حفاری دستی و محتاطانه انجام شود.","key_points":["توقف فوری حفاری مکانیزه","عدم اتکا به نقشه قدیمی یا نامطمئن","الزام ردیابی فیزیکی تاسیسات با لوکیتور کابل/اکتشاف دستی","هماهنگی با مالکان تاسیسات مجاور","انتقال به حفاری دستی محتاطانه نزدیک تاسیسات شناسایی‌شده","مستندسازی تصمیم توقف"],"excellent_answer_indicators":["آگاهی به اینکه آسیب به خط لوله گاز فعال یا کابل برق فشار قوی هنگام حفاری از حوادث فوتی رایج صنعت است","اصرار بر روش‌های اثبات‌شده ردیابی به‌جای حدس یا نقشه قدیمی","مدیریت هم‌زمان تاخیر پروژه با پیشنهاد اکتشاف دستی در بخش‌های پرریسک هم‌زمان با ادامه کار مکانیزه در بخش‌های تاییدشده ایمن"],"common_mistakes":["ادامه حفاری مکانیزه با احتیاط بیشتر به‌جای توقف کامل تا احراز موقعیت","اتکای صرف به نقشه قدیمی بدون ردیابی میدانی","نادیده گرفتن الزام هماهنگی با مالک تاسیسات مجاور"],"standard_reference":"OSHA 1926 Subpart P"},{"category":"PROBLEM_SOLVING","sub_category":"کنترل زیست‌محیطی (Environmental Control)","difficulty":"L3","question_text":"در حین عملیات پیگ‌رانی و تخلیه مایعات از خط لوله، مقداری مایع هیدروکربنی به‌طور غیرمنتظره روی خاک اطراف نشت می‌کند و تیم اجرایی برای جلوگیری از تاخیر می‌خواهد سریعاً خاک آلوده را با خاک تازه بپوشاند و کار را ادامه دهد. به‌عنوان کارشناس HSE چه اقداماتی را باید فوراً انجام دهید؟","reference_answer":"باید فوراً عملیات را متوقف و از پوشاندن ساده خاک آلوده به‌جای پاک‌سازی واقعی جلوگیری کنید. اقدام صحیح شامل ایزوله‌کردن منطقه، توقف منبع نشتی، ارزیابی وسعت و نوع آلودگی، اطلاع‌رسانی طبق رویه گزارش حوادث زیست‌محیطی داخلی و در صورت لزوم به مراجع محیط‌زیست، جمع‌آوری و دفع صحیح خاک آلوده مطابق رویه مدیریت پسماند خطرناک، و مستندسازی کامل واقعه برای بررسی علت ریشه‌ای است. پوشاندن آلودگی بدون پاک‌سازی هم تخلف محسوب می‌شود و هم ریسک بلندمدت آلودگی آب زیرزمینی و مسئولیت حقوقی پروژه را افزایش می‌دهد.","key_points":["توقف فوری منبع نشتی و عملیات","ایزوله‌سازی منطقه آلوده","رد قاطع پوشاندن خاک به‌جای پاک‌سازی واقعی","اطلاع‌رسانی رسمی حادثه زیست‌محیطی","جمع‌آوری و دفع صحیح خاک آلوده به‌عنوان پسماند خطرناک","مستندسازی و بررسی علت ریشه‌ای","اطلاع به مراجع ذی‌ربط در صورت لزوم قانونی"],"excellent_answer_indicators":["آگاهی از الزامات قانونی گزارش‌دهی زیست‌محیطی و مسئولیت حقوقی پروژه","رد قاطع راه‌حل سریع پنهان‌کننده به‌عنوان تخلف نه فقط ضعف فنی","نگاه به رویداد به‌عنوان یک حادثه قابل ثبت نیازمند تحلیل ریشه‌ای"],"common_mistakes":["پذیرش پوشاندن خاک آلوده به بهانه صرفه‌جویی در زمان","عدم گزارش رسمی حادثه زیست‌محیطی","برخورد با نشتی صرفاً به‌عنوان مسئله نظافتی بدون ارزیابی ریسک آلودگی"],"standard_reference":"ISO 14001"},{"category":"EXPERIENCE_BASED","sub_category":"تجربه توقف کار / Life Saving Rules","difficulty":"L3","question_text":"یک تجربه واقعی از زمانی که مجبور شدید به‌عنوان کارشناس HSE از اختیار توقف کار (Stop Work Authority) استفاده کنید را شرح دهید. چه اتفاقی رخ داد، چه تصمیمی گرفتید و نتیجه نهایی چه بود؟","reference_answer":"این سوال باید با یک تجربه واقعی و مشخص، نه فرضی یا کلی، با جزئیات کافی از نوع خطر، شرایط فشار زمانی یا مدیریتی و نحوه تصمیم‌گیری پاسخ داده شود. پاسخ قوی نشان می‌دهد که کارشناس خطر را به‌درستی و به‌موقع تشخیص داده، با وجود فشار احتمالی همکاران یا مدیریت پروژه قاطعانه کار را متوقف کرده، تصمیم را طبق رویه مستند کرده و اطلاع‌رسانی نموده، و مسیر رفع نقص و ازسرگیری ایمن کار را دنبال کرده است. در پایان باید نتیجه واقعی و درس‌آموخته مشخص بیان شود. ارزیاب باید به اصالت داستان، سطح خطر واقعی متوقف‌شده و پیامد مشخص آن توجه کند، نه صرفاً یک پاسخ کلیشه‌ای.","key_points":["تشخیص دقیق و به‌موقع خطر واقعی","وجود فشار واقعی زمانی، مدیریتی یا اجتماعی که بر آن غلبه شده","قاطعیت در تصمیم توقف بدون تعلل","مسیر مستندسازی و اطلاع‌رسانی رسمی طی‌شده","پیگیری رفع نقص تا ازسرگیری ایمن کار","نتیجه نهایی و درس‌آموخته مشخص","جزئیات واقعی و قابل‌راستی‌آزمایی داستان"],"excellent_answer_indicators":["داستان با جزئیات فنی دقیق و قابل‌باور که نشان می‌دهد فرد خودش تصمیم‌گیرنده اصلی بوده","اشاره به مقاومت واقعی مدیریت یا پیمانکار که با استدلال فنی و مستند غلبه شده","تبدیل تجربه به بهبود سیستمی مانند تغییر رویه یا آموزش نه فقط یک واقعه مجزا","روایت با اعتماد‌به‌نفس که نشان‌دهنده تجربه دست‌اول واقعی است"],"common_mistakes":["ارائه پاسخ کلی یا فرضی بدون جزئیات واقعی و قابل‌بررسی","توصیف موقعیتی که نهایتاً با فشار مدیریت کار با کاهش استاندارد ادامه یافته","روایت بدون ذکر مستندسازی یا پیگیری رسمی تصمیم"],"standard_reference":"IOGP Life-Saving Rules"},{"category":"EXPERIENCE_BASED","sub_category":"مدیریت شبه‌حادثه (Near Miss)","difficulty":"L2","question_text":"یک نمونه واقعی از یک شبه‌حادثه (Near Miss) که خودتان گزارش یا مدیریت کرده‌اید را شرح دهید. چگونه آن را شناسایی، گزارش و پیگیری کردید و چه اقدام اصلاحی از آن حاصل شد؟","reference_answer":"پاسخ باید یک رویداد واقعی و مشخص را روایت کند که در آن پتانسیل واقعی آسیب وجود داشته، نه صرفاً یک اتفاق بی‌اهمیت. فرد باید نشان دهد که رویداد را بدون تاخیر و بدون ترس از پیامد گزارش کرده، علت آن را حداقل به‌صورت مقدماتی بررسی کرده، و اقدام اصلاحی مشخصی مانند تغییر رویه، آموزش یا اصلاح تجهیز از آن نتیجه گرفته شده که از تکرار رویداد مشابه یا وقوع حادثه واقعی جلوگیری کرده است. ارزیاب باید به میزان مسئولیت‌پذیری فردی در گزارش‌دهی به‌جای کتمان، عمق تحلیل علت، و اثر واقعی اقدام اصلاحی توجه کند.","key_points":["شرح رویداد واقعی با پتانسیل آسیب مشخص","گزارش سریع و بدون کتمان رویداد","مشارکت فعال در بررسی و تحلیل مقدماتی علت","اقدام اصلاحی مشخص و قابل‌اندازه‌گیری","پیگیری اثربخشی اقدام اصلاحی","اشاره به یادگیری سازمانی حاصل از رویداد"],"excellent_answer_indicators":["نشان‌دادن درک اینکه Near Miss یک شاخص پیشرو حیاتی برای پیشگیری از حوادث واقعی است","به‌اشتراک‌گذاری فعال درس‌آموخته با سایر تیم‌ها یا سایت‌ها","نمونه‌ای که در آن گزارش‌دهی خودِ فرد بوده که نشان‌دهنده فرهنگ ایمنی شخصی قوی است"],"common_mistakes":["ارائه مثالی بسیار جزئی و بی‌اهمیت که واقعاً پتانسیل خطر نداشته","عدم اشاره به اقدام اصلاحی مشخص یا پیگیری آن","روایتی که نشان می‌دهد رویداد ابتدا کتمان و بعداً به اجبار گزارش شده است"],"standard_reference":""},{"category":"EXPERIENCE_BASED","sub_category":"تحقیق حادثه و تحلیل علت ریشه‌ای (RCA)","difficulty":"L4","question_text":"یک تجربه واقعی از مشارکت یا هدایت یک تحقیق حادثه که خودتان انجام داده‌اید را شرح دهید. از چه روش تحلیل علت ریشه‌ای استفاده کردید و نتیجه نهایی و اقدامات اصلاحی چه بود؟","reference_answer":"پاسخ باید یک حادثه واقعی، نه شبه‌حادثه فرضی، را با جزئیات کافی از نوع حادثه، فرآیند جمع‌آوری شواهد شامل مصاحبه، عکس‌برداری، بازسازی صحنه و بررسی مستندات، و روش تحلیل علت ریشه‌ای به‌کاررفته مانند پنج چرا، نمودار استخوان ماهی یا روش‌های ساختاریافته‌تر مانند ICAM یا TapRoot شرح دهد. پاسخ قوی نشان می‌دهد فرد فراتر از علت سطحی یا فردی به علل ریشه‌ای سیستمی مانند نقص رویه، ضعف نظارتی یا فرهنگ سازمانی رسیده و اقدامات اصلاحی SMART و قابل‌پیگیری تعریف کرده که اثربخشی آن‌ها نیز راستی‌آزمایی شده است. ارزیاب باید به عمق تحلیل، مشارکت واقعی فرد در فرآیند، و پیگیری واقعی اثربخشی اقدامات توجه کند.","key_points":["شرح حادثه واقعی با جزئیات مشخص","روش جمع‌آوری شواهد به‌کاررفته","روش تحلیل علت ریشه‌ای مشخص مانند پنج چرا، Fishbone، ICAM یا TapRoot","تمایز علت مستقیم از علل ریشه‌ای سیستمی","اقدامات اصلاحی SMART و قابل‌ردیابی","پیگیری اثربخشی اقدامات اصلاحی","اشتراک‌گذاری درس‌آموخته در سطح پروژه یا سازمان"],"excellent_answer_indicators":["رسیدن به علل ریشه‌ای سیستمی و سازمانی به‌جای توقف در سطح خطای انسانی","استفاده از یک روش ساختاریافته و نامگذاری‌شده تحلیل علت با تسلط بر جزئیات آن","نمونه‌ای که نشان دهد اقدام اصلاحی واقعاً پیاده و اثربخشی آن سنجیده شده است","نگاه بی‌طرفانه و غیرسرزنشی (Just Culture) در فرآیند تحقیق"],"common_mistakes":["توقف تحلیل در سطح خطای انسانی یا بی‌احتیاطی کارگر بدون رفتن به علل ریشه‌ای سیستمی","عدم ذکر روش مشخص تحلیل علت و اکتفا به توصیف کلی","نبود پیگیری واقعی اثربخشی اقدامات اصلاحی تعریف‌شده"],"standard_reference":""}]'::jsonb) as x(
  category text, sub_category text, difficulty text, question_text text, reference_answer text,
  key_points jsonb, excellent_answer_indicators jsonb, common_mistakes jsonb, standard_reference text
)
where not exists (select 1 from comp_question_bank where job_role = 'hse_specialist');

-- ---- contracts_specialist (23 questions) ----
insert into comp_question_bank (job_role, category, sub_category, difficulty, question_text, reference_answer, key_points, excellent_answer_indicators, common_mistakes, standard_reference)
select 'contracts_specialist', x.category, x.sub_category, x.difficulty, x.question_text, x.reference_answer,
       coalesce(x.key_points, '[]'::jsonb), coalesce(x.excellent_answer_indicators, '[]'::jsonb), coalesce(x.common_mistakes, '[]'::jsonb), coalesce(x.standard_reference, '')
from jsonb_to_recordset('[{"category":"GENERAL","sub_category":"Contract Administration Role","difficulty":"L1","question_text":"نقش شما به‌عنوان کارشناس بررسی صورت‌وضعیت و قراردادها را در چرخه اجرای یک پروژه EPC خطوط انتقال گاز توضیح دهید و مشخص کنید در تعامل با کارفرما/مشاور، پیمانکار اصلی، پیمانکاران جزء و واحد حقوقی، مسئولیت شما دقیقاً از کجا شروع و به کجا ختم می‌شود؟","reference_answer":"کارشناس بررسی صورت‌وضعیت مسئول تایید کمی و کیفی اقلام صورت‌وضعیت بر مبنای BOQ، نقشه‌های تاییدشده و متره واقعی است و باید هرگونه مغایرت با دستورکارهای تغییر تاییدشده را شناسایی کند. این نقش مستلزم هماهنگی مستمر با مهندسی سایت و کنترل پروژه برای صحت‌سنجی پیشرفت فیزیکی و با واحد حقوقی برای موارد مناقشه‌برانگیز است. تصمیم نهایی تایید یا رد پرداخت با کارفرما یا مشاور است و کارشناس نقش توصیه‌کننده و صحت‌سنج فنی-قراردادی دارد، نه تصمیم‌گیرنده مطلق. حفظ سوابق مکاتبات و مستندسازی هر تاییدیه از ارکان اصلی این نقش است.","key_points":["تایید کمی و کیفی اقلام صورت‌وضعیت بر مبنای BOQ/نقشه‌های تاییدشده/متره واقعی","بررسی مغایرت با دستورکار تغییرات (VO) تاییدشده","هماهنگی با مهندسی سایت/کنترل پروژه برای صحت‌سنجی متره","ارجاع موارد مناقشه‌برانگیز به واحد حقوقی/مدیر قرارداد","حفظ سوابق مکاتبات و مستندات پشتیبان","نقش توصیه‌کننده نه تصمیم‌گیرنده نهایی (تایید نهایی با کارفرما/مشاور)"],"excellent_answer_indicators":["تمایز روشن بین «تایید فنی/کمی» و «تصمیم قراردادی نهایی»","اشاره به مستندسازی زنجیره تاییدیه‌ها","آگاهی از تعامل با تمام ذی‌نفعان و نقطه توقف مسئولیت خود در صورت نیاز به نظر حقوقی"],"common_mistakes":["تصور اینکه کارشناس صورت‌وضعیت خودش تصمیم نهایی پرداخت را می‌گیرد","نادیده گرفتن نقش هماهنگی با سایت/کنترل پروژه","محدود کردن نقش صرفاً به «جمع زدن اعداد»"],"standard_reference":""},{"category":"GENERAL","sub_category":"Notice & Correspondence Management","difficulty":"L2","question_text":"در جریان بررسی صورت‌وضعیت ماهانه، متوجه می‌شوید پیمانکار برای یک تاخیر ادعایی، نامه اطلاع اولیه (Notice) را دیر یا اصلاً ارسال نکرده اما مبلغ آن را در صورت‌وضعیت لحاظ کرده است. چه اقدامی انجام می‌دهید و چرا حفظ سابقه مکاتبات در این‌گونه موارد اهمیت حیاتی دارد؟","reference_answer":"ابتدا باید الزام و مهلت ابلاغ مندرج در ماده دعاوی قرارداد بررسی و رجیستر مکاتبات به‌طور کامل جستجو شود تا واقعیت ارسال یا عدم ارسال ابلاغیه احراز گردد. در صورت احراز نقص یا تاخیر ابلاغ، باید پاسخ کتبی رسمی به پیمانکار ارسال شود که این نقص را صراحتاً ذکر کند و مبلغ ادعا تا روشن شدن اثر حقوقی آن (احتمال سقوط حق طبق شرط ابتدایی یا صرفاً رویه‌ای بودن ماده ابلاغ) تایید نشود. رجیستر مکاتبات به‌عنوان مهم‌ترین مدرک اثباتی در هرگونه اختلاف یا داوری آتی عمل می‌کند و نبود آن عملاً موضع کارفرما یا پیمانکار را در دفاع از حقوق خود تضعیف می‌کند. هر تصمیم اتخاذشده نیز باید با ذکر تاریخ و شماره نامه مستند شود.","key_points":["بررسی الزام و مهلت ابلاغ (Notice) طبق شرایط قرارداد","جستجو در سوابق مکاتبات برای احراز واقعی بودن یا نبودن ابلاغ","پاسخ کتبی به پیمانکار در خصوص نقص ابلاغ","عدم تایید مبلغ ادعا تا رفع ابهام/نظر حقوقی","نگهداری رجیستر مکاتبات به عنوان مدرک در دعاوی آتی","توجه به این‌که سکوت یا تاخیر کارفرما هم می‌تواند حق او را ساقط کند"],"excellent_answer_indicators":["اشاره به مفهوم «time-bar» و پیامد آن بر حقوق پیمانکار","تمایز بین رد قطعی و «نگهداری در تعلیق تا بررسی حقوقی»","تاکید بر مستندسازی هر تصمیم با تاریخ و مرجع نامه"],"common_mistakes":["نادیده گرفتن کامل موضوع ابلاغ و تایید مبلغ صرفاً چون کار واقعاً انجام شده","رد قطعی بدون بررسی متن دقیق ماده ابلاغ در قرارداد","عدم مستندسازی تصمیم"],"standard_reference":"FIDIC Red Book Clause 20.1 (Contractor''s Claims)"},{"category":"GENERAL","sub_category":"Professional Ethics & Impartiality","difficulty":"L3","question_text":"فرض کنید مدیر پروژه پیمانکار یا حتی مدیریت کارفرما تحت فشار زمانی/بودجه‌ای از شما می‌خواهد صورت‌وضعیتی را که از نظر فنی و قراردادی ایراد دارد، بدون اصلاح تایید کنید تا روند پرداخت یا برنامه پروژه متوقف نشود. چگونه با این فشار برخورد می‌کنید؟","reference_answer":"اصل بنیادین این است که هیچ بندی که با قرارداد یا واقعیت اجرایی مغایرت دارد نباید صرفاً به دلیل فشار مدیریتی تایید شود، زیرا مسئولیت فنی و حرفه‌ای تاییدیه با کارشناس صورت‌وضعیت باقی می‌ماند. رویکرد صحیح، مستندسازی کتبی دلایل فنی و قراردادی مغایرت و ارجاع تصمیم نهایی به سطح بالاتر مدیریتی یا حقوقی با ارائه گزارش شفاف است، نه پذیرش خاموش و نه امتناع بدون راه‌حل. یک راهکار عملی، تایید بخش غیرمناقشه‌برانگیز صورت‌وضعیت و تعلیق بخش مورد اختلاف تا رفع ابهام است تا هم روند پرداخت مسدود نشود و هم اصول قراردادی رعایت شود. حفظ بی‌طرفی نسبت به هر دو طرف و آگاهی از پیامدهای حقوقی تاییدیه نادرست، محور اصلی تصمیم‌گیری در چنین شرایطی است.","key_points":["عدم تایید بند مغایر با قرارداد صرفاً به دلیل فشار مدیریتی","مستندسازی کتبی دلایل فنی/قراردادی مغایرت","ارجاع تصمیم نهایی به سطح بالاتر مدیریتی/حقوقی با ارائه گزارش شفاف","پیشنهاد راه‌حل میانی مانند تایید بخش غیرمناقشه‌برانگیز و تعلیق بخش مشکوک","حفظ بی‌طرفی نسبت به هر دو طرف قرارداد","آگاهی از مسئولیت حرفه‌ای و پیامدهای تایید نادرست"],"excellent_answer_indicators":["تفکیک شفاف بین «تسریع فرآیند» و «دور زدن کنترل قراردادی»","اشاره به مفهوم مسئولیت حرفه‌ای (professional liability) و ریسک تاییدیه نادرست برای پروژه","ارائه راهکار عملی (تایید جزئی/مشروط) به جای فقط «نه گفتن»"],"common_mistakes":["تسلیم شدن کامل در برابر فشار و تایید بدون مستندسازی","امتناع کامل بدون ارائه راه‌حل جایگزین یا مسیر تشدید (escalation)","برخورد احساسی به جای مستندسازی حرفه‌ای"],"standard_reference":""},{"category":"GENERAL","sub_category":"Interface Management (Site/Project Controls)","difficulty":"L2","question_text":"برای صحت‌سنجی مقادیر مندرج در صورت‌وضعیت پیمانکار (مثلاً حجم خاکبرداری، طول جوش خط لوله، یا مقدار بتن‌ریزی)، چه فرآیند تعاملی با مهندسی سایت، QC/QA و واحد کنترل پروژه برقرار می‌کنید؟","reference_answer":"فرآیند صحیح مستلزم برگزاری بازدید و متره مشترک با مهندسی سایت پیش از تهیه صورت‌وضعیت و تطبیق مقادیر با نقشه‌های as-built و گزارش‌های روزانه/هفتگی پیشرفت است. مدارک تخصصی QC/QA مانند لاگ جوش، گزارش‌های NDT/رادیوگرافی و گزارش بتن‌ریزی باید به‌عنوان مستند پشتیبان عینی مقادیر مورد استفاده قرار گیرد، و این ارقام باید با منحنی پیشرفت فیزیکی واحد کنترل پروژه نیز تطبیق داده شود تا از هرگونه مغایرت سیستماتیک جلوگیری شود. این تعامل باید به‌صورت چرخه‌ای و منظم (نه فقط در زمان بحران) برقرار باشد تا اختلافات در همان مرحله وقوع شناسایی و مستند شوند، نه در پایان پروژه.","key_points":["متره مشترک/بازدید میدانی با مهندسی سایت پیش از تهیه صورت‌وضعیت","تطبیق با نقشه‌های as-built و گزارش‌های روزانه/هفتگی پیشرفت","استفاده از مدارک QC/QA (لاگ جوش، NDT، گزارش بتن‌ریزی) به عنوان مستند پشتیبان","تطبیق با منحنی پیشرفت فیزیکی کنترل پروژه","برقراری این تعامل به‌صورت چرخه‌ای و پیشگیرانه نه صرفاً واکنشی","مستندسازی هرگونه تطبیق و مغایرت با عکس/برگه متره"],"excellent_answer_indicators":["اشاره دقیق به انواع مدارک فنی خاص صنعت خط لوله (لاگ جوش، رادیوگرافی/NDT، تست هیدرواستاتیک)","تاکید بر شناسایی زودهنگام مغایرت به‌جای کشف آن در پایان پروژه","آگاهی از تاثیر مغایرت بر پیش‌بینی هزینه در کنترل پروژه"],"common_mistakes":["تایید مقدار ادعایی پیمانکار بدون تطبیق با گزارش سایت","عدم درخواست متره مشترک و اتکا صرف به اسناد پیمانکار","نادیده گرفتن ارتباط منظم با کنترل پروژه در تحلیل مغایرت"],"standard_reference":""},{"category":"GENERAL","sub_category":"Contractual Risk Management","difficulty":"L3","question_text":"چگونه ریسک‌های قراردادی یک پروژه EPC خط لوله گاز (مانند ریسک دعاوی تاخیر، نوسان قیمت مصالح مشمول تعدیل، و ادعاهای غیرمستند پیمانکاران جزء) را در طول اجرای پروژه شناسایی، ثبت و به سطوح بالاتر مدیریت پروژه گزارش می‌کنید؟","reference_answer":"مدیریت موثر ریسک قراردادی نیازمند نگهداری یک ریجستر ریسک قراردادی به‌روز است که بندهای پرریسک قرارداد مانند فرمول تعدیل، جریمه تاخیر و تغییرات حجمی را شناسایی و پایش کند. این ریسک‌ها باید در همکاری با واحد کنترل هزینه به‌صورت کمی و مالی برآورد شوند تا میزان مواجهه واقعی پروژه مشخص باشد، نه صرفاً توصیف کیفی. باید آستانه‌های مشخصی برای تشدید (escalation) بر اساس مبلغ یا اثر برنامه‌ای تعریف شود تا موارد پرریسک به‌موقع و پیش از تبدیل شدن به خسارت جدی به مدیر پروژه و واحد حقوقی گزارش شوند. در قراردادهایی که مکانیزم هشدار زودهنگام (Early Warning) دارند، استفاده فعال از این ابزار نیز بخشی از این فرآیند است.","key_points":["نگهداری ریجستر ریسک قراردادی به‌روز","شناسایی بندهای پرریسک قرارداد (تعدیل، جریمه تاخیر، تغییرات حجمی)","استفاده از مکانیزم هشدار زودهنگام (Early Warning) در صورت وجود در قرارداد","کمی‌سازی ریسک (برآورد مالی مواجهه) با همکاری کنترل هزینه","تعریف آستانه‌های تشدید (escalation threshold) بر اساس مبلغ/اثر برنامه‌ای","گزارش‌دهی دوره‌ای به مدیر پروژه/حقوقی با پیشنهاد اقدام اصلاحی"],"excellent_answer_indicators":["اشاره به مفهوم «Early Warning Notice» در قراردادهای مدرن","کمی‌سازی مالی ریسک به جای توصیف کیفی","تعریف شفاف آستانه تشدید و مسیر گزارش‌دهی سلسله‌مراتبی"],"common_mistakes":["گزارش ریسک صرفاً کیفی و بدون برآورد مالی","تشدید بیش از حد دیرهنگام (پس از وقوع خسارت)","نبود ریجستر مکتوب و اتکا به حافظه/گزارش شفاهی"],"standard_reference":""},{"category":"TECHNICAL","sub_category":"BOQ & WBS Payment Breakdown","difficulty":"L1","question_text":"تفاوت BOQ (فهرست مقادیر) و WBS (ساختار شکست کار) را در کاربرد آن‌ها برای تهیه صورت‌وضعیت توضیح دهید. اگر قرارداد بر مبنای قیمت مقطوع (Lump Sum) با پرداخت بر اساس درصد پیشرفت هر آیتم WBS باشد، نحوه تهیه صورت‌وضعیت ماهانه چه تفاوتی با قرارداد متره‌ای (Unit Price) دارد؟","reference_answer":"BOQ فهرست قیمت‌گذاری‌شده اقلام و مقادیر است که مبنای پرداخت در قراردادهای متره‌ای بر اساس مقدار واقعی انجام‌شده ضربدر نرخ واحد قرار می‌گیرد، در حالی که WBS ساختار شکست دامنه کار پروژه است که عمدتاً برای ردیابی پیشرفت به کار می‌رود و می‌تواند مبنای تهیه Schedule of Values یا شکست پرداخت در قراردادهای مقطوع باشد. در قرارداد Lump Sum پرداخت بر اساس درصد پیشرفت فیزیکی تاییدشده هر فعالیت یا تحویل‌شدنی (Deliverable) صورت می‌گیرد و نیازمند تعریف روشن معیار احراز آن درصد است، نه متره مجدد مقادیر. در قرارداد Unit Price هرگونه تغییر مقدار مستقیماً از طریق متره واقعی و مقایسه با BOQ در صورت‌وضعیت اثر می‌گذارد و لذا حساسیت به دقت متره در این نوع قرارداد بسیار بیشتر است.","key_points":["BOQ: پایه پرداخت در قراردادهای متره‌ای بر اساس مقدار واقعی انجام‌شده × نرخ واحد","WBS: ساختار شکست دامنه کار، پایه ردیابی پیشرفت و می‌تواند مبنای Schedule of Values در قراردادهای مقطوع باشد","در Lump Sum: پرداخت بر اساس درصد پیشرفت فعالیت/تحویل‌شدنی تاییدشده، نه متره مجدد","در Unit Price: هرگونه تغییر مقدار مستقیماً از طریق متره واقعی و مقایسه با BOQ در صورت‌وضعیت اثر می‌گذارد","نیاز به تعریف روشن معیار احراز پیشرفت در قراردادهای مقطوع","تاثیر متفاوت تغییرات کمی بر دو نوع قرارداد"],"excellent_answer_indicators":["توضیح مفهوم Schedule of Values/Payment Milestone Breakdown به عنوان پل بین WBS و پرداخت مقطوع","اشاره به ریسک «over-certification» در قراردادهای مقطوع در صورت نبود معیار دقیق درصد پیشرفت","درک تفاوت اثر تغییرات کمی در دو نوع قرارداد"],"common_mistakes":["یکسان دانستن BOQ و WBS","تصور اینکه در قرارداد مقطوع نیز متره دقیق مقادیر مبنای پرداخت است","نادیده گرفتن نیاز به معیار عینی درصد پیشرفت در Lump Sum"],"standard_reference":""},{"category":"TECHNICAL","sub_category":"Measurement Methods","difficulty":"L2","question_text":"فرض کنید در بخشی از خط لوله، پیمانکار حجم خاکبرداری ترانشه را بر اساس مقاطع طراحی (Design Cross Section) در صورت‌وضعیت درج کرده، اما بازدید میدانی نشان می‌دهد در برخی قسمت‌ها به دلیل شرایط ژئوتکنیکی، عرض واقعی ترانشه بیشتر از طراحی بوده است. چگونه این مورد را ارزیابی و روش صحیح اندازه‌گیری را تعیین می‌کنید؟","reference_answer":"ابتدا باید بند «روش اندازه‌گیری» (Method of Measurement) قرارداد بررسی شود تا مشخص گردد پایه پرداخت خط طراحی نظری است یا مقاطع واقعی اجراشده. در بیشتر قراردادهای این نوع، اضافه‌حجم ناشی از خط طراحی معمولاً پرداختنی نیست مگر آنکه ناشی از شرایط زمین غیرقابل پیش‌بینی یا دستور کتبی مهندس مقیم برای پایدارسازی ترانشه باشد که در این صورت باید به‌عنوان تغییر (Variation) بررسی شود. برای هرگونه اضافه‌حجم لازم است سرمقطع‌برداری مشترک قبل و بعد از عملیات و گزارش ژئوتکنیکی توجیهی ارائه شود و بدون تاییدیه کتبی مهندس مقیم برای ضرورت اضافه‌حجم، این مقدار نباید تایید شود.","key_points":["بررسی بند «روش اندازه‌گیری» (Method of Measurement) در قرارداد","تفکیک بین اضافه‌حجم ناشی از تقصیر اجرایی پیمانکار (غیرقابل پرداخت) و اضافه‌حجم ناشی از شرایط زمین/دستور مهندس (قابل بررسی به‌عنوان تغییر)","نیاز به سرمقطع‌برداری مشترک (Joint Cross-Section Survey) قبل و بعد از عملیات","الزام وجود مستندات ژئوتکنیکی و تاییدیه مهندس مقیم برای هرگونه اضافه‌حجم","عدم تایید حجم اضافی بدون دستور کتبی یا مصوبه تغییر","امکان طرح موضوع به‌عنوان Variation در صورت احراز ضرورت فنی"],"excellent_answer_indicators":["تمایز دقیق میان «خط طراحی نظری» و «خط واقعی اجراشده» و اثر آن در پرداخت","اشاره به لزوم تاییدیه مکتوب مهندس مقیم پیش از اجرای اضافه‌حجم به‌عنوان شرط اساسی پرداخت","آگاهی از ریسک ادعای بعدی پیمانکار در صورت نبود مستندسازی هم‌زمان"],"common_mistakes":["تایید حجم واقعی صرفاً بر مبنای اظهار پیمانکار بدون سرمقطع مشترک","نادیده گرفتن بند روش اندازه‌گیری مندرج در قرارداد","رد کامل ادعا بدون بررسی احتمال وجود دستور کارگاهی برای اضافه‌حجم"],"standard_reference":"FIDIC Red Book Clause 12 (Measurement and Evaluation)"},{"category":"TECHNICAL","sub_category":"Interim Payment Certification","difficulty":"L2","question_text":"مراحل بررسی و تایید یک صورت‌وضعیت موقت (Interim Payment Certificate) از دریافت صورت‌وضعیت پیمانکار تا صدور گواهی پرداخت را گام‌به‌گام شرح دهید. در صورت وجود اختلاف‌نظر بر سر بخشی از مبلغ، چه بخشی از صورت‌وضعیت باید پرداخت شود؟","reference_answer":"فرآیند شامل دریافت و بررسی تکمیل بودن مستندات صورت‌وضعیت، تطبیق مقادیر با متره/مستندات سایت و تغییرات تاییدشده، اعمال صحیح نرخ‌های قراردادی و تعدیل، و اعمال کسورات مانند پیش‌پرداخت، تضمین حسن انجام کار و جریمه تاخیر است. سپس باید گزارش توصیه‌ای تهیه شود که هرگونه قلم مورد اختلاف را با ذکر دلیل مشخص کند. اصل کلیدی این است که مبلغ غیرمناقشه‌برانگیز باید در مهلت قراردادی گواهی و پرداخت شود، حتی اگر بخش دیگری از صورت‌وضعیت مورد اختلاف باشد؛ توقف کل صورت‌وضعیت به دلیل اختلاف در یک قلم صحیح نیست و باید دلایل کسر یا رد اقلام به‌صورت کتبی و شفاف به پیمانکار اطلاع داده شود.","key_points":["دریافت و بررسی تکمیل بودن مستندات صورت‌وضعیت","تطبیق مقادیر با متره/مستندات سایت و تغییرات تاییدشده","اعمال صحیح نرخ، تعدیل، کسورات (پیش‌پرداخت، تضمین حسن انجام کار، جریمه)","تهیه گزارش توصیه با ذکر دقیق اقلام مورد اختلاف و دلیل","صدور گواهی برای مبلغ غیرمناقشه‌برانگیز در مهلت قراردادی حتی در صورت وجود اختلاف بر سر بخشی دیگر","اطلاع‌رسانی کتبی و شفاف به پیمانکار درباره اقلام کسر/رد شده"],"excellent_answer_indicators":["تاکید صریح بر اصل «عدم توقیف کل صورت‌وضعیت به دلیل اختلاف در بخشی از آن»","اشاره به مهلت‌های قراردادی صدور گواهی و پیامد تاخیر در آن","ساختار مشخص گزارش توصیه با شفافیت اقلام رد/تعلیق‌شده"],"common_mistakes":["متوقف کردن کل صورت‌وضعیت به دلیل اختلاف در یک قلم","عدم اعلام کتبی دلایل کسر یا رد اقلام","نادیده گرفتن مهلت زمانی قراردادی برای صدور گواهی"],"standard_reference":"FIDIC Red Book Clause 14.6 (Issue of Interim Payment Certificates)"},{"category":"TECHNICAL","sub_category":"Variation / Change Order Processing","difficulty":"L3","question_text":"فرض کنید پیمانکار کاری خارج از حدود اولیه قرارداد (مثلاً مسیر جایگزین به دلیل تداخل با تاسیسات زیرزمینی) را اجرا کرده و اکنون آن را به‌عنوان تغییر (Variation) در صورت‌وضعیت درج کرده، اما دستور تغییر کتبی (Variation Order) هرگز صادر نشده است. رویکرد شما برای بررسی و قیمت‌گذاری این ادعا چیست؟","reference_answer":"ابتدا باید بررسی شود قرارداد صدور دستور کتبی پیش از اجرای تغییر را الزامی می‌داند یا خیر و سپس مکاتبات و صورتجلسات کارگاهی برای یافتن هرگونه دستور شفاهی یا تایید ضمنی نماینده کارفرما/مهندس جستجو شود، چرا که تایید ضمنی مستند (constructive change) تنها با شواهد مکاتباتی هم‌زمان قابل احراز است نه با ادعای بعدی. باید مشخص شود آیا تغییر مسیر واقعاً ناشی از ضرورت فنی غیرقابل پیش‌بینی (تداخل با تاسیسات) بوده یا تصمیم یک‌جانبه پیمانکار، زیرا تنها حالت اول می‌تواند مبنای استحقاق باشد. در صورت احراز استحقاق، قیمت‌گذاری باید بر اساس نرخ‌های مشابه موجود در BOQ یا در نبود آن نرخ منصفانه توافقی صورت گیرد و توصیه می‌شود حتی در صورت وجود استحقاق، دستور تغییر رسمی به‌صورت پسینی (retrospective) همراه با ارزیابی اثر هزینه‌ای و زمانی صادر شود.","key_points":["بررسی الزام دستور کتبی تغییر (VO) قبل از اجرا طبق قرارداد","جستجوی مدارک مکاتباتی/صورتجلسه که نشان‌دهنده تایید ضمنی یا دستور شفاهی کارفرما/مهندس باشد","تفکیک بین تغییر واقعاً ضروری (تداخل غیرقابل پیش‌بینی) و تصمیم یک‌جانبه پیمانکار","روش قیمت‌گذاری تغییر بر اساس نرخ‌های مشابه در BOQ یا در نبود آن نرخ منصفانه توافقی","نیاز به صدور VO رسمی حتی به‌صورت مصوب‌سازی پسینی (retrospective) قبل از تایید نهایی پرداخت","ارزیابی اثر تغییر بر برنامه زمانی به‌موازات اثر مالی"],"excellent_answer_indicators":["اشاره دقیق به مفهوم «constructive variation/change» و شرایط سخت‌گیرانه احراز آن","تاکید بر ریسک «تغییر خودسرانه پیمانکار بدون دستور» به‌عنوان ریسک عدم پرداخت","توجه هم‌زمان به اثر هزینه‌ای و زمانی تغییر"],"common_mistakes":["تایید ادعای تغییر صرفاً به دلیل انجام واقعی کار در سایت بدون بررسی وجود دستور یا تایید ضمنی","رد کامل ادعا بدون بررسی مکاتبات و صورتجلسات کارگاهی","قیمت‌گذاری خودسرانه بدون رجوع به رویه قراردادی ارزیابی تغییرات"],"standard_reference":"FIDIC Red Book Clause 13 (Variations and Adjustments)"},{"category":"TECHNICAL","sub_category":"Extension of Time & Delay Concurrency","difficulty":"L4","question_text":"پیمانکار برای دو ماه تاخیر در تکمیل بخشی از خط لوله، درخواست تمدید مدت (EOT) داده و علت را بارش‌های شدید غیرمترقبه اعلام کرده است. بررسی برنامه به‌روزشده نشان می‌دهد در همان بازه، پیمانکار به دلیل کمبود نیروی جوشکار ماهر (تحت کنترل خودش) نیز در مسیر بحرانی با تاخیر مواجه بوده است. چگونه این وضعیت تاخیر همزمان (concurrent delay) را تحلیل و تصمیم‌گیری می‌کنید؟","reference_answer":"لازم است یک تحلیل تاخیر مبتنی بر روش مسیر بحرانی (Time Impact Analysis) با استفاده از برنامه‌های به‌روزشده و گزارش‌های هم‌زمان انجام شود تا مشخص گردد کدام رویدادها واقعاً مسیر بحرانی را تحت تاثیر قرار داده‌اند، نه صرفاً پذیرش ادعای روایی. باید احراز شود بارش واقعاً غیرمترقبه و فراتر از آمار هواشناسی بلندمدت منطقه بوده و ابلاغ آن نیز به‌موقع طبق ماده دعاوی صورت گرفته است. در شرایط تاخیر همزمان که هم رویداد قابل انتساب به کارفرما/فورس ماژور و هم رویداد قابل انتساب به پیمانکار هر دو مسیر بحرانی را در یک بازه تحت تاثیر قرار داده‌اند، رویکرد متعارف این است که پیمانکار می‌تواند برای همان بازه مستحق تمدید مدت باشد (تا از جریمه تاخیر ناروا مصون بماند) اما مستحق جبران هزینه‌های ناشی از طولانی شدن پروژه (Prolongation Cost) در آن بازه هم‌پوشان نیست، زیرا تاخیر ناشی از تقصیر خودش در هر صورت رخ می‌داد. نتیجه‌گیری نهایی باید صرفاً پس از تحلیل کمّی دقیق و مستند اعلام شود، نه بر مبنای برداشت کلی.","key_points":["لزوم انجام تحلیل تاخیر مبتنی بر مسیر بحرانی (TIA/CPM) و نه صرفاً ادعای روایی","احراز واقعاً غیرمترقبه و شدید بودن بارش با مقایسه با آمار هواشناسی تاریخی/بلندمدت منطقه","بررسی ثبت به‌موقع ابلاغ (Notice) تاخیر طبق ماده دعاوی قرارداد","تشخیص تاخیر همزمان (Concurrent Delay) و اصل کلی عدم پرداخت هزینه‌های تاخیر برای بازه هم‌پوشان با تاخیر ناشی از تقصیر پیمانکار","امکان اعطای تمدید زمان صرفاً برای بخش قابل انتساب به رویداد کارفرما/فورس ماژور","نیاز به مستندسازی مقدار دقیق تاخیر خالص (net) با استفاده از برنامه به‌روزشده تاییدشده"],"excellent_answer_indicators":["تفکیک دقیق بین حق تمدید زمان (time) و حق جبران هزینه (cost) در شرایط تاخیر همزمان","اشاره به روش‌های شناخته‌شده تحلیل تاخیر (Time Impact Analysis) و رد تحلیل صرفاً توصیفی/global","تاکید بر مقایسه با داده تاریخی هواشناسی برای احراز غیرمترقبه بودن","آگاهی از پروتکل‌های صنعتی مانند SCL Delay and Disruption Protocol"],"common_mistakes":["تایید کامل EOT و هزینه‌های ناشی از تاخیر صرفاً بر مبنای اظهار پیمانکار بدون تحلیل مسیر بحرانی","رد کامل ادعا فقط به دلیل وجود تاخیر همزمان بدون تفکیک اثر هر رویداد","نادیده گرفتن بررسی سابقه ابلاغ به‌موقع"],"standard_reference":"FIDIC Red Book Clause 8.4 (Extension of Time); اصول تحلیل تاخیر همزمان مانند SCL Delay and Disruption Protocol"},{"category":"TECHNICAL","sub_category":"Liquidated Damages","difficulty":"L3","question_text":"در پروژه‌ای که سقف جریمه تاخیر (LD Cap) معادل ۱۰ درصد مبلغ قرارداد است، تاخیر واقعی پیمانکار به نقطه‌ای رسیده که جریمه محاسباتی از این سقف عبور می‌کند. علاوه بر این، بخشی از تاخیر ناشی از دیرکرد کارفرما در تحویل زمین بوده که برای آن EOT هنوز تایید نشده است. چگونه مبلغ صحیح جریمه قابل کسر از صورت‌وضعیت را تعیین می‌کنید؟","reference_answer":"قدم اول این است که همه ادعاهای EOT معلق، به‌ویژه تاخیر ناشی از دیرکرد کارفرما در تحویل زمین، ارزیابی و تاریخ تکمیل قراردادی اصلاح (Adjusted Completion Date) شود، زیرا محاسبه جریمه تنها بر مبنای تاریخ تکمیل نهایی‌شده معتبر است و تاخیر قابل انتساب به کارفرما نباید در محاسبه جریمه لحاظ شود. سپس جریمه فقط بر مبنای روزهای تاخیر خالص قابل انتساب به پیمانکار (net culpable delay) و با نرخ روزانه/هفتگی مندرج در قرارداد محاسبه می‌شود. باید سقف جریمه رعایت شود و کسر مبلغی بیش از سقف تعیین‌شده صحیح نیست؛ همچنین باید بررسی شود آیا رسیدن به سقف جریمه پیامد قراردادی دیگری مانند حق فسخ کارفرما را نیز فعال می‌کند. تا زمانی که ادعاهای EOT معلق نهایی نشوند، جریمه نباید به‌صورت قطعی در صورت‌وضعیت کسر شود.","key_points":["عدم قطعیت جریمه تاخیر تا نهایی‌شدن ارزیابی همه ادعاهای EOT معلق (به‌ویژه تاخیر تحویل زمین از سوی کارفرما)","محاسبه جریمه فقط بر مبنای روزهای تاخیر قابل انتساب به پیمانکار (net culpable delay) نه کل تاخیر خام","رعایت دقیق سقف جریمه (LD Cap) مندرج در قرارداد و عدم کسر مازاد بر آن","بررسی این‌که آیا رسیدن به سقف جریمه پیامد قراردادی دیگری (مانند حق فسخ) نیز فعال می‌کند","لزوم اصلاح تاریخ تکمیل قراردادی پیش از هرگونه محاسبه جریمه","مستندسازی شفاف مبنای محاسبه در گزارش صورت‌وضعیت"],"excellent_answer_indicators":["تاکید بر اصل «نمی‌توان جریمه را نهایی محاسبه کرد تا EOT معلق نهایی شود»","آگاهی از تمایز جریمه به‌عنوان خسارت مقطوع توافقی (Liquidated Damages) از جریمه کیفری و اثر آن بر قابلیت اجرا","توجه به پیامدهای رسیدن به سقف جریمه (حق فسخ کارفرما) به‌عنوان نکته حقوقی جانبی"],"common_mistakes":["محاسبه جریمه بر مبنای کل تاخیر خام بدون کسر تاخیرهای قابل انتساب به کارفرما","کسر جریمه بیش از سقف تعیین‌شده در قرارداد","نهایی کردن جریمه پیش از رسیدگی به ادعاهای EOT معلق پیمانکار"],"standard_reference":"FIDIC Red Book Clause 8.7 (Delay Damages)"},{"category":"TECHNICAL","sub_category":"Advance Payment & Recovery","difficulty":"L2","question_text":"نحوه محاسبه بازپرداخت (Recovery) پیش‌پرداخت در صورت‌وضعیت‌های موقت را توضیح دهید. اگر قرارداد فسخ شود در حالی که هنوز بخشی از پیش‌پرداخت مستهلک نشده، این مبلغ باقیمانده چگونه تسویه می‌شود؟","reference_answer":"پیش‌پرداخت معمولاً به‌صورت تناسبی و طبق درصد یا فرمول مندرج در قرارداد از هر صورت‌وضعیت موقت کسر می‌شود تا پیش از تکمیل کار به‌طور کامل مستهلک گردد، و این استهلاک باید هم‌گام با کاهش تدریجی ارزش تضمین پیش‌پرداخت (Advance Payment Guarantee) انجام شود. در صورت فسخ قرارداد پیش از استهلاک کامل، مانده مستهلک‌نشده بلافاصله به‌عنوان بدهی مسلم پیمانکار قابل مطالبه می‌شود و کارفرما می‌تواند برای وصول آن به ضبط تضمین پیش‌پرداخت (مشروط به اعتبار و ارزش کافی آن) اقدام کند. این تسویه باید در صورت‌حساب نهایی (Final Account) به‌طور دقیق منعکس شود، نه به‌عنوان مبلغی که به‌صورت خودکار بخشیده می‌شود.","key_points":["کسر تناسبی پیش‌پرداخت از هر صورت‌وضعیت موقت طبق درصد یا فرمول مندرج در قرارداد تا استهلاک کامل","لزوم وجود و اعتبار تضمین پیش‌پرداخت هم‌گام با میزان مستهلک‌نشده","در صورت فسخ، مانده مستهلک‌نشده بلافاصله قابل مطالبه از پیمانکار می‌شود","امکان مطالبه مانده از طریق ضبط تضمین پیش‌پرداخت","لزوم تطبیق مانده تضمین با مانده مستهلک‌نشده در هر مقطع (کاهش تدریجی تضمین)","انعکاس دقیق این تسویه در صورت‌حساب نهایی (Final Account)"],"excellent_answer_indicators":["اشاره به کاهش تدریجی ارزش تضمین پیش‌پرداخت متناسب با استهلاک به‌عنوان کنترل ریسک کلیدی","تاکید بر مطالبه فوری مانده در زمان فسخ به‌عنوان بدهی مسلم پیمانکار نه موضوع مذاکره","توجه به فرمول دقیق استهلاک مندرج در قرارداد (خطی یا با آستانه شروع)"],"common_mistakes":["نادیده گرفتن نیاز به تطبیق ارزش تضمین پیش‌پرداخت با مانده مستهلک‌نشده","تصور اینکه در فسخ، مانده پیش‌پرداخت به‌طور خودکار بخشیده یا نادیده گرفته می‌شود","محاسبه استهلاک بدون رجوع به فرمول دقیق قراردادی"],"standard_reference":"FIDIC Red Book Clause 14.2 (Advance Payment)"},{"category":"TECHNICAL","sub_category":"Retention","difficulty":"L1","question_text":"هدف از کسر تضمین حسن انجام کار (Retention Money) در صورت‌وضعیت‌های موقت چیست و روال معمول آزادسازی آن را توضیح دهید. اگر پیمانکار قبل از پایان دوره تضمین از پروژه خارج شود، تضمین باقیمانده چه سرنوشتی دارد؟","reference_answer":"تضمین حسن انجام کار به‌عنوان وثیقه در برابر نواقص یا کارهای ناتمامی که ممکن است در دوره تضمین کشف شود کسر می‌گردد و به کارفرما اهرمی برای اطمینان از رفع نواقص می‌دهد. آزادسازی معمولاً در دو مرحله انجام می‌شود: نیمه اول پس از صدور گواهی تحویل موقت و نیمه دوم پس از پایان دوره تضمین و تایید رفع کامل نواقص (Punch List) توسط کارفرما/مشاور. در صورت خروج یا عدم ایفای تعهدات پیمانکار پیش از پایان دوره تضمین، تضمین باقیمانده صرف جبران هزینه رفع نواقص یا تکمیل کار توسط شخص ثالث می‌شود و مانده احتمالی آن تنها از طریق تسویه‌حساب نهایی یا مسیر حقوقی و نه به‌صورت خودکار به پیمانکار بازگردانده می‌شود.","key_points":["هدف تضمین حسن انجام کار: پوشش ریسک نواقص/عیوب کشف‌شده در دوره تضمین","آزادسازی معمول در دو مرحله: نیمه اول پس از تحویل موقت، نیمه دوم پس از پایان دوره تضمین و رفع نواقص","عدم آزادسازی نیمه دوم تا تایید رفع کامل نواقص توسط کارفرما/مشاور","در صورت خروج/عدم ایفای تعهد پیمانکار، تضمین صرف جبران هزینه رفع نواقص یا تکمیل کار توسط شخص ثالث می‌شود","مابقی احتمالی تضمین صرفاً از طریق تسویه‌حساب نهایی/مسیر حقوقی قابل بازگشت است"],"excellent_answer_indicators":["تفکیک دقیق دو مرحله آزادسازی و شرط هر یک","توجه به این‌که تضمین نقش «اهرم اجرایی» دارد نه صرفاً کسر حسابداری","اشاره به امکان تبدیل نیمه اول تضمین به ضمانت‌نامه بانکی معادل طبق برخی قراردادها"],"common_mistakes":["آزادسازی کامل تضمین بلافاصله پس از تحویل موقت","نادیده گرفتن الزام رفع کامل نواقص پیش از آزادسازی نیمه دوم","تصور بازگشت خودکار تضمین به پیمانکار در صورت خروج زودهنگام از پروژه"],"standard_reference":"FIDIC Red Book Clause 14.9 (Payment of Retention Money)"},{"category":"TECHNICAL","sub_category":"Price Adjustment / Escalation Formula","difficulty":"L3","question_text":"در قراردادی که فرمول تعدیل قیمت بر اساس شاخص‌های قیمت مصالح و دستمزد در تاریخ مبنا تعریف شده، پیمانکار برای موادی که به دلیل تاخیر ناشی از خودش دیرتر از برنامه اصلی خریداری کرده، درخواست تعدیل بر مبنای شاخص‌های روز خرید (که بالاتر است) کرده است. آیا این ادعا قابل قبول است؟ چرا؟","reference_answer":"اصل کلی در فرمول‌های تعدیل قیمت این است که شاخص قابل اعمال بر مبنای دوره‌ای است که فعالیت طبق برنامه زمان‌بندی مصوب می‌بایست انجام می‌شد، نه تاریخ واقعی و تاخیریافته خرید، تا از انتفاع پیمانکار از تاخیر خودش جلوگیری شود. از آنجا که تاخیر در خرید ناشی از تاخیر قابل انتساب به خود پیمانکار بوده و برای آن EOT تاییدشده‌ای وجود ندارد، این ادعا نباید پذیرفته شود و تعدیل باید بر مبنای شاخص دوره برنامه‌ریزی‌شده اصلی محاسبه گردد. اگر بخشی از تاخیر ناشی از EOT تاییدشده (تاخیر مجاز) بود، امکان اعمال شاخص واقعی دوره تاخیریافته صرفاً برای همان بازه مجاز وجود داشت. در هر حال باید به متن دقیق فرمول تعدیل و تعریف «دوره مبنا» و «دوره اجرا» در اسناد قرارداد مراجعه شود.","key_points":["اصل کلی: تعدیل بر مبنای شاخص دوره‌ای که کار می‌بایست طبق برنامه مصوب انجام می‌شد، نه تاریخ واقعی تاخیریافته","لزوم بررسی این‌که آیا تاخیر خرید ناشی از تاخیر تاییدشده (EOT) بوده یا تقصیر پیمانکار","عدم پذیرش تعدیل با شاخص بالاتر برای تاخیر قابل انتساب به پیمانکار (اصل عدم انتفاع از تقصیر خود)","در صورت وجود EOT تاییدشده برای آن بازه، امکان اعمال شاخص واقعی دوره تاخیریافته صرفاً برای مدت مجاز","لزوم مراجعه دقیق به متن فرمول تعدیل و تعریف «دوره مبنا» و «دوره اجرا» در قرارداد","مستندسازی تاریخ برنامه‌ریزی‌شده اصلی فعالیت به‌عنوان مرجع محاسبه"],"excellent_answer_indicators":["اشاره دقیق به اصل حقوقی «منع انتفاع از تقصیر خود» در بحث تعدیل","تفکیک شفاف بین تاخیر مجاز (EOT تاییدشده) و تاخیر غیرمجاز در تعیین شاخص قابل اعمال","توجه به تعریف دقیق فرمول تعدیل مندرج در اسناد قرارداد به‌جای پاسخ کلی"],"common_mistakes":["پذیرش تعدیل بر مبنای شاخص روز خرید بدون بررسی علت تاخیر","رد کامل تعدیل بدون بررسی احتمال وجود EOT تاییدشده برای بخشی از تاخیر","عدم مراجعه به متن دقیق فرمول تعدیل قرارداد"],"standard_reference":"FIDIC Red Book Clause 13.8 (Adjustments for Changes in Cost)"},{"category":"SCENARIO","sub_category":"EOT Claim Validity Assessment","difficulty":"L3","question_text":"پیمانکار ادعای تمدید مدت ۴۵ روزه به دلیل «شرایط جوی نامساعد» ارائه کرده، اما تنها مستند ارائه‌شده یک جدول کلی از تعداد روزهای بارانی ماه است؛ بدون گزارش روزانه کارگاهی هم‌زمان و بدون ابلاغیه اولیه در زمان وقوع. به‌عنوان کارشناس بررسی صورت‌وضعیت، این ادعا را چگونه ارزیابی و چه تصمیمی اعلام می‌کنید؟","reference_answer":"این ادعا در وضعیت فعلی برای تایید فاقد مستندسازی کافی است، زیرا احراز استحقاق EOT نیازمند سه رکن اصلی است: ابلاغ به‌موقع در زمان وقوع رویداد طبق ماده دعاوی، مستندات هم‌زمان که توقف واقعی فعالیت‌های بحرانی را نشان دهند (گزارش روزانه، دفتر کارگاه، عکس، دستور توقف کار)، و اثبات اینکه بارش فراتر از آستانه هواشناسی نامساعد قابل‌انتظار طبق قرارداد یا آمار بلندمدت منطقه بوده و مشخصاً فعالیت‌های مسیر بحرانی را متاثر کرده است. یک جدول کلی بارش ماهانه به‌تنهایی هیچ‌یک از این ارکان را اثبات نمی‌کند و عدم ابلاغ به‌موقع نیز بسته به نوع ماده ابلاغ قرارداد می‌تواند به‌تنهایی موجب سقوط یا محدودیت حق ادعا شود. توصیه می‌شود ادعا در وضعیت فعلی تایید یا رد قطعی نشود، بلکه از پیمانکار به‌صورت کتبی خواسته شود مستندات هم‌زمان تکمیلی را در مهلت معین ارائه دهد.","key_points":["سه رکن لازم برای احراز ادعای EOT: ابلاغ به‌موقع، مستندات هم‌زمان، اثبات تاثیر بر مسیر بحرانی","جدول کلی بارش ماهانه به‌تنهایی برای احراز توقف واقعی کار کافی نیست","بررسی وجود آستانه بارش نامساعد تعریف‌شده در قرارداد در مقایسه با آمار بلندمدت منطقه","عدم ابلاغ به‌موقع می‌تواند به‌تنهایی موجب رد یا محدودیت ادعا شود بسته به نوع ماده ابلاغ","عدم تایید بدون مستندسازی توقف واقعی فعالیت‌های بحرانی مرتبط","درخواست کتبی از پیمانکار برای ارائه مستندات تکمیلی به جای رد یا تایید فوری"],"excellent_answer_indicators":["تفکیک دقیق میان «بارش رخ داده» و «بارش نامساعد فراتر از حد قابل‌انتظار قراردادی»","تاکید بر عدم کفایت مدرک کلی (global) در برابر مدرک متمرکز بر فعالیت بحرانی","اشاره به پیامد نبود ابلاغ به‌موقع بر اعتبار حقوقی ادعا","ارائه مسیر عملی (درخواست تکمیل مستندات) به‌جای قضاوت قطعی زودهنگام"],"common_mistakes":["تایید ادعا صرفاً به دلیل معقول به‌نظر رسیدن آن یا اصرار پیمانکار","رد قطعی و نهایی بدون دادن فرصت ارائه مستندات تکمیلی","عدم توجه به بند ابلاغ و مهلت آن در قرارداد"],"standard_reference":"FIDIC Red Book Clause 20.1 (Contractor''s Claims) و Clause 8.4 (Extension of Time)"},{"category":"SCENARIO","sub_category":"Variation Claim Without Instruction","difficulty":"L2","question_text":"در بازدید از سایت مشاهده می‌کنید پیمانکار برای عبور خط لوله از بستر یک رودخانه، به‌جای روش حفاری افقی مصوب (HDD)، به دلیل مشکل تجهیزات خودش از روش ترانشه باز (Open Cut) استفاده کرده که هزینه بیشتری برای وی داشته و اکنون این تفاوت هزینه را به‌عنوان ادعای تغییر مسیر (Variation) در صورت‌وضعیت درج کرده است. تصمیم شما چیست؟","reference_answer":"این ادعا در حالت عادی نباید به‌عنوان تغییر (Variation) پذیرفته شود، زیرا منشا تغییر روش اجرا محدودیت تجهیزاتی خود پیمانکار بوده، نه دستور مهندس/کارفرما یا شرایط غیرمترقبه سایت. تغییر معتبر مستلزم دستور صریح نماینده کارفرما یا وجود ضرورت فنی غیرقابل پیش‌بینی خارج از کنترل پیمانکار است؛ در اینجا علت تغییر کاملاً به عهده پیمانکار است و بنابراین هزینه اضافی باید بر عهده خودش باقی بماند و پرداخت صرفاً بر مبنای روش و نرخ اصلی مصوب (HDD) صورت گیرد. پیش از نهایی‌سازی رد ادعا، باید مکاتبات بررسی شود تا مشخص گردد آیا مهندس مقیم پیش‌تر با آگاهی از پیامد هزینه‌ای، تغییر روش را کتباً تایید کرده است یا خیر؛ در صورت وجود چنین تاییدیه‌ای نتیجه‌گیری تغییر می‌کند.","key_points":["منشا تغییر روش اجرا از محدودیت تجهیزاتی خود پیمانکار بوده، نه دستور کارفرما/مهندس یا شرایط غیرمترقبه","بدون دستور تغییر یا موافقت مکتوب قبلی، این هزینه اضافه از مصادیق تغییر (Variation) محسوب نمی‌شود","بررسی مکاتبات برای احراز وجود یا عدم وجود تاییدیه قبلی مهندس برای تغییر روش","در نبود چنین تاییدیه‌ای، هزینه اضافی بر عهده پیمانکار باقی می‌ماند و صرفاً بر مبنای نرخ/روش اصلی مصوب پرداخت صورت می‌گیرد","لزوم پاسخ کتبی و مستند به پیمانکار با ذکر دلیل رد ادعا"],"excellent_answer_indicators":["تاکید دقیق بر معیار «منشا تغییر» (تصمیم پیمانکار در برابر دستور کارفرما/شرایط غیرمترقبه) به‌عنوان محور اصلی تحلیل استحقاق","بررسی فعال مکاتبات پیش از نتیجه‌گیری قطعی به‌جای رد صرفاً شهودی","توجه به لزوم پاسخ مستند و شفاف به پیمانکار"],"common_mistakes":["رد یا تایید ادعا صرفاً بر مبنای اینکه هزینه واقعی متحمل شده یا نشده","عدم بررسی مکاتبات برای وجود تاییدیه احتمالی مهندس","خلط بین «تغییر روش اجرا» و «تغییر دامنه کار» به‌عنوان مفاهیم متفاوت قراردادی"],"standard_reference":"FIDIC Red Book Clause 13 (Variations)"},{"category":"PROBLEM_SOLVING","sub_category":"Quantity Verification vs As-built Records","difficulty":"L3","question_text":"در بررسی صورت‌وضعیت شماره ۱۲، متوجه می‌شوید مجموع مقدار تجمعی جوشکاری خط لوله (اینچ-جوش) اعلام‌شده توسط پیمانکار حدود ۸ درصد بیشتر از مقداری است که از گزارش‌های QC (لاگ جوش و رادیوگرافی تاییدشده) و برآورد کنترل پروژه به‌دست می‌آید. اولین اقدام شما چیست و چگونه این مغایرت را نهایی می‌کنید؟","reference_answer":"اولین اقدام، عدم تایید مقدار مازاد مورد اختلاف و تعلیق آن بخش تا رفع ابهام است، نه تایید محافظه‌کارانه یا رد کامل صورت‌وضعیت. باید مقدار ادعایی پیمانکار با مدارک عینی و مستقل QC از جمله لاگ جوش و رادیوگرافی/NDT تاییدشده و همچنین برآورد مستقل کنترل پروژه تطبیق داده شود، زیرا این مدارک مرجع قابل‌اتکاتری نسبت به اظهار پیمانکار هستند. باید جلسه تطبیق مشترک (Reconciliation) با حضور QC، مهندسی سایت و پیمانکار برگزار شود تا علت مغایرت (مانند شمارش تکراری جوش‌های تعمیری، احتساب جوش‌های هنوز تاییدنشده در NDT، یا جوش‌های تای‌این) شناسایی شود. در نهایت فقط مقدار تاییدشده توسط QC باید در این صورت‌وضعیت گواهی شود و در صورت تکرار این الگو، باید به‌عنوان یک ریسک سیستماتیک گزارش‌دهی مطرح و اصلاح فرآیندی (مانند الزام همراهی تاییدیه QC با هر صورت‌وضعیت) پیشنهاد شود.","key_points":["عدم تایید مقدار مازاد مورد اختلاف تا رفع ابهام (Hold/Freeze)","تطبیق مقدار ادعایی با مدارک عینی و مستقل QC (لاگ جوش، رادیوگرافی/NDT تاییدشده)","برگزاری جلسه تطبیق مشترک با حضور QC، مهندسی سایت و پیمانکار برای ریشه‌یابی علت مغایرت","مبنا قرار دادن مقدار تاییدشده QC/کنترل پروژه به‌عنوان مرجع نهایی نه اظهار پیمانکار","در صورت تکرار الگو، اعلام آن به‌عنوان ریسک سیستماتیک گزارش‌دهی و پیشنهاد اصلاح فرآیند","مستندسازی کامل فرآیند ریشه‌یابی و نتیجه در گزارش صورت‌وضعیت"],"excellent_answer_indicators":["اقدام فوری و روشن «عدم تایید تا رفع ابهام» به‌جای تایید محافظه‌کارانه یا رد کامل","استفاده از مدرک فنی خاص صنعت (لاگ جوش/NDT) به‌عنوان مرجع عینی سنجش به‌جای اظهارنظر کلی","پیشنهاد اقدام اصلاحی فرآیندی برای جلوگیری از تکرار مغایرت در آینده"],"common_mistakes":["تایید مقدار ادعایی پیمانکار با این استدلال که «در صورت‌وضعیت بعدی اصلاح می‌شود»","رد کامل صورت‌وضعیت به‌جای تفکیک بخش تاییدشده از بخش مورد اختلاف","عدم مراجعه به مدارک QC/NDT به‌عنوان مرجع مستقل تایید مقدار"],"standard_reference":""},{"category":"SCENARIO","sub_category":"Idle Equipment Claim & Notice Time-bar","difficulty":"L4","question_text":"پیمانکار ادعای هزینه بلااستفاده ماندن (Standing Time) دو دستگاه لوله‌گذار به مدت ۲۰ روز، به دلیل تاخیر کارفرما در آزادسازی عرصه (Right of Way)، ارائه کرده است. بررسی مکاتبات نشان می‌دهد پیمانکار در زمان وقوع تاخیر هیچ ابلاغیه‌ای مطابق ماده دعاوی قرارداد ارسال نکرده و اولین بار موضوع را ماه‌ها بعد، در صورت‌وضعیت پایان پروژه، مطرح کرده است. این ادعا را چگونه ارزیابی می‌کنید؟","reference_answer":"این ادعا با یک نقص جدی و به‌احتمال زیاد سرنوشت‌ساز در زمان ابلاغ مواجه است؛ در بسیاری از قراردادها به‌ویژه قراردادهای مبتنی بر FIDIC، ابلاغ به‌موقع ادعا شرط ابتدایی استحقاق (condition precedent) محسوب می‌شود و عدم ارسال آن در مهلت مقرر می‌تواند به سقوط کامل حق ادعا منجر شود. صرف‌نظر از موضوع ابلاغ، برای احراز ماهوی ادعا نیز باید اثبات شود که تجهیزات واقعاً غیرقابل استفاده مجدد در سایر بخش‌های سایت بوده‌اند (اصل تقلیل خسارت)، و علت واقعی همان تاخیر آزادسازی عرصه توسط کارفرما بوده که پیش‌تر برای آن EOT جداگانه‌ای اعطا نشده باشد. با توجه به تاخیر شدید در طرح ادعا و نبود مدارک هم‌زمان مانند تایم‌شیت تجهیزات یا گزارش روزانه توقف، توصیه می‌شود ادعا عمدتاً بر مبنای نقض مهلت ابلاغ رد شود و حتی در صورت بررسی ماهوی، به دلیل کمبود مستندات هم‌زمان قابل تایید نباشد؛ این رد باید با استناد صریح به بند ابلاغ قرارداد به‌صورت کتبی به پیمانکار اعلام شود.","key_points":["بررسی ماده ابلاغ (Notice) قرارداد و اینکه آیا ابلاغ به‌موقع شرط سقوط حق (condition precedent) محسوب می‌شود یا صرفاً رویه‌ای","عدم ارسال ابلاغیه هم‌زمان و طرح موضوع ماه‌ها بعد، ریسک جدی سقوط حق ادعا","حتی در صورت بررسی ماهوی، نیاز به اثبات بلااستفاده بودن واقعی تجهیزات (اصل تقلیل خسارت)","نیاز به مدارک هم‌زمان مانند تایم‌شیت تجهیزات، گزارش روزانه توقف، و تاریخ دقیق تحویل عرصه","بررسی همپوشانی این دوره با هرگونه EOT قبلاً تایید/رد شده برای همان علت","رد یا حداقل عدم تایید ادعا با استناد صریح به بند ابلاغ در پاسخ کتبی"],"excellent_answer_indicators":["استناد دقیق به مفهوم «ابلاغ به‌عنوان شرط ابتدایی استحقاق» و تاثیر قاطع آن بر سرنوشت ادعا حتی در صورت صحت ماهوی آن","توجه به اصل تقلیل خسارت (Mitigation) در ارزیابی ادعای بلااستفاده ماندن تجهیزات","ساختار تصمیم دو لایه (رد بر مبنای ابلاغ + رد/تردید بر مبنای کمبود مستندات ماهوی)"],"common_mistakes":["بررسی ادعا صرفاً بر مبنای ماهیت (آیا تاخیر واقعاً رخ داده) بدون توجه به نقض جدی مهلت ابلاغ","تایید ادعا با این توجیه که «تاخیر واقعاً از سمت کارفرما بوده»","نادیده گرفتن الزام اثبات عدم امکان استفاده جایگزین از تجهیزات"],"standard_reference":"FIDIC Red Book Clause 20.1 (Contractor''s Claims)"},{"category":"PROBLEM_SOLVING","sub_category":"Subcontract Back-to-Back Pass-Through Claim","difficulty":"L4","question_text":"پیمانکار اصلی، ادعای مالی یک پیمانکار جزء (Subcontractor) بابت تاخیر در تحویل تجهیزات توسط خودِ پیمانکار اصلی را عیناً و بدون هیچ بررسی یا تعدیل، در قالب صورت‌وضعیت خود به کارفرما منتقل کرده و درخواست پرداخت مستقیم آن را دارد. به‌عنوان کارشناس بررسی صورت‌وضعیت کارفرما، چه نکاتی را بررسی می‌کنید و چرا نمی‌توان چنین ادعایی را بدون بررسی مستقل پذیرفت؟","reference_answer":"رابطه قراردادی کارفرما فقط با پیمانکار اصلی برقرار است (Privity of Contract) و بنابراین ادعای پیمانکار جزء نمی‌تواند مستقیماً و بدون تبدیل شدن به ادعای مستقل پیمانکار اصلی، منطبق با شرایط قرارداد اصلی، در برابر کارفرما مطرح شود. باید بررسی شود آیا علت واقعی تاخیر یک رویداد قابل انتساب به کارفرما در قرارداد اصلی بوده (مثلاً تاخیر تایید نقشه یا کالای تحویلی کارفرما) یا صرفاً ضعف مدیریت تدارکات/پیمانکاران جزء توسط پیمانکار اصلی است که در قالب ادعا پنهان شده، زیرا تنها حالت اول قابل انتقال به کارفرما است. رعایت شرایط بند Back-to-Back در سطح پیمان فرعی، از جمله ابلاغ به‌موقع پیمانکار جزء به پیمانکار اصلی، شرط لازم است اما به‌تنهایی برای پذیرش نزد کارفرما کافی نیست؛ پیمانکار اصلی باید مستندات و تحلیل علیت مستقل خود را طبق ماده دعاوی قرارداد اصلی ارائه دهد. توصیه می‌شود از پیمانکار اصلی خواسته شود مستندات مستقل خود (نه صرفاً کاغذبازی منتقل‌شده از پیمانکار جزء) و تحلیل علیت به رویداد کارفرمایی را ارائه کند و بدون این تحلیل، ادعا پذیرفته نشود.","key_points":["رابطه قراردادی کارفرما فقط با پیمانکار اصلی برقرار است (Privity of Contract)؛ ادعای پیمانکار جزء باید به ادعای مستقل پیمانکار اصلی، منطبق با قرارداد اصلی، تبدیل شود","لزوم احراز اینکه علت تاخیر واقعاً رویداد قابل انتساب به کارفرما در قرارداد اصلی بوده، نه ضعف مدیریت تدارکات/پیمانکاران جزء توسط پیمانکار اصلی","بررسی رعایت شرایط بند Back-to-Back در پیمان فرعی که شرط لازم اما نه کافی برای پذیرش نزد کارفرماست","نیاز به مستندسازی و ابلاغ مستقل ادعا توسط پیمانکار اصلی تحت ماده دعاوی قرارداد اصلی","عدم پذیرش صرف انتقال کاغذبازی ادعای پیمانکار جزء بدون تحلیل مستقل علیت","درخواست مستندات مستقل به‌جای اتکا به مستندات ارائه‌شده توسط پیمانکار جزء"],"excellent_answer_indicators":["تحلیل دقیق مفهوم Privity of Contract و لزوم تبدیل ادعای زنجیره‌ای به ادعای مستقل پیمانکار اصلی تحت قرارداد اصلی","تفکیک شفاف بین ریسک قابل انتساب به کارفرما و ریسک ناشی از ضعف مدیریت زیرمجموعه پیمانکار اصلی","توجه به این‌که رعایت شرایط Back-to-Back در سطح پیمان فرعی شرط لازم است اما به‌خودی‌خود استحقاق در برابر کارفرما ایجاد نمی‌کند"],"common_mistakes":["پذیرش خودکار ادعا با این استدلال که «تاخیر واقعاً برای پیمانکار جزء هزینه داشته»","نادیده گرفتن لزوم احراز علیت مستقیم به رویداد کارفرمایی در سطح قرارداد اصلی","عدم بررسی رعایت شرایط ابلاغ در سطح پیمان فرعی و قرارداد اصلی به‌طور جداگانه"],"standard_reference":""},{"category":"EXPERIENCE_BASED","sub_category":"Dispute Resolution Experience","difficulty":"L3","question_text":"بزرگ‌ترین اختلاف صورت‌وضعیتی یا قراردادی که در طول سابقه کاری خود با آن مواجه شدید را شرح دهید: موضوع اختلاف چه بود، چه تحلیلی از استحقاق طرفین ارائه کردید، و نهایتاً چگونه و با چه نتیجه‌ای حل شد؟","reference_answer":"این سوال به‌جای پاسخ ثابت، با یک روایت واقعی سنجیده می‌شود. پاسخ قوی باید یک پروژه و موضوع مشخص (نه توصیف کلی) را روایت کند، ماده یا اصل قراردادی محوری اختلاف را دقیقاً نام ببرد، و نشان دهد تحلیل استحقاق بر اساس شواهد و مستندات (نه صرفاً نظر شخصی) صورت گرفته است. باید مسیر طی‌شده برای حل اختلاف (تصمیم مهندس مقیم، مذاکره مستقیم، هیات حل اختلاف، داوری) و نتیجه نهایی مشخص (مبلغ یا مدت زمان نهایی توافق‌شده یا حکم صادرشده) به‌روشنی بیان شود. یک پاسخ عالی همچنین درس آموخته یا اصلاح فرآیندی که پس از آن تجربه در پروژه‌های بعدی اعمال شده را نیز ذکر می‌کند.","key_points":["روایت یک تجربه واقعی و مشخص (نه پاسخ کلی/فرضی)","بیان دقیق موضوع اختلاف و ماده/اصل قراردادی محوری آن","تشریح مبنای تحلیل استحقاق (چرا ادعا معتبر/نامعتبر تشخیص داده شد) با اتکا به شواهد نه صرفاً نظر شخصی","توضیح مسیر حل اختلاف طی‌شده (تصمیم مهندس مقیم، مذاکره، هیات حل اختلاف، داوری)","بیان نتیجه نهایی مشخص (مبلغ/زمان نهایی توافق‌شده یا حکم صادرشده)","استخراج درس آموخته یا اصلاح فرآیندی که پس از آن اعمال شد"],"excellent_answer_indicators":["شفافیت و قابل‌راستی‌آزمایی بودن جزئیات (نوع پروژه/قرارداد، اعداد تقریبی)","نشان دادن موضع مستدل و مستند به‌جای موضع احساسی یا یک‌طرفه","اشاره به نقش شخصی خود در فرآیند نه صرفاً گزارش نتیجه کار دیگران","درس آموخته‌ای که واقعاً در تصمیمات بعدی به کار گرفته شده است"],"common_mistakes":["ارائه پاسخ کلی و غیرشخصی (نظری) به‌جای تجربه واقعی","عدم اشاره به مبنای مستند تحلیل استحقاق","ناتوانی در بیان نتیجه نهایی مشخص یا درس آموخته"],"standard_reference":""},{"category":"EXPERIENCE_BASED","sub_category":"Rejecting Claim Under Pressure","difficulty":"L3","question_text":"تجربه‌ای را شرح دهید که در آن مجبور شدید ادعا یا صورت‌وضعیت قابل‌توجهی از پیمانکار را رد یا به‌طور چشمگیر کاهش دهید، در حالی که تحت فشار برای تایید آن بودید (از سمت پیمانکار، مدیریت پروژه، یا حتی همکاران). چگونه تصمیم خود را مستدل و مستند کردید و واکنش طرف مقابل چه بود؟","reference_answer":"پاسخ قوی موقعیتی واقعی با فشار مشخص (چه کسی و به چه دلیل) را توصیف می‌کند و مبنای فنی/قراردادی دقیق تصمیم رد یا کاهش ادعا (مانند فقدان ابلاغ، نبود مستندات پشتیبان، نبود دستور تغییر) را روشن بیان می‌کند. باید نشان داده شود این تصمیم چگونه به‌صورت مکتوب (گزارش توصیه، نامه رد ادعا) مستند شده و در صورت تداوم فشار، چگونه به سطح بالاتر مدیریتی یا حقوقی ارجاع شده است. یک پاسخ کامل، نتیجه نهایی وضعیت (تایید رد، مصالحه جزئی، یا ارجاع به مرجع حل اختلاف) و نحوه مدیریت رابطه حرفه‌ای با طرف مقابل پس از تصمیم را نیز شرح می‌دهد.","key_points":["توصیف یک موقعیت واقعی با فشار مشخص (چه کسی، چرا)","مبنای فنی/قراردادی دقیق رد یا کاهش ادعا","نحوه مستندسازی مکتوب تصمیم (گزارش، نامه رد ادعا)","مسیر تشدید در صورت تداوم فشار (ارجاع به مدیر بالاتر/حقوقی)","نتیجه نهایی و نحوه مدیریت رابطه حرفه‌ای پس از تصمیم","حفظ بی‌طرفی و استقلال حرفه‌ای در طول فرآیند"],"excellent_answer_indicators":["شرح دقیق چگونگی تبدیل فشار غیررسمی به یک تصمیم مستند و قابل دفاع","عدم وجود نشانه تسلیم در برابر فشار بدون مبنای فنی","توصیف بلوغ در مدیریت رابطه حرفه‌ای پس از تصمیم سخت (نه لجبازی، نه تسلیم)"],"common_mistakes":["پاسخ کلی بدون جزئیات واقعی موقعیت","نشان دادن تسلیم نهایی در برابر فشار بدون مبنای مستند","عدم اشاره به مستندسازی یا مسیر تشدید تصمیم"],"standard_reference":""},{"category":"EXPERIENCE_BASED","sub_category":"EOT Negotiation Experience","difficulty":"L2","question_text":"تجربه خود را از فرآیند بررسی و نهایی‌سازی یک ادعای تمدید مدت (EOT) قابل‌توجه با پیمانکار شرح دهید: چگونه تحلیل تاخیر را انجام دادید، چالش‌های اصلی مذاکره با پیمانکار چه بود و نتیجه نهایی (تعداد روز تایید‌شده و اثر آن بر جریمه/برنامه) چه بود؟","reference_answer":"پاسخ قوی باید نشان دهد تحلیل تاخیر به‌صورت عملی و مبتنی بر برنامه زمان‌بندی به‌روزشده و روش مسیر بحرانی انجام شده، نه صرفاً توضیح کلامی رویداد. باید چالش‌های واقعی مذاکره با پیمانکار (مانند اختلاف بر سر فلوت موجود در برنامه، تشخیص مسیر بحرانی واقعی، یا تاخیر همزمان) توصیف شود. نتیجه نهایی باید به‌صورت کمّی و مشخص بیان گردد، از جمله تعداد روزهای تایید‌شده در برابر روزهای ادعایی و اثر آن بر جریمه تاخیر یا تاریخ تکمیل قرارداد. یک پاسخ کامل همچنین درس آموخته یا بهبود فرآیندی (مانند الزام به‌روزرسانی منظم‌تر برنامه زمانی) را که پس از این تجربه اعمال شده، ذکر می‌کند.","key_points":["توصیف واقعی و مشخص فرآیند تحلیل تاخیر (استفاده از برنامه زمان‌بندی به‌روز، نه فقط توضیح کلامی)","بیان چالش‌های مذاکره (اختلاف بر سر مسیر بحرانی، فلوت، تاخیر همزمان)","نتیجه کمی نهایی (تعداد روز تایید‌شده در برابر ادعایی، اثر بر جریمه/تاریخ تکمیل)","نقش شخصی در فرآیند تحلیل و مذاکره","درس آموخته یا بهبود فرآیندی متعاقب آن"],"excellent_answer_indicators":["اشاره به روش مشخص تحلیل تاخیر (مانند Time Impact Analysis) به‌جای توصیف کلی","ارائه اعداد/نتایج واقعی و قابل‌راستی‌آزمایی","نشان‌دادن یادگیری و بهبود فرآیندی پس از تجربه"],"common_mistakes":["پاسخ کاملاً نظری بدون تجربه شخصی واقعی","عدم ذکر نتیجه کمی مشخص","نادیده گرفتن نقش تحلیل مسیر بحرانی در فرآیند"],"standard_reference":""},{"category":"EXPERIENCE_BASED","sub_category":"Notice Time-bar Lesson Learned","difficulty":"L4","question_text":"تجربه‌ای را شرح دهید (از دیدگاه کارفرما یا پیمانکار، در نقشی که داشته‌اید) که در آن عدم رعایت به‌موقع الزامات ابلاغ (Notice) قراردادی منجر به از دست رفتن یک حق مالی یا زمانی واقعی و قابل‌توجه شد. چه درسی از آن گرفتید و چه تغییری در فرآیند کاری خود یا تیم ایجاد کردید؟","reference_answer":"پاسخ قوی یک مورد واقعی و مشخص از عدم رعایت مهلت ابلاغ را روایت می‌کند، ماده و مهلت دقیق قراردادی مربوطه را نام می‌برد، و اثر مالی یا زمانی از دست‌رفته را به‌صورت کمی بیان می‌کند. باید علت ریشه‌ای این خطا (مانند نبود سیستم پایش مهلت‌های ابلاغ یا ناآگاهی مهندسین سایت از الزامات قرارداد) تحلیل شود. مهم‌ترین بخش پاسخ، اقدام اصلاحی مشخص و سیستمی پس از این تجربه است، مانند ایجاد رجیستر پایش مهلت‌های ابلاغ، آموزش تیم سایت درباره رویدادهای مستلزم ابلاغ، یا چک‌لیست تشدید، که نشان می‌دهد درس گرفته‌شده واقعاً در عمل به کار گرفته شده است.","key_points":["ذکر مورد واقعی و مشخص عدم رعایت مهلت ابلاغ و ماده مربوطه","بیان کمی اثر مالی/زمانی از دست‌رفته به دلیل این تخلف زمانی","تحلیل علت ریشه‌ای (نبود سیستم پایش ابلاغ، ناآگاهی مهندسین سایت از الزامات قرارداد)","اقدام اصلاحی مشخص پس از آن (رجیستر پایش مهلت‌های ابلاغ، آموزش تیم سایت، چک‌لیست تشدید)","نتیجه اثبات‌شده بهبود در پروژه‌های بعدی در صورت وجود"],"excellent_answer_indicators":["کمی‌سازی دقیق اثر مالی/زمانی از دست رفته","ارائه یک اقدام اصلاحی سیستمی و قابل تکرار، نه فقط «دقت بیشتر کردیم»","نشان‌دادن درک عمیق از مفهوم time-bar به‌عنوان ریسک ساختاری قرارداد نه یک جزئیات اداری"],"common_mistakes":["پاسخ کلی/نظری بدون مورد واقعی","عدم بیان اثر کمی از دست‌رفته","نبود اقدام اصلاحی مشخص و قابل اندازه‌گیری پس از تجربه"],"standard_reference":""}]'::jsonb) as x(
  category text, sub_category text, difficulty text, question_text text, reference_answer text,
  key_points jsonb, excellent_answer_indicators jsonb, common_mistakes jsonb, standard_reference text
)
where not exists (select 1 from comp_question_bank where job_role = 'contracts_specialist');

